INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circuits'), 'circuits-combination-circuit', 'วงจรผสม', 'วงจรไฟฟ้าแบบผสมเป็นการรวมการต่อตัวต้านทานทั้งแบบอนุกรมและแบบขนานไว้ในระบบเดียวกัน การวิเคราะห์วงจรต้องยุบวงจรทีละขั้น โดยคำนวณส่วนที่ต่อขนานหรืออนุกรมอย่างชัดเจนก่อนจนกระทั่งได้ความต้านทานสมมูลรวม R_total จากนั้นใช้กฎของโอห์ม V = IR เพื่อหากระแสไฟฟ้ารวมและย้อนกลับไปคำนวณหาความต่างศักย์ตกคร่อมและกระแสย่อยในแต่ละสาขาของวงจรได้อย่างเป็นระบบ', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit'), 'youtube', 'https://www.youtube.com/watch?v=ucKBpVl8uBo', 'ucKBpVl8uBo', 'ฟิสิกส์ ม.5 บทที่ 14 ไฟฟ้ากระแส ep.3 (ตัวต้านทาน การต่อตัวต้านทานแบบอนุกรม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit'), 'ohm-law', 'วิเคราะห์ความสัมพันธ์ V และ I ในโครงข่ายวงจรผสม', '{"voltage":{"min":4,"max":30,"default":16},"resistance":{"min":2,"max":25,"default":8}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit'), 'match-circuit', 'ควบคุมระดับกระแสไฟฟ้าในวงจรผสมให้บรรลุเป้าหมาย', '{"targetCurrent":[0.8,4.5],"tolerance":0.1,"voltage":{"min":4,"max":24,"default":12},"resistance":{"min":2,"max":20,"default":8}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit'), 'แบบทดสอบ: วงจรผสม', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit')), 'choice', 'วิธีแรกในการวิเคราะห์วงจรผสมที่ถูกต้องคือข้อใด', '["หาความต้านทานรวมของส่วนที่ต่อขนานก่อน แล้วรวมกับส่วนอนุกรม","หากระแสแต่ละจุดก่อนโดยไม่ยุบความต้านทาน","ตัดตัวต้านทานส่วนใหญ่ทิ้ง","ใช้กฎข้อหนึ่งของนิวตันแทน"]', '0', 'การวิเคราะห์วงจรผสมเริ่มจากยุบส่วนที่ขนานรวมเป็นหนึ่ง แล้วรวมกับอนุกรมให้ได้ Rรวม จากนั้นจึงหากระแสรวมและย้อนกลับไปแต่ละส่วน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit')), 'choice', 'ในวงจรผสม ถ้ายุบความต้านทานขนาน 6 โอห์ม กับ 12 โอห์ม เป็นตัวเดียว ความต้านทานรวมของส่วนขนานนี้เท่ากับกี่โอห์ม', '["9 โอห์ม","4 โอห์ม","2 โอห์ม","18 โอห์ม"]', '1', '1/R = 1/6 + 1/12 = 3/12 = 1/4 ดังนั้น R = 4 โอห์ม', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit')), 'choice', 'กระแสไฟฟ้าที่ไหลเข้าจุดแยกของวงจรขนาน มีความสัมพันธ์กับกระแสที่ไหลออกจากจุดแยกอย่างไร', '["ไม่มีกฎเกี่ยวข้อง","กระแสเข้าต่างจากกระแสออกเสมอ","กระแสเข้าทั้งหมดเท่ากับผลรวมกระแสออก","กระแสเข้าดีกว่ากระแสออก"]', '2', 'ประจุไม่สูญหาย ณ จุดแยก กระแสเข้าทั้งหมดจึงเท่ากับผลรวมกระแสที่ไหลออก (ตามกฎข้อหนึ่งของเคอร์ชอฟฟ์)', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit')), 'number', 'วงจรผสมประกอบด้วยตัวต้านทาน 6 โอห์ม และ 12 โอห์ม ต่อขนานกัน แล้วต่ออนุกรมกับตัวต้านทาน 5 โอห์ม ความต้านทานรวมของวงจรเท่ากับกี่โอห์ม (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":9,"tolerance":0.5}', 'ส่วนขนาน R = (6×12)/(6+12) = 72/18 = 4 โอห์ม แล้วรวมอนุกรมกับ 5 โอห์ม ได้ Rรวม = 4 + 5 = 9 โอห์ม', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-combination-circuit')), 'number', 'จากวงจรข้อก่อนหน้า ถ้าต่อแบตเตอรี่ 18 โวลต์ คร่อมวงจร กระแสไฟฟ้ารวมเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'I = V/Rรวม = 18 / 9 = 2 แอมแปร์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circuits'), 'circuits-current-voltage-resistance', 'กระแสไฟฟ้า ความต่างศักย์ ความต้านทาน', 'กระแสไฟฟ้า (I) คืออัตราการไหลของประจุไฟฟ้าผ่านพื้นที่หน้าตัดของตัวนำในหนึ่งหน่วยเวลาตามสมการ I = Q/t โดยมีหน่วยเป็นแอมแปร์ ความต่างศักย์ (V) คือพลังงานต่อหนึ่งหน่วยประจุที่ใช้ขับเคลื่อนอิเล็กตรอนให้เคลื่อนที่ระหว่างสองจุด มีหน่วยเป็นโวลต์ ส่วนความต้านทาน (R) คือสมบัติขัดขวางการไหลของกระแสไฟฟ้า มีหน่วยเป็นโอห์ม ซึ่งขึ้นอยู่กับสภาพต้านทาน ความยาว และพื้นที่หน้าตัดของลวดตัวนำตามความสัมพันธ์ R = rho*L/A', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance'), 'youtube', 'https://www.youtube.com/watch?v=Ja4k6PCjDsM', 'Ja4k6PCjDsM', 'ฟิสิกส์ ม.5 บทที่ 14 ไฟฟ้ากระแส ep.2 (กฎของโอห์ม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance'), 'ohm-law', 'ปรับ V และ R แล้วดูกระแสและกำลังไฟฟ้า', '{"voltage":{"min":1,"max":24,"default":12},"resistance":{"min":1,"max":20,"default":6}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance'), 'match-circuit', 'ปรับวงจรให้ได้กระแสตามเป้าหมาย', '{"tolerance":0.1}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance'), 'แบบทดสอบ: กระแสไฟฟ้า ความต่างศักย์ ความต้านทาน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance')), 'choice', 'กระแสไฟฟ้าในวงจรหมายถึงข้อใด', '["อัตราการไหลของประจุไฟฟ้าผ่านจุดหนึ่งต่อหน่วยเวลา","ปริมาณพลังงานที่ใช้ต่อหน่วยเวลา","ความต่างศักย์ระหว่างปลายสองจุด","จำนวนความต้านทานในวงจร"]', '0', 'กระแสไฟฟ้า I คือ อัตราการเคลื่อนที่ของประจุผ่านจุดหนึ่งต่อหน่วยเวลา I = q/t หน่วยแอมแปร์ (คูลอมบ์/วินาที)', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance')), 'choice', 'หน่วยของความต่างศักย์ และความต้านทาน คือข้อใดตามลำดับ', '["โอห์ม และ แอมแปร์","โวลต์ และ โอห์ม","แอมแปร์ และ โวลต์","คูลอมบ์ และ โอห์ม"]', '1', 'ความต่างศักย์มีหน่วยโวลต์ (V) ความต้านทานมีหน่วยโอห์ม (Ω) กระแสมีหน่วยแอมแปร์ ประจุมีหน่วยคูลอมบ์', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance')), 'choice', 'ถ้าความต่างศักย์คงที่ แต่เพิ่มความต้านทานของวงจร กระแสไฟฟ้าจะเป็นอย่างไร', '["เท่าเดิม","เป็นศูนย์เสมอ","เพิ่มขึ้น","ลดลง"]', '3', 'จาก I = V/R เมื่อ V คงที่และ R เพิ่มขึ้น กระแส I จะลดลง เพราะความต้านทานขัดขวางการไหลของประจุ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance')), 'number', 'ประจุ 15 คูลอมบ์ ไหลผ่านจุดหนึ่งในเส้นลวดใช้เวลา 5 วินาที กระแสไฟฟ้าเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'I = q/t = 15 / 5 = 3 แอมแปร์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-current-voltage-resistance')), 'number', 'กระแสไฟฟ้า 2 แอมแปร์ ไหลในวงจรเป็นเวลา 10 วินาที ประจุไฟฟ้าทั้งหมดที่ไหลผ่านจุดหนึ่งเท่ากับกี่คูลอมบ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', 'q = It = 2 × 10 = 20 คูลอมบ์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circuits'), 'circuits-kirchhoff-battery', 'กฎของเคอร์ชอฟฟ์และแบตเตอรี', 'กฎของเคอร์ชอฟฟ์ประกอบด้วยกฎกระแสไฟฟ้า (KCL) ซึ่งกล่าวว่าผลรวมของกระแสที่ไหลเข้าจุดต่อย่อมเท่ากับผลรวมของกระแสที่ไหลออกจากจุดต่อนั้น (sigma I_in = sigma I_out) และกฎความต่างศักย์ (KVL) ซึ่งกล่าวว่าผลรวมพีชคณิตของความต่างศักย์รอบวงลูปปิดใดๆ มีค่าเท่ากับศูนย์ (sigma V = 0) นอกจากนี้แหล่งจ่ายไฟฟ้าจริงยังมีแรงเคลื่อนไฟฟ้า E และความต้านทานภายใน r ทำให้ความต่างศักย์ที่ขั้ววัดได้จริงเป็น V = E - Ir เมื่อมีกระแสไหล', 'senior', 7, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery'), 'youtube', 'https://www.youtube.com/watch?v=Ei-GN8iqJ4g', 'Ei-GN8iqJ4g', 'ฟิสิกส์ ม.5 บทที่ 14 ไฟฟ้ากระแส ep.7(แรงเคลื่อนไฟฟ้า, ค่า emf)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery'), 'ohm-law', 'จำลองแรงเคลื่อนไฟฟ้าและความต้านทานภายในของเซลล์ไฟฟ้า', '{"voltage":{"min":1.5,"max":18,"default":9},"resistance":{"min":1,"max":18,"default":5}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery'), 'match-circuit', 'ปรับสมดุลแรงดันเคอร์ชอฟฟ์เพื่อให้ได้กระแสตามเป้า', '{"targetCurrent":[0.6,4],"tolerance":0.12,"voltage":{"min":3,"max":21,"default":15},"resistance":{"min":2,"max":16,"default":6}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery'), 'แบบทดสอบ: กฎของเคอร์ชอฟฟ์และแบตเตอรี', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery')), 'choice', 'กฎข้อหนึ่งของเคอร์ชอฟฟ์ (กฎกระแส) กล่าวว่าอย่างไร', '["ผลรวมกระแสเข้าจุดใดจุดหนึ่งเท่ากับผลรวมกระแสออกจากจุดนั้น","กระแสเข้าต้องมากกว่ากระแสออกเสมอ","กระแสลดลงตามระยะทาง","กระแสในวงจรขนานเท่ากันทุกแขน"]', '0', 'เนื่องจากการอนุรักษ์ประจุ ประจุไม่สะสม ณ จุดเชื่อม ผลรวมกระแสเข้าจึงเท่ากับผลรวมกระแสออกเสมอ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery')), 'choice', 'แรงเคลื่อนไฟฟ้า (emf) ของแบตเตอรี หมายถึงข้อใด', '["ความต้านทานภายในของแบตเตอรี","ความต่างศักย์ที่ขั้วแบตเตอรีเมื่อมีกระแสไหล","งานที่แบตเตอรีทำต่อหนึ่งหน่วยประจุที่เคลื่อนครบวงจร","กำลังไฟฟ้าของแบตเตอรี"]', '2', 'emf คือพลังงานที่แบตเตอรีให้ต่อหนึ่งหน่วยประจุ (จูล/คูลอมบ์ หรือโวลต์) ความต่างศักย์ที่ขั้ว V = emf − Ir เมื่อมีกระแสไหล จึงอาจน้อยกว่า emf เนื่องจากความต้านทานภายใน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery')), 'choice', 'แบตเตอรีมีความต้านทานภายใน เมื่อมีกระแสไหล ความต่างศักย์ที่ขั้วแบตเตอรีเทียบกับ emf เป็นอย่างไร', '["มากกว่า emf","เป็นศูนย์","เท่ากันเสมอ","น้อยกว่า emf"]', '3', 'V = emf − Ir ความต่างศักย์ขั้วน้อยกว่า emf เพราะแรงดันส่วนหนึ่งตกคร่อมความต้านทานภายใน r', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery')), 'number', 'แบตเตอรี emf 12 โวลต์ มีความต้านทานภายใน 0.5 โอห์ม ต่อกับความต้านทานภายนอก 5.5 โอห์ม กระแสไฟฟ้าในวงจรเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'I = emf / (R + r) = 12 / (5.5 + 0.5) = 12 / 6 = 2 แอมแปร์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-kirchhoff-battery')), 'number', 'จากแบตเตอรีข้อก่อนหน้า (emf 12 โวลต์, r = 0.5 โอห์ม) เมื่อมีกระแส 2 แอมแปร์ไหล ความต่างศักย์ที่ขั้วแบตเตอรีเท่ากับกี่โวลต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":11,"tolerance":0.5}', 'V = emf − Ir = 12 − (2 × 0.5) = 12 − 1 = 11 โวลต์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circuits'), 'circuits-ohms-law', 'กฎของโอห์ม', 'กฎของโอห์มระบุว่า ภายใต้อุณหภูมิคงที่ กระแสไฟฟ้าที่ไหลผ่านตัวนำตัวหนึ่งจะแปรผันตรงกับความต่างศักย์ตกคร่อมตัวนำนั้น และแปรผกผันกับความต้านทานของตัวนำ สามารถเขียนเป็นสมการพื้นฐานได้ว่า V = IR กราฟความสัมพันธ์ระหว่างความต่างศักย์และกระแสไฟฟ้าของตัวนำชนิดโอห์มจะมีลักษณะเป็นเส้นตรงที่มีความชันเท่ากับความต้านทาน R ช่วยให้เราคำนวณและออกแบบวงจรไฟฟ้ากระแสตรงได้อย่างแม่นยำ', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-ohms-law'), 'youtube', 'https://www.youtube.com/watch?v=Ja4k6PCjDsM', 'Ja4k6PCjDsM', 'ฟิสิกส์ ม.5 บทที่ 14 ไฟฟ้ากระแส ep.2 (กฎของโอห์ม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-ohms-law'), 'ohm-law', 'ปรับ V และ R แล้วดูกระแสและกำลังไฟฟ้า', '{"voltage":{"min":1,"max":24,"default":12},"resistance":{"min":1,"max":20,"default":6}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-ohms-law'), 'match-circuit', 'ปรับวงจรให้ได้กระแสตามเป้าหมาย', '{"tolerance":0.1}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-ohms-law'), 'แบบทดสอบ: กฎของโอห์ม', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-ohms-law')), 'choice', 'กฎของโอห์มกล่าวถึงความสัมพันธ์ของปริมาณใด', '["มวลกับความเร่ง","ความต่างศักย์ กระแสไฟฟ้า และความต้านทาน","พลังงานกับอุณหภูมิ","แรงกับระยะทาง"]', '1', 'กฎของโอห์ม V = IR เชื่อมความต่างศักย์ (V) กระแสไฟฟ้า (I) และความต้านทาน (R) โดย V = IR', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-ohms-law')), 'choice', 'ตามกฎของโอห์ม ถ้าเพิ่มความต่างศักย์เป็น 2 เท่า โดยความต้านทานคงที่ กระแสไฟฟ้าจะเป็นกี่เท่าของเดิม', '["เท่าเดิม","4 เท่า","2 เท่า","1/2 เท่า"]', '2', 'จาก I = V/R เมื่อ R คงที่ กระแสแปรผันตรงกับความต่างศักย์ V เป็น 2 เท่า I จึงเป็น 2 เท่า', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-ohms-law')), 'choice', 'ตัวต้านทานตัวหนึ่งต่อกับแบตเตอรี่ 6 โวลต์ ทำให้กระแส 2 แอมแปร์ ไหลผ่าน ความต้านทานเท่ากับกี่โอห์ม', '["2 โอห์ม","12 โอห์ม","8 โอห์ม","3 โอห์ม"]', '3', 'R = V/I = 6 / 2 = 3 โอห์ม', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-ohms-law')), 'number', 'ตัวต้านทาน 4 โอห์ม ต่อกับแบตเตอรี่ 12 โวลต์ กระแสไฟฟ้าเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'I = V/R = 12 / 4 = 3 แอมแปร์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-ohms-law')), 'number', 'กระแส 0.5 แอมแปร์ ไหลผ่านตัวต้านทาน 20 โอห์ม ความต่างศักย์คร่อมตัวต้านทานเท่ากับกี่โวลต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":10,"tolerance":0.5}', 'V = IR = 0.5 × 20 = 10 โวลต์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circuits'), 'circuits-power-energy', 'กำลังไฟฟ้าและพลังงานไฟฟ้า', 'กำลังไฟฟ้า (P) คืออัตราการถ่ายโอนหรือใช้พลังงานไฟฟ้าในหนึ่งหน่วยเวลามีหน่วยเป็นวัตต์ (W) สามารถคำนวณได้จากความสัมพันธ์ P = VI หรือใช้กฎของโอห์มแทนค่าเป็น P = I^2*R และ P = V^2/R ส่วนพลังงานไฟฟ้า (W หรือ E) ที่เครื่องใช้ไฟฟ้าสิ้นเปลืองไปมีค่าเท่ากับกำลังไฟฟ้าคูณด้วยระยะเวลาที่ใช้งาน W = Pt โดยมีหน่วยวัดมาตรฐานสากลเป็นจูล และในระดับครัวเรือนนิยมคำนวณเป็นหน่วยกิโลวัตต์-ชั่วโมงหรือยูนิต (Unit)', 'senior', 6, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-power-energy'), 'youtube', 'https://www.youtube.com/watch?v=DrSLVCDQpLc', 'DrSLVCDQpLc', 'ฟิสิกส์ ม.5 บทที่ 14 ไฟฟ้ากระแส ep.6(พลังงานไฟฟ้า กำลังไฟฟ้า)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-power-energy'), 'ohm-law', 'ปรับ V และ R แล้วดูกระแสและกำลังไฟฟ้า', '{"voltage":{"min":1,"max":24,"default":12},"resistance":{"min":1,"max":20,"default":6}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-power-energy'), 'match-circuit', 'ปรับวงจรให้ได้กระแสตามเป้าหมาย', '{"tolerance":0.1}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-power-energy'), 'แบบทดสอบ: กำลังไฟฟ้าและพลังงานไฟฟ้า', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-power-energy')), 'choice', 'กำลังไฟฟ้าของวงจรที่ความต่างศักย์ V และกระแส I หาได้จากสูตรใด', '["P = VI","P = I/V","P = ½VI²","P = V/I"]', '0', 'กำลังไฟฟ้า P = VI หน่วยวัตต์ (จูล/วินาที) และสามารถเขียนได้เป็น P = I²R หรือ P = V²/R', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-power-energy')), 'choice', 'หน่วยของพลังงานไฟฟ้าตามบิลค่าไฟที่การไฟฟ้าเรียกเก็บ คือข้อใด', '["โวลต์","กิโลวัตต์-ชั่วโมง","แอมแปร์","โอห์ม"]', '1', 'พลังงานไฟฟ้าคิดในหน่วยกิโลวัตต์-ชั่วโมง (หน่วย) ซึ่งเท่ากับกำลังไฟฟ้าเป็นกิโลวัตต์คูณเวลาเป็นชั่วโมง ส่วนแอมแปร์คือหน่วยกระแส โอห์มคือความต้านทาน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-power-energy')), 'choice', 'หลอดไฟมีกำลัง 100 วัตต์ ใช้ไฟฟ้านาน 10 ชั่วโมง พลังงานไฟฟ้าที่ใช้คิดเป็นกี่หน่วย', '["100 หน่วย","0.1 หน่วย","1 หน่วย","10 หน่วย"]', '2', 'พลังงาน = P × t = 0.1 กิโลวัตต์ × 10 ชั่วโมง = 1 กิโลวัตต์-ชั่วโมง = 1 หน่วย', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-power-energy')), 'number', 'หลอดไฟต่อกับความต่างศักย์ 220 โวลต์ มีกระแสไหลผ่าน 0.5 แอมแปร์ กำลังไฟฟ้าของหลอดเท่ากับกี่วัตต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":110,"tolerance":0.5}', 'P = VI = 220 × 0.5 = 110 วัตต์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-power-energy')), 'number', 'เครื่องทำน้ำอุ่นใช้กำลัง 2 กิโลวัตต์ เปิดนาน 3 ชั่วโมง พลังงานไฟฟ้าที่ใช้เท่ากับกี่หน่วย (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":6,"tolerance":0.5}', 'พลังงาน = P × t = 2 กิโลวัตต์ × 3 ชั่วโมง = 6 กิโลวัตต์-ชั่วโมง = 6 หน่วย', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circuits'), 'circuits-resistors-parallel', 'ตัวต้านทานต่อขนาน', 'การต่อตัวต้านทานแบบขนานคือการนำปลายทั้งสองข้างของตัวต้านทานแต่ละตัวมาเชื่อมต่อกันที่จุดร่วมเดียวกัน ทำให้ความต่างศักย์ตกคร่อมตัวต้านทานทุกตัวมีค่าเท่ากัน V_total = V1 = V2 แต่กระแสไฟฟ้ารวมจะแยกไหลผ่านแต่ละสาขาตามสมการ I_total = I1 + I2 + ... สำหรับความต้านทานรวมจะหาได้จาก 1/R_total = 1/R1 + 1/R2 + ... ส่งผลให้ความต้านทานรวมน้อยกว่าความต้านทานของตัวที่น้อยที่สุดในวงจรเสมอ', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel'), 'youtube', 'https://www.youtube.com/watch?v=ucKBpVl8uBo', 'ucKBpVl8uBo', 'ฟิสิกส์ ม.5 บทที่ 14 ไฟฟ้ากระแส ep.3 (ตัวต้านทาน การต่อตัวต้านทานแบบอนุกรม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel'), 'ohm-law', 'จำลองการแยกไหลของกระแสในวงจรตัวต้านทานต่อขนาน', '{"voltage":{"min":2,"max":20,"default":8},"resistance":{"min":1,"max":15,"default":4}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel'), 'match-circuit', 'ปรับจูนกระแสรวมในวงจรขนานให้เข้าสู่เกณฑ์ที่กำหนด', '{"targetCurrent":[1,5.5],"tolerance":0.15,"voltage":{"min":2,"max":18,"default":6},"resistance":{"min":1,"max":12,"default":3}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel'), 'แบบทดสอบ: ตัวต้านทานต่อขนาน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel')), 'choice', 'ตัวต้านทานที่ต่อขนานกัน ความต่างศักย์คร่อมแต่ละตัวเป็นอย่างไร', '["เท่ากันทุกตัว","ต่างกันตามความต้านทาน","รวมกันเท่ากับศูนย์","มีเฉพาะตัวแรกเท่านั้น"]', '0', 'การต่อขนาน ปลายของทุกแขนต่ออยู่ที่จุดเดียวกัน ความต่างศักย์คร่อมทุกตัวจึงเท่ากันทั้งหมด', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel')), 'choice', 'ต่อตัวต้านทาน 6 โอห์ม และ 3 โอห์ม แบบขนาน ความต้านทานรวมเท่ากับกี่โอห์ม', '["4.5 โอห์ม","2 โอห์ม","18 โอห์ม","9 โอห์ม"]', '1', '1/Rรวม = 1/6 + 1/3 = 1/6 + 2/6 = 3/6 = 1/2 ดังนั้น Rรวม = 2 โอห์ม', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel')), 'choice', 'การต่อความต้านทานแบบขนาน ความต้านทานรวมเมื่อเทียบกับตัวต้านทานตัวใดตัวหนึ่งเป็นอย่างไร', '["เท่ากับผลบวกทุกตัว","มากกว่าตัวที่ใหญ่ที่สุด","เท่ากับตัวที่เล็กที่สุด","น้อยกว่าตัวที่เล็กที่สุด"]', '3', 'ความต้านทานรวมของการต่อขนานจะน้อยกว่าความต้านทานที่น้อยที่สุดเสมอ เพราะมีช่องทางให้กระแสไหลได้หลายทาง', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel')), 'number', 'ต่อตัวต้านทาน 12 โอห์ม และ 4 โอห์ม แบบขนาน ความต้านทานรวมเท่ากับกี่โอห์ม (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', '1/Rรวม = 1/12 + 1/4 = 1/12 + 3/12 = 4/12 = 1/3 ดังนั้น Rรวม = 3 โอห์ม', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-parallel')), 'number', 'แบตเตอรี่ 12 โวลต์ ต่อขนานกับตัวต้านทาน 4 โอห์ม และ 12 โอห์ม กระแสไฟฟ้ารวมที่ไหลจากแบตเตอรี่เท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 'Rรวม: 1/R = 1/4 + 1/12 = 4/12 จึง R = 3 โอห์ม แล้ว I = V/R = 12/3 = 4 แอมแปร์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circuits'), 'circuits-resistors-series', 'ตัวต้านทานต่ออนุกรม', 'การต่อตัวต้านทานแบบอนุกรมคือการนำตัวต้านทานมาต่อเรียงกันเป็นสายเดียว ทำให้กระแสไฟฟ้าที่ไหลผ่านตัวต้านทานทุกตัวมีค่าเท่ากันทั้งวงจร นั่นคือ I_total = I1 = I2 ความต้านทานรวมของวงจรมีค่าเท่ากับผลรวมของความต้านทานแต่ละตัว คือ R_total = R1 + R2 + ... ส่งผลให้ความต้านทานรวมมีค่าเพิ่มขึ้นเสมอ ส่วนความต่างศักย์ไฟฟ้ารวมจะแบ่งตกคร่อมตัวต้านทานแต่ละตัวตามสัดส่วนของความต้านทาน V_total = V1 + V2 + ...', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-resistors-series'), 'youtube', 'https://www.youtube.com/watch?v=ucKBpVl8uBo', 'ucKBpVl8uBo', 'ฟิสิกส์ ม.5 บทที่ 14 ไฟฟ้ากระแส ep.3 (ตัวต้านทาน การต่อตัวต้านทานแบบอนุกรม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-resistors-series'), 'ohm-law', 'จำลองการต่อตัวต้านทานแบบอนุกรมและวัดแรงดันตกคร่อม', '{"voltage":{"min":2,"max":24,"default":12},"resistance":{"min":2,"max":30,"default":15}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-resistors-series'), 'match-circuit', 'จัดกระแสไฟฟ้าในวงจรอนุกรมให้ตรงพิกัดเป้าหมาย', '{"targetCurrent":[0.5,3],"tolerance":0.1,"voltage":{"min":2,"max":24,"default":10},"resistance":{"min":4,"max":24,"default":12}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circuits-resistors-series'), 'แบบทดสอบ: ตัวต้านทานต่ออนุกรม', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-series')), 'choice', 'กระแสไฟฟ้าที่ไหลผ่านตัวต้านทานแต่ละตัวที่ต่อกันแบบอนุกรม มีค่าเป็นอย่างไร', '["เท่ากันทุกตัว","ไม่แน่นอนขึ้นกับแบตเตอรี่","เป็นศูนย์","ต่างกันตามค่าความต้านทาน"]', '0', 'ในวงจรอนุกรมมีทางเดียวที่กระแสไหล กระแสจึงเท่ากันทุกจุดและทุกตัวต้านทาน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-series')), 'choice', 'ต่อตัวต้านทาน 4 โอห์ม และ 6 โอห์ม แบบอนุกรม ความต้านทานรวมเท่ากับกี่โอห์ม', '["24 โอห์ม","2.4 โอห์ม","10 โอห์ม","8 โอห์ม"]', '2', 'ความต้านทานรวมอนุกรม Rรวม = R₁ + R₂ = 4 + 6 = 10 โอห์ม', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-series')), 'choice', 'ความต่างศักย์รวมของวงจรอนุกรมที่ประกอบด้วยตัวต้านทานหลายตัว มีค่าเท่ากับอะไร', '["ความต่างศักย์ของตัวที่มากที่สุดเท่านั้น","ครึ่งหนึ่งของผลรวม","ผลต่างของความต่างศักย์แต่ละตัว","ผลรวมของความต่างศักย์คร่อมแต่ละตัว"]', '3', 'ในวงจรอนุกรม ความต่างศักย์รวม Vรวม = V₁ + V₂ + ... คือผลรวมของความต่างศักย์คร่อมตัวต้านทานแต่ละตัว', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-series')), 'number', 'ต่อตัวต้านทาน 2 โอห์ม, 3 โอห์ม และ 5 โอห์ม แบบอนุกรม เข้ากับแบตเตอรี่ ความต้านทานรวมเท่ากับกี่โอห์ม (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":10,"tolerance":0.5}', 'Rรวม = 2 + 3 + 5 = 10 โอห์ม', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circuits-resistors-series')), 'number', 'แบตเตอรี่ 12 โวลต์ ต่ออนุกรมกับตัวต้านทาน 2 ตัวคือ 2 โอห์ม และ 4 โอห์ม กระแสไฟฟ้าในวงจรเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'Rรวม = 2 + 4 = 6 โอห์ม แล้ว I = V/R = 12/6 = 2 แอมแปร์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circular-motion'), 'circular-motion-angular-velocity', 'ความเร็วเชิงมุม คาบ และความถี่', 'การเคลื่อนที่แบบวงกลมอธิบายได้ด้วยปริมาณเชิงมุม ได้แก่ การกระจัดเชิงมุม (θ) ความเร็วเชิงมุม (ω = Δθ/Δt) คาบการหมุน (T) และความถี่ (f = 1/T) ความเร็วเชิงมุมสัมพันธ์กับความถี่ตามสมการ ω = 2πf = 2π/T ความเร็วเชิงเส้นตามแนวเส้นสัมผัสสัมพันธ์กับความเร็วเชิงมุมด้วยสมการ v = ωr เมื่อ r คือรัศมีการหมุน จุดที่อยู่ไกลจากจุดศูนย์กลางจะมีอัตราเร็วเชิงเส้นมากกว่าจุดที่อยู่ใกล้เสมอ', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity'), 'youtube', 'https://www.youtube.com/watch?v=1cY1UBryLGk', '1cY1UBryLGk', 'ฟิสิกส์ ม.4 บทที่ 7 การเคลื่อนที่แนวโค้ง ep.4 (การเคลื่อนที่แบบวงกลม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity'), 'circular-shm', 'ศึกษาความสัมพันธ์ระหว่างความเร็วเชิงมุม คาบ และความถี่ของการหมุน', '{"mass":{"min":0.5,"max":8,"step":0.5,"default":2},"radius":{"min":0.5,"max":4,"step":0.5,"default":1.5},"springK":{"min":10,"max":70,"step":4,"default":28}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity'), 'balance-force', 'ปรับสมดุลความเร่งเชิงเส้นให้สอดคล้องกับอัตราการหมุนเป้าหมาย', '{"targetAcc":[1.3,4.3],"tolerance":0.16,"force":{"min":18,"max":88,"default":42},"mass":{"min":1,"max":8,"default":4}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity'), 'แบบทดสอบ: ความเร็วเชิงมุม คาบ และความถี่', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity')), 'choice', 'ในการเคลื่อนที่แบบวงกลมสม่ำเสมอ ความเร็วเชิงมุม ω มีความสัมพันธ์กับคาบ T ตามข้อใด', '["ω = 2π/T","ω = 2πT","ω = T/2π","ω = T"]', '0', 'ในเวลาหนึ่งคาบวัตถุหมุนครบรอบ คิดเป็นมุม 2π เรเดียน ความเร็วเชิงมุมจึงเท่ากับ 2π/T', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity')), 'choice', 'ถ้าวัตถุหมุนครบ 1 รอบในเวลา 2 วินาที ความถี่ f ของการหมุนมีค่าเท่าใด', '["0.5 รอบต่อวินาที","2 รอบต่อวินาที","0.25 รอบต่อวินาที","4 รอบต่อวินาที"]', '0', 'ความถี่คือจำนวนรอบต่อหน่วยเวลา f = 1/T = 1/2 = 0.5 รอบต่อวินาที (เฮิรตซ์)', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity')), 'choice', 'อัตราเร็วเชิงเส้น v ที่ขอบของวัตถุที่หมุนด้วยความเร็วเชิงมุม ω และรัศมี r มีค่าตามข้อใด', '["v = ω/r","v = ωr","v = r/ω","v = 1/(ωr)"]', '1', 'อัตราเร็วเชิงเส้นสัมพันธ์กับความเร็วเชิงมุมด้วย v = ωr นั่นคือผลคูณของความเร็วเชิงมุมกับรัศมี', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity')), 'number', 'วงล้อหมุนครบ 200 รอบในเวลา 50 วินาที ความถี่การหมุนมีค่ากี่รอบต่อวินาที', NULL, '{"value":4,"tolerance":0.5}', 'ความถี่ f = จำนวนรอบ/เวลา = 200/50 = 4 รอบต่อวินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-angular-velocity')), 'number', 'วงล้อรัศมี 0.5 เมตร หมุนด้วยความเร็วเชิงมุม 4 เรเดียน/วินาที อัตราเร็วเชิงเส้นที่ขอบวงล้อมีค่ากี่เมตร/วินาที', NULL, '{"value":2,"tolerance":0.5}', 'v = ωr = 4 × 0.5 = 2 เมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circular-motion'), 'circular-motion-applications', 'ตัวอย่างประยุกต์การเคลื่อนที่วงกลม', 'การประยุกต์การเคลื่อนที่แบบวงกลมพบได้บ่อย เช่น การเลี้ยวรถบนถนนราบที่อาศัยแรงเสียดทานเป็นแรงสู่ศูนย์กลาง (fs = mv²/r ทำให้ v_max = √(μgr)) และการเลี้ยวรถบนถนนเอียงทำมุม θ ที่อาศัยองค์ประกอบของแรงแนวฉาก N sin θ ช่วยให้เลี้ยวได้โดยไม่ต้องพึ่งพาแรงเสียดทาน (tan θ = v²/gr) รวมถึงลูกตุ้มแกว่งเป็นวงกลมในแนวนอน (Conical Pendulum)', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-applications'), 'youtube', 'https://www.youtube.com/watch?v=bDC4CCDx4zg', 'bDC4CCDx4zg', 'ฟิสิกส์ ม.4 บทที่ 7 การเคลื่อนที่แนวโค้ง ep.6 (การเคลื่อนที่แบบวงกลม, การเลี้ยวโค้ง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-applications'), 'circular-shm', 'จำลองการเลี้ยวโค้งและการแกว่งแบบกรวยกลมในสถานการณ์ประยุกต์', '{"mass":{"min":0.5,"max":10,"step":0.5,"default":2.5},"radius":{"min":0.5,"max":4,"step":0.5,"default":1.8},"springK":{"min":12,"max":76,"step":4,"default":40}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-applications'), 'balance-force', 'ควบคุมแรงลัพธ์ขณะเลี้ยวโค้งเพื่อสร้างความเร่งปลอดภัยตามเป้า', '{"targetAcc":[1.4,4.4],"tolerance":0.15,"force":{"min":20,"max":90,"default":46},"mass":{"min":2,"max":10,"default":5}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-applications'), 'แบบทดสอบ: ตัวอย่างประยุกต์การเคลื่อนที่วงกลม', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-applications')), 'choice', 'ถนนโค้งที่ลาดเอียงเข้าหาใจกลางโค้งมีประโยชน์อย่างไร', '["ช่วยให้แรงปฏิกิริยาตั้งฉากมีองค์ประกอบที่ให้แรงสู่ศูนย์กลาง","ทำให้รถหยุดได้เร็วขึ้นเท่านั้น","ลดแรงโน้มถ่วงของรถ","ไม่ส่งผลต่อการเลี้ยว"]', '0', 'การเอียงถนนทำให้แรงปฏิกิริยาตั้งฉากมีองค์ประกอบพุ่งเข้าศูนย์กลาง ช่วยให้รถเลี้ยวโค้งได้โดยพึ่งแรงเสียดทานน้อยลง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-applications')), 'choice', 'ลูกตุ้มกรวยซึ่งเป็นวัตถุผูกเชือกแล้วหมุนเป็นวงกลมในแนวระนาบ แรงใดที่ให้แรงสู่ศูนย์กลาง', '["น้ำหนักของวัตถุ","แรงตึงเชือกที่มีองค์ประกอบพุ่งเข้าศูนย์กลาง","แรงเสียดทานระหว่างเชือกกับมือ","แรงลอยตัวในอากาศ"]', '1', 'แรงตึงเชือกเอียงทำมุมกับแนวตั้ง จึงมีองค์ประกอบในแนวราบพุ่งเข้าหาจุดศูนย์กลางของวงกลมทำหน้าที่เป็นแรงสู่ศูนย์กลาง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-applications')), 'choice', 'รถยนต์ในโค้งจะเป็นอันตรายที่สุดถ้าแรงเสียดทานที่ให้แรงสู่ศูนย์กลางไม่เพียงพอ ผลคืออย่างไร', '["รถหมุนออกนอกวิถีวงกลมตรง","รถหยุดนิ่งทันที","รถเร่งความเร็วขึ้น","รถลอยขึ้นจากถนนเสมอ"]', '2', 'เมื่อแรงเสียดทานให้แรงสู่ศูนย์กลางไม่พอ รถจะเคลื่อนออกนอกเส้นทางโค้งตามแนวเส้นสัมผัส จึงเกิดอุบัติเหตุได้', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-applications')), 'number', 'รถเลี้ยวโค้งรัศมี 20 เมตร ด้วยอัตราเร็ว 10 เมตร/วินาที ความเร่งสู่ศูนย์กลางของรถมีค่ากี่เมตร/วินาที²', NULL, '{"value":5,"tolerance":0.5}', 'a = v²/r = 10²/20 = 100/20 = 5 เมตร/วินาที²', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-applications')), 'number', 'ลูกตุ้มกรวยมวล 1 กิโลกรัม หมุนเป็นวงกลมรัศมี 1 เมตร ด้วยอัตราเร็ว 3 เมตร/วินาที แรงสู่ศูนย์กลางที่ต้องให้มีขนาดกี่นิวตัน', NULL, '{"value":9,"tolerance":0.5}', 'F = mv²/r = 1 × 3²/1 = 9 นิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circular-motion'), 'circular-motion-centripetal-acceleration', 'ความเร่งสู่ศูนย์กลาง', 'วัตถุที่เคลื่อนที่ในแนววงกลมด้วยอัตราเร็วคงตัวจะยังคงมีความเร่ง เนื่องจากทิศทางของความเร็วเปลี่ยนแปลงตลอดเวลา ความเร่งนี้เรียกว่าความเร่งสู่ศูนย์กลาง (Centripetal Acceleration, ac) มีทิศชี้เข้าหาจุดศูนย์กลางของวงกลมและตั้งฉากกับความเร็วสัมผัสเสมอ คำนวณได้จาก ac = v²/r = ω²r หากรัศมีเล็กลงหรืออัตราเร็วเพิ่มขึ้น ความเร่งสู่ศูนย์กลางจะมีค่าเพิ่มขึ้นอย่างรวดเร็ว', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration'), 'youtube', 'https://www.youtube.com/watch?v=2WT7rGM57oo', '2WT7rGM57oo', 'ฟิสิกส์ ม.4 บทที่ 7 การเคลื่อนที่แนวโค้ง ep.5 (การเคลื่อนที่แบบวงกลม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration'), 'circular-shm', 'สังเกตเวกเตอร์ความเร่งสู่ศูนย์กลางที่ตั้งฉากกับเวกเตอร์ความเร็วเสมอ', '{"mass":{"min":0.5,"max":8,"step":0.5,"default":1.5},"radius":{"min":0.5,"max":3.5,"step":0.5,"default":2},"springK":{"min":12,"max":72,"step":4,"default":36}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration'), 'balance-force', 'เทียบเคียงขนาดความเร่งสู่ศูนย์กลางด้วยการปรับอัตราส่วนแรงต่อมวล', '{"targetAcc":[1.6,4.6],"tolerance":0.15,"force":{"min":20,"max":92,"default":48},"mass":{"min":1,"max":8,"default":4}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration'), 'แบบทดสอบ: ความเร่งสู่ศูนย์กลาง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration')), 'choice', 'ทิศของความเร่งสู่ศูนย์กลางในการเคลื่อนที่แบบวงกลมสม่ำเสมอเป็นอย่างไร', '["พุ่งออกจากจุดศูนย์กลาง","พุ่งเข้าหาจุดศูนย์กลางเสมอ","ตามแนวเส้นสัมผัสวงกลม","ขึ้นกับทิศการหมุนเป็นกรณีไป"]', '1', 'ความเร่งสู่ศูนย์กลางมีทิศพุ่งเข้าหาจุดศูนย์กลางของวงกลมเสมอ เพราะต้องเปลี่ยนทิศของความเร็วให้โค้งตามวงกลม', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration')), 'choice', 'ความเร่งสู่ศูนย์กลาง a ของวัตถุที่เคลื่อนที่วงกลมรัศมี r ด้วยอัตราเร็ว v มีขนาดตามข้อใด', '["a = v/r","a = v²/r","a = vr","a = r/v²"]', '1', 'ขนาดความเร่งสู่ศูนย์กลางเท่ากับ v²/r ในวงกลมสม่ำเสมอขนาดจะคงที่แต่ทิศเปลี่ยนตลอดเวลา', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration')), 'choice', 'ถ้ารัศมีวงกลมเพิ่มขึ้นเป็น 2 เท่า โดยอัตราเร็ว v คงที่ ความเร่งสู่ศูนย์กลางจะเป็นเท่าใดของเดิม', '["เท่าเดิม","เป็น 2 เท่า","เป็นครึ่งหนึ่ง","เป็น 4 เท่า"]', '2', 'จาก a = v²/r เมื่อ r เพิ่มเป็น 2 เท่าและ v คงที่ ความเร่งจึงลดลงเป็นครึ่งหนึ่งของเดิม', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration')), 'number', 'วัตถุเคลื่อนที่เป็นวงกลมรัศมี 2 เมตร ด้วยอัตราเร็ว 4 เมตร/วินาที ความเร่งสู่ศูนย์กลางมีค่ากี่เมตร/วินาที²', NULL, '{"value":8,"tolerance":0.5}', 'a = v²/r = 4²/2 = 16/2 = 8 เมตร/วินาที²', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-acceleration')), 'number', 'รถคันหนึ่งวิ่งเป็นวงกลมรัศมี 10 เมตร ด้วยอัตราเร็ว 5 เมตร/วินาที ความเร่งสู่ศูนย์กลางมีค่ากี่เมตร/วินาที² (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":2.5,"tolerance":0.05}', 'a = v²/r = 5²/10 = 25/10 = 2.5 เมตร/วินาที²', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'circular-motion'), 'circular-motion-centripetal-force', 'แรงสู่ศูนย์กลาง', 'การที่วัตถุจะเคลื่อนที่เป็นวงกลมได้ต้องมีแรงลัพธ์กระทำในทิศพุ่งเข้าหาจุดศูนย์กลาง เรียกว่าแรงสู่ศูนย์กลาง (Centripetal Force, Fc) ตามกฎข้อที่สองของนิวตัน Fc = m ac = mv²/r = m ω²r แรงสู่ศูนย์กลางไม่ใช่แรงชนิดใหม่ แต่เป็นแรงจริงในธรรมชาติที่ทำหน้าที่ดึงเข้าหาศูนย์กลาง เช่น แรงดึงเชือก แรงเสียดทานระหว่างยางรถยนต์กับถนน หรือแรงดึงดูดระหว่างมวล', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force'), 'youtube', 'https://www.youtube.com/watch?v=2WT7rGM57oo', '2WT7rGM57oo', 'ฟิสิกส์ ม.4 บทที่ 7 การเคลื่อนที่แนวโค้ง ep.5 (การเคลื่อนที่แบบวงกลม)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force'), 'circular-shm', 'ปรับแรงสู่ศูนย์กลางและสังเกตผลกระทบต่อรัศมีการเคลื่อนที่วงกลม', '{"mass":{"min":1,"max":9,"step":0.5,"default":3},"radius":{"min":0.5,"max":4,"step":0.5,"default":2.5},"springK":{"min":16,"max":80,"step":4,"default":44}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force'), 'balance-force', 'จัดสมดุลแรงสู่ศูนย์กลางเพื่อให้ระบบมีความเร่งเข้าสู่ค่าเป้าหมาย', '{"targetAcc":[1.5,4.8],"tolerance":0.15,"force":{"min":22,"max":96,"default":52},"mass":{"min":2,"max":9,"default":4}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force'), 'แบบทดสอบ: แรงสู่ศูนย์กลาง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force')), 'choice', 'แรงสู่ศูนย์กลางที่กระทำต่อวัตถุเคลื่อนที่วงกลมรัศมี r อัตราเร็ว v มวล m มีขนาดตามข้อใด', '["F = m v r","F = m v² / r","F = m r / v","F = m v / r"]', '1', 'แรงสู่ศูนย์กลาง F = mv²/r หรือเทียบเท่า mω²r โดยเป็นแรงที่ทำให้วัตถุเปลี่ยนทิศเข้าหาจุดศูนย์กลาง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force')), 'choice', 'การเคลื่อนที่แบบวงกลม แรงสู่ศูนย์กลางเป็นแรงชนิดใด', '["แรงชนิดใหม่พิเศษที่เกิดแค่ในการหมุน","แรงลัพธ์ที่พุ่งเข้าหาจุดศูนย์กลาง","แรงที่พุ่งออกจากศูนย์กลางเสมอ","แรงโน้มถ่วงเท่านั้น"]', '1', 'แรงสู่ศูนย์กลางไม่ใช่แรงชนิดใหม่ แต่คือแรงลัพธ์ที่พุ่งเข้าหาจุดศูนย์กลาง อาจมาจากแรงจริงชนิดใดก็ได้ตามสถานการณ์', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force')), 'choice', 'ทิศของแรงสู่ศูนย์กลางที่ต้องกระทำต่อวัตถุที่หมุนเป็นวงกลมเป็นอย่างไร', '["พุ่งออกจากศูนย์กลาง","ตามแนวเส้นสัมผัส","พุ่งเข้าหาจุดศูนย์กลาง","เฉียง 45 องศาเข้าหาศูนย์กลาง"]', '2', 'แรงสู่ศูนย์กลางมีทิศเข้าหาจุดศูนย์กลางเสมอ เพื่อให้ความเร่งเข้าหาศูนย์กลางและวัตถุเคลื่อนที่ตามวิถีวงกลม', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force')), 'number', 'วัตถุมวล 2 กิโลกรัม เคลื่อนที่วงกลมรัศมี 3 เมตร ด้วยอัตราเร็ว 6 เมตร/วินาที แรงสู่ศูนย์กลางมีขนาดกี่นิวตัน', NULL, '{"value":24,"tolerance":0.5}', 'F = mv²/r = 2 × 6²/3 = 2 × 36/3 = 24 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'circular-motion-centripetal-force')), 'number', 'วัตถุมวล 0.5 กิโลกรัม เคลื่อนที่วงกลมรัศมี 2 เมตร ด้วยอัตราเร็ว 4 เมตร/วินาที แรงสู่ศูนย์กลางมีขนาดกี่นิวตัน', NULL, '{"value":4,"tolerance":0.5}', 'F = mv²/r = 0.5 × 4²/2 = 0.5 × 16/2 = 4 นิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'momentum-collisions'), 'collision-elastic', 'การชนแบบยืดหยุ่น', 'การชนแบบยืดหยุ่น (Elastic Collision) เป็นการชนที่มีทั้งการอนุรักษ์โมเมนตัม (Σp_ก่อน = Σp_หลัง) และการอนุรักษ์พลังงานจลน์ (ΣEk_ก่อน = ΣEk_หลัง) โดยไม่มีการสูญเสียพลังงานในรูปความร้อนหรือเสียง สำหรับการชนในหนึ่งมิติ จะได้ความสัมพันธ์ของความเร็วสัมพัทธ์คือ u1 - u2 = v2 - v1 ในกรณีที่มวลทั้งสองก้อนเท่ากัน (m1 = m2) วัตถุจะแลกเปลี่ยนความเร็วกันอย่างสมบูรณ์หลังการชน', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'collision-elastic'), 'youtube', 'https://www.youtube.com/watch?v=AIpDktoEgVc', 'AIpDktoEgVc', 'ฟิสิกส์ ม.4 บทที่ 6 โมเมนตัมและการชน ep.5(การชนแบบยืดหยุ่น, การชนแบบไม่ยืดหยุ่น)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'collision-elastic'), 'youtube', 'https://www.youtube.com/watch?v=WSmiSrPYGnA', 'WSmiSrPYGnA', 'ฟิสิกส์ ม.4 บทที่ 6 โมเมนตัมและการชน ep.4 (การชน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'collision-elastic'), 'momentum-collision', 'จำลองการชนแบบยืดหยุ่นสมบูรณ์ที่อนุรักษ์ทั้งโมเมนตัมและพลังงานจลน์', '{"m1":{"min":1,"max":7,"default":2},"u1":{"min":2,"max":10,"default":7},"m2":{"min":1,"max":7,"default":2},"u2":{"min":-6,"max":2,"default":0}}');
