INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-capacitor'), 'match-circuit', 'ปรับกระแสประจุเข้าสู่ตัวเก็บประจุให้ตรงเกณฑ์เป้าหมาย', '{"targetCurrent":[0.7,3.8],"tolerance":0.1,"voltage":{"min":2,"max":20,"default":12},"resistance":{"min":2,"max":20,"default":8}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-capacitor'), 'แบบทดสอบ: ตัวเก็บประจุ', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-capacitor')), 'choice', 'ความจุไฟฟ้า C ของตัวเก็บประจุ นิยามด้วยสูตรใด', '["C = V/Q","C = Q/V","C = ½QV","C = QV"]', '1', 'ความจุ C = Q/V โดย Q คือประจุที่เก็บได้และ V คือความต่างศักย์ระหว่างแผ่น หน่วยฟารัด C = ½QV คือสูตรพลังงานสะสมในตัวเก็บประจุ ไม่ใช่ความจุ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-capacitor')), 'choice', 'ต่อตัวเก็บประจุความจุเท่ากัน 2 ตัวแบบอนุกรม ความจุรวมจะต่างจากตัวเก็บประจุตัวเดียวอย่างไร', '["ค่าเป็น 2 เท่า","ค่าเป็น 4 เท่า","ค่าน้อยลง","ค่าเท่าเดิม"]', '2', 'การต่ออนุกรม ความจุรวม 1/C = 1/C₁ + 1/C₂ เมื่อ C₁ = C₂ = C จะได้ Cรวม = C/2 จึงน้อยกว่าตัวเดี่ยว ส่วนการต่อขนานความจุรวมจะมากกว่า', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-capacitor')), 'choice', 'การต่อตัวเก็บประจุแบบใดที่ทำให้ความจุรวมมีค่าเท่ากับผลบวกของความจุแต่ละตัว', '["ต่อแบบผสมแล้วใส่ฉนวน","ไม่มีวิธีใด","ต่ออนุกรม","ต่อขนาน"]', '3', 'เมื่อต่อขนาน ประจุรวม Q = Q₁ + Q₂ และความต่างศักย์เท่ากัน จึง Cรวม = C₁ + C₂ หรือเท่ากับผลบวกความจุแต่ละตัว', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-capacitor')), 'number', 'ตัวเก็บประจุความจุ 20 ไมโครฟารัด ต่อกับความต่างศักย์ 12 โวลต์ ประจุที่สะสมบนแผ่นตัวนำเป็นกี่ไมโครคูลอมบ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":240,"tolerance":0.5}', 'Q = CV = 20 × 12 = 240 ไมโครคูลอมบ์ ใช้หน่วยไมโครตรงกัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-capacitor')), 'number', 'ตัวเก็บประจุความจุ 10 ไมโครฟารัด ต่อกับความต่างศักย์ 6 โวลต์ ประจุที่สะสมเป็นกี่ไมโครคูลอมบ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":60,"tolerance":0.5}', 'Q = CV = 10 × 6 = 60 ไมโครคูลอมบ์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'electrostatics'), 'electrostatics-charge-electrification', 'ประจุไฟฟ้าและการทำให้เป็นไฟฟ้า', 'ประจุไฟฟ้าในธรรมชาติมีสองชนิดคือประจุบวกและประจุลบ โดยประจุชนิดเดียวกันจะผลักกันและประจุต่างชนิดกันจะดึงดูดกันตามหลักการพื้นฐาน การทำให้วัตถุมีประจุไฟฟ้าสามารถทำได้สามวิธีหลัก ได้แก่ การขัดสีหรือการถูกัน การสัมผัส และการเหนี่ยวนำทางไฟฟ้า ทั้งนี้ปริมาณประจุไฟฟ้ารวมของระบบที่แยกเดี่ยวจะคงที่เสมอตามกฎการอนุรักษ์ประจุไฟฟ้า (Law of Conservation of Charge) และประจุจะมีค่าเป็นจำนวนเต็มเท่าของประจุมูลฐาน e ตามสมการ Q = ne', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-charge-electrification'), 'youtube', 'https://www.youtube.com/watch?v=KWRoq4zckv4', 'KWRoq4zckv4', 'ฟิสิกส์ ม.5 บทที่ 13 ไฟฟ้าสถิต ep.1(การเสียดสีและการเหนี่ยวนำทางไฟฟ้า)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
