INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-charge-electrification'), 'แบบทดสอบ: ประจุไฟฟ้าและการทำให้เป็นไฟฟ้า', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-electrification')), 'choice', 'การทำให้แท่งแก้วเป็นไฟฟ้าด้วยการถูด้วยผ้าไหม เกิดจากกระบวนการใดเป็นหลัก', '["อิเล็กตรอนเคลื่อนที่จากแก้วไปยังผ้าไหม","โปรตอนเคลื่อนที่จากผ้าไหมไปยังแก้ว","นิวตรอนถูกสร้างขึ้นใหม่ที่ผิวแก้ว","ประจุบวกถูกสร้างขึ้นจากความร้อนของการถู"]', '0', 'การถูทำให้อิเล็กตรอน (ประจุลบ) เคลื่อนที่ระหว่างวัตถุ แก้วเสียอิเล็กตรอนจึงมีประจุบวก ส่วนโปรตอนยึดแน่นในนิวเคลียสไม่เคลื่อนที่ วัตถุที่เป็นกลางเกิดประจุได้จากการถ่ายโอนอิเล็กตรอน ไม่ใช่การสร้างประจุใหม่', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-electrification')), 'choice', 'วิธีใดทำให้วัตถุมีประจุโดยไม่ต้องสัมผัสกับวัตถุที่มีประจุโดยตรง', '["การเสียดสี","การเหนี่ยวนำ","การสัมผัส","การละลาย"]', '1', 'การเหนี่ยวนำทำให้ประจุในตัวนำถูกจัดเรียงใหม่เมื่อมีประจุภายนอกมาใกล้ โดยไม่มีการสัมผัส เมื่อต่อลงดินแล้วถอนสายดิน ตัวนำจะเหลือประจุสุทธิ ส่วนการเสียดสีและสัมผัสต้องมีการถ่ายโอนประจุโดยตรง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-electrification')), 'choice', 'วัตถุ A มีประจุ +3 ไมโครคูลอมบ์ วัตถุ B มีประจุ −5 ไมโครคูลอมบ์ นำทั้งสองมาสัมผัสกันแล้วแยกออกจากกัน แต่ละวัตถุจะมีประจุเท่าใด', '["+3 และ −5 ไมโครคูลอมบ์","+4 และ −4 ไมโครคูลอมบ์","−1 และ −1 ไมโครคูลอมบ์","0 และ −2 ไมโครคูลอมบ์"]', '2', 'เมื่อนำตัวนำสองอันมาสัมผัสกัน ประจุรวม = +3 + (−5) = −2 ไมโครคูลอมบ์ จะกระจายเท่าๆ กัน แล้วแต่ละอันได้ −1 ไมโครคูลอมบ์ ตามหลักการอนุรักษ์ประจุ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-electrification')), 'number', 'แท่งวัตถุหนึ่งสูญเสียอิเล็กตรอนไป ทำให้มีประจุสุทธิ 8 ไมโครคูลอมบ์ ถ้าประจุอิเล็กตรอนหนึ่งตัวคือ 1.6 คูณ 10 ยกกำลัง −19 คูลอมบ์ (เขียนเป็น 0.00000000000000000016 คูลอมบ์) จำนวนอิเล็กตรอนที่สูญเสียเป็นกี่ล้านล้านตัว (สูตร n = Q หารประจุต่อตัว ตอบเป็นจำนวนเต็ม)', NULL, '{"value":50,"tolerance":0.5}', 'n = Q/e = 0.000008/0.00000000000000000016 = 50000000000000 ตัว = 50 ล้านล้านตัว', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-electrification')), 'number', 'วัตถุ A มีประจุ +6 ไมโครคูลอมบ์ วัตถุ B ไม่มีประจุ นำ A สัมผัสกับ B แล้วแยกออกจากกัน A จะมีประจุกี่ไมโครคูลอมบ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'ประจุรวมก่อนสัมผัส = +6 ไมโครคูลอมบ์ เมื่อตัวนำเท่ากันสัมผัสกัน ประจุจะกระจายเท่าๆ กัน A จึงเหลือครึ่งหนึ่ง คือ 3 ไมโครคูลอมบ์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'electrostatics'), 'electrostatics-charge-motion-uniform-field', 'การเคลื่อนที่ของประจุในสนามไฟฟ้าสม่ำเสมอ', 'เมื่ออนุภาคมีประจุ q มวล m เคลื่อนที่เข้าไปในบริเวณสนามไฟฟ้าสม่ำเสมอ E จะเกิดแรงไฟฟ้ากระทำคงที่ขนาด F = qE ในทิศเดียวกับสนามสำหรับประจุบวก และทิศตรงข้ามสนามสำหรับประจุลบ แรงนี้ทำให้อนุภาคมีความเร่งคงที่ตามกฎการเคลื่อนที่ของนิวตัน a = F/m = qE/m หากอนุภาคถูกยิงทำมุมหรือตั้งฉากกับทิศของสนามไฟฟ้า เส้นทางการเคลื่อนที่ของอนุภาคจะมีลักษณะเป็นแนวโค้งพาราโบลาคล้ายกับการเคลื่อนที่แบบโพรเจกไทล์ภายใต้แรงโน้มถ่วง', 'senior', 6, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field'), 'youtube', 'https://www.youtube.com/watch?v=xM8_XG37xqY', 'xM8_XG37xqY', 'ฟิสิกส์ ม.5 บทที่ 13 ไฟฟ้าสถิต ep.5 (สนามไฟฟ้า)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field'), 'coulomb', 'จำลองแรงกระทำต่อประจุในสนามไฟฟ้าสม่ำเสมอ', '{"q1":{"min":1,"max":8,"default":2},"q2":{"min":1,"max":8,"default":6},"r":{"min":0.1,"max":0.8,"step":0.05,"default":0.4}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field'), 'match-circuit', 'ควบคุมกระแสขับเคลื่อนประจุในสนามไฟฟ้าให้แม่นยำ', '{"targetCurrent":[0.5,4.8],"tolerance":0.1,"voltage":{"min":2,"max":22,"default":14},"resistance":{"min":2,"max":18,"default":7}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field'), 'แบบทดสอบ: การเคลื่อนที่ของประจุในสนามไฟฟ้าสม่ำเสมอ', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field')), 'choice', 'โปรตอนวางนิ่งในสนามไฟฟ้าสม่ำเสมอ ทิศของแรงที่กระทำต่อโปรตอนเป็นอย่างไร', '["ทิศเดียวกับสนามไฟฟ้า","ทิศตรงข้ามกับสนามไฟฟ้า","ตั้งฉากกับสนามไฟฟ้า","ไม่มีแรงกระทำ"]', '0', 'F = qE โปรตอนมีประจุบวก จึงมีแรงทิศเดียวกับสนามไฟฟ้า ส่วนอิเล็กตรอน (ประจุลบ) จะได้แรงทิศตรงข้ามสนาม', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field')), 'choice', 'ประจุประจุหนึ่งเคลื่อนที่เข้าไปในสนามไฟฟ้าสม่ำเสมอในทิศตั้งฉากกับสนาม วิถีการเคลื่อนที่ของประจุจะเป็นแนวใด (ไม่คิดแรงโน้มถ่วง)', '["เส้นตรงแนวตั้งฉาก","เส้นโค้งคล้ายพาราโบลา","วงกลม","เส้นตรงแนวนอน"]', '1', 'ในทิศตั้งฉากกับสนามประจุไม่มีความเร่ง ส่วนทิศตามสนามมีแรงคงตัวและความเร่งคงที่ คล้ายการเคลื่อนที่แบบโพรเจกไทล์ จึงได้วิถีพาราโบลา', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field')), 'choice', 'ประจุประจุหนึ่งวางนิ่งอยู่ในสนามไฟฟ้าสม่ำเสมอ ความเร่งของประจุขึ้นกับปริมาณใด', '["มวลคูณสนาม (mE)","ระยะทางคูณสนาม","เฉพาะสนามไฟฟ้าเท่านั้น","ประจุคูณสนามหารด้วยมวล (qE/m)"]', '3', 'จาก F = qE = ma จะได้ความเร่ง a = qE/m จึงขึ้นกับขนาดประจุ ขนาดสนาม และมวลของประจุ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field')), 'number', 'ประจุ 3 ไมโครคูลอมบ์ วางในสนามไฟฟ้าสม่ำเสมอ 5000 นิวตัน/คูลอมบ์ แรงที่กระทำต่อประจุมีขนาดกี่นิวตัน (ตอบเป็นทศนิยม 3 ตำแหน่ง)', NULL, '{"value":0.015,"tolerance":0.005}', 'F = qE = 0.000003 × 5000 = 0.015 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'electrostatics-charge-motion-uniform-field')), 'number', 'สนามไฟฟ้าสม่ำเสมอ 1000 นิวตัน/คูลอมบ์ ประจุ 2 ไมโครคูลอมบ์ แรงที่กระทำต่อประจุมีขนาดกี่นิวตัน (ตอบเป็นทศนิยม 3 ตำแหน่ง)', NULL, '{"value":0.002,"tolerance":0.0005}', 'F = qE = 0.000002 × 1000 = 0.002 นิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'electrostatics'), 'electrostatics-electric-field', 'สนามไฟฟ้า', 'สนามไฟฟ้า (E) คือบริเวณที่ประจุไฟฟ้าส่งแรงไปกระทำต่อประจุทดสอบ นิยามจากแรงไฟฟ้าต่อหนึ่งหน่วยประจุทดสอบบวกตามสมการ E = F/q มีหน่วยเป็นนิวตันต่อคูลอมบ์ (N/C) หรือโวลต์ต่อเมตร (V/m) สำหรับสนามไฟฟ้าที่เกิดจากจุดประจุ Q ที่ระยะ r คำนวณได้จาก E = k*Q/r^2 เส้นแรงไฟฟ้าจะมีทิศพุ่งออกจากประจุบวกและพุ่งเข้าหาประจุลบ โดยความหนาแน่นของเส้นแรงไฟฟ้าจะสะท้อนถึงขนาดความเข้มของสนามไฟฟ้าในบริเวณนั้น', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'electrostatics-electric-field'), 'youtube', 'https://www.youtube.com/watch?v=J8Q9uyJaMNc', 'J8Q9uyJaMNc', 'ฟิสิกส์ ม.5 บทที่ 13 ไฟฟ้าสถิต ep.4 (สนามไฟฟ้า)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
