INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'equilibrium-translational'), 'แบบทดสอบ: สมดุลต่อการเลื่อนที่', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-translational')), 'choice', 'เงื่อนไขของสมดุลต่อการเลื่อนที่คือข้อใด', '["แรงลัพธ์เป็นศูนย์","ความเร็วเป็นศูนย์เสมอ","มีแรงโมเมนต์เท่านั้น","พลังงานเป็นศูนย์"]', '0', 'สมดุลต่อการเลื่อนที่หมายถึงแรงลัพธ์เป็นศูนย์ ความเร่งเป็นศูนย์ วัตถุจึงไม่เปลี่ยนความเร็ว', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-translational')), 'choice', 'วัตถุที่มีแรงลัพธ์เป็นศูนย์ จำเป็นต้องหยุดนิ่งหรือไม่', '["จำเป็นต้องหยุดนิ่ง","ไม่จำเป็น อาจเคลื่อนที่ด้วยความเร็วคงที่ได้","ต้องเคลื่อนที่ด้วยความเร่ง","ต้องหมุนอยู่เสมอ"]', '1', 'แรงลัพธ์ศูนย์ทำให้ความเร่งเป็นศูนย์ วัตถุอาจหยุดนิ่งหรือเคลื่อนที่ด้วยความเร็วคงที่ตามกฎข้อที่หนึ่งของนิวตัน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-translational')), 'choice', 'สมดุลกลทั้งหมดต้องมีเงื่อนไขสองข้อครบ ข้อใดคือทั้งสองเงื่อนไข', '["แรงลัพธ์เป็นศูนย์ และโมเมนต์รวมเป็นศูนย์","ความเร็วเป็นศูนย์ และไม่มีแรง","พลังงานจลน์คงที่ และพลังศักย์เท่ากัน","เวลาเป็นศูนย์ และระยะทางเป็นศูนย์"]', '0', 'สมดุลกลต้องมีทั้งสมดุลต่อการเลื่อนที่ (แรงลัพธ์ = 0) และสมดุลต่อการหมุน (โมเมนต์รวม = 0)', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-translational')), 'number', 'วัตถุมวล 10 กิโลกรัม แขวนนิ่งด้วยเชือกเส้นเดียว แรงตึงเชือกมีค่ากี่นิวตัน (ใช้ g = 10 เมตร/วินาที²)', NULL, '{"value":100,"tolerance":0.5}', 'วัตถุหยุดนิ่งแรงลัพธ์ศูนย์ แรงตึงเชือกเท่ากับน้ำหนัก T = mg = 10 × 10 = 100 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'equilibrium-translational')), 'number', 'กล่องมวล 5 กิโลกรัม วางนิ่งบนโต๊ะเรียบ แรงปฏิกิริยาตั้งฉากที่โต๊ะกระทำต่อกล่องมีค่ากี่นิวตัน (ใช้ g = 10 เมตร/วินาที²)', NULL, '{"value":50,"tolerance":0.5}', 'กล่องหยุดนิ่งในแนวตั้ง แรงปฏิกิริยาตั้งฉากเท่ากับน้ำหนัก N = mg = 5 × 10 = 50 นิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'friction'), 'friction-coefficient', 'สัมประสิทธิ์ความเสียดทาน', 'สัมประสิทธิ์ความเสียดทาน (μ) เป็นค่าไร้มิติที่บอกถึงความฝืดระหว่างคู่ผิวสัมผัส ขึ้นอยู่กับชนิดของวัสดุและสภาพพื้นผิว ไม่ขึ้นกับพื้นที่ผิวสัมผัส แรงเสียดทานคำนวณจาก f = μN โดย N คือแรงปฏิกิริยาตั้งฉาก การวัดสัมประสิทธิ์แรงเสียดทานสถิตทำได้โดยวางวัตถุบนพื้นเอียงแล้วค่อยๆ เพิ่มมุมจนวัตถุเริ่มไถล ซึ่งจะได้ μs = tan θ', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'friction-coefficient'), 'youtube', 'https://www.youtube.com/watch?v=fpEzjT5hi2Y', 'fpEzjT5hi2Y', 'ฟิสิกส์ ม.4 บทที่ 3 แรงและกฎการเคลื่อนที่ ep.8(แรงเสียดทานและเฉลยแบบฝึกหัด)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'friction-coefficient'), 'newton-force', 'ปรับเปลี่ยนค่าสัมประสิทธิ์แรงเสียดทานเพื่อสังเกตการเคลื่อนที่ของมวล', '{"force":{"min":10,"max":90,"default":50},"mass":{"min":2,"max":16,"default":5},"friction":{"min":0.05,"max":0.8,"step":0.05,"default":0.4}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'friction-coefficient'), 'balance-force', 'ประเมินผลของสัมประสิทธิ์แรงต้านเพื่อคำนวณความเร่งให้แม่นยำ', '{"targetAcc":[1.5,4.2],"tolerance":0.16,"force":{"min":22,"max":88,"default":48},"mass":{"min":2,"max":9,"default":4}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'friction-coefficient'), 'แบบทดสอบ: สัมประสิทธิ์ความเสียดทาน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'friction-coefficient')), 'choice', 'สัมประสิทธิ์ความเสียดทานมีนิยามตามข้อใด', '["แรงเสียดทานคูณกับแรงปฏิกิริยาตั้งฉาก","อัตราส่วนระหว่างแรงเสียดทานกับแรงปฏิกิริยาตั้งฉาก","น้ำหนักของวัตถุหารด้วยแรงเสียดทาน","ความเร่งของวัตถุคูณกับมวล"]', '1', 'สัมประสิทธิ์ความเสียดทาน μ = f/N คืออัตราส่วนระหว่างแรงเสียดทาน f กับแรงปฏิกิริยาตั้งฉาก N ของผิวสัมผัส', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'friction-coefficient')), 'choice', 'สัมประสิทธิ์ความเสียดทานมีหน่วยเป็นอะไร', '["นิวตัน","นิวตัน/เมตร","ไม่มีหน่วย","กิโลกรัม"]', '2', 'สัมประสิทธิ์ความเสียดทานเป็นอัตราส่วนระหว่างแรงกับแรง จึงไม่มีหน่วย เป็นเพียงค่าตัวเลขของผิวสัมผัสชนิดหนึ่ง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'friction-coefficient')), 'choice', 'ถ้าทำให้ผิวของวัตถุหนึ่งลื่นขึ้นจนสัมประสิทธิ์ความเสียดทานลดลงจากเดิมครึ่งหนึ่ง โดยแรงปฏิกิริยาตั้งฉากเท่าเดิม แรงเสียดทานจะเป็นอย่างไร', '["เพิ่มขึ้นเป็นสองเท่า","เท่าเดิม","ลดลงเป็นครึ่งหนึ่ง","เป็นศูนย์เสมอ"]', '2', 'จาก f = μN เมื่อ μ ลดลงครึ่งหนึ่ง และ N คงที่ แรงเสียดทาน f จึงลดลงเป็นครึ่งหนึ่งของเดิม', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'friction-coefficient')), 'number', 'วัตถุมวล 5 กิโลกรัม วางบนพื้นราบ ใช้แรงดึงจนเริ่มเคลื่อนที่พอดีได้ 20 นิวตัน สัมประสิทธิ์ความเสียดทานสถิตมีค่าเท่าใด (ใช้ g = 10 เมตร/วินาที² ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":0.4,"tolerance":0.05}', 'แรงปฏิกิริยาตั้งฉาก N = mg = 5 × 10 = 50 นิวตัน และแรงเสียดทานสถิตสูงสุด f = 20 นิวตัน ดังนั้น μ = f/N = 20/50 = 0.4', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'friction-coefficient')), 'number', 'วัตถุมวล 10 กิโลกรัม เคลื่อนที่ด้วยความเร็วคงที่บนพื้นราบ โดยมีแรงดึง 30 นิวตัน สัมประสิทธิ์ความเสียดทานจลน์มีค่าเท่าใด (ใช้ g = 10 เมตร/วินาที² ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":0.3,"tolerance":0.05}', 'เคลื่อนที่ด้วยความเร็วคงที่ แรงดึงเท่ากับแรงเสียดทานจลน์ คือ 30 นิวตัน และ N = 10 × 10 = 100 นิวตัน ดังนั้น μ = 30/100 = 0.3', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'friction'), 'friction-incline-calculation', 'การคำนวณแรงเสียดทานบนพื้นราบและพื้นเอียง', 'บนพื้นราบ แรงกดแนวฉากมีค่าเท่ากับน้ำหนัก N = mg ส่งผลให้แรงเสียดทานคือ f = μmg แต่บนพื้นเอียงทำมุม θ กับแนวราบ น้ำหนักจะแตกออกเป็น mg sin θ ขนานกับพื้นเอียง และ mg cos θ ตั้งฉากกับพื้นเอียง แรงกดแนวฉากจึงลดลงเหลือ N = mg cos θ ทำให้แรงเสียดทานบนพื้นเอียงมีค่าเป็น f = μ mg cos θ การคำนวณความเร่งต้องพิจารณาแรงลัพธ์ตามแนวเอียง ΣF = ma', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'friction-incline-calculation'), 'youtube', 'https://www.youtube.com/watch?v=snhN5avsrnE', 'snhN5avsrnE', 'ฟิสิกส์ ม.4 บทที่ 3 แรงและกฎการเคลื่อนที่ ep.7(โจทย์กฎการเคลื่อนที่ของนิวตัน, แรงเสียดทาน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'friction-incline-calculation'), 'youtube', 'https://www.youtube.com/watch?v=fpEzjT5hi2Y', 'fpEzjT5hi2Y', 'ฟิสิกส์ ม.4 บทที่ 3 แรงและกฎการเคลื่อนที่ ep.8(แรงเสียดทานและเฉลยแบบฝึกหัด)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'friction-incline-calculation'), 'newton-force', 'วิเคราะห์แรงตั้งฉากและแรงเสียดทานเมื่อมีแรงดึงบนระนาบเอียง', '{"force":{"min":15,"max":95,"default":58},"mass":{"min":2,"max":15,"default":6},"friction":{"min":0.1,"max":0.75,"step":0.05,"default":0.3}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'friction-incline-calculation'), 'balance-force', 'ปรับสมดุลแรงดึงต้านแรงเสียดทานระนาบเอียงให้ได้ความเร่งกำหนด', '{"targetAcc":[1.1,3.9],"tolerance":0.15,"force":{"min":24,"max":94,"default":50},"mass":{"min":2,"max":10,"default":6}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'friction-incline-calculation'), 'แบบทดสอบ: การคำนวณแรงเสียดทาน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'friction-incline-calculation')), 'choice', 'วัตถุวางอยู่บนพื้นเอียงมุม θ จากแนวระดับ ความสัมพันธ์ข้อใดถูกต้องเมื่อวัตถุเริ่มไถลลงพอดี', '["สัมประสิทธิ์ความเสียดทานเท่ากับ sin θ","แทนเจนต์ของมุมเท่ากับสัมประสิทธิ์ความเสียดทานสถิต หรือ tan θ = μs","สัมประสิทธิ์ความเสียดทานเท่ากับ cos θ","แรงเสียดทานเท่ากับน้ำหนักเสมอ"]', '1', 'เมื่อวัตถุเริ่มไถลพอดี แรงเสียดทานสถิตสูงสุดเท่ากับองค์ประกอบของน้ำหนักตามแนวเอียง โดย μs = tan θ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'friction-incline-calculation')), 'choice', 'บนพื้นเอียงมุม θ แรงปฏิกิริยาตั้งฉาก (N) ที่พื้นกระทำต่อวัตถุมวล m มีค่าเท่าใด', '["mg cos θ","mg sin θ","mg","mg tan θ"]', '0', 'บนพื้นเอียง แรงปฏิกิริยาตั้งฉากเท่ากับองค์ประกอบของน้ำหนักที่ตั้งฉากกับผิวนั่นคือ N = mg cos θ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'friction-incline-calculation')), 'choice', 'วัตถุเคลื่อนที่ด้วยความเร็วคงที่บนพื้นราบโดยมีแรงดึงแนวนอน แรงดึงเทียบกับแรงเสียดทานจลน์เป็นอย่างไร', '["แรงดึงมากกว่าแรงเสียดทานจลน์","แรงดึงน้อยกว่าแรงเสียดทานจลน์","แรงดึงเท่ากับแรงเสียดทานจลน์","ไม่แน่นอนขึ้นกับความเร็ว"]', '2', 'เคลื่อนที่ด้วยความเร็วคงที่แสดงว่าความเร่งเป็นศูนย์ แรงลัพธ์เป็นศูนย์ แรงดึงจึงเท่ากับแรงเสียดทานจลน์พอดี', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'friction-incline-calculation')), 'number', 'วัตถุวางบนพื้นเอียงมุม 37 องศา ซึ่ง sin 37° = 0.6 และ cos 37° = 0.8 ถ้าวัตถุเริ่มไถลลงพอดี สัมประสิทธิ์ความเสียดทานสถิตมีค่าเท่าใด (ตอบเป็นทศนิยม 2 ตำแหน่ง)', NULL, '{"value":0.75,"tolerance":0.005}', 'เมื่อเริ่มไถลพอดี μs = tan 37° = sin 37°/cos 37° = 0.6/0.8 = 0.75', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'friction-incline-calculation')), 'number', 'วัตถุมวล 4 กิโลกรัม เคลื่อนที่ด้วยความเร็วคงที่บนพื้นราบโดยมีแรงดึงแนวนอน 30 นิวตัน สัมประสิทธิ์ความเสียดทานจลน์มีค่าเท่าใด (ใช้ g = 10 เมตร/วินาที² ตอบเป็นทศนิยม 2 ตำแหน่ง)', NULL, '{"value":0.75,"tolerance":0.005}', 'ความเร็วคงที่ แรงดึงเท่ากับแรงเสียดทานจลน์ 30 นิวตัน และ N = 4 × 10 = 40 นิวตัน ดังนั้น μ = 30/40 = 0.75', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'friction'), 'friction-static-kinetic', 'แรงเสียดทานสถิตและจลน์', 'แรงเสียดทานเป็นแรงต้านการเคลื่อนที่ที่เกิดขึ้นที่ผิวสัมผัส แรงเสียดทานสถิต (fs) เกิดขึ้นเมื่อวัตถุยังไม่เคลื่อนที่ มีค่าตั้งแต่ศูนย์จนถึงค่าสูงสุด fs(max) = μs N เมื่อวัตถุเริ่มไถล แรงต้านจะเปลี่ยนเป็นแรงเสียดทานจลน์ (fk) ซึ่งมีค่าคงที่ fk = μk N โดยทั่วไปสัมประสิทธิ์ความเสียดทานสถิตจะมากกว่าสัมประสิทธิ์ความเสียดทานจลน์ (μs > μk) เสมอ', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'friction-static-kinetic'), 'youtube', 'https://www.youtube.com/watch?v=fpEzjT5hi2Y', 'fpEzjT5hi2Y', 'ฟิสิกส์ ม.4 บทที่ 3 แรงและกฎการเคลื่อนที่ ep.8(แรงเสียดทานและเฉลยแบบฝึกหัด)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
