INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'friction-static-kinetic'), 'แบบทดสอบ: แรงเสียดทานสถิตและจลน์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'friction-static-kinetic')), 'choice', 'วัตถุวางนิ่งบนพื้น เราใช้แรงดึงในแนวนอนเล็กน้อย วัตถุยังไม่เคลื่อนที่ เนื่องจากมีแรงใดต้านแรงดึงเอาไว้', '["แรงเสียดทานสถิต","แรงเสียดทานจลน์","แรงโน้มถ่วงของโลก","แรงแม่เหล็กจากพื้น"]', '0', 'เมื่อวัตถุยังไม่เคลื่อนที่ แรงต้านการเคลื่อนที่คือแรงเสียดทานสถิต ซึ่งมีค่าเท่ากับแรงดึงพอดีจนกว่าแรงดึงจะเกินค่าสูงสุด', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'friction-static-kinetic')), 'choice', 'เมื่อวัตถุกำลังเคลื่อนที่บนพื้น แรงเสียดทานจลน์ที่กระทำต่อวัตถุมีทิศทางใด', '["ตามทิศทางการเคลื่อนที่ของวัตถุ","ตรงข้ามกับทิศทางการเคลื่อนที่ของวัตถุ","ตั้งฉากกับพื้นผิว","พุ่งเข้าหาจุดศูนย์กลางของโลก"]', '1', 'แรงเสียดทานจลน์มีทิศตรงข้ามกับทิศทางการเคลื่อนที่ของวัตถุเสมอ โดยเกิดจากการสัมผัสระหว่างผิวทั้งสอง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'friction-static-kinetic')), 'choice', 'วัตถุชนิดเดียวกันบนพื้นเดียวกัน ให้แรงปฏิกิริยาตั้งฉาก (พื้น) เท่ากัน ข้อใดถูกต้อง', '["แรงเสียดทานสถิตสูงสุดเท่ากับแรงเสียดทานจลน์","แรงเสียดทานสถิตสูงสุดน้อยกว่าแรงเสียดทานจลน์","แรงเสียดทานสถิตสูงสุดมากกว่าแรงเสียดทานจลน์","ค่าเท่ากันเมื่อความเร็วมากพอ"]', '2', 'โดยทั่วไปแรงเสียดทานสถิตสูงสุดมีค่ามากกว่าแรงเสียดทานจลน์ เพราะต้องใช้แรงมากกว่าจึงจะทำให้วัตถุเริ่มเคลื่อนที่ได้', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'friction-static-kinetic')), 'number', 'วัตถุมวล 6 กิโลกรัม วางนิ่งบนพื้นราบ ใช้แรง 15 นิวตัน ดึงในแนวนอน วัตถุยังไม่เคลื่อนที่ แรงเสียดทานสถิตในขณะนั้นมีค่ากี่นิวตัน', NULL, '{"value":15,"tolerance":0.5}', 'วัตถุยังไม่เคลื่อนที่ แรงลัพธ์ในแนวนอนเป็นศูนย์ แรงเสียดทานสถิตจึงเท่ากับแรงดึงพอดี คือ 15 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'friction-static-kinetic')), 'number', 'ใช้แรง 40 นิวตัน ดึงวัตถุมวล 5 กิโลกรัม บนพื้นราบ วัตถุเคลื่อนที่ด้วยความเร่ง 4 เมตร/วินาที² แรงเสียดทานจลน์มีค่ากี่นิวตัน', NULL, '{"value":20,"tolerance":0.5}', 'จากกฎข้อที่สอง แรงลัพธ์ = ma = 5 × 4 = 20 นิวตัน และแรงลัพธ์ = 40 − แรงเสียดทานจลน์ ดังนั้นแรงเสียดทานจลน์ = 40 − 20 = 20 นิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'oscillation-gravity'), 'gravitation-newton-law', 'กฎความโน้มถ่วงสากล', 'กฎความโน้มถ่วงสากลของนิวตันระบุว่า วัตถุทุกคู่ในเอกภพจะดึงดูดซึ่งกันและกันด้วยแรงที่แปรผันตรงกับผลคูณของมวลทั้งสอง และแปรผกผันกับกำลังสองของระยะห่างระหว่างจุดศูนย์กลางมวล คำนวณได้จาก Fg = G(m1 m2)/r² โดย G คือค่าคงตัวโน้มถ่วงสากล (6.67 × 10^-11 N·m²/kg²) แรงนี้เป็นแรงดึงดูดร่วมกันระหว่างสองวัตถุตามกฎข้อที่สามของนิวตัน', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'gravitation-newton-law'), 'youtube', 'https://www.youtube.com/watch?v=GXADPm6XCAU', 'GXADPm6XCAU', 'ฟิสิกส์ ม.4 บทที่ 3 แรงและกฎการเคลื่อนที่ ep.9(กฎแรงดึงดูดระหว่างมวล, แรงโน้มถ่วง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'gravitation-newton-law'), 'circular-shm', 'จำลองการโคจรรอบศูนย์กลางมวลภายใต้แรงโน้มถ่วงดึงดูด', '{"mass":{"min":1,"max":10,"step":0.5,"default":4},"radius":{"min":0.8,"max":4,"step":0.5,"default":2.2},"springK":{"min":16,"max":80,"step":4,"default":48}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'gravitation-newton-law'), 'balance-force', 'คำนวณแรงดึงดูดโน้มถ่วงระหว่างมวลเพื่อสร้างความเร่งตามเกณฑ์', '{"targetAcc":[1.1,4.1],"tolerance":0.16,"force":{"min":16,"max":86,"default":38},"mass":{"min":2,"max":10,"default":6}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'gravitation-newton-law'), 'แบบทดสอบ: กฎความโน้มถ่วงสากล', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'gravitation-newton-law')), 'choice', 'แรงโน้มถ่วงระหว่างมวล m₁ และ m₂ ห่างกัน r มีขนาดตามข้อใด', '["F = G m₁ m₂ / r²","F = G m₁ m₂ r²","F = G r² / (m₁ m₂)","F = G m₁ m₂ / r"]', '0', 'กฎความโน้มถ่วงสากล F = Gm₁m₂/r² แรงแปรผกผันกับกำลังสองของระยะห่าง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'gravitation-newton-law')), 'choice', 'ทิศทางของแรงโน้มถ่วงระหว่างวัตถุสองก้อนเป็นอย่างไร', '["ผลักกันเสมอ","ดึงดูดกันเสมอ","ผลักหรือดึงขึ้นกับชนิดมวล","ไม่มีแรงระหว่างวัตถุใดๆ"]', '1', 'แรงโน้มถ่วงเป็นแรงดึงดูดระหว่างมวลเสมอ ไม่มีแรงผลักโน้มถ่วง ทิศเข้าหากัน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'gravitation-newton-law')), 'choice', 'ถ้าเพิ่มระยะห่างระหว่างมวลสองก้อนเป็น 2 เท่า แรงโน้มถ่วงเปลี่ยนเป็นกี่เท่าของเดิม', '["2 เท่า","4 เท่า","1/4 เท่า","1/2 เท่า"]', '2', 'F แปรผกผันกับ r² เมื่อ r เป็น 2 เท่า F จึงเป็น 1/4 เท่า', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'gravitation-newton-law')), 'number', 'วัตถุมวล 5 กิโลกรัม วางบนผิวโลก แรงโน้มถ่วงที่โลกกระทำต่อวัตถุมีค่ากี่นิวตัน (ใช้ g = 10 เมตร/วินาที²)', NULL, '{"value":50,"tolerance":0.5}', 'แรงโน้มถ่วงที่ผิวโลกเท่ากับน้ำหนักของวัตถุ F = mg = 5 × 10 = 50 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'gravitation-newton-law')), 'number', 'วัตถุมวล 3 กิโลกรัม วางบนผิวโลก แรงโน้มถ่วงที่โลกกระทำต่อวัตถุมีค่ากี่นิวตัน (ใช้ g = 10 เมตร/วินาที²)', NULL, '{"value":30,"tolerance":0.5}', 'F = mg = 3 × 10 = 30 นิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'oscillation-gravity'), 'gravitation-satellite-field', 'สนามโน้มถ่วงและดาวเทียม', 'สนามโน้มถ่วง (g) ณ ระยะห่าง r จากจุดศูนย์กลางดาวเคราะห์มีค่าเท่ากับ g = GM/r² สำหรับดาวเทียมที่โคจรรอบดาวเคราะห์ แรงดึงดูดโน้มถ่วงทำหน้าที่เป็นแรงสู่ศูนย์กลาง GMm/r² = mv²/r ทำให้อัตราเร็วในการโคจรคือ v = √(GM/r) ดาวเทียมค้างฟ้า (Geostationary Satellite) มีคาบการโคจรเท่ากับ 24 ชั่วโมง เท่ากับการหมุนรอบตัวเองของโลก จึงปรากฏหยุดนิ่งเทียบกับพื้นโลก', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'gravitation-satellite-field'), 'youtube', 'https://www.youtube.com/watch?v=2Ly9CpgEjGw', '2Ly9CpgEjGw', '4.3 การหาความเร็วหลุดพ้นและการโคจรของดาวเทียม บทที่ 4 เทคโนโลยีอวกาศ', 'Physic_krujee', 'https://www.youtube.com/channel/UCjoQl1oTKyPl6eF2-kOI2Pw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'gravitation-satellite-field'), 'youtube', 'https://www.youtube.com/watch?v=GXADPm6XCAU', 'GXADPm6XCAU', 'ฟิสิกส์ ม.4 บทที่ 3 แรงและกฎการเคลื่อนที่ ep.9(กฎแรงดึงดูดระหว่างมวล, แรงโน้มถ่วง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'gravitation-satellite-field'), 'circular-shm', 'จำลองวงโคจรของดาวเทียมรอบดาวเคราะห์ด้วยความเร็วโคจรคงตัว', '{"mass":{"min":0.5,"max":10,"step":0.5,"default":3},"radius":{"min":1,"max":4,"step":0.5,"default":2.8},"springK":{"min":10,"max":70,"step":4,"default":32}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'gravitation-satellite-field'), 'balance-force', 'ปรับแรงโน้มถ่วงและมวลดาวเทียมให้ได้ความเร่งเข้าสู่ศูนย์กลางตามเป้า', '{"targetAcc":[1.3,4.5],"tolerance":0.15,"force":{"min":20,"max":94,"default":48},"mass":{"min":2,"max":10,"default":5}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'gravitation-satellite-field'), 'แบบทดสอบ: สนามโน้มถ่วงและดาวเทียม', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'gravitation-satellite-field')), 'choice', 'ความเร็วของดาวเทียมที่โคจรรอบดาวเคราะห์ ขึ้นกับปริมาณใด', '["มวลของดาวเทียม","มวลของดาวเคราะห์และระยะวงโคจรเท่านั้น ไม่ขึ้นกับมวลดาวเทียม","สีของดาวเทียม","ขนาดพื้นที่ของดาวเทียม"]', '1', 'ความเร็วโคจร v = √(GM/r) ขึ้นกับมวลดาวเคราะห์ M และรัศมีวงโคจร r ไม่ขึ้นกับมวลดาวเทียม', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'gravitation-satellite-field')), 'choice', 'การที่ดาวเทียมโคจรรอบโลกเป็นวงกลมโดยไม่หลุดออก เกิดจากสมดุลของแรงใด', '["แรงโน้มถ่วงทำหน้าที่เป็นแรงสู่ศูนย์กลาง","แรงแม่เหล็กของโลก","ไม่มีแรงใดกระทำ","แรงดันอากาศของบรรยากาศ"]', '0', 'แรงโน้มถ่วงของโลกทำหน้าที่เป็นแรงสู่ศูนย์กลาง mv²/r = GMm/r² ทำให้ดาวเทียมโคจรเป็นวงกลม', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'gravitation-satellite-field')), 'choice', 'ถ้าวัตถุอยู่สูงขึ้นจากผิวโลก สนามโน้มถ่วง g จะเป็นอย่างไร', '["มีค่าลดลง","มีค่าเพิ่มขึ้น","คงที่เดิม","เป็นศูนย์เสมอทันที"]', '0', 'g = GM/r² เมื่ออยู่สูงขึ้น r ใหญ่ขึ้น สนามโน้มถ่วงจึงลดลงตามกำลังสองของระยะทาง', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'gravitation-satellite-field')), 'number', 'วัตถุมวล 5 กิโลกรัม อยู่ในที่ที่มีสนามโน้มถ่วง 10 นิวตัน/กิโลกรัม แรงโน้มถ่วงที่กระทำต่อวัตถุมีค่ากี่นิวตัน', NULL, '{"value":50,"tolerance":0.5}', 'แรงโน้มถ่วง F = mg = 5 × 10 = 50 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'gravitation-satellite-field')), 'number', 'ดาวเคราะห์ B มีสนามโน้มถ่วงที่ผิวดาวเคราะห์เป็น 1/4 ของโลก และมีรัศมีเท่ากับโลก ดาวเคราะห์ B มีมวลเป็นกี่เท่าของโลก (ตอบเป็นทศนิยม 2 ตำแหน่ง)', NULL, '{"value":0.25,"tolerance":0.005}', 'g = GM/r² เมื่อรัศมีเท่ากัน g แปรผันตรงกับมวล ถ้า g เป็น 1/4 มวลจึงเป็น 1/4 = 0.25 เท่าของโลก', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'induction-ac'), 'induction-ac-ac-rms', 'ไฟฟ้ากระแสสลับและค่า rms', 'ไฟฟ้ากระแสสลับ (AC) มีแรงดันและกระแสไฟฟ้าเปลี่ยนแปลงค่าตามเวลาในรูปของฟังก์ชันไซน์ v(t) = V_max*sin(omega*t) ค่าประสิทธิผลหรือค่า rms (Root Mean Square) คือค่าแรงดันหรือกระแสคงที่ที่ให้ผลความร้อนเทียบเท่ากับไฟฟ้ากระแสตรง สำหรับสัญญาณรูปไซน์ ค่า rms คำนวณได้จาก V_rms = V_max/sqrt(2) หรือประมาณ 0.707*V_max และ I_rms = I_max/sqrt(2) ไฟฟ้าตามบ้านในประเทศไทยที่ระบุ 220 โวลต์จึงหมายถึงค่า V_rms โดยมีแรงดันสูงสุดจริง V_max ประมาณ 311 โวลต์', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-ac-rms'), 'youtube', 'https://www.youtube.com/watch?v=OjGkTmnvZmk', 'OjGkTmnvZmk', 'ฟิสิกส์ ม.6 บทที่ 15 แม่เหล็กและไฟฟ้า ep.7(ไฟฟ้ากระแสสลับ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-ac-rms'), 'magnetic-induction', 'วิเคราะห์รูปคลื่นไซน์และค่าประสิทธิผลของไฟฟ้ากระแสสลับ', '{"bField":{"min":0.4,"max":2,"step":0.1,"default":1.2},"speed":{"min":3,"max":20,"step":1,"default":15}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-ac-rms'), 'quantum-lab', 'ควบคุมความถี่เพื่อปรับเทียบค่า rms ของกระแสสลับ', '{"targetEk":[1,3.2],"workFunction":2.4,"tolerance":0.15,"frequency":{"min":5.5,"max":16,"step":0.2,"default":9}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-ac-rms'), 'แบบทดสอบ: ไฟฟ้ากระแสสลับและค่า rms', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-ac-rms')), 'choice', 'ค่า rms ของแรงดันไฟฟ้ากระแสสลับ มีความหมายตรงกับข้อใด', '["ค่าแรงดันที่ให้กำลังเฉลี่ยเท่ากับกระแสตรง","ค่าแรงดันเป็นศูนย์","ค่าเฉลี่ยเลขคณิตของแรงดัน","ค่าแรงดันสูงสุดในครึ่งรอบ"]', '0', 'ค่า rms (ค่าประสิทธิผล) คือค่าแรงดันกระแสตรงที่ให้กำลังเฉลี่ยเท่ากัน ความสัมพันธ์ V_rms = V_max/√2 เพราะกำลังแปรผันกับกำลังสองของแรงดัน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-ac-rms')), 'choice', 'ค่าแรงดันสูงสุด V_max กับค่า rms V_rms ของกระแสสลับไซน์ มีความสัมพันธ์กันอย่างไร', '["V_rms = V_max × √2","V_rms = V_max/√2","V_max = 2V_rms","V_max = V_rms"]', '1', 'สำหรับคลื่นไซน์ V_rms = V_max/√2 ดังนั้นค่า rms จึงน้อยกว่าค่าแรงดันสูงสุดประมาณ 0.707 เท่า', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-ac-rms')), 'choice', 'แรงดันไฟฟ้า 220 โวลต์ ที่ใช้ในบ้าน เป็นค่าแบบใด', '["ค่าแรงดันทันที ณ เวลาใดเวลาหนึ่ง","ค่าแรงดันสูงสุด","ค่า rms","ค่าเฉลี่ย"]', '2', 'แรงดันไฟบ้าน 220 โวลต์เป็นค่า rms (ค่าประสิทธิผล) ซึ่งเครื่องวัดไฟฟ้าทั่วไปอ่านค่า rms ส่วนค่าแรงดันสูงสุดจริงคือ 220×√2 ≈ 311 โวลต์', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-ac-rms')), 'number', 'แรงดันไฟฟ้ากระแสสลับมีค่าสูงสุด 311 โวลต์ ค่า rms ของแรงดันนี้เท่ากับกี่โวลต์ (ใช้ √2 ≈ 1.414 ตอบเป็นจำนวนเต็ม)', NULL, '{"value":220,"tolerance":0.5}', 'V_rms = V_max/√2 = 311/1.414 ≈ 220 โวลต์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-ac-rms')), 'number', 'ค่ากระแส rms ในวงจรคือ 5 แอมแปร์ ค่ากระแสสูงสุดของกระแสสลับไซน์เท่ากับกี่แอมแปร์ (ใช้ √2 ≈ 1.41 ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":7.1,"tolerance":0.05}', 'I_max = I_rms × √2 = 5 × 1.41 = 7.05 ≈ 7.1 แอมแปร์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'induction-ac'), 'induction-ac-faraday-flux', 'ฟลักซ์แม่เหล็กและกฎของฟาราเดย์', 'ฟลักซ์แม่เหล็ก (Phi) คือผลคูณเชิงสเกลาร์ระหว่างสนามแม่เหล็ก B กับพื้นที่ตั้งฉาก A ตามสมการ Phi = B*A*cos(theta) มีหน่วยเป็นเวเบอร์ (Wb) กฎการเหนี่ยวนำของฟาราเดย์ระบุว่า เมื่อฟลักซ์แม่เหล็กที่ผ่านวงปิดเกิดการเปลี่ยนแปลงตามเวลา จะทำให้เกิดแรงเคลื่อนไฟฟ้าเหนี่ยวนำ (emf หรือ epsilon) ขึ้นในวงจรตามสมการ epsilon = -N*(delta_Phi/delta_t) โดย N คือจำนวนรอบของขดลวด ปรากฏการณ์นี้เป็นหัวใจสำคัญในการสร้างเครื่องกำเนิดไฟฟ้าหรือไดนาโม', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux'), 'youtube', 'https://www.youtube.com/watch?v=7bqyfKKZrnk', '7bqyfKKZrnk', 'ฟิสิกส์ ม.6 บทที่ 15 แม่เหล็กและไฟฟ้า ep.5 (แรงเคลื่อนไฟฟ้าเหนี่ยวนำ,emf, กระแสเหนี่ยวนำและหม้อแปลง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux'), 'magnetic-induction', 'จำลองฟลักซ์แม่เหล็กและแรงเคลื่อนไฟฟ้าเหนี่ยวนำฟาราเดย์', '{"bField":{"min":0.3,"max":2,"step":0.1,"default":1},"speed":{"min":3,"max":18,"step":1,"default":11}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux'), 'quantum-lab', 'ปรับจูนอัตราเปลี่ยนฟลักซ์เพื่อสร้างพลังงานไฟฟ้าเป้าหมาย', '{"targetEk":[0.8,3],"workFunction":2.2,"tolerance":0.15,"frequency":{"min":5,"max":15,"step":0.2,"default":8}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux'), 'แบบทดสอบ: ฟลักซ์แม่เหล็กและกฎของฟาราเดย์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux')), 'choice', 'ฟลักซ์แม่เหล็กที่ผ่านขดลวดที่มีพื้นที่ A ในสนามแม่เหล็กสม่ำเสมอ B ที่ตั้งฉากกับพื้นที่ หาได้จากสูตรใด', '["Φ = BA","Φ = A/B","Φ = ½BA²","Φ = B/A"]', '0', 'ฟลักซ์แม่เหล็ก Φ = B·A·cos θ เมื่อสนามตั้งฉากกับพื้นที่ θ = 0 องศา cos θ = 1 จึง Φ = BA หน่วยเวเบอร์', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux')), 'choice', 'กฎของฟาราเดย์กล่าวว่าอะไร ทำให้เกิดแรงเคลื่อนไฟฟ้าเหนี่ยวนำในขดลวด', '["การมีกระแสไหลผ่านขดลวด","การเปลี่ยนแปลงของฟลักซ์แม่เหล็กที่ผ่านขดลวด","อุณหภูมิของขดลวดเพิ่มขึ้น","ความต้านทานของขดลวดน้อยลง"]', '1', 'แรงเคลื่อนไฟฟ้าเหนี่ยวนำ (emf) เกิดเมื่อฟลักซ์แม่เหล็กที่ผ่านขดลวดเปลี่ยนไปตามเวลาตามกฎ faraday emf = −NΔΦ/Δt ไม่ใช่เกิดจากกระแสคงที่', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux')), 'choice', 'ถ้าเพิ่มจำนวนรอบของขดลวดเป็น 2 เท่า โดยอัตราการเปลี่ยนแปลงฟลักซ์คงที่ แรงเคลื่อนไฟฟ้าเหนี่ยวนำจะเป็นกี่เท่า', '["1/2 เท่า","4 เท่า","เท่าเดิม","2 เท่า"]', '3', 'emf = −NΔΦ/Δt แรงเคลื่อนไฟฟ้าเหนี่ยวนำแปรผันตรงกับจำนวนรอบ N เมื่อ N เป็น 2 เท่า emf จึงเป็น 2 เท่า', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux')), 'number', 'ขดลวด 100 รอบ มีฟลักซ์แม่เหล็กเปลี่ยนจาก 0.02 เวเบอร์ เป็น 0.08 เวเบอร์ ในเวลา 0.5 วินาที แรงเคลื่อนไฟฟ้าเหนี่ยวนำเฉลี่ยเท่ากับกี่โวลต์ (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":12,"tolerance":0.05}', 'emf = NΔΦ/Δt = 100 × (0.08 − 0.02)/0.5 = 100 × 0.06/0.5 = 100 × 0.12 = 12 โวลต์ (ใช้ขนาด ไม่ใส่เครื่องหมายลบ)', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-faraday-flux')), 'number', 'ขดลวด 200 รอบ มีฟลักซ์ผ่านลดลงจาก 0.05 เวเบอร์ เป็น 0.01 เวเบอร์ ในเวลา 0.4 วินาที แรงเคลื่อนไฟฟ้าเหนี่ยวนำเฉลี่ยเท่ากับกี่โวลต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', 'emf = NΔΦ/Δt = 200 × (0.05 − 0.01)/0.4 = 200 × 0.04/0.4 = 200 × 0.1 = 20 โวลต์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'induction-ac'), 'induction-ac-lenz-law', 'กฎของเลนซ์', 'กฎของเลนซ์กล่าวว่า กระแสไฟฟ้าเหนี่ยวนำที่เกิดขึ้นในขดลวดจะมีทิศทางไปสร้างสนามแม่เหล็กใหม่เพื่อต่อต้านการเปลี่ยนแปลงของฟลักซ์แม่เหล็กเดิมที่ทำให้เกิดมัน เครื่องหมายลบในกฎของฟาราเดย์ epsilon = -N*(delta_Phi/delta_t) จึงเป็นตัวแทนทางคณิตศาสตร์ของกฎของเลนซ์ กฎนี้สอดคล้องกับกฎการอนุรักษ์พลังงานอย่างสมบูรณ์ เพราะต้องมีงานทางกลเข้าไปต้านแรงแม่เหล็กเพื่อเปลี่ยนรูปเป็นพลังงานไฟฟ้า และยังอธิบายปรากฏการณ์กระแสวน (Eddy Current) และระบบเบรกแม่เหล็ก', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-lenz-law'), 'youtube', 'https://www.youtube.com/watch?v=7bqyfKKZrnk', '7bqyfKKZrnk', 'ฟิสิกส์ ม.6 บทที่ 15 แม่เหล็กและไฟฟ้า ep.5 (แรงเคลื่อนไฟฟ้าเหนี่ยวนำ,emf, กระแสเหนี่ยวนำและหม้อแปลง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-lenz-law'), 'magnetic-induction', 'จำลองทิศทางของกระแสเหนี่ยวนำตามกฎของเลนซ์', '{"bField":{"min":0.2,"max":1.8,"step":0.1,"default":0.7},"speed":{"min":2,"max":16,"step":1,"default":8}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-lenz-law'), 'quantum-lab', 'ทดลองต้านการเปลี่ยนแปลงสนามแม่เหล็กในห้องปฏิบัติการ', '{"targetEk":[0.9,2.7],"workFunction":2,"tolerance":0.15,"frequency":{"min":4.5,"max":14.5,"step":0.2,"default":7.5}}');
