INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-lenz-law')), 'choice', 'กฎของเลนซ์ใช้กำหนดอะไร', '["ทิศทางของกระแสเหนี่ยวนำ","ขนาดของมวล","ความเร็วของแสง","ขนาดของความต้านทาน"]', '0', 'กฎของเลนซ์กำหนดทิศทางของกระแสเหนี่ยวนำและแรงเคลื่อนไฟฟ้าเหนี่ยวนำ โดยกระแสเหนี่ยวนำจะมีทิศต้านการเปลี่ยนแปลงของฟลักซ์ที่ทำให้เกิดมัน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-lenz-law')), 'choice', 'เมื่อแท่งแม่เหล็กขั้วเหนือเคลื่อนเข้าหาขดลวด กระแสเหนี่ยวนำในขดลวดจะสร้างขั้วแม่เหล็กอย่างไรที่ด้านใกล้แท่ง', '["ไม่มีขั้ว","สลับไปสลับมา","ขั้วเหนือ","ขั้วใต้"]', '2', 'เพื่อทำงานต้านการเข้าใกล้ของขั้วเหนือ กระแสเหนี่ยวนำจะสร้างขั้วเหนือที่ด้านใกล้แท่ง (ขั้วเหมือนกันผลักกัน) ตามกฎของเลนซ์ที่ว่ากระแสตอบโต้การเปลี่ยนแปลงฟลักซ์', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-lenz-law')), 'choice', 'กฎของเลนซ์สอดคล้องกับหลักการอนุรักษ์พลังงานอย่างไร', '["พลังงานถูกทำลาย","ไม่เกี่ยวข้องกับพลังงาน","กระแสเหนี่ยวนำสร้างพลังงานจากความว่างเปล่า","พลังงานที่ใช้ถูกรักษาไว้โดยงานต้านแรงแม่เหล็ก"]', '3', 'กระแสเหนี่ยวนำที่ต้านการเปลี่ยนแปลงฟลักซ์ทำให้ต้องทำงานต้านแรงแม่เหล็ก ซึ่งพลังงานส่วนนี้คือพลังงานที่ถูกเปลี่ยน ถ้ากระแสไม่ต้าน พลังงานก็จะถูกสร้างจากสิ่งไม่มีที่มา ละเมิดการอนุรักษ์พลังงาน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-lenz-law')), 'number', 'ขดลวดมีฟลักซ์แม่เหล็กเพิ่มขึ้น 0.3 เวเบอร์ ในเวลา 0.2 วินาที ขดลวดมี 50 รอบ แรงเคลื่อนไฟฟ้าเหนี่ยวนำเฉลี่ยเท่ากับกี่โวลต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":75,"tolerance":0.5}', 'emf = NΔΦ/Δt = 50 × 0.3/0.2 = 50 × 1.5 = 75 โวลต์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-lenz-law')), 'number', 'วงจรหนึ่งมีฟลักซ์แม่เหล็กลดลง 0.4 เวเบอร์ ในเวลา 0.4 วินาที ทำให้เกิดแรงเคลื่อนไฟฟ้าเหนี่ยวนำ 20 โวลต์ จำนวนรอบของขดลวดเท่ากับกี่รอบ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', 'N = emf×Δt/ΔΦ = 20 × 0.4/0.4 = 20 รอบ', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'induction-ac'), 'induction-ac-transformer', 'หม้อแปลง', 'หม้อแปลงไฟฟ้าเป็นอุปกรณ์ที่ใช้เปลี่ยนระดับความต่างศักย์ไฟฟ้ากระแสสลับ ทำงานโดยอาศัยการเหนี่ยวนำร่วมระหว่างขดลวดปฐมภูมิ (N1) และขดลวดทุติยภูมิ (N2) พันอยู่บนแกนเหล็กเดียวกัน ความสัมพันธ์ของแรงดันไฟฟ้าสอดคล้องกับสมการ V1/V2 = N1/N2 หากไม่มีการสูญเสียพลังงาน กำลังไฟฟ้าขาเข้าจะเท่ากับกำลังไฟฟ้าขาออก P1 = P2 ทำให้ V1*I1 = V2*I2 ดังนั้นหม้อแปลงที่เพิ่มแรงดันจะทำให้กระแสลดลง ซึ่งช่วยลดการสูญเสียพลังงานความร้อนในสายส่งระยะไกล', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-transformer'), 'youtube', 'https://www.youtube.com/watch?v=P6hSs4q9wzk', 'P6hSs4q9wzk', 'ฟิสิกส์ ม.6 บทที่ 15 แม่เหล็กและไฟฟ้า ep.6(หม้อแปลงไฟฟ้า)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-transformer'), 'magnetic-induction', 'จำลองอัตราส่วนรอบและการแปลงแรงดันในหม้อแปลงไฟฟ้า', '{"bField":{"min":0.3,"max":1.9,"step":0.1,"default":0.8},"speed":{"min":2,"max":18,"step":1,"default":12}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-transformer'), 'quantum-lab', 'ปรับแต่งระดับพลังงานไฟฟ้าตามอัตราส่วนการแปลงของหม้อแปลง', '{"targetEk":[0.7,3.1],"workFunction":2.1,"tolerance":0.15,"frequency":{"min":4.8,"max":15.2,"step":0.2,"default":8.2}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'induction-ac-transformer'), 'แบบทดสอบ: หม้อแปลง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-transformer')), 'choice', 'หม้อแปลงทำงานได้กับไฟฟ้าชนิดใด', '["กระแสตรงเท่านั้น","กระแสสลับเท่านั้น","ทั้งกระแสตรงและสลับ","ไม่ใช้ไฟฟ้า"]', '1', 'หม้อแปลงต้องอาศัยฟลักซ์แม่เหล็กที่เปลี่ยนแปลงตามเวลา จึงทำงานด้วยไฟฟ้ากระแสสลับ กระแสตรงให้ฟลักซ์คงที่จึงเกิดการเหนี่ยวนำไม่ได้', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-transformer')), 'choice', 'ในหม้อแปลงอุดมคติ อัตราส่วนของแรงดันขาออกต่อขาเข้า เท่ากับอัตราส่วนของอะไร', '["ความต้านทานขดปฐมภูมิ","ความยาวของแกนเหล็ก","จำนวนรอบขดทุติยภูมิต่อขดปฐมภูมิ","จำนวนรอบขดปฐมภูมิต่อทุติยภูมิ"]', '2', 'V₂/V₁ = N₂/N₁ แรงดันแปรผันตรงกับจำนวนรอบ ดังนั้นหม้อแปลงเพิ่มแรงดัน (step-up) จึงมีรอบขดทุติยภูมิมากกว่าปฐมภูมิ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-transformer')), 'choice', 'หม้อแปลงอุดมคติที่มีกำลังไฟฟ้าขาเข้าเท่ากับขาออก ถ้าแรงดันเพิ่มขึ้นเป็น 10 เท่า กระแสจะเปลี่ยนอย่างไร', '["เท่าเดิม","กลายเป็นศูนย์","เพิ่มขึ้น 10 เท่า","ลดลง 10 เท่า"]', '3', 'กำลัง P = VI คงที่ในหม้อแปลงอุดมคติ ถ้า V เพิ่ม 10 เท่า I ต้องลดลง 10 เท่า เพื่อให้ผลคูณ VI คงที่ นี่คือหลักการส่งไฟฟ้าแรงสูงเพื่อลดกระแสและความสูญเสีย', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-transformer')), 'number', 'หม้อแปลงมีขดปฐมภูมิ 400 รอบ ขดทุติยภูมิ 2000 รอบ ต่อแรงดันปฐมภูมิ 220 โวลต์ แรงดันขาออกที่ขดทุติยภูมิเท่ากับกี่โวลต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":1100,"tolerance":0.5}', 'V₂ = V₁ × N₂/N₁ = 220 × 2000/400 = 220 × 5 = 1100 โวลต์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'induction-ac-transformer')), 'number', 'หม้อแปลงอุดมคติขดปฐมภูมิแรงดัน 220 โวลต์ กระแส 5 แอมแปร์ ขดทุติยภูมิแรงดัน 1100 โวลต์ กระแสที่ขดทุติยภูมิเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":1,"tolerance":0.5}', 'กำลังคงที่: V₁I₁ = V₂I₂ → I₂ = V₁I₁/V₂ = 220×5/1100 = 1100/1100 = 1 แอมแปร์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-electricity'), 'jr-electricity-circuits', 'วงจรไฟฟ้า', 'วงจรไฟฟ้าอย่างง่ายประกอบด้วยแหล่งกำเนิดไฟฟ้า สายไฟ สวิตช์ และโหลดหรือเครื่องใช้ไฟฟ้า การต่อหลอดไฟหรือตัวต้านทานทำได้สองวิธีหลัก คือการต่อแบบอนุกรมและขนาน ในการต่อแบบอนุกรม กระแสไฟฟ้าจะไหลผ่านหลอดไฟทางเดียวเท่ากันหมด ถ้าหลอดหนึ่งดับ หลอดอื่นจะดับไปด้วย ส่วนการต่อแบบขนาน แต่ละหลอดจะได้ความต่างศักย์เท่ากับแหล่งกำเนิด V_total = V1 = V2 ถ้าหลอดหนึ่งดับ หลอดอื่นยังคงสว่างได้ตามปกติ', 'junior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits'), 'youtube', 'https://www.youtube.com/watch?v=jtpSa88iihg', 'jtpSa88iihg', 'วงจรไฟฟ้าแบบอนุกรม (วิทยาศาสตร์ ม. 3 เล่ม 2 หน่วยที่ 6 บทที่ 1 วงจรไฟฟ้าอย่างง่าย)', 'Proj14 ม.3', 'https://www.youtube.com/channel/UCEDTSRW-0iUxL_45MR3ESPg', 1);
