INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits'), 'ohm-law', 'สำรวจวงจรไฟฟ้าพื้นฐานแบบอนุกรมและขนาน', '{"voltage":{"min":1.5,"max":18,"default":6},"resistance":{"min":2,"max":20,"default":6}}');
