INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits'), 'แบบทดสอบ: วงจรไฟฟ้า', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits')), 'choice', 'วงจรไฟฟ้าที่สมบูรณ์ต้องประกอบด้วยอะไร', '["แหล่งพลังงาน ตัวนำ สายไฟ และอุปกรณ์ไฟฟ้า ต่อเป็นวงปิด","แหล่งพลังงานเท่านั้น","เฉพาะสายไฟ","แบตเตอรี่และสวิตช์เท่านั้น"]', '0', 'วงจรไฟฟ้าสมบูรณ์ต้องมีแหล่งพลังงาน สายไฟ อุปกรณ์ใช้ไฟ และสวิตช์ ต่อกันเป็นวงปิดให้กระแสไหลครบวงจร', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits')), 'choice', 'ในวงจรอนุกรม ถ้าหลอดไฟหลอดหนึ่งขาด หลอดอื่นจะเป็นอย่างไร', '["สว่างมากขึ้น","ไม่เปลี่ยนแปลง","สว่างเท่าเดิม","ดับทั้งหมด เพราะกระแสไหลผ่านทีละหลอด"]', '3', 'วงจรอนุกรมกระแสไหลผ่านหลอดทีละหลอดต่อเนื่องกัน ถ้าหลอดหนึ่งขาดวงจรขาด กระแสไหลไม่ได้ หลอดทั้งหมดจึงดับ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits')), 'choice', 'ข้อใดกล่าวถูกต้องเกี่ยวกับวงจรขนาน', '["กระแสไหลผ่านหลอดเดียวเท่านั้น","ถ้าหลอดหนึ่งขาด หลอดอื่นยังติดอยู่ เพราะแต่ละเส้นทางเป็นอิสระต่อกัน","หลอดทุกหลอดต้องติดหรือดับพร้อมกันเสมอ","วงจรขนานใช้กับแบตเตอรี่ไม่ได้"]', '1', 'วงจรขนานแต่ละเส้นทางเป็นอิสระต่อกัน หลอดหนึ่งขาดจึงไม่ตัดวงจรของหลอดอื่น', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits')), 'number', 'กระแสไฟฟ้าในวงจรอนุกรมมีค่า 2 แอมแปร์ กระแสที่ไหลผ่านหลอดแต่ละหลอดในวงจรนี้เท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'ในวงจรอนุกรมกระแสมีค่าเท่ากันทุกจุด จึงไหลผ่านหลอดแต่ละหลอดเท่ากับ 2 แอมแปร์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-circuits')), 'number', 'วงจรขนานมีกระแสรวม 6 แอมแปร์ แบ่งไหลผ่านหลอดสองเส้นทางเท่ากัน กระแสในแต่ละเส้นทางเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'กระแสรวมแบ่งไปตามเส้นทาง 6 ÷ 2 = 3 แอมแปร์ในแต่ละเส้นทาง', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-electricity'), 'jr-electricity-current-voltage-resistance', 'กระแส ความต่างศักย์ ความต้านทาน', 'ในวงจรไฟฟ้าพื้นฐาน กระแสไฟฟ้า (I) วัดอัตราการไหลของประจุผ่านสายไฟ มีหน่วยเป็นแอมแปร์ (A) แรงดันหรือความต่างศักย์ (V) คือแรงผลักดันที่ทำให้ประจุไฟฟ้าเคลื่อนที่ผ่านวงจร มีหน่วยเป็นโวลต์ (V) และความต้านทาน (R) คือความยากง่ายที่วัสดุขัดขวางการไหลของกระแส มีหน่วยเป็นโอห์ม ตัวนำไฟฟ้าที่ดีจะมีค่าความต้านทานต่ำ ส่วนฉนวนไฟฟ้าจะมีค่าความต้านทานสูงมาก ทำให้กระแสไม่สามารถไหลผ่านได้', 'junior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-electricity-current-voltage-resistance'), 'youtube', 'https://www.youtube.com/watch?v=26FxaMirYnI', '26FxaMirYnI', 'ความสัมพันธ์ระหว่างกระแสไฟฟ้าและความต่างศักย์ไฟฟ้า (วิทยาศาสตร์ ม. 3 เล่ม 2 หน่วยที่ 6 บทที่ 1)', 'Proj14 ม.3', 'https://www.youtube.com/channel/UCEDTSRW-0iUxL_45MR3ESPg', 1);
