INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-ohms-law')), 'choice', 'กฎของโอห์มกล่าวว่าอย่างไร', '["V = I + R","กระแสแปรผกผันกับความต่างศักย์","กระแสไฟฟ้าแปรผันตรงกับความต่างศักย์และแปรผกผันกับความต้านทาน","ความต้านทานเท่ากับกระแสคูณโวลต์"]', '2', 'กฎของโอห์มกล่าวว่าเมื่ออุณหภูมิคงที่ กระแสแปรผันตรงกับความต่างศักย์และแปรผกผันกับความต้านทาน คือ V = IR', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-ohms-law')), 'choice', 'ถ้าความต่างศักย์คงที่แต่เพิ่มความต้านทาน กระแสไฟฟ้าจะเป็นอย่างไร', '["ลดลง","เพิ่มขึ้น","เท่าเดิม","เพิ่มขึ้นเป็นสองเท่า"]', '0', 'จาก I = V / R เมื่อ V คงที่และ R มากขึ้น กระแสจะลดลง ความต้านทานมากขัดขวางกระแสมาก', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-ohms-law')), 'choice', 'หลอดไฟต่อกับแบตเตอรี่ 6 โวลต์ กระแสไหลผ่านหลอด 2 แอมแปร์ ความต้านทานของหลอดเท่ากับกี่โอห์ม', '["12 โอห์ม","3 โอห์ม","8 โอห์ม","4 โอห์ม"]', '1', 'R = V / I = 6 ÷ 2 = 3 โอห์ม', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-ohms-law')), 'number', 'แบตเตอรี่ 12 โวลต์ต่อกับตัวต้านทาน 4 โอห์ม กระแสไฟฟ้าในวงจรเท่ากับกี่แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'I = V / R = 12 ÷ 4 = 3 แอมแปร์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-ohms-law')), 'number', 'กระแส 0.5 แอมแปร์ไหลผ่านตัวต้านทาน 10 โอห์ม ความต่างศักย์คร่อมตัวต้านทานเท่ากับกี่โวลต์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":5,"tolerance":0.5}', 'V = IR = 0.5 × 10 = 5 โวลต์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-electricity'), 'jr-electricity-static-intro', 'ไฟฟ้าสถิตเบื้องต้น', 'ไฟฟ้าสถิตเกิดจากการสะสมของประจุไฟฟ้าบนผิววัตถุเนื่องจากการเสียดสีกัน โดยอิเล็กตรอนจะถ่ายโอนจากวัตถุหนึ่งไปยังอีกวัตถุหนึ่ง วัตถุที่สูญเสียอิเล็กตรอนจะมีประจุบวก ส่วนวัตถุที่ได้รับอิเล็กตรอนจะมีประจุลบ ประจุชนิดเดียวกันจะออกแรงผลักกัน ขณะที่ประจุต่างชนิดกันจะดูดกันตามกฎของคูลอมบ์ F = k*q1*q2/r^2 ปรากฏการณ์นี้สามารถพบเห็นได้ง่ายในชีวิตประจำวัน เช่น ฟ้าแลบ ฟ้าร้อง หรือไฟฟ้าสถิตเมื่อหวีผมในสภาพอากาศแห้ง', 'junior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-electricity-static-intro'), 'youtube', 'https://www.youtube.com/watch?v=jNLjs8pooV8', 'jNLjs8pooV8', 'I know PHYSICS ep.16 - ไฟฟ้าสถิต (Part 1 : พฤติกรรมของประจุไฟฟ้า)', 'I know PHYSICs a little', 'https://www.youtube.com/channel/UC0qWWV4YLpxnAQGJ8ednXlA', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-electricity-static-intro'), 'coulomb', 'สำรวจแรงผลักและแรงดูดของประจุไฟฟ้าสถิตเบื้องต้น', '{"q1":{"min":1,"max":6,"default":2},"q2":{"min":1,"max":6,"default":3},"r":{"min":0.15,"max":0.8,"step":0.05,"default":0.3}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-electricity-static-intro'), 'match-circuit', 'เกมปรับวงจรจำลองการถ่ายโอนประจุไฟฟ้าสถิต', '{"targetCurrent":[0.5,3],"tolerance":0.1,"voltage":{"min":1,"max":15,"default":6},"resistance":{"min":2,"max":15,"default":5}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-electricity-static-intro'), 'แบบทดสอบ: ไฟฟ้าสถิตเบื้องต้น', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-static-intro')), 'choice', 'เมื่อนำหวีพลาสติกถูกับผ้าขนสัตว์แล้วนำไปใกล้กระดาษชิ้นเล็กๆ กระดาษถูกดูดติดเพราะเหตุใด', '["หวีร้อนขึ้นจนกระดาษติด","หวีกลายเป็นแม่เหล็กถาวร","กระดาษมีแม่เหล็กในตัว","หวีมีประจุไฟฟ้าจากการขัดสี จึงดูดวัตถุอื่นได้"]', '3', 'การถูทำให้เกิดประจุไฟฟ้าสถิตบนหวี หวีที่ประจุไฟฟ้าจึงดูดชิ้นกระดาษเล็กๆ ได้', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-static-intro')), 'choice', 'ประจุไฟฟ้าชนิดเดียวกันสองก้อนวางใกล้กัน จะเกิดอะไร', '["ดูดกัน","ผลักกัน","ไม่ทำปฏิกิริยากัน","ดูดกันที่ระยะไกลและผลักกันที่ระยะใกล้"]', '1', 'ประจุชนิดเดียวกัน (บวกกับบวก หรือลบกับลบ) จะผลักกัน ส่วนประจุต่างชนิดกันจะดูดกัน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-static-intro')), 'choice', 'ประจุบวกกับประจุลบวางใกล้กัน จะเกิดพฤติกรรมใด', '["ผลักกัน","ไม่ทำปฏิกิริยากัน","ดูดกัน","ผลักแล้วดูดสลับกัน"]', '2', 'ประจุต่างชนิดกันคือประจุบวกกับประจุลบ จะดูดเข้าหากัน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-static-intro')), 'number', 'นำประจุ +3 หน่วยมารวมกับประจุ −5 หน่วย ประจุสุทธิทั้งหมดเป็นเท่าใด (ตอบเป็นตัวเลขพร้อมเครื่องหมายถ้าเป็นลบ)', NULL, '{"value":-2,"tolerance":0.5}', 'ประจุสุทธิ = 3 + (−5) = −2 หน่วย', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-electricity-static-intro')), 'number', 'นำประจุ +4 หน่วยมารวมกับประจุ −4 หน่วย ประจุสุทธิทั้งหมดเป็นเท่าใด (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":0,"tolerance":0.5}', 'ประจุสุทธิ = 4 + (−4) = 0 หน่วย ประจุบวกลบทักล้างกันพอดี', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-forces-motion'), 'jr-forces-motion-acceleration', 'ความเร่ง', 'ความเร่งคืออัตราการเปลี่ยนแปลงความเร็วของวัตถุในหนึ่งหน่วยเวลา มีหน่วยเป็นเมตรต่อวินาที² (m/s²) คำนวณได้จากสูตร a = (v - u)/t เมื่อความเร็วเพิ่มขึ้น ความเร่งจะมีค่าเป็นบวก เมื่อความเร็วลดลง ความเร่งจะมีค่าเป็นลบซึ่งเรียกว่าความหน่วง หากวัตถุเคลื่อนที่ด้วยความเร็วสม่ำเสมอ ความเร่งจะมีค่าเป็นศูนย์', 'junior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-forces-motion-acceleration'), 'youtube', 'https://www.youtube.com/watch?v=geABdJ7qpaM', 'geABdJ7qpaM', 'สอนศาสตร์ ฟิสิกส์ ม.ต้น | พี่ลูกตาล : การเคลื่อนที่ ตอนที่ 2', 'TruePlookpanya Channel', 'https://www.youtube.com/channel/UCjj4VB9nW0zN5reBS0cIf6A', 1);
