INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-forces-motion-acceleration'), 'newton-force', 'สังเกตการเพิ่มขึ้นของความเร็วต่อวินาทีเมื่อมีแรงลัพธ์กระทำ', '{"force":{"min":15,"max":90,"default":45},"mass":{"min":1,"max":15,"default":4},"friction":{"min":0,"max":0.5,"step":0.05,"default":0.1}}');
