INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-force-effects')), 'choice', 'หน่วยของแรงในระบบเอสไอคือข้อใด', '["กิโลกรัม","นิวตัน","จูล","เมตรต่อวินาทีกำลังสอง"]', '1', 'แรงมีหน่วยเป็นนิวตัน ส่วนกิโลกรัมเป็นหน่วยมวล และจูลเป็นหน่วยงาน จึงไม่ใช่หน่วยแรง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-force-effects')), 'choice', 'ข้อใดเป็นผลของแรงที่กระทำต่อวัตถุ', '["ทำให้มวลของวัตถุเปลี่ยนไป","ทำให้อุณหภูมิของวัตถุเปลี่ยน","ทำให้ความเร็วเปลี่ยนหรือเปลี่ยนรูปร่าง","ทำให้ตำแหน่งอ้างอิงเปลี่ยน"]', '2', 'แรงทำให้วัตถุเปลี่ยนความเร็ว (เริ่มเคลื่อนที่ หยุด หรือเปลี่ยนทิศ) หรือเปลี่ยนรูปร่าง แต่มวลและอุณหภูมิไม่เปลี่ยนเพราะแรง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-force-effects')), 'choice', 'แรงขนาด 10 นิวตันดันกล่องไปทางขวา เมื่อใช้แรงเท่าเดิมดันไปทางซ้าย ผลที่เกิดกับกล่องต่างจากเดิมเพราะเหตุใด', '["ขนาดของแรงต่างกัน","มวลของกล่องต่างกัน","เวลาในการออกแรงไม่ลงตัว","ทิศทางของแรงต่างกัน"]', '3', 'แรงเป็นปริมาณเวกเตอร์ ขนาดเท่ากันแต่ทิศทางต่างกันย่อมให้ผลต่างกัน กล่องจะเคลื่อนที่คนละทิศ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-force-effects')), 'number', 'ออกแรงผลักกล่องมวล 2 กิโลกรัมให้มีความเร่ง 3 เมตร/วินาที² ต้องใช้แรงเท่าใด (ตอบเป็นนิวตัน จำนวนเต็ม)', NULL, '{"value":6,"tolerance":0.5}', 'F = ma = 2 x 3 = 6 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-force-effects')), 'number', 'ถ้าออกแรง 20 นิวตันแล้วกล่องมีความเร่ง 10 เมตร/วินาที² มวลของกล่องเป็นเท่าใด (ตอบเป็นกิโลกรัม จำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'm = F/a = 20 / 10 = 2 กิโลกรัม', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-forces-motion'), 'jr-forces-motion-friction', 'แรงเสียดทาน', 'แรงเสียดทานเป็นแรงที่เกิดขึ้นระหว่างผิวสัมผัสของวัตถุสองชิ้นในทิศตรงข้ามกับการเคลื่อนที่หรือแนวโน้มที่จะเคลื่อนที่ ขนาดของแรงเสียดทานขึ้นอยู่กับน้ำหนักกดทับและความขรุขระของผิวสัมผัส แต่ไม่ขึ้นกับขนาดของพื้นที่ผิวสัมผัส แรงเสียดทานมีทั้งประโยชน์ เช่น ช่วยให้เราเดินได้โดยไม่ลื่นไถล และข้อเสีย เช่น ทำให้เครื่องจักรเกิดการสึกหรอและสูญเสียพลังงาน', 'junior', 6, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction'), 'youtube', 'https://www.youtube.com/watch?v=FV6qJPnBjEU', 'FV6qJPnBjEU', 'สอนศาสตร์ ฟิสิกส์ ม.ต้น | พี่ลูกตาล : แรงในชีวิตประจำวัน ตอนที่ 1', 'TruePlookpanya Channel', 'https://www.youtube.com/channel/UCjj4VB9nW0zN5reBS0cIf6A', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction'), 'youtube', 'https://www.youtube.com/watch?v=OOMb6NAJ0IA', 'OOMb6NAJ0IA', 'สอนศาสตร์ ฟิสิกส์ ม.ต้น | พี่ลูกตาล : แรงในชีวิตประจำวัน ตอนที่ 2', 'TruePlookpanya Channel', 'https://www.youtube.com/channel/UCjj4VB9nW0zN5reBS0cIf6A', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction'), 'newton-force', 'ศึกษาแรงเสียดทานระหว่างผิวสัมผัสที่ต้านการเคลื่อนที่ของวัตถุ', '{"force":{"min":15,"max":90,"default":48},"mass":{"min":1,"max":15,"default":5},"friction":{"min":0.1,"max":0.8,"step":0.05,"default":0.35}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction'), 'balance-force', 'เอาชนะแรงเสียดทานของพื้นผิวเพื่อเร่งมวลให้เข้าเกณฑ์เป้าหมาย', '{"targetAcc":[1.4,4.6],"tolerance":0.16,"force":{"min":22,"max":90,"default":48},"mass":{"min":2,"max":9,"default":4}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction'), 'แบบทดสอบ: แรงเสียดทาน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction')), 'choice', 'แรงเสียดทานมีทิศทางใดเมื่อเทียบกับการเคลื่อนที่ของวัตถุ', '["เดียวกับทิศการเคลื่อนที่","ตั้งฉากกับการเคลื่อนที่","ไม่มีทิศทางที่แน่นอน","ตรงข้ามกับทิศการเคลื่อนที่"]', '3', 'แรงเสียดทานต้านการเคลื่อนที่ จึงมีทิศตรงข้ามกับทิศการเคลื่อนที่ของวัตถุ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction')), 'choice', 'ข้อใดทำให้แรงเสียดทานมีค่ามากขึ้น', '["ผิวสัมผัสขรุขระมากขึ้น","ทำให้วัตถุหนักน้อยลง","ลดแรงกดของวัตถุต่อพื้น","ทำให้ผิวสัมผัสลื่นขึ้น"]', '0', 'แรงเสียดทานเพิ่มขึ้นเมื่อผิวขรุขระหรือแรงกดตั้งฉากมากขึ้น การทำให้ลื่นหรือเบาลงจะลดแรงเสียดทาน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction')), 'choice', 'เมื่อผลักกล่องบนพื้นขรุขระ แรงเสียดทานกระทำต่อกล่องอย่างไร', '["ช่วยผลักกล่องไปข้างหน้า","ต้านการไถลของกล่อง","เพิ่มความเร็วให้กล่อง","ไม่มีผลต่อการเคลื่อนที่"]', '1', 'แรงเสียดทานต้านการไถลของกล่อง ทำให้กล่องเคลื่อนที่ช้าลง ไม่ใช่ช่วยผลัก', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction')), 'number', 'มีแรงขับ 14 นิวตันไปข้างหน้า ขณะที่แรงเสียดทาน 6 นิวตันต้าน แรงลัพธ์มีขนาดเท่าใด (ตอบเป็นนิวตัน จำนวนเต็ม)', NULL, '{"value":8,"tolerance":0.5}', 'แรงเสียดทานตรงข้ามกับแรงขับ แรงลัพธ์ = 14 - 6 = 8 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-friction')), 'number', 'มีแรงขับ 20 นิวตันและแรงเสียดทาน 5 นิวตัน กล่องมวล 5 กิโลกรัมมีความเร่งเท่าใด (ตอบเป็นเมตร/วินาที² จำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'แรงลัพธ์ = 20 - 5 = 15 นิวตัน แล้ว a = F/m = 15 / 5 = 3 เมตร/วินาที²', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-forces-motion'), 'jr-forces-motion-net-force', 'แรงลัพธ์และการรวมแรง', 'แรงลัพธ์คือผลรวมของแรงหลายแรงที่กระทำต่อวัตถุเดียวกัน หากมีแรงสองแรงกระทำในทิศทางเดียวกัน แรงลัพธ์จะเท่ากับผลบวกของแรงทั้งสอง หากกระทำในทิศทางตรงกันข้าม แรงลัพธ์จะเท่ากับผลต่างของแรงทั้งสองและมีทิศไปทางแรงที่มากกว่า หากแรงลัพธ์รวมกันได้ศูนย์ วัตถุจะรักษาสภาพการเคลื่อนที่เดิมไว้ตามหลักสมดุล', 'junior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
