INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-net-force')), 'choice', 'แรง 5 นิวตันกับ 3 นิวตันกระทำทิศเดียวกัน แรงลัพธ์มีขนาดเท่าใด', '["8 นิวตัน","2 นิวตัน","15 นิวตัน","5 นิวตัน"]', '0', 'แรงไปทางเดียวกันบวกกัน = 5 + 3 = 8 นิวตัน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-net-force')), 'choice', 'แรง 7 นิวตันไปทางขวากับแรง 3 นิวตันไปทางซ้าย แรงลัพธ์มีขนาดและทิศทางใด', '["10 นิวตันไปทางขวา","4 นิวตันไปทางขวา","4 นิวตันไปทางซ้าย","10 นิวตันไปทางซ้าย"]', '1', 'แรงตรงข้ามกันหักล้าง = 7 - 3 = 4 นิวตัน ไปทางข้างที่มีแรงมากกว่าคือทางขวา', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-net-force')), 'choice', 'แรงลัพธ์เป็นศูนย์หมายความว่าอย่างไร', '["ไม่มีแรงใดกระทำต่อวัตถุเลย","วัตถุเคลื่อนที่เร็วขึ้นเสมอ","แรงที่กระทำรวมกันแล้วหักล้างหมดพอดี","มวลของวัตถุเป็นศูนย์"]', '2', 'แรงลัพธ์เป็นศูนย์ หมายความว่าทุกแรงรวมกันแล้วหักล้างหมดพอดี ไม่ใช่ว่าไม่มีแรงกระทำ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-net-force')), 'number', 'แรงสองแรงขนาด 12 นิวตันและ 8 นิวตันไปแนวเดียวกันและทิศเดียวกัน แรงลัพธ์มีขนาดเท่าใด (ตอบเป็นนิวตัน จำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', 'แรงทิศเดียวกันบวกกัน = 12 + 8 = 20 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-net-force')), 'number', 'แรง 15 นิวตันไปทางขวากับแรง 6 นิวตันไปทางซ้าย แรงลัพธ์มีขนาดเท่าใด (ตอบเป็นนิวตัน จำนวนเต็ม)', NULL, '{"value":9,"tolerance":0.5}', 'แรงตรงข้ามหักล้าง = 15 - 6 = 9 นิวตัน ไปทางขวา', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-forces-motion'), 'jr-forces-motion-position-displacement', 'ตำแหน่ง ระยะทาง และการกระจัด', 'ตำแหน่งคือจุดที่วัตถุอยู่โดยระบุเทียบกับจุดอ้างอิง ระยะทางคือความยาวทั้งหมดตามเส้นทางที่วัตถุเคลื่อนที่จริง เป็นปริมาณสเกลาร์ ส่วนการกระจัดคือระยะห่างในแนวเส้นตรงจากจุดเริ่มต้นไปยังจุดสุดท้ายพร้อมระบุทิศทาง เป็นปริมาณเวกเตอร์ หากเดินวนรอบสนามหนึ่งรอบแล้วกลับมาที่เดิม ระยะทางจะเท่ากับความยาวรอบสนาม แต่การกระจัดจะเป็นศูนย์', 'junior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
