INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-position-displacement')), 'choice', 'ข้อใดคือความหมายของการกระจัด', '["ระยะตรงจากจุดเริ่มต้นถึงจุดสุดท้ายพร้อมบอกทิศทาง","ความยาวรวมของเส้นทางที่เดินจริงทั้งหมด","ระยะทางหารด้วยเวลา","ระยะห่างจากจุดเริ่มต้นเพียงอย่างเดียว"]', '0', 'การกระจัดคือระยะทางในแนวตรงจากจุดเริ่มต้นถึงจุดสุดท้ายพร้อมทิศทาง ไม่ใช่ความยาวรวมของเส้นทางที่เดิน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-position-displacement')), 'choice', 'ถ้าเดินจากบ้านไปร้านด้วยระยะทาง 100 เมตร แล้วเดินกลับมาบ้านทางเดิม การกระจัดมีค่าเท่าใด', '["100 เมตร","0 เมตร","200 เมตร","50 เมตร"]', '1', 'การกระจัดวัดจากจุดเริ่มต้นถึงจุดสุดท้าย ซึ่งก็คือบ้านทั้งสองครั้ง จึงเป็น 0 เมตร ส่วนระยะทางรวมเป็น 200 เมตร', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-position-displacement')), 'choice', 'ข้อใดคือหน่วยของระยะทางในระบบเอสไอ', '["เมตรต่อวินาที","วินาที","เมตร","กิโลกรัม"]', '2', 'ระยะทางวัดความยาวของเส้นทาง จึงใช้หน่วยเมตรในระบบเอสไอ ไม่ใช้เมตรต่อวินาทีซึ่งเป็นหน่วยความเร็ว', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-position-displacement')), 'number', 'เดินจากจุด A ไปทางขวา 7 เมตร แล้วเดินต่อทางขวาอีก 5 เมตร การกระจัดจาก A มีค่าเท่าใด (ตอบเป็นเมตร จำนวนเต็ม)', NULL, '{"value":12,"tolerance":0.5}', 'การกระจัด = 7 + 5 = 12 เมตร เพราะเดินไปทางเดียวกันจึงบวกกันตรงๆ', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-position-displacement')), 'number', 'เดินออกจากจุดเริ่มต้นไปทางทิศเหนือ 4 เมตร แล้วย้อนกลับมาทางทิศใต้ 4 เมตร ระยะทางที่เดินทั้งหมดมีค่าเท่าใด (ตอบเป็นเมตร จำนวนเต็ม)', NULL, '{"value":8,"tolerance":0.5}', 'ระยะทางคือความยาวเส้นทางที่เดินจริงรวมกัน จึงเป็น 4 + 4 = 8 เมตร (ส่วนการกระจัดเป็น 0 เมตร)', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-forces-motion'), 'jr-forces-motion-speed-velocity', 'อัตราเร็วและความเร็ว', 'อัตราเร็วคือระยะทางที่วัตถุเคลื่อนที่ได้ในหนึ่งหน่วยเวลา คำนวณจาก v = s/t เป็นปริมาณสเกลาร์ที่บอกเพียงความเร็วช้า ส่วนความเร็วคือการกระจัดที่เปลี่ยนแปลงไปในหนึ่งหน่วยเวลา คำนวณจาก v = s เวกเตอร์ / t เป็นปริมาณเวกเตอร์ที่มีทั้งขนาดและทิศทาง หน่วยมาตรฐานสากลของทั้งสองปริมาณคือเมตรต่อวินาที (m/s)', 'junior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-forces-motion-speed-velocity'), 'youtube', 'https://www.youtube.com/watch?v=8I6ZBdtvaZc', '8I6ZBdtvaZc', 'สอนศาสตร์ ฟิสิกส์ ม.ต้น | พี่ลูกตาล : การเคลื่อนที่ ตอนที่ 1', 'TruePlookpanya Channel', 'https://www.youtube.com/channel/UCjj4VB9nW0zN5reBS0cIf6A', 1);
