INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-speed-velocity')), 'choice', 'ข้อใดบอกความต่างระหว่างอัตราเร็วกับความเร็วได้ถูกต้อง', '["อัตราเร็วมีหน่วยต่างจากความเร็ว","ความเร็วระบุทิศทาง แต่อัตราเร็วไม่ระบุทิศทาง","อัตราเร็วมีค่ามากกว่าความเร็วเสมอ","อัตราเร็วคือการกระจัดต่อเวลา"]', '3', 'ความเร็วเป็นปริมาณที่มีทิศทาง ส่วนอัตราเร็วมีเพียงขนาดและไม่มีทิศทาง อัตราเร็วคือ ระยะทาง/เวลา ไม่ใช่การกระจัด/เวลา', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-speed-velocity')), 'choice', 'วิ่งรอบสนามวงกลมครบ 1 รอบกลับมาที่จุดเริ่มต้น อัตราเร็วเฉลี่ยและความเร็วเฉลี่ยเป็นอย่างไร', '["อัตราเร็วเฉลี่ยมากกว่า 0 แต่ความเร็วเฉลี่ยเป็น 0","ทั้งอัตราเร็วเฉลี่ยและความเร็วเฉลี่ยเป็น 0","ทั้งสองมีค่ามากกว่า 0","อัตราเร็วเฉลี่ยเป็น 0 แต่ความเร็วเฉลี่ยมากกว่า 0"]', '0', 'กลับมาที่จุดเริ่มต้น การกระจัดรวมเป็น 0 ความเร็วเฉลี่ยจึงเป็น 0 แต่ระยะทางรวมมากกว่า 0 อัตราเร็วเฉลี่ยจึงมากกว่า 0', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-speed-velocity')), 'choice', 'หน่วยของความเร็วในระบบเอสไอคือข้อใด', '["เมตร","เมตรต่อวินาที","เมตรต่อวินาทีกำลังสอง","วินาทีต่อเมตร"]', '1', 'ความเร็วคือการกระจัดต่อเวลา จึงมีหน่วยเป็นเมตร/วินาที ไม่ใช่เมตร/วินาที² ซึ่งเป็นหน่วยความเร่ง', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-speed-velocity')), 'number', 'รถวิ่งได้ระยะทาง 120 เมตรในเวลา 30 วินาที อัตราเร็วเฉลี่ยเป็นเท่าใด (ตอบเป็นเมตร/วินาที จำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 'อัตราเร็วเฉลี่ย = ระยะทาง / เวลา = 120 / 30 = 4 เมตร/วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-forces-motion-speed-velocity')), 'number', 'คนวิ่งได้การกระจัด 300 เมตรในเวลา 100 วินาที ความเร็วเฉลี่ยเป็นเท่าใด (ตอบเป็นเมตร/วินาที จำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'ความเร็วเฉลี่ย = การกระจัด / เวลา = 300 / 100 = 3 เมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-heat'), 'jr-heat-expansion-thermal-equilibrium', 'การขยายตัวและสมดุลความร้อน', 'เมื่อวัตถุได้รับความร้อน อนุภาคจะเคลื่อนที่และสั่นเร็วขึ้นทำให้เกิดการขยายตัวทางความร้อนตามความสัมพันธ์ ΔL = α L0 ΔT สำหรับของแข็ง และการขยายปริมาตรในแก๊สตามกฎของชาร์ล V/T = ค่าคงตัว เมื่อนำวัตถุสองชิ้นที่มีอุณหภูมิต่างกันมาสัมผัสกัน จะเกิดการถ่ายโอนความร้อนจนกระทั่งอุณหภูมิเท่ากัน เรียกว่าเกิดสมดุลความร้อน โดยความร้อนที่วัตถุหนึ่งสูญเสียจะเท่ากับความร้อนที่อีกวัตถุหนึ่งได้รับพอดี (Qลด = Qเพิ่ม)', 'junior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-heat-expansion-thermal-equilibrium'), 'youtube', 'https://www.youtube.com/watch?v=A9VG9_DdjiY', 'A9VG9_DdjiY', 'ความร้อนกับการขยายหรือหดตัวของสสาร  (วิทยาศาสตร์ ม. 1 เล่ม 2 หน่วยที่ 5 บทที่ 1)', 'Proj14 ม.1', 'https://www.youtube.com/channel/UCK4CGaln7bIajKzTAd0fLZg', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-heat-expansion-thermal-equilibrium'), 'youtube', 'https://www.youtube.com/watch?v=hURTArGYv6s', 'hURTArGYv6s', 'สมดุลความร้อน (วิทยาศาสตร์ ม. 1 เล่ม 2 หน่วยที่ 5 บทที่ 2 สมดุลความร้อน)', 'Proj14 ม.1', 'https://www.youtube.com/channel/UCK4CGaln7bIajKzTAd0fLZg', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-heat-expansion-thermal-equilibrium'), 'ideal-gas', 'ศึกษาการขยายตัวของปริมาตรแก๊สเมื่ออุณหภูมิเพิ่มขึ้น', '{"temperature":{"min":200,"max":600,"step":20,"default":380},"volume":{"min":2,"max":10,"step":0.5,"default":7},"moles":{"min":0.5,"max":3,"step":0.5,"default":1}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-heat-expansion-thermal-equilibrium'), 'thermal-piston', 'ปรับปริมาตรกระบอกสูบให้ความดันคงที่เมื่ออุณหภูมิเปลี่ยน', '{"tolerance":14,"targetPressure":[150,300],"temperature":{"min":200,"max":600,"default":360},"volume":{"min":2,"max":10,"step":0.5,"default":5.5}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-heat-expansion-thermal-equilibrium'), 'แบบทดสอบ: การขยายตัวและสมดุลความร้อน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-expansion-thermal-equilibrium')), 'choice', 'เมื่อของแข็งส่วนใหญ่ได้รับความร้อน จะมีขนาดเปลี่ยนแปลงอย่างไร', '["หดตัวเล็กลง","ขยายตัวใหญ่ขึ้น","ไม่เปลี่ยนแปลงขนาด","กลายเป็นของเหลวทันที"]', '1', 'เมื่อร้อน อนุภาคสั่นแรงขึ้นและมีระยะห่างมากขึ้น สสสารส่วนใหญ่จึงขยายตัว เช่น รางรถไฟต้องเผื่อช่องว่างไว้', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-expansion-thermal-equilibrium')), 'choice', 'สมดุลความร้อนเกิดขึ้นเมื่อใด', '["เมื่ออุณหภูมิของสองวัตถุต่างกันมาก","เมื่อวัตถุหนึ่งเย็นลงเรื่อยๆ","เมื่อความร้อนในระบบหมดไป","เมื่อวัตถุที่สัมผัสกันมีอุณหภูมิเท่ากัน"]', '3', 'วัตถุที่สัมผัสกันจะถ่ายโอนความร้อนจนอุณหภูมิเท่ากัน แล้วหยุดการถ่ายโอนความร้อนสุทธิ ภาวะนี้คือสมดุลความร้อน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-expansion-thermal-equilibrium')), 'choice', 'ข้อใดกล่าวถูกต้องเกี่ยวกับสมดุลความร้อน', '["ความร้อนไหลจากเย็นไปร้อน","ผสมน้ำร้อนกับน้ำเย็น อุณหภูมิสุดท้ายเท่ากับอุณหภูมิน้ำเย็น","อุณหภูมิของสารที่สัมผัสกันจะเท่ากันและไม่มีการถ่ายโอนความร้อนสุทธิ","อุณหภูมิรวมของระบบเพิ่มขึ้นตลอดเวลา"]', '2', 'เมื่อถึงสมดุลความร้อน อุณหภูมิของสารที่สัมผัสกันเท่ากัน และความร้อนสุทธิที่ไหลระหว่างกันเป็นศูนย์', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-expansion-thermal-equilibrium')), 'number', 'น้ำร้อน 80 องศาเซลเซียส ผสมกับน้ำเย็น 20 องศาเซลเซียส ในปริมาณเท่ากัน และไม่มีการสูญเสียความร้อน อุณหภูมิสมดุลประมาณเท่ากับกี่องศาเซลเซียส (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":50,"tolerance":0.5}', 'น้ำชนิดเดียวกันปริมาณเท่ากัน อุณหภูมิสมดุลคือค่าเฉลี่ย = (80 + 20) ÷ 2 = 50 องศาเซลเซียส', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-expansion-thermal-equilibrium')), 'number', 'แท่งโลหะยาว 100 เซนติเมตร เมื่อถูกความร้อนขยายตัวเพิ่มขึ้น 0.1 เซนติเมตร ความยาวใหม่ของแท่งโลหะเท่ากับกี่เซนติเมตร (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":100.1,"tolerance":0.05}', 'ความยาวใหม่ = 100 + 0.1 = 100.1 เซนติเมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-heat'), 'jr-heat-specific-heat-phase-change', 'ความร้อนจำเพาะและการเปลี่ยนสถานะ', 'ปริมาณความร้อนที่ใช้ในการเปลี่ยนอุณหภูมิของสารคำนวณได้จากสูตร Q = mcΔT โดย c คือความร้อนจำเพาะของสารแต่ละชนิด ส่วนในขณะที่สารเปลี่ยนสถานะ อุณหภูมิจะคงที่เนื่องจากความร้อนถูกใช้ไปทำลายแรงยึดเหนี่ยวระหว่างโมเลกุล ซึ่งคำนวณได้จากสูตร Q = mL โดย L คือความร้อนแฝงจำเพาะ เช่น ความร้อนแฝงของการหลอมเหลวหรือการกลายเป็นไอ ความเข้าใจเกี่ยวกับค่า c และ L ช่วยให้อธิบายปรากฏการณ์ของสารในธรรมชาติและออกแบบการระบายความร้อนได้อย่างถูกต้อง', 'junior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-heat-specific-heat-phase-change'), 'youtube', 'https://www.youtube.com/watch?v=7DRDjRtjYSY', '7DRDjRtjYSY', 'ความร้อนกับการเปลี่ยนสถานะ (วิทยาศาสตร์ ม. 1 เล่ม 2 หน่วยที่ 5 บทที่ 1)', 'Proj14 ม.1', 'https://www.youtube.com/channel/UCK4CGaln7bIajKzTAd0fLZg', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-heat-specific-heat-phase-change'), 'ideal-gas', 'สังเกตความดันและอุณหภูมิของแก๊สเมื่อให้พลังงานความร้อน', '{"temperature":{"min":200,"max":600,"step":20,"default":420},"volume":{"min":2,"max":10,"step":0.5,"default":4},"moles":{"min":0.5,"max":3,"step":0.5,"default":2}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-heat-specific-heat-phase-change'), 'thermal-piston', 'ควบคุมความดันแก๊สในกระบวนการเปลี่ยนสถานะพลังงาน', '{"tolerance":10,"targetPressure":[160,280],"temperature":{"min":200,"max":600,"default":440},"volume":{"min":2,"max":10,"step":0.5,"default":4}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-heat-specific-heat-phase-change'), 'แบบทดสอบ: ความร้อนจำเพาะและการเปลี่ยนสถานะ', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-specific-heat-phase-change')), 'choice', 'พลังงานความร้อนแฝงจำเพาะเกี่ยวข้องกับเหตุการณ์ใด', '["การเพิ่มอุณหภูมิของสาร","การนำความร้อน","การขยายตัวของสสาร","การเปลี่ยนสถานะของสารที่อุณหภูมิคงที่"]', '3', 'ความร้อนแฝงจำเพาะคือความร้อนที่ใช้ในการเปลี่ยนสถานะของสารมวล 1 กิโลกรัม โดยอุณหภูมิไม่เปลี่ยนแปลงระหว่างการเปลี่ยนสถานะ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-specific-heat-phase-change')), 'choice', 'ขณะน้ำแข็งกำลังละลายเป็นน้ำ อุณหภูมิของส่วนผสมจะเป็นอย่างไร', '["คงที่จนกว่าน้ำแข็งจะละลายหมด","เพิ่มขึ้นเรื่อยๆ ตลอดเวลา","ลดลงเรื่อยๆ","เพิ่มขึ้นเป็นสองเท่าทันที"]', '0', 'ในระหว่างการละลาย ความร้อนที่ได้รับใช้เปลี่ยนสถานะไม่ใช่เพิ่มอุณหภูมิ อุณหภูมิจึงคงที่จนน้ำแข็งละลายหมด', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-specific-heat-phase-change')), 'choice', 'น้ำแข็งละลายใช้ความร้อนแฝงของการหลอมเหลว ส่วนน้ำเดือดเป็นไอใช้ความร้อนแฝงของปริมาณใด', '["การแข็งตัว","การกลายเป็นไอ","การควบแน่น","การระเหิด"]', '1', 'การเปลี่ยนของเหลวเป็นแก๊ส (น้ำเดือดเป็นไอ) ใช้ความร้อนแฝงของการกลายเป็นไอ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-specific-heat-phase-change')), 'number', 'น้ำแข็ง 1 กิโลกรัมละลายเป็นน้ำหมดพอดี ความร้อนแฝงจำเพาะการหลอมเหลวของน้ำเท่ากับ 334000 จูล/กิโลกรัม ความร้อนที่ใช้ทั้งหมดเท่ากับกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":334000,"tolerance":0.5}', 'ความร้อน = มวล × ความร้อนแฝง = 1 × 334000 = 334000 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-specific-heat-phase-change')), 'number', 'น้ำมวล 2 กิโลกรัมอุณหภูมิเพิ่มขึ้น 5 องศาเซลเซียส ความร้อนจำเพาะของน้ำเท่ากับ 4200 จูล/(กิโลกรัม·องศา) ความร้อนที่ต้องใช้เท่ากับกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":42000,"tolerance":0.5}', 'Q = mcΔt = 2 × 4200 × 5 = 42000 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-heat'), 'jr-heat-temperature', 'ความร้อนและอุณหภูมิ', 'อุณหภูมิเป็นปริมาณที่บอกระดับพลังงานจลน์เฉลี่ยของอนุภาคในระบบ โดยวัดในหน่วยองศาเซลเซียสหรือเคลวินตามความสัมพันธ์ T(K) = T(°C) + 273.15 ส่วนความร้อน (Q) คือพลังงานความร้อนที่ถ่ายโอนระหว่างระบบที่มีความแตกต่างของอุณหภูมิ พลังงานความร้อนจะถ่ายโอนจากบริเวณที่มีอุณหภูมิสูงกว่าไปยังบริเวณที่มีอุณหภูมิต่ำกว่าโดยธรรมชาติเสมอ จนกระทั่งระบบเข้าสู่สมดุลความร้อน', 'junior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
