INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-transfer')), 'choice', 'การนำความร้อนเกิดได้ดีที่สุดในสสารชนิดใด', '["อากาศ","สุญญากาศ","โลหะ","น้ำมัน"]', '2', 'การนำความร้อนเป็นการถ่ายโอนผ่านของแข็ง โลหะมีอิเล็กตรอนอิสระจึงนำความร้อนได้ดี ส่วนอากาศและสุญญากาศนำได้ไม่ดี', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-transfer')), 'choice', 'การพาความร้อนเกิดได้ในสสารชนิดใด', '["ของเหลวและก๊าซ","เฉพาะของแข็ง","เฉพาะสุญญากาศ","สสารทุกชนิดเท่าเทียมกัน"]', '0', 'การพาความร้อนเกิดในของเหลวและก๊าซ เพราะอนุภาคเคลื่อนที่พาความร้อนไปด้วย เกิดการไหลเวียนของสสาร', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-transfer')), 'choice', 'ความร้อนจากดวงอาทิตย์เดินทางมายังโลกด้วยวิธีใด', '["การนำความร้อน","การแผ่รังสีความร้อน","การพาความร้อน","การนำไฟฟ้า"]', '1', 'อวกาศเป็นสุญญากาศ การนำและการพาเกิดขึ้นไม่ได้ ความร้อนจากดวงอาทิตย์จึงมาถึงโลกด้วยการแผ่รังสีเท่านั้น', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-transfer')), 'number', 'โต๊ะโลหะและเก้าอี้ไม้อยู่ในห้องเดียวกัน จริงๆ แล้วมีอุณหภูมิเท่ากัน 25 องศาเซลเซียส เมื่อจับโลหะรู้สึกเย็นกว่าเพราะโลหะนำความร้อนจากมือได้ดี อุณหภูมิของโลหะเท่ากับกี่องศาเซลเซียส (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":25,"tolerance":0.5}', 'ทั้งสองอยู่ในห้องเดียวกันจึงมีอุณหภูมิเท่ากัน 25 องศาเซลเซียส ความรู้สึกเย็นต่างกันเกิดจากความสามารถนำความร้อน ไม่ใช้อุณหภูมิที่ต่างกัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-heat-transfer')), 'number', 'น้ำ 2 ลิตรในถ้วยใหญ่กับน้ำ 1 ลิตรในถ้วยเล็ก ตั้งอยู่ในห้องเดียวกัน โดยทั้งสองมีอุณหภูมิ 30 องศาเซลเซียส น้ำในถ้วยใหญ่มีอุณหภูมิเท่ากับกี่องศาเซลเซียส (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":30,"tolerance":0.5}', 'อุณหภูมิไม่ขึ้นกับปริมาณของสสาร น้ำทั้งสองถ้วยมีอุณหภูมิเท่ากันคือ 30 องศาเซลเซียส', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-light'), 'jr-light-lenses-mirrors', 'เลนส์และกระจก', 'เลนส์นูนและกระจกเว้าทำหน้าที่รวมแสง ส่วนเลนส์เว้าและกระจกนูนทำหน้าที่กระจายแสง การเกิดภาพคำนวณได้จากสูตรเลนส์บาง 1/f = 1/s + 1/s'' และกำลังขยาย m = y''/y = -s''/s ภาพที่เกิดขึ้นอาจเป็นภาพจริงหัวกลับที่รับบนฉากได้ หรือภาพเสมือนหัวตั้งที่ไม่สามารถรับบนฉากแต่เห็นได้ด้วยตาเปล่า เลนส์นูนถูกนำไปสร้างแว่นขยาย กล้องจุลทรรศน์ และกล้องโทรทรรศน์อย่างแพร่หลาย', 'junior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-light-lenses-mirrors'), 'youtube', 'https://www.youtube.com/watch?v=pP5UIG9b-Ug', 'pP5UIG9b-Ug', 'เลนส์และภาพที่เกิดจากเลนส์  (วิทยาศาสตร์ ม. 3 เล่ม 1 หน่วยที่ 3 บทที่ 2 แสง)', 'Proj14 ม.3', 'https://www.youtube.com/channel/UCEDTSRW-0iUxL_45MR3ESPg', 1);
