INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-reflection')), 'choice', 'กฎการสะท้อนของแสงกล่าวว่าอย่างไร', '["มุมตกกระทบเท่ากับมุมสะท้อน","มุมตกกระทบมากกว่ามุมสะท้อน","มุมตกกระทบน้อยกว่ามุมสะท้อน","มุมสะท้อนเป็น 90 องศาเสมอ"]', '0', 'กฎการสะท้อนคือมุมตกกระทบเท่ากับมุมสะท้อน และรังสีตกกระทบ รังสีสะท้อน กับเส้นปกติอยู่ในระนาบเดียวกัน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-reflection')), 'choice', 'มุมตกกระทบวัดจากเส้นใด', '["ผิวของกระจก","แนวระดับ","เส้นปกติซึ่งตั้งฉากกับผิวกระจก","รังสีสะท้อน"]', '2', 'มุมตกกระทบและมุมสะท้อนวัดจากเส้นปกติ (เส้นตั้งฉากกับผิวสะท้อน) ไม่ได้วัดจากผิวกระจก', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-reflection')), 'choice', 'ภาพของวัตถุที่เห็นจากกระจกเงาราบมีลักษณะอย่างไร', '["หัวกลับด้าน","เป็นภาพเสมือน หัวตั้ง และซ้ายขวาสลับกัน","ใหญ่กว่าวัตถุเสมอ","เป็นภาพจริงที่ปรากฏหลังกระจก"]', '1', 'ภาพจากกระจกเงาราบเป็นภาพเสมือน หัวตั้ง ขนาดเท่าวัตถุ แต่ซ้ายขวาสลับกัน ดูเหมือนอยู่หลังกระจก', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-reflection')), 'number', 'แสงตกกระทบกระจกเงาราบด้วยมุมตกกระทบ 30 องศา มุมสะท้อนเท่ากับกี่องศา (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":30,"tolerance":0.5}', 'ตามกฎการสะท้อน มุมสะท้อนเท่ากับมุมตกกระทบ จึงเท่ากับ 30 องศา', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-reflection')), 'number', 'รังสีแสงตกกระทบกระจกเงาราบทำมุม 40 องศากับเส้นปกติ มุมสะท้อนเท่ากับกี่องศา (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":40,"tolerance":0.5}', 'มุมสะท้อนเท่ากับมุมตกกระทบ ซึ่งวัดจากเส้นปกติได้ 40 องศา มุมสะท้อนจึงเท่ากับ 40 องศา', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-light'), 'jr-light-refraction', 'การหักเหของแสง', 'การหักเหของแสงเกิดขึ้นเมื่อแสงเดินทางผ่านรอยต่อระหว่างตัวกลางสองชนิดที่มีความหนาแน่นเชิงแสงหรือดัชนีหักเหต่างกัน ทำให้อัตราเร็วและความยาวคลื่นของแสงเปลี่ยนไปในขณะที่ความถี่ยังคงเดิม เมื่อแสงเดินทางจากตัวกลางที่มีดัชนีหักเหน้อยไปยังตัวกลางที่มีดัชนีหักเหมาก แสงจะหักเหเบนเข้าหาเส้นแนวฉาก ปรากฏการณ์นี้ทำให้เรามองเห็นวัตถุในน้ำอยู่ตื้นกว่าตำแหน่งจริง', 'junior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
