INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-refraction')), 'choice', 'การหักเหของแสงเกิดจากสาเหตุใด', '["แสงเปลี่ยนสีเมื่อเข้าตัวกลางใหม่","อัตราเร็วของแสงเปลี่ยนเมื่อเปลี่ยนตัวกลาง","แสงสะท้อนกลับไปทางเดิมเสมอ","แสงถูกดูดกลืนโดยตัวกลาง"]', '1', 'การหักเหเกิดเพราะอัตราเร็วของแสงเปลี่ยนเมื่อผ่านเข้าสู่ตัวกลางใหม่ที่มีสมบัติต่างกัน จึงทำให้ทิศของแสงเปลี่ยน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-refraction')), 'choice', 'เมื่อแสงเดินทางจากอากาศเข้าสู่น้ำ มุมหักเหเมื่อเทียบกับเส้นปกติจะเป็นอย่างไร', '["มากกว่ามุมตกกระทบ","เท่ากับมุมตกกระทบ","หักเหออกห่างจากเส้นปกติ","น้อยกว่ามุมตกกระทบ โดยหักเหเข้าหาเส้นปกติ"]', '3', 'น้ำหนาแน่นกว่าอากาศ แสงเดินทางช้าลงเมื่อเข้าสู่น้ำ จึงหักเหเข้าหาเส้นปกติ ทำให้มุมหักเหน้อยกว่ามุมตกกระทบ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-refraction')), 'choice', 'หลอดดูดที่จุ่มในน้ำมองดูเหมือนหักงอตรงผิวน้ำ เพราะเหตุใด', '["การสะท้อนของแสงที่ผิวน้ำ","การดูดกลืนแสงโดยน้ำ","การหักเหของแสงเมื่อเปลี่ยนจากน้ำสู่อากาศ","แสงเดินทางช้าลงในอากาศ"]', '2', 'แสงจากส่วนที่อยู่ในน้ำเปลี่ยนตัวกลางสู่อากาศ ทำให้หักเห เราเห็นภาพของหลอดจึงเหมือนหักงอ นี่คือการหักเหของแสง', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-refraction')), 'number', 'แสงเดินทางจากอากาศ (อัตราเร็ว 300000 กิโลเมตร/วินาที) เข้าสู่แก้วซึ่งแสงเดินทางได้เพียง 2 ใน 3 ของอัตราเร็วในอากาศ อัตราเร็วของแสงในแก้วเท่ากับกี่กิโลเมตร/วินาที (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":200000,"tolerance":0.5}', 'อัตราเร็วในแก้ว = 2/3 × 300000 = 200000 กิโลเมตร/วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-refraction')), 'number', 'จากข้อก่อนหน้า แสงในแก้วเดินทางช้ากว่าในอากาศกี่กิโลเมตร/วินาที (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":100000,"tolerance":0.5}', 'ผลต่าง = 300000 − 200000 = 100000 กิโลเมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-light'), 'jr-light-sources-propagation', 'แหล่งกำเนิดแสงและการเคลื่อนที่ของแสง', 'แสงเป็นพลังงานรูปหนึ่งที่แผ่คลื่นแม่เหล็กไฟฟ้าออกจากแหล่งกำเนิดแสง เช่น ดวงอาทิตย์ หลอดไฟ หรือเปลวเทียน ในตัวกลางโปร่งใสเนื้อเดียวแสงจะเดินทางเป็นเส้นตรงด้วยความเร็วประมาณ 300,000 กิโลเมตรต่อวินาที การเคลื่อนที่เป็นเส้นตรงของแสงทำให้เกิดเงาคมชัดเมื่อมีวัตถุทึบแสงมาขวางกั้น เกิดเป็นเงามืดและเงามัว รวมถึงเป็นหลักการพื้นฐานในการเกิดภาพในกล้องรูเข็ม', 'junior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
