INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-light-sources-propagation'), 'แบบทดสอบ: แหล่งกำเนิดแสงและการเคลื่อนที่ของแสง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-sources-propagation')), 'choice', 'ข้อใดเป็นแหล่งกำเนิดแสง', '["ดวงจันทร์","กระจกเงา","หนังสือเรียน","ดวงอาทิตย์"]', '3', 'ดวงอาทิตย์เป็นแหล่งกำเนิดแสงที่เปล่งแสงเอง ส่วนดวงจันทร์ กระจก และหนังสือเป็นเพียงวัตถุที่สะท้อนแสงจากแหล่งอื่น', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-sources-propagation')), 'choice', 'แสงเดินทางในตัวกลางโปร่งใสชนิดเดียวกันได้อย่างไร (โดยประมาณ)', '["เดินทางเป็นเส้นโค้ง","เดินทางเป็นเส้นตรง","เดินทางเป็นวงกลม","หยุดนิ่งไม่เคลื่อนที่"]', '1', 'แสงเดินทางเป็นเส้นตรงในตัวกลางโปร่งใสเดียวกัน ถ้าตัวกลางต่างกันหรืองอไปตามสภาพ แสงอาจหักเหหรือโค้งได้', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-sources-propagation')), 'choice', 'เมื่อแสงตกกระทบวัตถุทึบแสง เกิดเงาที่ด้านตรงข้าม เพราะเหตุใด', '["แสงเดินทางเป็นเส้นตรง จึงอ้อมผ่านวัตถุทึบไม่ได้","แสงสะท้อนจากวัตถุทึบทั้งหมด","แสงหักเหเมื่อผ่านวัตถุทึบ","แสงมีหลายสี"]', '0', 'เพราะแสงเดินทางเป็นเส้นตรง จึงไม่อ้อมผ่านวัตถุทึบแสง ด้านตรงข้ามจึงไม่มีแสงตกถึงและเกิดเงา', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-sources-propagation')), 'number', 'แสงจากดวงอาทิตย์เดินทางมายังโลกด้วยอัตราเร็ว 300000 กิโลเมตร/วินาที และใช้เวลาประมาณ 500 วินาที ระยะทางจากโลกถึงดวงอาทิตย์ประมาณกี่กิโลเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":150000000,"tolerance":0.5}', 'ระยะทาง = อัตราเร็ว × เวลา = 300000 × 500 = 150000000 กิโลเมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-light-sources-propagation')), 'number', 'แสงเดินทางด้วยอัตราเร็ว 300000 กิโลเมตร/วินาที ถ้าระยะทางจากโลกถึงดวงอาทิตย์เป็น 150000000 กิโลเมตร แสงใช้เวลาเดินทางกี่วินาที (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":500,"tolerance":0.5}', 'เวลา = ระยะทาง ÷ อัตราเร็ว = 150000000 ÷ 300000 = 500 วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-magnetism'), 'jr-magnetism-electromagnet', 'แม่เหล็กไฟฟ้าและการใช้ประโยชน์', 'แม่เหล็กไฟฟ้าสร้างขึ้นโดยการนำลวดตัวนำมาพันรอบแกนเหล็กอ่อนแล้วปล่อยกระแสไฟฟ้าให้ไหลผ่าน เมื่อมีกระแสไฟฟ้าไหล แกนเหล็กจะมีสมบัติเป็นแม่เหล็กทันที และเมื่อตัดกระแสไฟฟ้า อำนาจแม่เหล็กก็จะหมดไป ความเข้มของสนามแม่เหล็กไฟฟ้าสามารถเพิ่มขึ้นได้โดยการเพิ่มจำนวนรอบขดลวด เพิ่มปริมาณกระแสไฟฟ้า หรือใส่แกนเหล็กอ่อน แม่เหล็กไฟฟ้านิยมนำไปใช้ในปั้นจั่นยกเศษเหล็ก รีเลย์ กระดิ่งไฟฟ้า และมอเตอร์', 'junior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-magnetism-electromagnet'), 'youtube', 'https://www.youtube.com/watch?v=52KymjgWU_U', '52KymjgWU_U', 'I know PHYSICS ep.18 - แม่เหล็กไฟฟ้า (Part 1 : พื้นฐานของแม่เหล็กไฟฟ้า)', 'I know PHYSICs a little', 'https://www.youtube.com/channel/UC0qWWV4YLpxnAQGJ8ednXlA', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-magnetism-electromagnet'), 'magnetic-induction', 'ศึกษาการเหนี่ยวนำแม่เหล็กไฟฟ้าและการทำงานของแกนเหล็ก', '{"bField":{"min":0.2,"max":1.8,"step":0.1,"default":0.8},"speed":{"min":3,"max":16,"step":1,"default":9}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-magnetism-electromagnet'), 'quantum-lab', 'ปรับจูนสนามแม่เหล็กไฟฟ้าให้มีพลังงานตามเป้าหมาย', '{"targetEk":[0.7,2.7],"workFunction":1.8,"tolerance":0.15,"frequency":{"min":4,"max":14,"step":0.2,"default":6.8}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-magnetism-electromagnet'), 'แบบทดสอบ: แม่เหล็กไฟฟ้าและการใช้ประโยชน์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-electromagnet')), 'choice', 'แม่เหล็กไฟฟ้าเกิดขึ้นจากหลักการใด', '["การถูแม่เหล็กซ้ำๆ หลายครั้ง","การให้ความร้อนแก่แม่เหล็กถาวร","กระแสไฟฟ้าไหลผ่านขดลวดที่พันรอบแกนเหล็ก","การผสมโลหะชนิดต่างๆ เข้าด้วยกัน"]', '2', 'เมื่อกระแสไฟฟ้าไหลผ่านขดลวดที่พันรอบแกนเหล็ก จะเกิดสนามแม่เหล็กขึ้นบริเวณโดยรอบ เรียกว่าแม่เหล็กไฟฟ้า', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-electromagnet')), 'choice', 'จะทำให้แม่เหล็กไฟฟ้าแรงขึ้นได้อย่างไร', '["ลดจำนวนรอบของขดลวด","เพิ่มจำนวนรอบของขดลวดหรือเพิ่มกระแสไฟฟ้า","ใช้แกนพลาสติกแทนแกนเหล็ก","ลดกระแสไฟฟ้าที่ไหลผ่าน"]', '1', 'ความแรงของแม่เหล็กไฟฟ้าเพิ่มขึ้นเมื่อมีจำนวนรอบของขดลวดมากขึ้นหรือกระแสไฟฟ้ามากขึ้น และใช้แกนเหล็กช่วยรวมสนาม', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-electromagnet')), 'choice', 'ข้อใดเป็นการใช้ประโยชน์จากแม่เหล็กไฟฟ้า', '["เข็มทิศ","แม่เหล็กติดตู้เย็น","หินแม่เหล็กธรรมชาติ","กระดิ่งไฟฟ้า ลำโพง และรถเครนยกเหล็ก"]', '3', 'แม่เหล็กไฟฟ้าที่เปิดปิดได้ตามกระแส นำไปใช้ในกระดิ่งไฟฟ้า ลำโพง และรถเครนยกเหล็ก ซึ่งต่างจากแม่เหล็กถาวรที่เปิดปิดไม่ได้', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-electromagnet')), 'number', 'ขดลวดของแม่เหล็กไฟฟ้ามี 50 รอบ เพิ่มเป็น 100 รอบโดยกระแสคงที่ ความแรงของแม่เหล็กไฟฟ้าเพิ่มขึ้นเป็นกี่เท่า (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'จำนวนรอบเพิ่มเป็น 100 ÷ 50 = 2 เท่า ความแรงของแม่เหล็กไฟฟ้าจึงเพิ่มประมาณ 2 เท่า', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-electromagnet')), 'number', 'เพิ่มกระแสไฟฟ้าจาก 1 แอมแปร์เป็น 3 แอมแปร์โดยจำนวนรอบคงที่ ความแรงของแม่เหล็กไฟฟ้าเพิ่มขึ้นเป็นกี่เท่า (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'กระแสเพิ่มจาก 1 เป็น 3 ต่อ 1 = 3 เท่า ความแรงของแม่เหล็กไฟฟ้าจึงเพิ่มประมาณ 3 เท่า', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-magnetism'), 'jr-magnetism-magnetic-field', 'สนามแม่เหล็ก', 'สนามแม่เหล็กคืออาณาบริเวณรอบแท่งแม่เหล็กที่มีแรงแม่เหล็กส่งไปถึง เราสามารถตรวจสอบแนวเส้นสนามแม่เหล็กได้โดยใช้ผงตะไบเหล็กหรือเข็มทิศ ปลายเข็มทิศขั้วเหนือจะชี้ตามทิศทางของสนามแม่เหล็กเสมอ โลกของเรามีสนามแม่เหล็กโลกห่อหุ้มอยู่ โดยขั้วแม่เหล็กโลกทางเหนือจะอยู่ใกล้ขั้วโลกใต้ทางภูมิศาสตร์ และขั้วแม่เหล็กโลกทางใต้จะอยู่ใกล้ขั้วโลกเหนือทางภูมิศาสตร์ ทำให้เข็มทิศช่วยนำทางเราได้ทั่วโลก', 'junior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-magnetism-magnetic-field'), 'youtube', 'https://www.youtube.com/watch?v=DYUSQIv_qJU', 'DYUSQIv_qJU', 'แรงและสนามของแรง ตอนที่ 2 (วิทยาศาสตร์ ม. 2 เล่ม 1 หน่วยที่ 4 บทที่ 2)', 'Proj14 ม.2', 'https://www.youtube.com/channel/UCkGQRzlwZFWkOin9SiP7JUQ', 1);
