INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-magnetic-field')), 'choice', 'สนามแม่เหล็กคืออะไร', '["แผ่นเหล็กแผ่นบางที่วางใกล้แม่เหล็ก","บริเวณรอบแม่เหล็กที่ยังมีแรงแม่เหล็กกระทำต่อวัตถุแม่เหล็ก","อากาศที่อยู่รอบแม่เหล็ก","แสงที่ปล่อยออกมาจากแม่เหล็ก"]', '1', 'สนามแม่เหล็กเป็นบริเวณรอบแม่เหล็กที่ วัตถุแม่เหล็กอื่นจะได้รับแรงแม่เหล็ก ใกล้ขั้วแรงมาก ไกลๆ แรงน้อยลง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-magnetic-field')), 'choice', 'เส้นแรงแม่เหล็กรอบแท่งแม่เหล็กมีทิศทางอย่างไร', '["จากขั้วใต้ไปขั้วเหนือภายนอกแท่ง","สุ่มไปทุกทิศทาง","เข้าหาวัตถุเสมอ","จากขั้วเหนือไปขั้วใต้ภายนอกแท่ง และใต้ไปเหนือภายในแท่ง"]', '3', 'เส้นแรงแม่เหล็กมีทิศจากขั้วเหนือไปขั้วใต้ภายนอกแท่ง และจากใต้ไปเหนือภายในแท่ง รวมเป็นวงปิด', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-magnetic-field')), 'choice', 'เส้นแรงแม่เหล็กจะหนาแน่นที่สุดบริเวณใด', '["บริเวณขั้วแม่เหล็ก","ตรงกลางของแท่งแม่เหล็ก","บริเวณที่ไม่มีขั้ว","กระจายเท่าๆ กันทุกจุด"]', '0', 'เส้นแรงแม่เหล็กหนาแน่นที่สุดที่ขั้ว เพราะสนามแม่เหล็กเข้มที่สุดที่ขั้ว ยิ่งไกลออกไปเส้นแรงยิ่งห่าง', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-magnetic-field')), 'number', 'จำนวนเส้นแรงแม่เหล็กแทนความเข้มของสนาม ถ้าแม่เหล็กแท่งหนึ่งมีเส้นแรง 10 เส้น และอีกแท่งหนึ่งเข้มกว่า 3 เท่า แท่งที่เข้มกว่าควรมีเส้นแรงกี่เส้น (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":30,"tolerance":0.5}', 'สนามเข้ม 3 เท่าจึงมีเส้นแรง 3 เท่า = 3 × 10 = 30 เส้น', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-magnetism-magnetic-field')), 'number', 'แม่เหล็กแท่งหนึ่งมีเส้นแรงจากขั้วเหนือ 15 เส้น อีกแท่งหนึ่งมี 45 เส้น แท่งที่สองมีสนามแม่เหล็กเข้มเป็นกี่เท่าของแท่งแรก (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', '45 ÷ 15 = 3 เท่า จำนวนเส้นแรงแปรผันตรงกับความเข้มของสนาม', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-magnetism'), 'jr-magnetism-properties', 'สมบัติของแม่เหล็ก', 'แม่เหล็กเป็นวัตถุที่มีแรงดึงดูดสารแม่เหล็ก เช่น เหล็ก โคบอลต์ และนิกเกิล แท่งแม่เหล็กทุกแท่งจะมีสองขั้วเสมอคือขั้วเหนือ (N) และขั้วใต้ (S) โดยขั้วเหมือนกันจะออกแรงผลักกัน และขั้วต่างกันจะออกแรงดูดกัน หากตัดแท่งแม่เหล็กออกเป็นสองท่อน แต่ละท่อนก็จะสร้างขั้วเหนือและขั้วใต้ขึ้นมาใหม่เสมอ เส้นแรงแม่เหล็กภายนอกแท่งแม่เหล็กจะพุ่งออกจากขั้วเหนือและโค้งวนกลับเข้าสู่ขั้วใต้', 'junior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
