INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pascal-atmosphere'), 'แบบทดสอบ: หลักของพาสคัลและความดันบรรยากาศ', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pascal-atmosphere')), 'choice', 'หลักของพาสคัลกล่าวว่า เมื่อกดของเหลวในภาชนะปิดสนิท ความดันที่เพิ่มขึ้นจะ', '["เกิดขึ้นเฉพาะจุดที่กดเท่านั้น","เกิดขึ้นเฉพาะที่ก้นภาชนะ","ลดลงตามระยะทางที่ไกลออกไป","ถ่ายทอดไปทุกทิศทุกทางด้วยขนาดเท่ากัน"]', '3', 'ความดันที่เพิ่มขึ้นในของเหลวที่ปิดสนิทถ่ายทอดเท่ากันทุกทิศทุกทาง จึงใช้หลักการนี้ในแม่แรงไฮดรอลิก', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pascal-atmosphere')), 'choice', 'อุปกรณ์ในข้อใดใช้หลักของพาสคัล', '["บันไดเลื่อน","พัดลม","แม่แรงไฮดรอลิก","ถังเก็บน้ำ"]', '2', 'แม่แรงไฮดรอลิกใช้หลักของพาสคัล ออกแรงเล็กที่ลูกสูบเล็ก แล้วความดันถ่ายทอดไปดันลูกสูบใหญ่ให้เกิดแรงมาก', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pascal-atmosphere')), 'choice', 'ความดันบรรยากาศเกิดจากสาเหตุใด', '["น้ำหนักของอากาศกดลงบนพื้นโลก","แสงจากดวงอาทิตย์","แรงดึงดูดของดวงจันทร์","การหมุนรอบตัวเองของโลก"]', '0', 'อากาศมีน้ำหนักและกดทับทุกสิ่งที่อยู่ใต้ชั้นบรรยากาศ ทำให้เกิดความดันบรรยากาศที่กระทำต่อวัตถุทุกด้าน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pascal-atmosphere')), 'number', 'แม่แรงไฮดรอลิกมีพื้นที่ลูกสูบเล็ก 0.02 ตารางเมตร ออกแรงกด 40 นิวตัน ความดันที่เกิดขึ้นในของเหลวเท่ากับกี่พาสคัล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2000,"tolerance":0.5}', 'P = F / A = 40 ÷ 0.02 = 2000 พาสคัล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pascal-atmosphere')), 'number', 'ความดันในระบบไฮดรอลิก 500 พาสคัล กระทำบนพื้นที่ลูกสูบใหญ่ 0.1 ตารางเมตร จะเกิดแรงดันเท่ากับกี่นิวตัน (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":50,"tolerance":0.5}', 'F = P × A = 500 × 0.1 = 50 นิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-pressure-fluids'), 'jr-pressure-fluids-pressure', 'ความดัน', 'ความดัน (P) นิยามจากขนาดของแรงที่กระทำตั้งฉากต่อหนึ่งหน่วยพื้นที่ตามสมการ P = F/A โดยมีหน่วยเป็นนิวตันต่อตารางเมตรหรือพาสคัล (Pa) หากพื้นที่รับแรงมีขนาดเล็กลง ความดันจะมีค่าสูงขึ้นแม้ใช้แรงกดเท่าเดิม เช่น คมมีดหรือปลายเข็ม ในของไหล ความดันจะส่งผ่านไปทุกทิศทางอย่างสม่ำเสมอ ซึ่งเป็นแนวคิดพื้นฐานสำคัญในการทำความเข้าใจพฤติกรรมของของเหลวและแก๊ส', 'junior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pressure'), 'youtube', 'https://www.youtube.com/watch?v=dmqBYDEe63c', 'dmqBYDEe63c', 'I know PHYSICS ep.14 - ของไหล (Part 2 : ความดัน)', 'I know PHYSICs a little', 'https://www.youtube.com/channel/UC0qWWV4YLpxnAQGJ8ednXlA', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-pressure-fluids-pressure'), 'fluid-pressure', 'จำลองความสัมพันธ์ของแรงกดต่อหนึ่งหน่วยพื้นที่ในของเหลว', '{"density":{"min":600,"max":1400,"step":50,"default":1000},"depth":{"min":0.5,"max":8,"step":0.5,"default":2.5},"objectDensity":{"min":400,"max":1600,"step":50,"default":900}}');
