INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-sound-echo-hearing'), 'แบบทดสอบ: เสียงสะท้อนและการได้ยิน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-echo-hearing')), 'choice', 'เสียงสะท้อน (echo) เกิดจากสาเหตุใด', '["เสียงเดินทางช้าเกินไป","เสียงมีความดังสูงเกินไป","เสียงสะท้อนกลับมายังผู้ฟังจากผิวสะท้อน","เสียงเดินทางเร็วเกินไป"]', '2', 'เมื่อเสียงเดินทางไปกระทบผิวแข็งเช่นกำแพงหรือหน้าผาแล้วสะท้อนกลับมายังผู้ฟัง เรียกว่าเสียงสะท้อน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-echo-hearing')), 'choice', 'เราจะได้ยินเสียงสะท้อนแยกชัดเจนจากเสียงเดิมเมื่อใด', '["เมื่อเสียงเดิมดังมากจนก้อง","เมื่ออยู่ใกล้กำแพงมาก","เมื่อไม่มีเสียงอื่นในบริเวณนั้น","เมื่อแหล่งสะท้อนอยู่ไกลพอให้เสียงสะท้อนกลับมาหลังเสียงเดิมสิ้นสุด"]', '3', 'ถ้าแหล่งสะท้อนอยู่ไกลพอ เสียงสะท้อนจะกลับมาหลังเสียงเดิมสิ้นสุดลง จึงได้ยินแยกเป็นสองเสียง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-echo-hearing')), 'choice', 'การวัดความลึกทะเลด้วยโซนาร์ใช้สมบัติใดของเสียง', '["การสะท้อนของเสียง","การดูดกลืนเสียง","การหักเหของเสียง","ความดังของเสียง"]', '0', 'โซนาร์ส่งเสียงลงไปในน้ำ เมื่อเสียงสะท้อนจากพื้นทะเลกลับมา วัดเวลาที่ใช้จึงคำนวณความลึกได้', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-echo-hearing')), 'number', 'ส่งเสียงลงไปในบ่อน้ำ ได้ยินเสียงสะท้อนกลับมาหลังจาก 0.5 วินาที ถ้าอัตราเร็วเสียง 340 เมตร/วินาที ปากบ่อถึงผิวน้ำลึกกี่เมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":85,"tolerance":0.5}', 'เสียงเดินทางลงไปและกลับขึ้นมา ระยะทางจริงจึงหารสอง s = v × t ÷ 2 = 340 × 0.5 ÷ 2 = 85 เมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-echo-hearing')), 'number', 'คลื่นเสียงเดินทางจากผิวน้ำไปถึงก้นทะเลและสะท้อนกลับมาใช้เวลา 2 วินาที ถ้าอัตราเร็วเสียงในน้ำ 1500 เมตร/วินาที ทะเลลึกกี่เมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":1500,"tolerance":0.5}', 'ความลึก = v × t ÷ 2 = 1500 × 2 ÷ 2 = 1500 เมตร ต้องหารสองเพราะเสียงไปและกลับ', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-sound'), 'jr-sound-frequency-amplitude', 'ความถี่ แอมพลิจูด และระดับเสียง', 'ระดับเสียงหรือความทุ้มแหลมขึ้นอยู่กับความถี่ของคลื่นเสียง (f) โดยเสียงความถี่สูงคือเสียงแหลม และเสียงความถี่ต่ำคือเสียงทุ้ม หูมนุษย์ทั่วไปได้ยินเสียงในช่วงความถี่ประมาณ 20 ถึง 20,000 เฮิรตซ์ ส่วนความดังของเสียงขึ้นอยู่กับแอมพลิจูด (A) ของคลื่นหรือพลังงานในการสั่น ยิ่งแอมพลิจูดมากเสียงจะยิ่งดัง ระดับความเข้มเสียงวัดในหน่วยเดซิเบล (dB) ซึ่งช่วยให้เราเข้าใจขีดจำกัดความปลอดภัยในการรับฟังเสียงในชีวิตประจำวัน', 'junior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
