INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-production-propagation')), 'choice', 'เสียงเกิดขึ้นจากสาเหตุใด', '["การสั่นสะเทือนของแหล่งกำเนิดเสียง","การไหลของอากาศอย่างเดียว","แสงที่มากระทบวัตถุ","การหมุนของโลก"]', '0', 'เสียงเกิดจากการสั่นสะเทือนของวัตถุ แล้วสั่นถ่ายทอดผ่านตัวกลางไปยังหู เช่น สายกีตาร์สั่นสะเทือนเมื่อดีด', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-production-propagation')), 'choice', 'เสียงเดินทางผ่านตัวกลางชนิดใดได้ดีที่สุด', '["สุญญากาศ","อากาศที่บางมาก","ของแข็ง","เสียงไม่ต้องใช้ตัวกลาง"]', '2', 'เสียงเดินทางผ่านของแข็งได้ดีที่สุด เพราะอนุภาคอยู่ชิดกันถ่ายทอดการสั่นได้ดี อัตราเร็วเสียงในของแข็งจึงสูงที่สุด', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-production-propagation')), 'choice', 'เสียงไม่สามารถเดินทางในสุญญากาศได้ เพราะเหตุใด', '["แสงบังการเคลื่อนที่ของเสียง","สุญญากาศมีอุณหภูมิสูงเกินไป","ความดันในสุญญากาศสูงเกินไป","ไม่มีตัวกลางให้การสั่นถ่ายทอด"]', '3', 'เสียงต้องอาศัยตัวกลางในการสั่นถ่ายทอด ในสุญญากาศไม่มีอนุภาคให้สั่นต่อกัน เสียงจึงเดินทางไม่ได้', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-production-propagation')), 'number', 'เสียงเดินทางในอากาศด้วยอัตราเร็วประมาณ 340 เมตร/วินาที ถ้าได้ยินเสียงฟ้าร้องหลังเห็นฟ้าแลบ 3 วินาที ฟ้าผ่าอยู่ห่างประมาณกี่เมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":1020,"tolerance":0.5}', 'ระยะทาง = อัตราเร็ว × เวลา = 340 × 3 = 1020 เมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-sound-production-propagation')), 'number', 'เสียงเดินทางในอากาศได้ระยะ 680 เมตรในเวลา 2 วินาที อัตราเร็วของเสียงเท่ากับกี่เมตร/วินาที (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":340,"tolerance":0.5}', 'อัตราเร็ว = ระยะทาง ÷ เวลา = 680 ÷ 2 = 340 เมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-work-energy'), 'jr-work-energy-conservation', 'การเปลี่ยนรูปและการอนุรักษ์พลังงาน', 'กฎการอนุรักษ์พลังงานระบุว่า พลังงานไม่สามารถสร้างขึ้นใหม่หรือสูญหายไปได้ แต่สามารถเปลี่ยนจากรูปหนึ่งไปสู่อีกรูปหนึ่งได้ เช่น การแกว่งของชิงช้าหรือลูกตุ้ม พลังงานศักย์ที่จุดสูงสุดจะเปลี่ยนเป็นพลังงานจลน์ทั้งหมดที่จุดต่ำสุด พลังงานกลรวม Ek + Ep จะมีค่าคงที่เสมอหากไม่มีแรงต้านอากาศหรือแรงเสียดทานมาเปลี่ยนพลังงานกลเป็นพลังงานความร้อน', 'junior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-conservation'), 'youtube', 'https://www.youtube.com/watch?v=DUjw7PYlV7Q', 'DUjw7PYlV7Q', 'I know PHYSICS ep.5 - งานและพลังงาน (Part 3 : กฎการอนุรักษ์พลังงาน)', 'I know PHYSICs a little', 'https://www.youtube.com/channel/UC0qWWV4YLpxnAQGJ8ednXlA', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-conservation'), 'newton-force', 'สังเกตการถ่ายโอนพลังงานกลและพลังงานสูญเสียในระบบการเคลื่อนที่', '{"force":{"min":10,"max":90,"default":42},"mass":{"min":1,"max":15,"default":5},"friction":{"min":0,"max":0.5,"step":0.05,"default":0.15}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-conservation'), 'balance-force', 'รักษาระดับการเปลี่ยนรูปพลังงานโดยสร้างความเร่งให้ตรงเป้าหมาย', '{"targetAcc":[1.4,4.4],"tolerance":0.15,"force":{"min":19,"max":89,"default":45},"mass":{"min":2,"max":9,"default":5}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-conservation'), 'แบบทดสอบ: การเปลี่ยนรูปและการอนุรักษ์พลังงาน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-conservation')), 'choice', 'กฎการอนุรักษ์พลังงานกล่าวว่าอย่างไร', '["พลังงานไม่สูญหายและไม่เกิดขึ้นใหม่ แต่เปลี่ยนรูปไปได้","พลังงานถูกสร้างขึ้นมาใหม่ได้เสมอ","พลังงานทั้งหมดจะหายไปเมื่อทำงาน","พลังงานไม่สามารถเปลี่ยนรูปได้"]', '0', 'พลังงานรวมของระบบคงที่ เพียงเปลี่ยนรูปไปมา พลังงานจลน์อาจเปลี่ยนเป็นพลังงานศักย์ พลังงานความร้อน หรือพลังงานรูปอื่นได้', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-conservation')), 'choice', 'ลูกตุ้มแกว่งจากจุดสูงสุด จุดใดมีพลังงานจลน์มากที่สุด', '["จุดสูงสุดทั้งสองด้าน","ทุกจุดเท่ากัน","จุดต่ำสุด (จุดศูนย์กลางการแกว่ง)","จุดเริ่มต้น"]', '2', 'ที่จุดต่ำสุดลูกตุ้มเคลื่อนที่เร็วที่สุดจึงมีพลังงานจลน์มากที่สุด ขณะที่พลังงานศักย์น้อยที่สุด ส่วนที่จุดสูงสุดพลังงานจลน์เป็นศูนย์', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-conservation')), 'choice', 'เมื่อรถเบรกจนหยุดนิ่ง พลังงานจลน์ของรถส่วนใหญ่เปลี่ยนไปเป็นพลังงานรูปใด', '["พลังงานนิวเคลียร์","พลังงานไฟฟ้า","พลังงานลม","พลังงานความร้อนเนื่องจากการเสียดสี"]', '3', 'การเบรกทำให้ผ้าเบรกกับล้อเสียดสีกัน พลังงานจลน์จึงเปลี่ยนเป็นพลังงานความร้อนตามกฎการอนุรักษ์พลังงาน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-conservation')), 'number', 'ลูกบอลมวล 1 กิโลกรัมตกลงมาจากความสูง 5 เมตร (ไม่คิดแรงต้านอากาศ ใช้ g = 10 เมตร/วินาที²) เมื่อถึงพื้นลูกบอลมีพลังงานจลน์เท่ากับกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":50,"tolerance":0.5}', 'ที่จุดสูงสุดมี Ep = mgh = 1 × 10 × 5 = 50 จูล เมื่อถึงพื้นพลังงานศักย์เปลี่ยนเป็นพลังงานจลน์ทั้งหมด จึงได้ 50 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-conservation')), 'number', 'ถ้าพลังงานศักย์โน้มถ่วง 100 จูลถูกเปลี่ยนเป็นพลังงานจลน์ทั้งหมด วัตถุจะได้รับพลังงานจลน์เท่ากับกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":100,"tolerance":0.5}', 'ตามกฎการอนุรักษ์พลังงาน พลังงานรวมคงที่ 100 จูล เมื่อเปลี่ยนเป็นพลังงานจลน์ทั้งหมดจึงเท่ากับ 100 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-work-energy'), 'jr-work-energy-kinetic-potential', 'พลังงานจลน์และพลังงานศักย์', 'พลังงานจลน์คือพลังงานที่สะสมอยู่ในวัตถุที่กำลังเคลื่อนที่ คำนวณจาก Ek = (1/2)mv² ขึ้นอยู่กับมวลและกำลังสองของอัตราเร็ว ส่วนพลังงานศักย์โน้มถ่วงคือพลังงานที่สะสมเนื่องจากตำแหน่งความสูง คำนวณจาก Ep = mgh โดย h คือความสูงจากระดับอ้างอิง วัตถุที่อยู่สูงและมีมวลมากจะมีพลังงานศักย์สะสมอยู่มาก ซึ่งพร้อมจะเปลี่ยนเป็นพลังงานจลน์เมื่อตกลงมา', 'junior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-kinetic-potential'), 'youtube', 'https://www.youtube.com/watch?v=5jYaDsv_scE', '5jYaDsv_scE', 'I know PHYSICS ep.5 - งานและพลังงาน (Part 2 : พลังงาน)', 'I know PHYSICs a little', 'https://www.youtube.com/channel/UC0qWWV4YLpxnAQGJ8ednXlA', 1);
