INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-kinetic-potential'), 'แบบทดสอบ: พลังงานจลน์และพลังงานศักย์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-kinetic-potential')), 'choice', 'พลังงานจลน์คือพลังงานของวัตถุในลักษณะใด', '["วัตถุที่อยู่นิ่ง","วัตถุที่กำลังเคลื่อนที่","วัตถุที่อยู่สูงขึ้นจากพื้น","พลังงานที่เกิดจากความร้อน"]', '1', 'พลังงานจลน์เป็นพลังงานของวัตถุที่เคลื่อนที่ คำนวณจาก Ek = ½mv² วัตถุที่เคลื่อนที่เร็วหรือมีมวลมากจึงมีพลังงานจลน์มาก', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-kinetic-potential')), 'choice', 'พลังงานศักย์โน้มถ่วงของวัตถุขึ้นกับปริมาณใดเป็นหลัก', '["ความเร็วของวัตถุ","มวลและความเร็วเท่านั้น","ขนาดของวัตถุเท่านั้น","มวล ความสูง และความเร่งโน้มถ่วง"]', '3', 'พลังงานศักย์โน้มถ่วงคำนวณจาก Ep = mgh จึงขึ้นกับมวล ความสูง และค่าความเร่งโน้มถ่วง g', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-kinetic-potential')), 'choice', 'ลูกบอลมวลเท่ากันสองลูก ลูกหนึ่งอยู่สูง 2 เมตร อีกลูกอยู่สูง 4 เมตรจากพื้น ข้อใดถูกต้อง', '["ลูกที่สูง 4 เมตรมีพลังงานศักย์มากกว่า","ลูกที่สูง 2 เมตรมีพลังงานศักย์มากกว่า","ลูกทั้งสองมีพลังงานศักย์เท่ากัน","ลูกที่สูง 4 เมตรมีพลังงานจลน์มากกว่า"]', '0', 'Ep = mgh มวลเท่ากันแต่สูงกว่าจึงมีพลังงานศักย์โน้มถ่วงมากกว่า', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-kinetic-potential')), 'number', 'วัตถุมวล 2 กิโลกรัม เคลื่อนที่ด้วยความเร็ว 3 เมตร/วินาที พลังงานจลน์เท่ากับกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":9,"tolerance":0.5}', 'Ek = ½mv² = ½ × 2 × 3² = 9 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-kinetic-potential')), 'number', 'วัตถุมวล 5 กิโลกรัม อยู่สูงจากพื้น 4 เมตร มีพลังงานศักย์โน้มถ่วงกี่จูล (ใช้ g = 10 เมตร/วินาที² ตอบเป็นจำนวนเต็ม)', NULL, '{"value":200,"tolerance":0.5}', 'Ep = mgh = 5 × 10 × 4 = 200 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-work-energy'), 'jr-work-energy-simple-machines', 'เครื่องกลอย่างง่าย', 'เครื่องกลอย่างง่ายเป็นอุปกรณ์ที่ช่วยอำนวยความสะดวกหรือผ่อนแรงในการทำงาน เช่น คาน รอก พื้นเอียง ลิ่ม สกรู และล้อกับเพลา การได้เปรียบเชิงกล (Mechanical Advantage, MA) คืออัตราส่วนระหว่างแรงต้านต่อแรงพยายาม (MA = W/E) แม้เครื่องกลจะช่วยผ่อนแรงโดยให้เราออกแรงน้อยลง แต่เราต้องออกแรงเป็นระยะทางที่ยาวขึ้น งานรวมที่ได้รับจึงไม่เคยมากกว่างานที่ป้อนเข้าไปเสมอ', 'junior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-simple-machines'), 'youtube', 'https://www.youtube.com/watch?v=8XePcyL34IY', '8XePcyL34IY', 'เครื่องกลอย่างง่าย (วิทยาศาสตร์ ม. 2 เล่ม 2 หน่วยที่ 5 บทที่ 1)', 'Proj14 ม.2', 'https://www.youtube.com/channel/UCkGQRzlwZFWkOin9SiP7JUQ', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-simple-machines'), 'youtube', 'https://www.youtube.com/watch?v=z30DLo0FYtY', 'z30DLo0FYtY', 'I know PHYSICS ep.5 - งานและพลังงาน (Part 4 : เครื่องกล & ประสิทธิภาพเครื่องกล)', 'I know PHYSICs a little', 'https://www.youtube.com/channel/UC0qWWV4YLpxnAQGJ8ednXlA', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-simple-machines'), 'newton-force', 'จำลองการผ่อนแรงของเครื่องกลอย่างง่ายเมื่อออกแรงลากมวล', '{"force":{"min":10,"max":80,"default":30},"mass":{"min":2,"max":18,"default":6},"friction":{"min":0.05,"max":0.6,"step":0.05,"default":0.15}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-simple-machines'), 'balance-force', 'ปรับการได้เปรียบเชิงกลของแรงและมวลให้ความเร่งเข้าเป้าหมาย', '{"targetAcc":[1.2,4],"tolerance":0.17,"force":{"min":16,"max":84,"default":36},"mass":{"min":2,"max":10,"default":5}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-simple-machines'), 'แบบทดสอบ: เครื่องกลอย่างง่าย', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-simple-machines')), 'choice', 'เครื่องกลอย่างง่ายช่วยให้ทำงานได้สะดวกขึ้น โดยอาศัยหลักใด', '["ลดงานทั้งหมดที่ต้องทำลง","ทำลายพลังงานส่วนเกิน","สร้างพลังงานใหม่ขึ้นมา","เปลี่ยนแรงหรือทิศทางของแรงให้เหมาะกับการใช้งาน"]', '3', 'เครื่องกลอย่างง่ายไม่ได้ลดงานรวมลง แต่ช่วยให้ออกแรงน้อยลง ได้เปรียบเชิงกล หรือเปลี่ยนทิศทางของแรง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-simple-machines')), 'choice', 'ข้อใดคือเครื่องกลอย่างง่าย', '["มอเตอร์ไฟฟ้า","รอก","เครื่องกำเนิดไฟฟ้า","แบตเตอรี่"]', '1', 'รอกเป็นเครื่องกลอย่างง่ายชนิดหนึ่ง ช่วยเปลี่ยนทิศทางของแรง ส่วนมอเตอร์และเครื่องกำเนิดไฟฟ้าเป็นเครื่องจักรที่ซับซ้อนกว่า', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-simple-machines')), 'choice', 'คานอันหนึ่งใช้จุดหมุนตรงกลาง หากออกแรงน้อยที่ปลายด้านหนึ่งเพื่อยกของอีกด้าน ผลเป็นอย่างไร', '["ไม่สามารถยกของได้","ต้องออกแรงมากกว่าเดิมเสมอ","ออกแรงน้อยลงได้ แต่ต้องดันเป็นระยะทางไกลขึ้น","งานที่ต้องใช้ลดลงเหลือครึ่งหนึ่ง"]', '2', 'คานให้ข้อได้เปรียบเชิงกล ออกแรงน้อยลงแต่ระยะทางยาวขึ้น ผลคูณแรงกับระยะทาง (งาน) ยังคงเท่าเดิมตามกฎการอนุรักษ์พลังงาน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-simple-machines')), 'number', 'รอกเดี่ยวตายตัวใช้เปลี่ยนทิศทางของแรงเท่านั้น ถ้าต้องการยกของหนัก 50 นิวตัน ต้องออกแรงดึงอย่างน้อยกี่นิวตัน (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":50,"tolerance":0.5}', 'รอกเดี่ยวตายตัวไม่ให้ข้อได้เปรียบเชิงกล จึงต้องออกแรงเท่ากับน้ำหนักของคือ 50 นิวตัน เพียงแต่เปลี่ยนทิศทางจากดึงขึ้นเป็นดึงลง', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'jr-work-energy-simple-machines')), 'number', 'คานอันหนึ่งออกแรง 20 นิวตันยกของหนัก 40 นิวตันได้ อัตราได้เปรียบเชิงกลเท่ากับเท่าใด (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'อัตราได้เปรียบเชิงกล = น้ำหนักที่ยก ÷ แรงที่ใช้ = 40 ÷ 20 = 2 เท่า', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'jr-work-energy'), 'jr-work-energy-work-power', 'งานและกำลัง', 'งานในทางวิทยาศาสตร์เกิดขึ้นเมื่อมีแรงกระทำต่อวัตถุแล้วทำให้วัตถุเคลื่อนที่ไปตามแนวแรง คำนวณได้จาก W = F s มีหน่วยเป็นจูล (J) หากออกแรงแต่ไม่มีการเคลื่อนที่ เช่น ดันกำแพง จะไม่ถือว่าเกิดงาน ส่วนกำลังคืออัตราการทำงานในหนึ่งหน่วยเวลา คำนวณจาก P = W/t มีหน่วยเป็นวัตต์ (W) เครื่องจักรที่มีกำลังมากสามารถทำงานปริมาณเท่ากันได้ในเวลาที่สั้นกว่า', 'junior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-work-power'), 'youtube', 'https://www.youtube.com/watch?v=v3rbY9zjel4', 'v3rbY9zjel4', 'งานและกำลัง (วิทยาศาสตร์ ม. 2 เล่ม 2 หน่วยที่ 5 บทที่ 1)', 'Proj14 ม.2', 'https://www.youtube.com/channel/UCkGQRzlwZFWkOin9SiP7JUQ', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-work-power'), 'youtube', 'https://www.youtube.com/watch?v=R1nMZjchfeY', 'R1nMZjchfeY', 'I know PHYSICS ep.5 - งานและพลังงาน (Part 1 : งานและกำลัง)', 'I know PHYSICs a little', 'https://www.youtube.com/channel/UC0qWWV4YLpxnAQGJ8ednXlA', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'jr-work-energy-work-power'), 'newton-force', 'วัดงานที่ทำได้และกำลังเฉลี่ยเมื่อออกแรงลากมวลให้เคลื่อนที่', '{"force":{"min":10,"max":85,"default":40},"mass":{"min":1,"max":14,"default":4},"friction":{"min":0,"max":0.5,"step":0.05,"default":0.1}}');
