INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-gas-laws')), 'choice', 'กฎของบอยล์กล่าวถึงความสัมพันธ์ระหว่างปริมาณใดที่อุณหภูมิคงที่', '["ความดันกับอุณหภูมิ","ความดันกับปริมาตร","ปริมาตรกับมวล","ความดันกับขนาดโมเลกุล"]', '1', 'กฎของบอยล์กล่าวว่า PV = ค่าคงที่ที่อุณหภูมิคงที่ ความดันแปรผกผันกับปริมาตร', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-gas-laws')), 'choice', 'ที่ความดันคงที่ ถ้าอุณหภูมิสัมบูรณ์ของแก๊สเพิ่มขึ้นเป็น 2 เท่า ปริมาตรจะเปลี่ยนอย่างไร', '["ลดลงครึ่งหนึ่ง","คงเดิม","เพิ่มขึ้นเป็น 2 เท่า","เพิ่มขึ้นเป็น 4 เท่า"]', '2', 'กฎของชาร์ล V/T = คงที่ ปริมาตรแปรผันตรงกับอุณหภูมิสัมบูรณ์ ที่ T เป็น 2 เท่า V จึงเป็น 2 เท่า', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-gas-laws')), 'choice', 'กฎของแก๊สข้อใดใช้ได้เมื่อจำนวนโมลคงที่', '["P1V1/T1 = P2V2/T2","P1V1 = P2 + V2","V1/T1 = P2/T2","P1T1 = V1T2"]', '0', 'กฎรวมของแก๊สสำหรับแก๊สปริมาณคงที่คือ P1V1/T1 = P2V2/T2 รวมกฎบอยล์และชาร์ลเข้าด้วยกัน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-gas-laws')), 'number', 'แก๊สมีปริมาตร 2 ลิตร ที่ความดัน 1 บรรยากาศ ถ้าอุณหภูมิคงที่และเพิ่มความดันเป็น 4 บรรยากาศ ปริมาตรใหม่เป็นกี่ลิตร (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":0.5,"tolerance":0.05}', 'กฎบอยล์ P1V1 = P2V2 → 1 × 2 = 4 × V2 → V2 = 0.5 ลิตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-gas-laws')), 'number', 'แก๊สมีปริมาตร 3 ลิตร ที่อุณหภูมิ 300 เคลวิน ความดันคงที่ ถ้าอุณหภูมิเพิ่มเป็น 600 เคลวิน ปริมาตรใหม่เป็นกี่ลิตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":6,"tolerance":0.5}', 'กฎชาร์ล V1/T1 = V2/T2 → 3/300 = V2/600 → V2 = 6 ลิตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'kinetic-theory'), 'kinetic-theory-ideal-gas', 'ทฤษฎีจลน์ของแก๊สและแก๊สอุดมคติ', 'ทฤษฎีจลน์ของแก๊สอธิบายพฤติกรรมระดับโมเลกุลโดยสมมติให้โมเลกุลของแก๊สมีขนาดเล็กมาก เคลื่อนที่แบบสุ่ม และเกิดการชนแบบยืดหยุ่นสมบูรณ์ ความดันของแก๊สเกิดจากการที่โมเลกุลพุ่งชนผนังภาชนะและถ่ายโอนโมเมนตัม โดยมีความสัมพันธ์ P = (1/3) * (N/V) * m * v_rms^2 แบบจำลองนี้ช่วยเชื่อมโยงปริมาณระดับจุลภาค เช่น พลังงานจลน์เฉลี่ยของโมเลกุล เข้ากับปริมาณมหภาค เช่น ความดันและอุณหภูมิสัมบูรณ์', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
