INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-ideal-gas')), 'choice', 'ความดันของแก๊สในภาชนะเกิดจากสิ่งใดตามทฤษฎีจลน์ของแก๊ส', '["แรงโน้มถ่วงระหว่างโมเลกุล","โมเลกุลหยุดนิ่งเฉย","โมเลกุลแก๊สชนผนังภาชนะ","การขยายตัวของภาชนะ"]', '2', 'โมเลกุลแก๊สเคลื่อนที่สุ่มตลอดเวลา การชนกับผนังภาชนะทำให้เกิดแรงและความดันต่อผนัง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-ideal-gas')), 'choice', 'สมบัติข้อใดของแก๊สอุดมคติ', '["อนุภาคไม่มีขนาดและไม่มีการดึงดูดระหว่างกัน","อนุภาคมีแรงดึงดูดกันมาก","อนุภาคมีขนาดใหญ่ใกล้เคียงภาชนะ","อนุภาคหยุดนิ่งไม่เคลื่อนที่"]', '0', 'แก๊สอุดมคติสมมติให้โมเลกุลเป็นจุดไม่มีปริมาตร และไม่มีการดึงดูดหรือผลักกันระหว่างโมเลกุล', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-ideal-gas')), 'choice', 'เมื่ออุณหภูมิของแก๊สเพิ่มขึ้น พลังงานจลน์เฉลี่ยของโมเลกุลเป็นอย่างไร', '["ลดลง","เพิ่มขึ้น","คงที่","เพิ่มแล้วลดลงสลับกัน"]', '1', 'พลังงานจลน์เฉลี่ยแปรผันตรงกับอุณหภูมิสัมบูรณ์ของแก๊ส เมื่ออุณหภูมิสูงขึ้นโมเลกุลเคลื่อนที่เร็วขึ้น', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-ideal-gas')), 'number', 'แก๊สอุดมคติมีจำนวนโมล 2 โมล ก๊าซมีค่าคงที่แก๊ส R = 8.3 จูล/โมล·เคลวิน ถ้าอุณหภูมิเป็น 300 เคลวิน พลังงานภายในของแก๊สอะตอมเดี่ยวเป็นกี่จูล (สูตร U = 1.5nRT ตอบเป็นจำนวนเต็ม)', NULL, '{"value":7470,"tolerance":0.5}', 'U = 1.5 × 2 × 8.3 × 300 = 1.5 × 2 × 2490 = 7470 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'kinetic-theory-ideal-gas')), 'number', 'ถ้าอุณหภูมิสัมบูรณ์ของแก๊สเพิ่มจาก 300 เคลวินเป็น 900 เคลวิน พลังงานจลน์เฉลี่ยของโมเลกุลเพิ่มขึ้นเป็นกี่เท่าของเดิม (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.05}', 'พลังงานจลน์เฉลี่ยแปรผันตรงกับ T 900/300 = 3 เท่า', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'kinetic-theory'), 'kinetic-theory-molecular-energy', 'พลังงานจลน์เฉลี่ยและอัตราเร็ว rms', 'พลังงานจลน์เฉลี่ยของโมเลกุลแก๊สอะตอมเดี่ยวขึ้นอยู่กับอุณหภูมิสัมบูรณ์เพียงอย่างเดียวตามสูตร E_k = (3/2) k_B T ส่งผลให้อัตราเร็วรากที่สองของกำลังสองเฉลี่ยหรืออัตราเร็ว rms มีค่าเป็น v_rms = sqrt(3RT / M) = sqrt(3 k_B T / m) ที่อุณหภูมิเท่ากัน แก๊สที่มีมวลโมเลกุลน้อยกว่าจะมีความเร็วเฉลี่ยสูงกว่าแก๊สที่มีมวลโมเลกุลมาก ความสัมพันธ์นี้ยืนยันว่าอุณหภูมิคือตัวแทนพลังงานจลน์ของการเคลื่อนที่ของอนุภาค', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'kinetic-theory-molecular-energy'), 'youtube', 'https://www.youtube.com/watch?v=5yXbE7ako1A', '5yXbE7ako1A', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.8 (อัตราเร็วเฉลี่ยและพลังงานจลน์เฉลี่ยของแก๊ส)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'kinetic-theory-molecular-energy'), 'youtube', 'https://www.youtube.com/watch?v=gn3GpEfX08U', 'gn3GpEfX08U', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.7(ทฤษฎีจลน์แก๊ส,แก๊สอุดมคติ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
