INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-convex-concave-images'), 'youtube', 'https://www.youtube.com/watch?v=FfU1_TOUb3I', 'FfU1_TOUb3I', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.8 (เลนส์นูนและเลนส์นูน แบบฝึกหัด)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
