INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-eye-vision'), 'แบบทดสอบ: ตาและการมองเห็น', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-eye-vision')), 'choice', 'ภาพที่เกิดบนเรตินาของตาเป็นภาพชนิดใด', '["ภาพเสมือนหัวตั้ง","ภาพจริงหัวกลับ","ภาพจริงหัวตั้ง","ภาพเสมือนหัวกลับ"]', '1', 'เลนส์ตาเป็นเลนส์นูน เมื่อมองวัตถุไกลเกิดภาพจริงเล็กหัวกลับบนเรตินา สมองจึงกลับภาพให้เรารู้สึกตั้งตรง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-eye-vision')), 'choice', 'คนสายตาสั้นมองวัตถุไกลไม่ชัด เพราะภาพตกอยู่บริเวณใด', '["หน้าเรตินา","หลังเรตินา","ที่เรตินาพอดี","ที่กระจกตา"]', '0', 'สายตาสั้นลูกตายาวเกินไป ภาพของวัตถุไกลจึงเกิดหน้าเรตินา ต้องใช้แว่นเลนส์เว้ากระจายแสงให้ภาพถอยหลัง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-eye-vision')), 'choice', 'แว่นตาที่เหมาะกับคนสายตาสั้นคือแว่นชนิดใด', '["แว่นเลนส์นูน","แว่นเลนส์เรียบ","แว่นเลนส์เว้า","แว่นสองชั้นรูปร่างใดก็ได้"]', '2', 'สายตาสั้นภาพเกิดหน้าเรตินา ต้องใช้เลนส์เว้ากระจายรังสีให้ภาพถอยหลัง ตกบนเรตินาพอดี', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-eye-vision')), 'number', 'สายตาสั้นมองไกลสุดชัดที่ 2.5 เมตร ต้องใช้แว่นที่ทำให้วัตถุไกลสุดปรากฏว่าอยู่ห่าง 2.5 เมตร กำลังของเลนส์แว่นเป็นกี่ไดออปเตอร์โดยประมาณ (ตอบทศนิยม 1 ตำแหน่ง ใช้ f = 2.5 เมตร)', NULL, '{"value":0.4,"tolerance":0.05}', 'P = 1/f = 1/2.5 = 0.4 ไดออปเตอร์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-eye-vision')), 'number', 'แว่นสายตายาวมีเลนส์กำลัง +5 ไดออปเตอร์ ความยาวโฟกัสเป็นกี่เมตร (ตอบทศนิยม 2 ตำแหน่ง)', NULL, '{"value":0.2,"tolerance":0.005}', 'f = 1/P = 1/5 = 0.2 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'lenses'), 'lenses-optical-instruments', 'ทัศนอุปกรณ์', 'ทัศนูปกรณ์ทางแสง เช่น กล้องจุลทรรศน์และกล้องโทรทรรศน์ ใช้การรวมกันของเลนส์นูนอย่างน้อยสองชิ้น คือ เลนส์ใกล้วัตถุและเลนส์ใกล้ตา เลนส์ใกล้วัตถุจะสร้างภาพจริงขนาดขยาย จากนั้นภาพนี้จะทำหน้าที่เป็นวัตถุให้แก่เลนส์ใกล้ตาเพื่อขยายต่อเป็นภาพเสมือนขนาดใหญ่ กำลังขยายเชิงมุมรวมของกล้องคำนวณได้จากผลคูณของกำลังขยายจากเลนส์แต่ละชุด M_รวม = M_obj * M_eye ซึ่งช่วยให้มองเห็นวัตถุขนาดเล็กมากหรือวัตถุที่อยู่ไกลลิบได้อย่างละเอียด', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments'), 'youtube', 'https://www.youtube.com/watch?v=FfU1_TOUb3I', 'FfU1_TOUb3I', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.8(เลนส์นูนและเลนส์นูน แบบฝึกหัด)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
