INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments'), 'lens-focus', 'ปรับระยะเลนส์ในกล้องทัศนูปกรณ์ให้ภาพตกบนระนาบสายตา', '{"tolerance":1.3,"targetDistance":[23,52],"focalLength":15,"objectDistance":{"min":18,"max":60,"default":22}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments'), 'แบบทดสอบ: ทัศนอุปกรณ์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments')), 'choice', 'กล้องจุลทรรศน์ประกอบด้วยเลนส์สำคัญสองชุดใด', '["เลนส์เว้าสองตัวเท่ากัน","เลนส์นูนกับกระจกโค้งเว้า","เลนส์ใกล้วัตถุและเลนส์ใกล้ตา","เลนส์ตาและเลนส์แว่นตา"]', '2', 'กล้องจุลทรรศน์ใช้เลนส์ใกล้วัตถุสร้างภาพกลางขนาดใหญ่ แล้วเลนส์ใกล้ตาขยายอีกครั้ง ความยาว/การขยายจึงยิ่งใหญ่', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments')), 'choice', 'ภาพขั้นกลางของวัตถุที่เกิดจากเลนส์ใกล้วัตถุของกล้องจุลทรรศน์มีลักษณะใด', '["ภาพเสมือนหัวกลับ","ภาพจริงหัวกลับ","ภาพจริงหัวตั้ง","ภาพเสมือนหัวตั้ง"]', '1', 'เลนส์ใกล้วัตถุวางวัตถุไว้เกินความยาวโฟกัสเล็กน้อยให้เกิดภาพจริงหัวกลับขยาย แล้วเลนส์ใกล้ตาขยายต่อ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments')), 'choice', 'คนสายตายาวควรมองวัตถุใกล้ด้วยแว่นตาที่มีเลนส์ชนิดใด', '["เลนส์นูน","เลนส์เว้า","เลนส์ทรงกระบอก","เลนส์แก้วใสธรรมดา"]', '0', 'สายตายาวมองเห็นไกลชัดแต่ใกล้ไม่ชัด แว่นตาที่ใช้คือแว่นเลนส์นูนรวมแสงช่วยรวมรังสีให้ตกบนเรตินาพอดี', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments')), 'number', 'กล้องจุลทรรศน์มีเลนส์ใกล้วัตถุขยาย 20 เท่า และเลนส์ใกล้ตาขยาย 10 เท่า กำลังขยายรวมเป็นกี่เท่า (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":200,"tolerance":0.5}', 'กำลังขยายรวมเท่ากับผลคูณของกำลังขยายทั้งสอง = 20 × 10 = 200 เท่า', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-optical-instruments')), 'number', 'แว่นตาอันหนึ่งมีความยาวโฟกัส 0.5 เมตร กำลังของเลนส์เป็นกี่ไดออปเตอร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.05}', 'กำลังของเลนส์ P = 1/f = 1/0.5 = 2 ไดออปเตอร์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'lenses'), 'lenses-power-diopters', 'กำลังของเลนส์ (ไดออปเตอร์)', 'กำลังของเลนส์ (P) คือปริมาณที่บ่งบอกความสามารถในการรวมแสงหรือกระจายแสงของเลนส์ นิยามจากส่วนกลับของความยาวโฟกัสในหน่วยเมตร P = 1/f(m) มีหน่วยเป็นไดออปเตอร์ (D) เลนส์นูนมีกำลังเป็นบวกช่วยแก้ปัญหาสายตายาว ส่วนเลนส์เว้ามีกำลังเป็นลบช่วยแก้ปัญหาสายตาสั้น เมื่อนำเลนส์บางหลายชิ้นมาวางชิดกัน กำลังรวมของระบบเลนส์จะเท่ากับผลรวมทางพีชคณิตของแต่ละชิ้น P_รวม = P1 + P2', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-power-diopters'), 'youtube', 'https://www.youtube.com/watch?v=kdgiKtv-lCQ', 'kdgiKtv-lCQ', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.9 (สรุปสูตรเตรียมสอบ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
