INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-power-diopters'), 'แบบทดสอบ: กำลังของเลนส์ (ไดออปเตอร์)', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-power-diopters')), 'choice', 'เลนส์นูนมีความยาวโฟกัส 0.5 เมตร กำลังของเลนส์เท่ากับเท่าใด', '["0.5 ไดออปเตอร์","2 ไดออปเตอร์","5 ไดออปเตอร์","20 ไดออปเตอร์"]', '1', 'P = 1/f = 1/0.5 = 2 ไดออปเตอร์', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-power-diopters')), 'choice', 'เลนส์เว้ามีความยาวโฟกัสเป็นลบ กำลังของเลนส์เว้าเป็นแบบใด', '["เป็นบวก","เป็นลบ","เป็นศูนย์","ขึ้นกับขนาดของเลนส์"]', '1', 'เนื่องจากความยาวโฟกัสเลนส์เว้าเป็นลบ กำลัง P = 1/f จึงเป็นลบด้วย', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-power-diopters')), 'choice', 'กำลังของเลนส์ P = 1/f เมื่อ f ต้องมีหน่วยเป็นอะไร', '["เซนติเมตร","มิลลิเมตร","เมตร","กิโลเมตร"]', '2', 'กำลังมีหน่วยไดออปเตอร์เมื่อ f อยู่ในหน่วยเมตร ต้องแปลงความยาวโฟกัสเป็นเมตรเสมอ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-power-diopters')), 'number', 'เลนส์นูนมีความยาวโฟกัส 0.25 เมตร กำลังของเลนส์เท่ากับกี่ไดออปเตอร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 'P = 1/f = 1/0.25 = 4 ไดออปเตอร์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-power-diopters')), 'number', 'เลนส์มีความยาวโฟกัส 0.2 เมตร กำลังของเลนส์เท่ากับกี่ไดออปเตอร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":5,"tolerance":0.5}', 'P = 1/f = 1/0.2 = 5 ไดออปเตอร์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'lenses'), 'lenses-thin-lens', 'เลนส์บางและสมการเลนส์', 'สมการเลนส์บาง 1/f = 1/s + 1/s'' อธิบายความสัมพันธ์ระหว่างความยาวโฟกัส (f) ระยะวัตถุ (s) และระยะภาพ (s'') โดยใช้เครื่องหมายบวกสำหรับเลนส์นูนและภาพจริง เครื่องหมายลบสำหรับเลนส์เว้าและภาพเสมือน อัตราส่วนขนาดภาพต่อขนาดวัตถุเรียกว่ากำลังขยาย m = y''/y = -s''/s ซึ่งบอกทั้งขนาดสัมพัทธ์และการกลับทิศของภาพ สมการนี้เป็นเครื่องมือพื้นฐานในการคำนวณและออกแบบระบบทัศนูปกรณ์ต่างๆ', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-thin-lens'), 'youtube', 'https://www.youtube.com/watch?v=_MpAHoSyP04', '_MpAHoSyP04', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.7 (เลนส์นูน,เลนส์เว้า)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-thin-lens'), 'youtube', 'https://www.youtube.com/watch?v=FfU1_TOUb3I', 'FfU1_TOUb3I', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.8 (เลนส์นูนและเลนส์นูน แบบฝึกหัด)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-thin-lens'), 'thin-lens', 'จำลองรังสีแสงผ่านเลนส์บางตามสมการ 1/f = 1/s + 1/s''', '{"objectDistance":{"min":10,"max":60,"step":1,"default":28},"focalLength":{"min":8,"max":25,"step":1,"default":12},"isConcave":false}');
