INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'lenses-thin-lens'), 'แบบทดสอบ: เลนส์บางและสมการเลนส์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-thin-lens')), 'choice', 'เลนส์นูนมีสมบัติต่อแสงที่ผ่านอย่างไร', '["รวมแสงเข้าหาจุดโฟกัส","แยกแสงออกจากกัน","ดูดกลืนแสง","ไม่เปลี่ยนทิศแสง"]', '0', 'เลนส์นูน (convex/converging lens) รวมแสงคู่ขนานเข้าหาจุดโฟกัสหลังเลนส์ จึงมีความยาวโฟกัสเป็นบวก', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-thin-lens')), 'choice', 'สมการเลนส์บางที่สัมพันธ์ระยะโฟกัส f ระยะวัตถุ s และระยะภาพ s'' คือข้อใด', '["f = s + s''","1/f = 1/s + 1/s''","f = s − s''","1/f = s + s''"]', '1', 'สมการเลนส์บางคือ 1/f = 1/s + 1/s'' ใช้กับเลนส์บางทั้งนูนและเว้าโดยใช้เครื่องหมายตามหลักการ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-thin-lens')), 'choice', 'เลนส์นูนมีความยาวโฟกัส 10 เซนติเมตร วางวัตถุไว้หน้าเลนส์ 30 เซนติเมตร จะได้ระยะภาพเท่าใด', '["7.5 เซนติเมตร","20 เซนติเมตร","15 เซนติเมตร","40 เซนติเมตร"]', '2', '1/10 = 1/30 + 1/s'' → 1/s'' = 1/10 − 1/30 = 2/30 → s'' = 15 เซนติเมตร', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-thin-lens')), 'number', 'เลนส์นูนมีความยาวโฟกัส 15 เซนติเมตร วางวัตถุไว้หน้าเลนส์ 30 เซนติเมตร ระยะภาพเท่ากับกี่เซนติเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":30,"tolerance":0.5}', '1/15 = 1/30 + 1/s'' → 1/s'' = 1/15 − 1/30 = 1/30 → s'' = 30 เซนติเมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'lenses-thin-lens')), 'number', 'เลนส์นูนมีความยาวโฟกัส 20 เซนติเมตร วางวัตถุไว้หน้าเลนส์ 60 เซนติเมตร ระยะภาพเท่ากับกี่เซนติเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":30,"tolerance":0.5}', '1/20 = 1/60 + 1/s'' → 1/s'' = 1/20 − 1/60 = 2/60 → s'' = 30 เซนติเมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'reflection-refraction'), 'light-reflection', 'การสะท้อนของแสง: กฎการสะท้อน', 'การสะท้อนของแสงเกิดขึ้นเมื่อรังสีแสงกระทบผิวรอยต่อของตัวกลางแล้วเบนกลับสู่ตัวกลางเดิม โดยเป็นไปตามกฎการสะท้อน คือ มุมตกกระทบเท่ากับมุมสะท้อน (θ_i = θ_r) และรังสีตกกระทบ เส้นแนวฉาก กับรังสีสะท้อนอยู่ในระนาบเดียวกันเสมอ สำหรับกระจกเงาราบ จะเกิดภาพเสมือนที่ระยะภาพเท่ากับระยะวัตถุ (s'' = s) ขนาดภาพเท่ากับขนาดวัตถุ (m = 1) และมีสมบัติกลับซ้ายขวาหรือปรัศวภาควิโลม', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'light-reflection'), 'youtube', 'https://www.youtube.com/watch?v=OWvMKjP-d1s', 'OWvMKjP-d1s', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.1 (สมบัติของแสง,การสะท้อนของแสง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
