INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'light-reflection')), 'choice', 'กฎการสะท้อนของแสงกล่าวว่าอย่างไร', '["มุมตกกระทบเท่ากับมุมสะท้อน","มุมตกกระทบมากกว่ามุมสะท้อน","มุมตกกระทบน้อยกว่ามุมสะท้อน","มุมสะท้อนเป็น 90 องศาเสมอ"]', '0', 'กฎการสะท้อน: มุมตกกระทบเท่ากับมุมสะท้อน และรังสีตกกระทบ รังสีสะท้อน กับเส้นปกติอยู่ในระนาบเดียวกัน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'light-reflection')), 'number', 'แสงตกกระทบกระจกเงาระนาบด้วยมุมตกกระทบ 35 องศา มุมสะท้อนเท่ากับกี่องศา', NULL, '{"value":35,"tolerance":0.5}', 'มุมสะท้อนเท่ากับมุมตกกระทบ จึงเป็น 35 องศา', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'light-reflection')), 'choice', 'มุมตกกระทบวัดจากเส้นใด', '["ผิวของกระจก","เส้นปกติ ซึ่งตั้งฉากกับผิวกระจก","แนวระดับ","รังสีสะท้อน"]', '1', 'มุมตกกระทบและมุมสะท้อนวัดจากเส้นปกติ ไม่ได้วัดจากผิวกระจก', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'light-reflection')), 'number', 'รังสีแสงตกกระทบกระจกเงาระนาบทำมุม 30 องศากับผิวกระจก มุมสะท้อนมีค่ากี่องศา (วัดจากเส้นปกติ)', NULL, '{"value":60,"tolerance":0.5}', 'มุมที่ทำกับผิวกระจกคือ 30 องศา จึงทำมุม 90 − 30 = 60 องศากับเส้นปกติ มุมตกกระทบจึงเป็น 60 องศา และมุมสะท้อนเท่ากับ 60 องศา', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'light-reflection')), 'choice', 'เมื่อแสงตกตั้งฉากกับกระจกเงาระนาบ (มุมตกกระทบ 0 องศา) รังสีสะท้อนเป็นอย่างไร', '["สะท้อนกลับตามแนวเดิม","สะท้อนทำมุม 90 องศา","ทะลุผ่านกระจก","หายไป"]', '0', 'มุมตกกระทบ 0 องศา มุมสะท้อนจึงเป็น 0 องศาด้วย รังสีสะท้อนกลับไปตามแนวเดิม', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'magnetism'), 'magnetism-charge-motion-in-field', 'การเคลื่อนที่ของประจุในสนามแม่เหล็ก', 'เมื่ออนุภาคมีประจุเคลื่อนที่ตั้งฉากกับสนามแม่เหล็กสม่ำเสมอ แรงแม่เหล็ก F = qvB จะมีทิศตั้งฉากกับความเร็วตลอดเวลา จึงทำหน้าที่เป็นแรงสู่ศูนย์กลาง F_c = m*v^2/R ส่งผลให้อนุภาคเคลื่อนที่เป็นวงกลมด้วยอัตราเร็วคงที่ รัศมีความโค้งของวงโคจรหาได้จาก R = mv/(qB) คาบของการเคลื่อนที่ T = 2*pi*m/(qB) จะเป็นอิสระจากอัตราเร็วของอนุภาค หลักการนี้นำไปใช้สร้างอุปกรณ์เร่งอนุภาคไซโคลทรอนและเครื่องแมสสเปกโตรมิเตอร์สำหรับแยกไอโซโทป', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-charge-motion-in-field'), 'youtube', 'https://www.youtube.com/watch?v=mcKqt6hLbgg', 'mcKqt6hLbgg', 'ฟิสิกส์ ม.6 บทที่ 15 แม่เหล็กและไฟฟ้า ep.2 (แรงที่กระทำต่อประจุที่เคลื่อนที่ในสนามแม่เหล็ก)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-charge-motion-in-field'), 'magnetic-induction', 'วิเคราะห์รัศมีวงโคจรของประจุในสนามแม่เหล็กสม่ำเสมอ', '{"bField":{"min":0.3,"max":1.8,"step":0.1,"default":0.9},"speed":{"min":3,"max":18,"step":1,"default":12}}');
