INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-charge-motion-in-field')), 'choice', 'ประจุเคลื่อนที่ตั้งฉากกับสนามแม่เหล็กสม่ำเสมอ วิถีการเคลื่อนที่ของประจุเป็นแนวใด', '["วงกลม","พาราโบลา","ไซน์","เส้นตรง"]', '0', 'แรงแม่เหล็กตั้งฉากกับความเร็วเสมอและทำหน้าที่เป็นแรงสู่ศูนย์กลาง ทำให้ประจุเคลื่อนที่เป็นวงกลมด้วยรัศมีคงที่ R = mv/(qB)', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-charge-motion-in-field')), 'choice', 'จาก R = mv/(qB) ถ้าเพิ่มความเร็วของประจุเป็น 2 เท่า โดยสนามและประจุคงที่ รัศมีวงโคจรจะเปลี่ยนเป็นกี่เท่า', '["เท่าเดิม","2 เท่า","1/2 เท่า","4 เท่า"]', '1', 'R = mv/(qB) รัศมีแปรผันตรงกับความเร็ว v เมื่อ v เป็น 2 เท่า R จึงเป็น 2 เท่า', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-charge-motion-in-field')), 'choice', 'เหตุใดแรงแม่เหล็กจึงไม่เพิ่มอัตราเร็วของประจุที่เคลื่อนที่ในสนามแม่เหล็กสม่ำเสมอ', '["ประจุเสียพลังงานเสมอ","แรงแม่เหล็กมีค่าน้อยมาก","แรงแม่เหล็กตั้งฉากกับความเร็ว จึงทำงานเป็นศูนย์","แรงแม่เหล็กขนานกับความเร็ว"]', '2', 'แรงแม่เหล็กตั้งฉากกับการกระจัดเสมอ งานที่ทำจึงเป็นศูนย์ อัตราเร็ว (ขนาดความเร็ว) จึงไม่เปลี่ยน มีเพียงทิศทางที่เปลี่ยน ทำให้เคลื่อนที่วนเป็นวงกลม', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-charge-motion-in-field')), 'number', 'ประจุ q เคลื่อนที่ตั้งฉากกับสนามแม่เหล็กสม่ำเสมอด้วยความเร็ว v รัศมีวงโคจร R กำหนด R = mv/(qB) ถ้าประจุเดิมเคลื่อนที่ด้วยความเร็ว 2 เท่า รัศมีวงโคจรเปลี่ยนเป็นกี่เท่าของเดิม (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.05}', 'R แปรผันตรงกับความเร็ว R = mv/(qB) เมื่อ v เป็น 2 เท่า R จึงเป็น 2 เท่า', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-charge-motion-in-field')), 'number', 'อนุภาคมีรัศมีวงโคจร 1 เมตรในสนามแม่เหล็ก ถ้าเพิ่มความแรงสนามแม่เหล็กเป็น 2 เท่า โดยมวลและความเร็วคงที่ รัศมีวงโคจรใหม่เป็นกี่เมตร (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":0.5,"tolerance":0.05}', 'R แปรผกผันกับ B R = mv/(qB) เมื่อ B เป็น 2 เท่า R เหลือครึ่งหนึ่ง = 0.5 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'magnetism'), 'magnetism-field-force-moving-charge', 'สนามแม่เหล็กและแรงต่อประจุเคลื่อนที่', 'เมื่ออนุภาคมีประจุไฟฟ้า q เคลื่อนที่ด้วยความเร็ว v เข้าไปในสนามแม่เหล็กสม่ำเสมอ B จะเกิดแรงแม่เหล็ก (Magnetic Force) กระทำต่ออนุภาคนั้น ขนาดของแรงคำนวณได้จากสมการ F = q*v*B*sin(theta) โดย theta คือมุมระหว่างเวกเตอร์ความเร็ว v กับสนามแม่เหล็ก B ทิศทางของแรงหาได้จากกฎมือขวา โดยนิ้วทั้งสี่ชี้ตามทิศความเร็ว วนไปหาสนามแม่เหล็ก นิ้วหัวแม่มือจะชี้ทิศแรงสำหรับประจุบวก และตรงกันข้ามสำหรับประจุลบ ถ้าประจุเคลื่อนที่ขนานกับสนาม แรงจะเป็นศูนย์', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-field-force-moving-charge'), 'youtube', 'https://www.youtube.com/watch?v=mcKqt6hLbgg', 'mcKqt6hLbgg', 'ฟิสิกส์ ม.6 บทที่ 15 แม่เหล็กและไฟฟ้า ep.2 (แรงที่กระทำต่อประจุที่เคลื่อนที่ในสนามแม่เหล็ก)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-field-force-moving-charge'), 'magnetic-induction', 'จำลองแรงแม่เหล็กกระทำต่ออนุภาคประจุที่กำลังเคลื่อนที่', '{"bField":{"min":0.2,"max":2,"step":0.1,"default":1},"speed":{"min":2,"max":20,"step":1,"default":8}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-field-force-moving-charge'), 'quantum-lab', 'ทดลองจูนระดับความถี่เพื่อวิเคราะห์แรงกระทำต่อประจุ', '{"targetEk":[0.8,2.8],"workFunction":2.1,"tolerance":0.15,"frequency":{"min":4,"max":15,"step":0.2,"default":7.2}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-field-force-moving-charge'), 'แบบทดสอบ: สนามแม่เหล็กและแรงต่อประจุเคลื่อนที่', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-field-force-moving-charge')), 'choice', 'แรงแม่เหล็กที่กระทำต่อประจุเคลื่อนที่ในสนามแม่เหล็ก คำนวณได้จากสูตรใดเมื่อความเร็วตั้งฉากกับสนาม', '["F = qvB","F = mg","F = qv²B","F = qE"]', '0', 'แรงแม่เหล็กต่อประจุเคลื่อนที่ F = qvB sin θ เมื่อ θ = 90 องศา sin θ = 1 จึง F = qvB แรงนี้ตั้งฉากกับทั้งความเร็วและสนามแม่เหล็ก', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-field-force-moving-charge')), 'choice', 'ถ้าประจุเคลื่อนที่ขนานกับทิศของสนามแม่เหล็ก แรงแม่เหล็กที่กระทำต่อประจุมีค่าเท่าใด', '["ครึ่งหนึ่งของ qvB","เป็นศูนย์","เท่ากับ qvB²","เท่ากับ qvB"]', '1', 'F = qvB sin θ เมื่อ θ = 0 องศา sin θ = 0 แรงจึงเป็นศูนย์ แรงแม่เหล็กเกิดขึ้นเมื่อประจุเคลื่อนที่ตั้งฉากหรือเฉียงกับสนามเท่านั้น', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-field-force-moving-charge')), 'choice', 'แรงแม่เหล็กที่กระทำต่อประจุเคลื่อนที่มีทิศทางเป็นอย่างไรเมื่อเทียบกับทิศการเคลื่อนที่', '["ขนานกับการเคลื่อนที่เสมอ","ในทิศเดียวกับการเคลื่อนที่","ตรงข้ามกับการเคลื่อนที่","ตั้งฉากกับการเคลื่อนที่เสมอ"]', '3', 'แรงแม่เหล็กตั้งฉากกับทิศของความเร็วและสนามแม่เหล็กเสมอ งานที่ทำจึงเป็นศูนย์ทำให้ความเร็วของประจุไม่เปลี่ยนขนาด แต่เปลี่ยนทิศเท่านั้น', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-field-force-moving-charge')), 'number', 'ประจุ 3 ไมโครคูลอมบ์ เคลื่อนที่ด้วยความเร็ว 2 เมตร/วินาที ตั้งฉากกับสนามแม่เหล็ก 0.5 เทสลา แรงแม่เหล็กมีขนาดกี่ไมโครนิวตัน (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'F = qvB = 3 × 2 × 0.5 = 3 ไมโครนิวตัน เมื่อใช้ q ในหน่วยไมโครคูลอมบ์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-field-force-moving-charge')), 'number', 'ประจุ 5 ไมโครคูลอมบ์ เคลื่อนที่ด้วยความเร็ว 4 เมตร/วินาที ตั้งฉากกับสนามแม่เหล็ก 0.1 เทสลา แรงแม่เหล็กมีขนาดกี่ไมโครนิวตัน (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'F = qvB = 5 × 4 × 0.1 = 2 ไมโครนิวตัน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'magnetism'), 'magnetism-field-from-current', 'สนามแม่เหล็กจากกระแสไฟฟ้า', 'กระแสไฟฟ้าที่ไหลผ่านตัวนำจะเหนี่ยวนำให้เกิดสนามแม่เหล็กขึ้นรอบตัวนำนั้นเสมอ สำหรับลวดตรงยาว เส้นสนามแม่เหล็กจะวนเป็นวงกลมรอบสายไฟ ทิศทางหาได้จากกฎมือขวาโดยให้นิ้วหัวแม่มือชี้ตามทิศกระแส และนิ้วทั้งสี่วนตามทิศสนามแม่เหล็ก ขนาดสนามแม่เหล็กแปรผันตามกระแส I และแปรผกผันกับระยะห่าง r หากนำขดลวดมาพันเป็นเกลียวโซเลนอยด์ จะเกิดสนามแม่เหล็กสม่ำเสมอภายในขดลวด คล้ายกับแท่งแม่เหล็กถาวร', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-field-from-current'), 'youtube', 'https://www.youtube.com/watch?v=s7A5gGmsCEk', 's7A5gGmsCEk', 'ฟิสิกส์ ม.6 บทที่ 15 แม่เหล็กและไฟฟ้า ep.3(แรงแม่เหล็ก, สนามแม่เหล็กที่เกิดจากกระไฟไหลในตัวนำ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-field-from-current'), 'magnetic-induction', 'จำลองสนามแม่เหล็กที่เกิดขึ้นรอบสายไฟและขดลวดโซเลนอยด์', '{"bField":{"min":0.3,"max":2,"step":0.1,"default":0.7},"speed":{"min":4,"max":20,"step":1,"default":14}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-field-from-current'), 'quantum-lab', 'ปรับเทียบสนามแม่เหล็กจากกระแสไฟฟ้าให้บรรลุเป้าหมาย', '{"targetEk":[0.9,2.9],"workFunction":2,"tolerance":0.2,"frequency":{"min":5,"max":15,"step":0.2,"default":7.8}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-field-from-current'), 'แบบทดสอบ: สนามแม่เหล็กจากกระแสไฟฟ้า', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-field-from-current')), 'choice', 'กฎมือขวาสำหรับเส้นลวดตรงที่มีกระแส ใช้นิ้วหัวแม่มือชี้ทิศกระแส นิ้วที่กำจะชี้ทิศของอะไร', '["ทิศของสนามแม่เหล็กรอบๆ ลวด","ทิศของกระแสไฟฟ้า","ทิศของแรงแม่เหล็ก","ทิศของการเคลื่อนที่ของประจุ"]', '0', 'สำหรับลวดตรง นิ้วหัวแม่มือชี้ทิศกระแส นิ้วที่กำรอบชี้ทิศสนามแม่เหล็กที่วนรอบลวดตามเข็มนาฬิกาหรือทวนเข็มตามทิศกระแส', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-field-from-current')), 'choice', 'สนามแม่เหล็กจากเส้นลวดตรงยาวที่กระแส I ไหล มีขนาดแปรผันกับระยะห่าง r จากลวดอย่างไร', '["แปรผกผันกับ r²","แปรผันตรงกับ r","แปรผกผันกับ r","ไม่ขึ้นกับ r"]', '2', 'B = μ₀I/(2πr) สนามแม่เหล็กจากลวดตรงยาวแปรผกผันกับระยะห่าง r ยิ่งไกลจากลวดสนามยิ่งอ่อนลงเป็นสัดส่วน 1/r', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-field-from-current')), 'choice', 'สนามแม่เหล็กภายในโซเลนอยด์ (ขดลวดยาว) ไม่แรงเท่าไรขึ้นกับปริมาณใด', '["เฉพาะความยาวลวด","เส้นผ่านศูนย์กลางของลวด","เฉพาะสีของฉนวน","จำนวนรอบต่อความยาวและกระแส"]', '3', 'สนามภายในโซเลนอยด์ B = μ₀nI โดย n คือจำนวนรอบต่อหน่วยความยาว และ I คือกระแส จึงขึ้นกับจำนวนรอบและกระแสที่ไหล', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-field-from-current')), 'number', 'เส้นลวดตรงยาวมีกระแส 4 แอมแปร์ สนามแม่เหล็กที่จุดห่างจากลวด 0.4 เมตร เป็นกี่ไมโครเทสลา โดยกำหนดให้ค่าคงที่รวมของสูตร B = k×I/r กับ k = 2 ไมโครเทสลา·เมตร/แอมแปร์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', 'B = k×I/r = 2×4/0.4 = 20 ไมโครเทสลา', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-field-from-current')), 'number', 'สนามแม่เหล็กที่จุดหนึ่งจากเส้นลวดตรงมีกระแส 4 แอมแปร์ เป็น 20 ไมโครเทสลา ถ้าเพิ่มกระแสเป็น 8 แอมแปร์ ที่จุดเดิมสนามเป็นกี่ไมโครเทสลา (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":40,"tolerance":0.5}', 'B แปรผันตรงกับกระแส 8/4 = 2 เท่า → 20×2 = 40 ไมโครเทสลา', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'magnetism'), 'magnetism-force-on-current-wire', 'แรงต่อลวดที่มีกระแส', 'เมื่อวางลวดตัวนำที่มีกระแสไฟฟ้าไหลผ่านเข้าไปในสนามแม่เหล็กสม่ำเสมอ B ลวดตัวนำจะได้รับแรงกระทำจากสนามแม่เหล็กเนื่องจากอิเล็กตรอนนำกำลังเคลื่อนที่ ขนาดของแรงแม่เหล็กที่กระทำต่อลวดความยาว L คำนวณได้จากสูตร F = I*L*B*sin(theta) โดย theta คือมุมระหว่างแนวทิศทางกระแสไฟฟ้ากับสนามแม่เหล็ก ทิศทางของแรงสามารถหาได้โดยใช้กฎมือขวา หลักการนี้เป็นพื้นฐานสำคัญในการประดิษฐ์มอเตอร์ไฟฟ้ากระแสตรง ลำโพง และกัลวาโนมิเตอร์', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-force-on-current-wire'), 'youtube', 'https://www.youtube.com/watch?v=nZoLcm6_i4A', 'nZoLcm6_i4A', 'ฟิสิกส์ ม.6 บทที่ 15 แม่เหล็กและไฟฟ้า ep.4(แรงกระทำต่อตัวนำที่มีกระแสไหลในสนามแม่เหล็ก,มอเตอร์ไฟฟ้า)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-force-on-current-wire'), 'magnetic-induction', 'จำลองแรงแม่เหล็กที่กระทำต่อเส้นลวดตัวนำมีกระแสไฟฟ้า', '{"bField":{"min":0.2,"max":1.6,"step":0.1,"default":0.6},"speed":{"min":2,"max":16,"step":1,"default":10}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-force-on-current-wire'), 'quantum-lab', 'ทดสอบการเบี่ยงเบนของลวดตัวนำผ่านระดับพลังงานโฟตอน', '{"targetEk":[0.6,2.5],"workFunction":1.8,"tolerance":0.15,"frequency":{"min":4,"max":14,"step":0.2,"default":6.8}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-force-on-current-wire'), 'แบบทดสอบ: แรงต่อลวดที่มีกระแส', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-force-on-current-wire')), 'choice', 'ลวดตัวนำยาว L ยาวตรง มีกระแส I ไหล วางตั้งฉากกับสนามแม่เหล็กสม่ำเสมอ B แรงแม่เหล็กที่กระทำต่อลวดเท่ากับเท่าใด', '["F = BI/L","F = BIL","F = B/LI","F = IL/B"]', '1', 'แรงต่อลวดตัวนำ F = BIL sin θ เมื่อลวดตั้งฉากกับสนาม θ = 90 องศา sin θ = 1 จึง F = BIL', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-force-on-current-wire')), 'choice', 'ถ้าเพิ่มกระแสไฟฟ้าที่ไหลผ่านลวดเป็น 2 เท่า โดยสนามแม่เหล็กและความยาวคงที่ แรงแม่เหล็กจะเป็นกี่เท่าของเดิม', '["1/2 เท่า","เท่าเดิม","2 เท่า","4 เท่า"]', '2', 'F = BIL แรงแปรผันตรงกับกระแส เมื่อ I เป็น 2 เท่า และ B และ L คงที่ F จึงเป็น 2 เท่า', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-force-on-current-wire')), 'choice', 'อุปกรณ์ใดทำงานโดยอาศัยแรงที่กระทำต่อขดลวดที่มีกระแสไฟฟ้าในสนามแม่เหล็ก', '["แบตเตอรี","ตัวเก็บประจุ","หม้อแปลง","มอเตอร์ไฟฟ้า"]', '3', 'มอเตอร์ไฟฟ้าทำงานโดยใช้แรงแม่เหล็กที่กระทำต่อขดลวดตัวนำที่มีกระแสไหลในสนามแม่เหล็ก ทำให้ขดลวดหมุนและเกิดการหมุนของเพลา', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-force-on-current-wire')), 'number', 'ลวดยาว 0.5 เมตร มีกระแส 4 แอมแปร์ วางตั้งฉากกับสนามแม่เหล็ก 1.5 เทสลา แรงแม่เหล็กที่กระทำต่อลวดเท่ากับกี่นิวตัน (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'F = BIL = 1.5 × 4 × 0.5 = 3 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-force-on-current-wire')), 'number', 'ลวดยาว 0.4 เมตร มีกระแส 2.5 แอมแปร์ วางตั้งฉากกับสนามแม่เหล็กสม่ำเสมอ ทำให้เกิดแรง 1 นิวตัน ความเข้มสนามแม่เหล็กมีค่ากี่เทสลา (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":1,"tolerance":0.05}', 'B = F/(IL) = 1 / (2.5 × 0.4) = 1 / 1.0 = 1 เทสลา', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'magnetism'), 'magnetism-parallel-wires', 'แรงระหว่างลวดคู่ขนาน', 'เมื่อวางลวดตัวนำยาวคู่ขนานสองเส้นให้ห่างกันระยะ d และมีกระแสไฟฟ้า I1 และ I2 ไหลผ่าน ลวดแต่ละเส้นจะสร้างสนามแม่เหล็กไปกระทำต่ออีกลวดหนึ่ง หากกระแสไฟฟ้าไหลในทิศทางเดียวกัน ลวดทั้งสองจะดูดกัน แต่หากกระแสไฟฟ้าไหลในทิศตรงข้ามกัน ลวดทั้งสองจะผลักกัน ขนาดของแรงต่อหนึ่งหน่วยความยาวหาได้จาก F/L = (mu_0*I1*I2)/(2*pi*d) ปรากฏการณ์นี้เป็นนิยามมาตรฐานสากลในอดีตของหน่วยวัดกระแสไฟฟ้าแอมแปร์', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-parallel-wires'), 'youtube', 'https://www.youtube.com/watch?v=s7A5gGmsCEk', 's7A5gGmsCEk', 'ฟิสิกส์ ม.6 บทที่ 15 แม่เหล็กและไฟฟ้า ep.3(แรงแม่เหล็ก, สนามแม่เหล็กที่เกิดจากกระไฟไหลในตัวนำ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-parallel-wires'), 'magnetic-induction', 'จำลองแรงกระทำระหว่างลวดตัวนำคู่ขนานที่มีกระแสไหล', '{"bField":{"min":0.2,"max":1.5,"step":0.1,"default":0.5},"speed":{"min":2,"max":15,"step":1,"default":6}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-parallel-wires'), 'quantum-lab', 'คำนวณสมดุลแรงดูดผลักระหว่างลวดคู่ขนานด้วยแล็บโฟตอน', '{"targetEk":[0.7,2.6],"workFunction":1.9,"tolerance":0.15,"frequency":{"min":4,"max":14,"step":0.2,"default":6.5}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'magnetism-parallel-wires'), 'แบบทดสอบ: แรงระหว่างลวดคู่ขนาน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-parallel-wires')), 'choice', 'ลวดคู่ขนานสองเส้นมีกระแสไหลในทิศเดียวกัน แรงระหว่างลวดเป็นแบบใด', '["ดึงดูดกัน","ผลักกันแล้วดึงดูดสลับกัน","ผลักกัน","เป็นศูนย์"]', '0', 'ลวดคู่ขนานที่กระแสไหลทิศเดียวกันจะดึงดูดกัน ส่วนกระแสทิศตรงข้ามจะผลักกัน เพราะสนามแม่เหล็กของลวดหนึ่งกระทำแรงต่อกระแสของอีกลวดหนึ่ง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-parallel-wires')), 'choice', 'ทุกเมตรของลวดคู่ขนานที่กระแสไหลทิศตรงข้าม ระยะห่างคงที่ แรงระหว่างลวดมีลักษณะอย่างไร', '["แรงขึ้นกับสีของลวด","ผลักกันทุกหน่วยความยาว","ดึงดูดกันทุกหน่วยความยาว","ไม่เกิดแรง"]', '1', 'กระแสทิศตรงข้ามในลวดคู่ขนานทำให้เกิดแรงผลักกันต่อหน่วยความยาว F/L = μ₀I₁I₂/(2πr) โดยทิศทางกำหนดด้วยกฎมือขวาและแรงแม่เหล็ก', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-parallel-wires')), 'choice', 'ถ้าเพิ่มระยะห่างระหว่างลวดคู่ขนานเป็น 2 เท่า แรงระหว่างลวดต่อหน่วยความยาวจะเปลี่ยนเป็นกี่เท่าของเดิม', '["เท่าเดิม","2 เท่า","1/2 เท่า","4 เท่า"]', '2', 'F/L = μ₀I₁I₂/(2πr) แรงแปรผกผันกับระยะห่าง r เมื่อ r เป็น 2 เท่า แรงจึงเป็น 1/2 เท่า', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-parallel-wires')), 'number', 'เส้นลวดคู่ขนานสองเส้นห่างกัน 0.2 เมตร มีกระแสตัวละ 4 แอมแปร์ ไหลทิศเดียวกัน แรงระหว่างลวดต่อความยาว 1 เมตรเป็น 32 ไมโครนิวตัน ถ้าเพิ่มระยะห่างเป็น 0.4 เมตร โดยกระแสทั้งคู่คงเดิม แรงระหว่างลวดต่อความยาวเป็นกี่ไมโครนิวตัน (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":16,"tolerance":0.5}', 'แรงต่อความยาวแปรผกผันกับระยะห่าง F/L ∝ 1/r เมื่อ r เพิ่มเป็น 2 เท่า แรงลดลงครึ่งหนึ่ง → 32/2 = 16 ไมโครนิวตันต่อเมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'magnetism-parallel-wires')), 'number', 'เส้นลวดคู่ขนานห่างกัน 0.1 เมตร กระแสทั้งคู่ 5 แอมแปร์ ทิศเดียวกัน ถ้าแรงระหว่างลวดต่อความยาว 1 เมตรคำนวณได้เป็น 50 ไมโครนิวตัน แล้วเพิ่มกระแสทั้งคู่เป็น 2 เท่า แรงใหม่ต่อความยาวเป็นกี่ไมโครนิวตัน (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":200,"tolerance":0.5}', 'แรงแปรผันตรงกับผลคูณกระแส F ∝ I1I2 เมื่อกระแสทั้งคู่เพิ่ม 2 เท่า แรงเพิ่ม 4 เท่า → 50×4 = 200 ไมโครนิวตัน/เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'mechanical-waves'), 'mechanical-waves-components', 'ส่วนประกอบของคลื่น', 'องค์ประกอบพื้นฐานของคลื่นฮาร์มอนิกประกอบด้วย แอมพลิจูด (A) คือการกระจัดสูงสุดจากแนวสมดุลซึ่งบ่งบอกระดับพลังงานของคลื่น, คาบ (T) คือเวลาที่คลื่นเคลื่อนที่ได้ครบหนึ่งลูกคลื่น และความถี่ (f) คือจำนวนลูกคลื่นในหนึ่งวินาที โดยมีความสัมพันธ์ส่วนกลับ f = 1/T ความยาวคลื่น (λ) คือระยะทางระหว่างสันคลื่นถึงสันคลื่นที่อยู่ติดกัน ทั้งหมดสัมพันธ์กันผ่านสมการอัตราเร็วคลื่น v = fλ', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'mechanical-waves-components'), 'youtube', 'https://www.youtube.com/watch?v=g2qcNKE5a9M', 'g2qcNKE5a9M', 'ฟิสิกส์ ม.5 บทที่ 9 คลื่น ep.2', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
