INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'mechanical-waves-components'), 'harmonic-wave', 'ปรับ f, λ และ A แล้วดูอัตราเร็วคลื่น', '{"frequency":{"min":1,"max":10,"default":2},"wavelength":{"min":1,"max":10,"default":4}}');
