INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-components')), 'choice', 'ระยะจากแนวสมดุลของคลื่นไปจนถึงยอดคลื่นเรียกว่าอะไร', '["แอมพลิจูด","ความยาวคลื่น","คาบ","เฟส"]', '0', 'แอมพลิจูดคือระยะห่างจากตำแหน่งสมดุลถึงตำแหน่งสูงสุด (ยอดหรือท้อง) ของคลื่น', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-components')), 'choice', 'ความยาวคลื่นวัดจากจุดใดถึงจุดใด', '["จากยอดคลื่นถึงท้องคลื่นถัดไป","จากยอดคลื่นหนึ่งถึงยอดคลื่นถัดไป","จากแนวสมดุลถึงยอดคลื่น","จากจุดเริ่มไปตลอดความยาวเชือก"]', '1', 'ความยาวคลื่นเป็นระยะจากจุดที่มีเฟสเดียวกันต่อเนื่อง เช่น ยอดถึงยอด หรือท้องถึงท้อง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-components')), 'choice', 'ถ้าคลื่นทำการสั่นครบ 4 รอบในเวลา 8 วินาที คาบของคลื่นเป็นเท่าใด', '["4 วินาที","8 วินาที","2 วินาที","32 วินาที"]', '2', 'คาบคือเวลาต่อ 1 รอบ T = 8/4 = 2 วินาที', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-components')), 'number', 'คลื่นที่มีคาบ 0.5 วินาที จะมีความถี่เป็นกี่เฮิรตซ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.05}', 'ความถี่เป็นส่วนกลับของคาบ f = 1/T = 1/0.5 = 2 เฮิรตซ์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-components')), 'number', 'คลื่นหนึ่งมีความถี่ 5 เฮิรตซ์ ใช้เวลากี่วินาทีจึงจะครบ 20 รอบ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.05}', 'เวลาทั้งหมด = จำนวนรอบ/ความถี่ = 20/5 = 4 วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'mechanical-waves'), 'mechanical-waves-definition-types', 'ความหมายและชนิดของคลื่น', 'คลื่นกลเป็นการถ่ายโอนพลังงานผ่านตัวกลางโดยอาศัยการสั่นของอนุภาคตัวกลางรอบตำแหน่งสมดุล โดยตัวกลางไม่ได้เคลื่อนที่ไปตามคลื่น แบ่งตามทิศทางการสั่นของอนุภาคได้ 2 แบบ คือ คลื่นตามขวางที่อนุภาคสั่นตั้งฉากกับทิศทางคลื่น เช่น คลื่นในเส้นเชือก และคลื่นตามยาวที่อนุภาคสั่นขนานกับทิศทางคลื่น เช่น คลื่นเสียงและคลื่นสปริง หากแบ่งตามการใช้ตัวกลาง คลื่นกลต้องอาศัยตัวกลาง แต่คลื่นแม่เหล็กไฟฟ้าสามารถแผ่ผ่านสุญญากาศได้', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
