INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'mechanical-waves-definition-types'), 'wave-tuner', 'ปรับความถี่การสั่นของคลื่นกลให้สอดคล้องกับอัตราเร็วเป้าหมาย', '{"tolerance":1.1,"targetSpeed":[6,30],"frequency":{"min":1,"max":10,"default":2},"wavelength":{"min":1,"max":10,"default":4.5}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'mechanical-waves-definition-types'), 'แบบทดสอบ: ความหมายและชนิดของคลื่น', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-definition-types')), 'choice', 'คลื่นกลที่เคลื่อนที่ผ่านตัวกลาง ถ่ายทอดสิ่งใดจากจุดหนึ่งไปยังอีกจุดหนึ่ง', '["พลังงาน โดยที่ตัวกลางไม่เคลื่อนที่ตามไปด้วย","ตัวกลางไปพร้อมกับคลื่น","มวลของตัวกลางทั้งหมด","ความร้อนเท่านั้น"]', '0', 'คลื่นกลถ่ายทอดพลังงานผ่านตัวกลาง โดยอนุภาคของตัวกลางสั่นอยู่กับที่และไม่เคลื่อนที่ตามคลื่นไปด้วย', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-definition-types')), 'choice', 'คลื่นที่อนุภาคของตัวกลางสั่นในแนวตั้งฉากกับทิศการเคลื่อนที่ของคลื่น เรียกว่าคลื่นชนิดใด', '["คลื่นตามยาว","คลื่นตามขวาง","คลื่นแม่เหล็กไฟฟ้า","คลื่นนิ่ง"]', '1', 'คลื่นตามขวางคือคลื่นที่อนุภาคสั่นตั้งฉากกับทิศทางที่คลื่นเคลื่อนที่ เช่น คลื่นในเส้นเชือก', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-definition-types')), 'choice', 'เสียงในอากาศจัดเป็นคลื่นชนิดใด และเพราะเหตุใด', '["ตามขวาง เพราะเสียงสะท้อนได้","ตามขวาง เพราะอนุภาคสั่นขวางทิศการเคลื่อนที่","ตามยาว เพราะอนุภาคสั่นขนานกับทิศการเคลื่อนที่ของคลื่น","ไม่เป็นคลื่นกลเพราะผ่านสุญญากาศได้"]', '2', 'เสียงเป็นคลื่นตามยาว อนุภาคของตัวกลางสั่นไปตามแนวเดียวกับทิศที่เสียงเคลื่อนที่ ทำให้เกิดช่วงอัดและช่วงขยาย', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-definition-types')), 'number', 'คลื่นน้ำมีความถี่ 2 รอบต่อวินาที และความยาวคลื่น 4 เมตร อัตราเร็วของคลื่นเท่ากับกี่เมตรต่อวินาที (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":8,"tolerance":0.5}', 'v = fλ = 2 × 4 = 8 เมตรต่อวินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-definition-types')), 'number', 'คลื่นลูกหนึ่งมีความยาวคลื่น 5 เมตร และเคลื่อนที่ด้วยอัตราเร็ว 20 เมตรต่อวินาที ความถี่ของคลื่นเท่ากับกี่รอบต่อวินาที (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 'จาก v = fλ จะได้ f = v/λ = 20/5 = 4 รอบต่อวินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'mechanical-waves'), 'mechanical-waves-speed', 'อัตราเร็วของคลื่น v = fλ', 'อัตราเร็วของคลื่น (v) คือระยะทางที่หน้าคลื่นเคลื่อนที่ไปได้ในหนึ่งหน่วยเวลา คำนวณได้จากสมการหลัก v = s/t = fλ อัตราเร็วของคลื่นกลจะขึ้นอยู่กับสมบัติความยืดหยุ่นและความหนาแน่นของตัวกลางเป็นสำคัญ โดยไม่ขึ้นกับความถี่ เช่น คลื่นในเส้นเชือกมีอัตราเร็ว v = sqrt(T/μ) เมื่อ T คือแรงตึงเชือก และ μ คือมวลต่อหน่วยความยาว หากตัวกลางเดิมไม่เปลี่ยน อัตราเร็วคลื่นจะคงตัวเสมอ', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'mechanical-waves-speed'), 'youtube', 'https://www.youtube.com/watch?v=SU7c0I48JQ8', 'SU7c0I48JQ8', 'ฟิสิกส์ ม.5 บทที่ 9 คลื่น ep.1', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'mechanical-waves-speed'), 'youtube', 'https://www.youtube.com/watch?v=8CNIpCw8vIE', '8CNIpCw8vIE', 'ฟิสิกส์ ม.ปลาย บทที่9 คลื่น แบบเข้าใจง่าย(ฉบับเด็ก Cambridge)', 'Mr.Phoops', 'https://www.youtube.com/channel/UCx5Rw-I8iWy6EcVz2zpwRrw', 2);
