INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'mechanical-waves-superposition'), 'แบบทดสอบ: การซ้อนทับของคลื่นและคลื่นนิ่ง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-superposition')), 'choice', 'หลักการซ้อนทับของคลื่นกล่าวว่าการกระจัดลัพธ์ ณ จุดหนึ่งเมื่อคลื่นสองขบวนมาพบกันเท่ากับปริมาณใด', '["ผลรวมเชิงพีชคณิตของการกระจัดของแต่ละคลื่น ณ จุดนั้น","ผลต่างของการกระจัดเสมอ","ผลคูณของการกระจัดของแต่ละคลื่น","การกระจัดของคลื่นที่มีแอมพลิจูดมากกว่าเท่านั้น"]', '0', 'หลักการซ้อนทับ: การกระจัดลัพธ์เท่ากับผลรวมเชิงพีชคณิตของการกระจัดของคลื่นแต่ละขบวน ณ ตำแหน่งและเวลานั้น', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-superposition')), 'choice', 'เมื่อยอดคลื่นของสองขบวนมาพบกันพอดี (แทรกสอดแบบเสริม) การกระจัดลัพธ์เป็นอย่างไร', '["เท่ากับศูนย์","มีค่าน้อยกว่าคลื่นเดิม","มีขนาดใหญ่ที่สุดเท่ากับผลรวมของแอมพลิจูด","เท่ากับคลื่นเดิม"]', '2', 'ยอดพบยอดทำให้การกระจัดรวมกันเป็นการกระจัดลัพธ์ใหญ่สุด เท่ากับผลรวมของแอมพลิจูดทั้งสอง เรียกว่าการแทรกสอดแบบเสริม', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-superposition')), 'choice', 'คลื่นนิ่งในเส้นเชือกเกิดจากอะไร', '["คลื่นขบวนเดียวเคลื่อนที่ไปตามเชือก","คลื่นสองขบวนความถี่เท่ากันเคลื่อนที่สวนทางกันในเส้นเชือก","คลื่นสองขบวนที่มีความถี่ต่างกันมาก","เสียงที่สะท้อนจากผนัง"]', '1', 'คลื่นนิ่งเกิดจากการซ้อนทับของคลื่นสองขบวนที่มีความถี่และแอมพลิจูดเท่ากัน แต่เคลื่อนที่สวนทางกัน มีบัพและปฏิบัพคงที่', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-superposition')), 'number', 'คลื่นสองขบวนมีการกระจัด +3 เซนติเมตร และ −1 เซนติเมตร ที่จุดเดียวกันพอดี การกระจัดลัพธ์มีค่าเท่ากับกี่เซนติเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'การกระจัดลัพธ์ = 3 + (−1) = 2 เซนติเมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'mechanical-waves-superposition')), 'number', 'คลื่นสองขบวนมีการกระจัด +4 เซนติเมตร และ +3 เซนติเมตร ที่จุดเดียวกันพอดี การกระจัดลัพธ์มีค่าเท่ากับกี่เซนติเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":7,"tolerance":0.5}', 'การกระจัดลัพธ์ = 4 + 3 = 7 เซนติเมตร (แทรกสอดแบบเสริม)', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'mechanical-waves'), 'mechanical-waves-surface-string', 'คลื่นผิวน้ำและคลื่นในเส้นเชือก', 'คลื่นผิวน้ำเป็นคลื่นผสมที่มีการเคลื่อนที่ของอนุภาคน้ำเป็นวงกลมหรือวงรี อัตราเร็วของคลื่นน้ำในบริเวณน้ำลึกขึ้นกับความยาวคลื่นและแรงโน้มถ่วง ส่วนในน้ำตื้นอัตราเร็วจะขึ้นกับความลึกของน้ำตามสูตร v = sqrt(gh) สำหรับคลื่นในเส้นเชือกเป็นคลื่นตามขวางที่อัตราเร็วขึ้นกับแรงตึงและมวลต่อหน่วยความยาวของเส้นเชือก การทดลองกับคลื่นทั้งสองชนิดนี้ช่วยให้เห็นภาพพฤติกรรมของคลื่นกลได้อย่างชัดเจนในห้องปฏิบัติการ', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'mechanical-waves-surface-string'), 'youtube', 'https://www.youtube.com/watch?v=SU7c0I48JQ8', 'SU7c0I48JQ8', 'ฟิสิกส์ ม.5 บทที่ 9 คลื่น ep.1', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'mechanical-waves-surface-string'), 'youtube', 'https://www.youtube.com/watch?v=8CNIpCw8vIE', '8CNIpCw8vIE', 'ฟิสิกส์ ม.ปลาย บทที่9 คลื่น แบบเข้าใจง่าย(ฉบับเด็ก Cambridge)', 'Mr.Phoops', 'https://www.youtube.com/channel/UCx5Rw-I8iWy6EcVz2zpwRrw', 2);
