INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-connected-masses')), 'choice', 'มวลสองก้อนติดกันบนพื้นลื่นถูกดึงด้วยแรง F ทั้งระบบมีความเร่งเท่าใด', '["F / (m1 + m2)","F / m1","F / m2","F / (m1 - m2)"]', '0', 'มองทั้งระบบเป็นมวลรวม m1 + m2 ดังนั้น a = F / (m1 + m2)', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-connected-masses')), 'choice', 'สองก้อนผูกเชือกกันบนพื้นลื่นมวลรวม 5 กิโลกรัม มีแรงลัพธ์ 20 นิวตัน ความเร่งร่วมของระบบเป็นเท่าใด', '["5 เมตร/วินาที²","4 เมตร/วินาที²","0.25 เมตร/วินาที²","3 เมตร/วินาที²"]', '1', 'a = F / มวลรวม = 20 / 5 = 4 เมตร/วินาที² ทุกก้อนในระบบมีความเร่งเท่ากัน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-connected-masses')), 'choice', 'สำหรับเชือกที่เบาและไม่ยืด แรงตึงในเชือกเป็นอย่างไรตลอดเส้นเชือก', '["ไม่เท่ากันตลอด","เท่ากันตลอดเส้น","เท่ากับน้ำหนักเสมอ","เป็นศูนย์เสมอ"]', '1', 'เชือกเบาไม่ยืด แรงตึงมีค่าคงที่ตลอดเส้นเชือก จึงใช้แทนค่าเดียวกันได้ทั้งระบบ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-connected-masses')), 'number', 'ระบบมวลรวม 10 กิโลกรัมมีแรงลัพธ์ 50 นิวตัน ความเร่งร่วมเป็นเท่าใด (ตอบเป็นเมตร/วินาที² จำนวนเต็ม)', NULL, '{"value":5,"tolerance":0.5}', 'a = F / มวลรวม = 50 / 10 = 5 เมตร/วินาที²', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-connected-masses')), 'number', 'มวล 3 กิโลกรัมกับ 7 กิโลกรัมผูกติดกันบนพื้นลื่น ถูกดึงด้วยแรง 40 นิวตัน ความเร่งร่วมเป็นเท่าใด (ตอบเป็นเมตร/วินาที² จำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 'มวลรวม = 3 + 7 = 10 กิโลกรัม a = 40 / 10 = 4 เมตร/วินาที²', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'newton-laws'), 'newton-laws-inertia', 'กฎข้อที่ 1 ของนิวตัน (ความเฉื่อย)', 'กฎการเคลื่อนที่ข้อที่ 1 ของนิวตัน หรือกฎความเฉื่อย กล่าวว่า วัตถุจะคงสภาพหยุดนิ่งหรือเคลื่อนที่ด้วยความเร็วคงที่ในแนวเส้นตรง ตราบใดที่ไม่มีแรงลัพธ์ภายนอกที่ไม่เป็นศูนย์มากระทำ (ΣF = 0) ความเฉื่อยคือสมบัติของวัตถุที่พยายามต้านการเปลี่ยนแปลงสภาพการเคลื่อนที่ โดยมวล (m) ของวัตถุเป็นปริมาณที่ใช้วัดความเฉื่อย วัตถุที่มีมวลมากจะเปลี่ยนสภาพการเคลื่อนที่ได้ยากกว่าวัตถุที่มีมวลน้อย', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
