INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-net-force'), 'แบบทดสอบ: แรงและแรงลัพธ์ (การรวมแรง)', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-net-force')), 'choice', 'แรงลัพธ์หมายถึงสิ่งใด', '["แรงที่มีค่าน้อยที่สุดเพียงแรงเดียว","ผลรวมเวกเตอร์ของทุกแรงที่กระทำต่อวัตถุ","ผลรวมมวลของวัตถุ","แรงโน้มถ่วงเท่านั้น"]', '1', 'แรงลัพธ์คือผลรวมเวกเตอร์ของทุกแรงที่กระทำต่อวัตถุ ไม่ใช่การเลือกแรงใดแรงหนึ่ง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-net-force')), 'choice', 'แรง 10 นิวตันกับ 6 นิวตันกระทำทิศเดียวกัน แรงลัพธ์มีขนาดเท่าใด', '["4 นิวตัน","16 นิวตัน","60 นิวตัน","12 นิวตัน"]', '1', 'แรงไปทิศเดียวกันบวกกัน = 10 + 6 = 16 นิวตัน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-net-force')), 'choice', 'แรง 10 นิวตันไปทางขวากับ 6 นิวตันไปทางซ้าย แรงลัพธ์มีขนาดและทิศทางใด', '["4 นิวตันไปทางซ้าย","16 นิวตันไปทางขวา","4 นิวตันไปทางขวา","6 นิวตันไปทางซ้าย"]', '2', 'แรงตรงข้ามกันหักล้าง = 10 - 6 = 4 นิวตัน ไปทางขวา', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-net-force')), 'number', 'แรง 25 นิวตันกับ 15 นิวตันไปทิศเดียวกัน แรงลัพธ์มีขนาดเท่าใด (ตอบเป็นนิวตัน จำนวนเต็ม)', NULL, '{"value":40,"tolerance":0.5}', 'แรงทิศเดียวกันบวกกัน = 25 + 15 = 40 นิวตัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-net-force')), 'number', 'แรง 30 นิวตันไปทางขวากับ 12 นิวตันไปทางซ้าย แรงลัพธ์มีขนาดเท่าใด (ตอบเป็นนิวตัน จำนวนเต็ม)', NULL, '{"value":18,"tolerance":0.5}', 'แรงตรงข้ามกันหักล้าง = 30 - 12 = 18 นิวตัน ไปทางขวา', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'newton-laws'), 'newton-laws-second-law', 'กฎข้อที่ 2 ของนิวตัน', 'กฎการเคลื่อนที่ข้อที่ 2 ของนิวตัน ระบุว่า เมื่อมีแรงลัพธ์ที่ไม่เป็นศูนย์มากระทำต่อวัตถุ วัตถุจะเคลื่อนที่ด้วยความเร่งในทิศเดียวกับแรงลัพธ์ โดยขนาดความเร่งแปรผันตรงกับขนาดของแรงลัพธ์และแปรผกผันกับมวลของวัตถุ เขียนเป็นสมการสำคัญคือ ΣF = ma แรงมีหน่วยเป็นนิวตัน (N) ซึ่งเท่ากับ kg·m/s² สมการนี้เป็นแกนกลางของการวิเคราะห์กลศาสตร์คลาสสิกทั้งหมด', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-second-law'), 'youtube', 'https://www.youtube.com/watch?v=49kgcKlI6Zg', '49kgcKlI6Zg', '3.3 แรงและกฎการเคลื่อนที่ของนิวตัน (Newton''s Laws of Motion) | ฟิสิกส์ ม.4 เทอม 1 | ฟิสิกส์ ม.ปลาย', 'ปลาอะคาเดมี', 'https://www.youtube.com/channel/UCtTD069k4v4IAHpf708ykeQ', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-second-law'), 'youtube', 'https://www.youtube.com/watch?v=6zSI0tYtt98', '6zSI0tYtt98', 'ฟิสิกส์ ม.4 บทที่ 3 แรงและกฎการเคลื่อนที่ ep.5(โจทย์กฎการเคลื่อนที่ของนิวตัน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-second-law'), 'newton-force', 'ตรวจสอบความสัมพันธ์ระหว่างแรงดึง มวล และความเร่งตามกฎข้อที่ 2', '{"force":{"min":10,"max":100,"default":50},"mass":{"min":1,"max":16,"default":4},"friction":{"min":0,"max":0.5,"step":0.05,"default":0.1}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-second-law'), 'balance-force', 'จับคู่แรงดึงกับมวลวัตถุให้เกิดความเร่งเป้าหมายตามสมการนิวตัน', '{"targetAcc":[1.5,4.8],"tolerance":0.15,"force":{"min":20,"max":95,"default":45},"mass":{"min":1,"max":9,"default":4}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-second-law'), 'แบบทดสอบ: กฎข้อที่ 2 ของนิวตัน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-second-law')), 'choice', 'กฎข้อที่ 2 ของนิวตันเขียนเป็นสมการได้ดังนี้', '["F = m / v","F = m + a","F = m x g","F = ma"]', '3', 'กฎข้อที่ 2 คือ F = ma หรือแรงลัพธ์เท่ากับมวลคูณความเร่ง นั่นคือ a = F/m', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-second-law')), 'choice', 'ถ้าแรงลัพธ์คงที่แล้วเพิ่มมวลเป็น 2 เท่า ความเร่งของวัตถุเป็นเท่าใดเมื่อเทียบกับเดิม', '["ครึ่งหนึ่งของเดิม","เท่าเดิม","สองเท่าของเดิม","สี่เท่าของเดิม"]', '0', 'a = F/m เมื่อมวลเพิ่มเป็น 2 เท่าด้วยแรงเท่าเดิม ความเร่งจึงลดลงเป็นครึ่งหนึ่ง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-second-law')), 'choice', 'แรงลัพธ์ 10 นิวตันกระทำกับมวล 2 กิโลกรัม ความเร่งเป็นเท่าใด', '["20 เมตร/วินาที²","5 เมตร/วินาที²","0.2 เมตร/วินาที²","12 เมตร/วินาที²"]', '1', 'a = F/m = 10 / 2 = 5 เมตร/วินาที²', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-second-law')), 'number', 'แรงลัพธ์ 30 นิวตันกระทำกับมวล 6 กิโลกรัม ความเร่งเป็นเท่าใด (ตอบเป็นเมตร/วินาที² จำนวนเต็ม)', NULL, '{"value":5,"tolerance":0.5}', 'a = F/m = 30 / 6 = 5 เมตร/วินาที²', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'newton-laws-second-law')), 'number', 'แรงลัพธ์ 45 นิวตันทำให้วัตถุมีความเร่ง 5 เมตร/วินาที² มวลของวัตถุเป็นเท่าใด (ตอบเป็นกิโลกรัม จำนวนเต็ม)', NULL, '{"value":9,"tolerance":0.5}', 'm = F/a = 45 / 5 = 9 กิโลกรัม', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'newton-laws'), 'newton-laws-third-law', 'กฎข้อที่ 3 ของนิวตัน', 'กฎการเคลื่อนที่ข้อที่ 3 ของนิวตัน กล่าวว่า ทุกแรงกิริยา (Action) ย่อมมีแรงปฏิกิริยา (Reaction) ที่มีขนาดเท่ากันแต่มีทิศทางตรงกันข้ามเสมอ (F_action = -F_reaction) แรงทั้งสองนี้เกิดขึ้นพร้อมกัน เป็นแรงชนิดเดียวกัน แต่กระทำต่อวัตถุคนละก้อน จึงไม่สามารถนำมาหักล้างกันได้ เช่น แรงที่เท้าดันพื้นกับแรงที่พื้นดันเท้า หรือแรงดึงดูดระหว่างโลกกับดวงจันทร์', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-third-law'), 'youtube', 'https://www.youtube.com/watch?v=49kgcKlI6Zg', '49kgcKlI6Zg', '3.3 แรงและกฎการเคลื่อนที่ของนิวตัน (Newton''s Laws of Motion) | ฟิสิกส์ ม.4 เทอม 1 | ฟิสิกส์ ม.ปลาย', 'ปลาอะคาเดมี', 'https://www.youtube.com/channel/UCtTD069k4v4IAHpf708ykeQ', 1);
