INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'newton-laws-third-law'), 'newton-force', 'จำลองแรงกิริยาและแรงปฏิกิริยาระหว่างแรงผลักกับแรงสัมผัส', '{"force":{"min":0,"max":80,"default":45},"mass":{"min":1,"max":14,"default":6},"friction":{"min":0,"max":0.6,"step":0.05,"default":0.2}}');
