INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'nuclear-nucleus-binding-energy'), 'quantum-lab', 'คำนวณพลังงานยึดเหนี่ยวนิวเคลียสด้วยแบบจำลองควอนตัม', '{"targetEk":[1.1,3.1],"workFunction":2.5,"tolerance":0.15,"frequency":{"min":6,"max":16,"step":0.2,"default":9.5}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'nuclear-nucleus-binding-energy'), 'แบบทดสอบ: โครงสร้างนิวเคลียสและพลังงานยึดเหนี่ยว', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-nucleus-binding-energy')), 'choice', 'นิวเคลียสของอะตอมประกอบด้วยอนุภาคใด', '["โปรตอนเท่านั้น","โปรตอนและนิวตรอน","อิเล็กตรอนและโปรตอน","อิเล็กตรอนเท่านั้น"]', '1', 'นิวเคลียสประกอบด้วยโปรตอน (ประจุบวก) และนิวตรอน (ไม่มีประจุ) รวมเรียกว่านิวคลีออน ส่วนอิเล็กตรอนโคจรรอบนิวเคลียส', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-nucleus-binding-energy')), 'choice', 'เลขมวล (mass number) ของนิวเคลียส หมายถึงอะไร', '["จำนวนโปรตอน","จำนวนนิวตรอน","จำนวนโปรตอนรวมกับนิวตรอน","จำนวนอิเล็กตรอน"]', '2', 'เลขมวล A = จำนวนโปรตอน (Z) + จำนวนนิวตรอน (N) คือจำนวนนิวคลีออนทั้งหมด ส่วนเลขอะตอม Z คือจำนวนโปรตอน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-nucleus-binding-energy')), 'choice', 'มวลพร่อง (mass defect) ของนิวเคลียสคืออะไร', '["มวลนิวเคลียสจริงมากกว่าผลรวมมวลนิวคลีออน","มวลของนิวตรอนลบมวลโปรตอน","ไม่มีนิยาม","ผลรวมมวลนิวคลีออนมากกว่า มวลนิวเคลียสจริง"]', '3', 'มวลพร่อง = มวลรวมนิวคลีออนที่แยกกัน − มวลนิวเคลียสจริง มวลที่หายไปเปลี่ยนเป็นพลังงานยึดเหนี่ยวตาม E = Δmc² ซึ่งเป็นสาเหตุที่นิวเคลียสเสถียร', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-nucleus-binding-energy')), 'number', 'นิวเคลียสไอโซโทปหนึ่งมีเลขมวล 27 และจำนวนโปรตอน 13 จำนวนนิวตรอนในนิวเคลียสเป็นกี่ตัว (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":14,"tolerance":0.5}', 'จำนวนนิวตรอน = เลขมวล − จำนวนโปรตอน = 27 − 13 = 14 ตัว', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'nuclear-nucleus-binding-energy')), 'number', 'ไอโซโทปหนึ่งมีนิวตรอน 8 ตัว และเลขมวล 16 จำนวนโปรตอนเท่ากับกี่ตัว (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":8,"tolerance":0.5}', 'จำนวนโปรตอน Z = เลขมวล − จำนวนนิวตรอน = 16 − 8 = 8 โปรตอน', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'nuclear'), 'nuclear-radioactivity-half-life', 'กัมมันตภาพรังสีและครึ่งชีวิต', 'การสลายตัวของนิวเคลียสกัมมันตรังสีเป็นกระบวนการแบบสุ่มที่ไม่ขึ้นกับปัจจัยภายนอก โดยปล่อยรังสีแอลฟา บีตา หรือแกมมาออกมา ครึ่งชีวิต (T_half) คือระยะเวลาที่จำนวนนิวเคลียสกัมมันตรังสีลดลงเหลือครึ่งหนึ่งของเดิม ปริมาณสารที่เหลืออยู่ ณ เวลา t คำนวณได้จากสูตร N(t) = N0*(1/2)^(t/T_half) หรือ N(t) = N0*e^(-lambda*t) โดยมีค่าคงตัวการสลาย lambda = ln(2)/T_half และกัมมันตภาพ A(t) = lambda*N(t) มีหน่วยวัดเป็นเบกเคอเรล (Bq) หรือคูรี (Ci)', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'nuclear-radioactivity-half-life'), 'youtube', 'https://www.youtube.com/watch?v=Zt3rB4sofhA', 'Zt3rB4sofhA', 'ฟิสิกส์ ม.6 บทที่ 20 ฟิสิกส์นิวเคลียร์และฟิสิกส์อนุภาค ep.4 (การสลายตัวให้ รังสีแอลฟา บีต้า แกมมา)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
