INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'oscillation-spring-pendulum')), 'choice', 'คาบการแกว่งของสปริงมวล m ค่าคงที่สปริง k หาได้จากข้อใด', '["T = 2π√(m/k)","T = 2π√(k/m)","T = 2π√(mk)","T = m/k"]', '0', 'คาบสปริง T = 2π√(m/k) คาบเพิ่มขึ้นเมื่อมวลเพิ่มหรือสปริงอ่อนลง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'oscillation-spring-pendulum')), 'choice', 'คาบของลูกตุ้มอย่างง่ายขึ้นกับปริมาณใด', '["มวลของลูกตุ้ม","ความยาวเชือกและความเร่งโน้มถ่วง","แอมพลิจูด","เฉพาะมวลและแอมพลิจูด"]', '1', 'คาบลูกตุ้ม T = 2π√(L/g) ขึ้นกับความยาวเชือกและความเร่งโน้มถ่วง ไม่ขึ้นกับมวลหรือแอมพลิจูด', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'oscillation-spring-pendulum')), 'choice', 'ถ้าเพิ่มมวลที่ห้อยกับสปริงเป็น 4 เท่า (สปริงเดียวกัน) คาบการแกว่งเปลี่ยนเป็นกี่เท่าของเดิม', '["4 เท่า","2 เท่า","เท่าเดิม","ครึ่งหนึ่ง"]', '1', 'T ∝ √m เมื่อ m เป็น 4 เท่า T จึงเป็น √4 = 2 เท่าของเดิม', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'oscillation-spring-pendulum')), 'number', 'ลูกตุ้มอย่างง่ายยาว 2.5 เมตร ในที่ที่มี g = 10 เมตร/วินาที² คาบการแกว่งมีค่ากี่วินาที (ใช้ π ≈ 3.14 ตอบเป็นทศนิยม 2 ตำแหน่ง)', NULL, '{"value":3.14,"tolerance":0.005}', 'T = 2π√(L/g) = 2π√(2.5/10) = 2π×0.5 = π ≈ 3.14 วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'oscillation-spring-pendulum')), 'number', 'สปริงค่าคงที่ 100 นิวตัน/เมตร ห้อยมวล 1 กิโลกรัม คาบการแกว่งมีค่ากี่วินาที (ใช้ π ≈ 3.14 ตอบเป็นทศนิยม 2 ตำแหน่ง)', NULL, '{"value":0.63,"tolerance":0.005}', 'T = 2π√(m/k) = 2π√(1/100) = 2π×0.1 = 0.2π ≈ 0.628 ≈ 0.63 วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'projectile'), 'projectile-application', 'การประยุกต์โพรเจกไทล์', 'การประยุกต์โพรเจกไทล์ครอบคลุมสถานการณ์เช่น การขว้างวัตถุออกจากหน้าผาในแนวราบ (Uy = 0, Sy = (1/2)gt²) หรือการยิงข้ามสิ่งกีดขวางจากระดับความสูงต่างกัน เวลาตกถึงพื้นขึ้นอยู่กับความสูงแนวดิ่งเป็นหลัก คือ t = √(2h/g) เมื่อไม่มีความเร็วต้นในแนวดิ่ง ความเร็วรวมที่กระทบพื้นหาได้จากการรวมเวกเตอร์ v = √(Vx² + Vy²) ซึ่งต้องนำไปใช้จริงทั้งในด้านการกีฬา การขนส่ง และวิศวกรรม', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-application'), 'youtube', 'https://www.youtube.com/watch?v=UTMXSCv2Slo', 'UTMXSCv2Slo', 'ฟิสิกส์ ม.4 บทที่ 7 การเคลื่อนที่แนวโค้ง ep.1 (การเคลื่อนที่แบบโพรเจกไทล์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
