INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-application')), 'choice', 'ขว้างลูกบอลออกในแนวราบจากหน้าผา เวลาที่ลูกถึงพื้นขึ้นกับสิ่งใด', '["ความเร็วต้นในแนวราบ","ระยะทางแนวราบของหน้าผา","ความสูงของหน้าผา","มวลของลูกบอล"]', '2', 'เวลาตกขึ้นกับการเคลื่อนที่แนวตั้งเท่านั้น คือ t = √(2h/g) ไม่ขึ้นกับความเร็วแนวราบและมวล', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-application')), 'choice', 'ตลอดวิถีโพรเจกไทล์โดยไม่คิดแรงต้านอากาศ ปริมาณใดไม่เปลี่ยนค่า', '["ความเร็วในแนวตั้ง","ความเร่งในแนวตั้ง","ความเร็วรวมของวัตถุ","ความเร็วในแนวราบ"]', '3', 'ความเร็วแนวราบคงที่ตลอด เพราะแนวราบไม่มีความเร่ง ส่วนความเร็วแนวตั้งเปลี่ยนไปเรื่อยๆ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-application')), 'choice', 'ยิงจากพื้นแนวนอนที่มุม 45 องศาโดยไม่คิดแรงต้านอากาศ เมื่อเทียบกับมุมอื่นที่ความเร็วต้นเท่ากัน ปริมาณใดมีค่ามากที่สุด', '["ระยะไกลสุด","เวลาขึ้นถึงจุดสูงสุด","ความสูงสูงสุด","ความเร็วต้นแนวตั้ง"]', '0', 'มุม 45 องศาให้ระยะไกลสุดมากที่สุด สำหรับความสูงและเวลาขึ้น มุม 90 องศาจะมากกว่า', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-application')), 'number', 'ขว้างลูกบอลออกในแนวราบจากหน้าผาสูง 20 เมตร ใช้เวลากี่วินาทีจึงถึงพื้น (ใช้ g = 10 เมตร/วินาที² และ t = √(2h/g) ตอบเป็นวินาที จำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 't = √(2 x 20 / 10) = √4 = 2 วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-application')), 'number', 'ยิงวัตถุจากพื้นแนวนอนที่มุม 45 องศา ด้วยความเร็วต้น 20 เมตร/วินาที ระยะไกลสุดเป็นเท่าใด (ใช้ g = 10 เมตร/วินาที² และ sin 90° = 1 ตอบเป็นเมตร จำนวนเต็ม)', NULL, '{"value":40,"tolerance":0.5}', 'R = v² sin 2θ / g = 400 x sin 90° / 10 = 40 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'projectile'), 'projectile-axis-analysis', 'การวิเคราะห์โพรเจกไทล์ตามแนวแกน', 'การวิเคราะห์โพรเจกไทล์ทำได้โดยแยกพิจารณาแกนราบและแกนดิ่งออกจากกันอย่างเด็ดขาด ในแนวราบไม่มีความเร่ง (ax = 0) ความเร็วคงที่ตามสมการ Sx = Ux t โดย Ux = u cos θ ส่วนในแนวดิ่งมีความเร่งโน้มถ่วง (ay = -g) ใช้สมการสุวัต เช่น Vy = Uy - gt และ Sy = Uy t - (1/2)gt² โดยเชื่อมโยงทั้งสองแกนด้วยตัวแปรเวลาร่วม t', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-axis-analysis'), 'youtube', 'https://www.youtube.com/watch?v=ZrFyxC3x3-w', 'ZrFyxC3x3-w', 'ฟิสิกส์ ม.4 บทที่ 7 การเคลื่อนที่แนวโค้ง ep.2 (การเคลื่อนที่แบบโพรเจกไทล์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-axis-analysis'), 'youtube', 'https://www.youtube.com/watch?v=UTMXSCv2Slo', 'UTMXSCv2Slo', 'ฟิสิกส์ ม.4 บทที่ 7 การเคลื่อนที่แนวโค้ง ep.1 (การเคลื่อนที่แบบโพรเจกไทล์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-axis-analysis'), 'projectile', 'ยิงและดูองค์ประกอบความเร็วแต่ละแนวแกน', '{"angle":{"min":10,"max":80,"default":45},"speed":{"min":10,"max":40,"default":25}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-axis-analysis'), 'aim-and-shoot', 'ยิงให้โดนเป้า: ปรับมุมและความเร็ว', '{"targetDistance":[40,120],"tolerance":4}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-axis-analysis'), 'แบบทดสอบ: การวิเคราะห์โพรเจกไทล์ตามแนวแกน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-axis-analysis')), 'choice', 'ในแนวราบของการเคลื่อนที่โพรเจกไทล์ โดยไม่คิดแรงต้านอากาศ ความเร็วเป็นอย่างไร', '["คงที่","เพิ่มขึ้นเรื่อยๆ","ลดลงเรื่อยๆ","เป็นศูนย์"]', '0', 'แนวราบไม่มีแรงกระทำ ความเร่งแนวราบจึงเป็นศูนย์ ความเร็วแนวราบคงที่ตลอดวิถี', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-axis-analysis')), 'choice', 'ในแนวตั้งของการเคลื่อนที่โพรเจกไทล์ ความเร่งมีค่าเท่าใด', '["0","g ในทิศลง","g ในทิศขึ้น","ขึ้นกับมุมยิง"]', '1', 'แนวตั้งมีแต่แรงโน้มถ่วง ความเร่งจึงเท่ากับ g ในทิศลงเสมอ ไม่ขึ้นกับมุมยิง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-axis-analysis')), 'choice', 'ที่จุดสูงสุดของวิถีโพรเจกไทล์ ความเร็วในแนวตั้งมีค่าเท่าใด', '["เท่ากับตอนยิง","ใหญ่ที่สุด","ศูนย์","เท่ากับความเร็วแนวราบ"]', '2', 'ที่จุดสูงสุดความเร็วแนวตั้งเป็นศูนย์ แต่ความเร็วแนวราบยังคงอยู่ จึงไม่หยุดนิ่งสนิท', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-axis-analysis')), 'number', 'ยิงด้วยความเร็วต้น 40 เมตร/วินาทีที่มุม 30 องศากับแนวราบ ความเร็วในแนวราบเป็นเท่าใด (กำหนด cos 30° ≈ 0.866 ตอบเป็นเมตร/วินาที ทศนิยม 1 ตำแหน่ง)', NULL, '{"value":34.6,"tolerance":0.05}', 'vx = v cos θ = 40 x 0.866 = 34.64 ≈ 34.6 เมตร/วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'projectile-axis-analysis')), 'number', 'จากข้อก่อนที่ยิงด้วยความเร็วต้น 40 เมตร/วินาทีมุม 30 องศา ความเร็วเริ่มต้นในแนวตั้งเป็นเท่าใด (กำหนด sin 30° = 0.5 ตอบเป็นเมตร/วินาที จำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', 'vy = v sin θ = 40 x 0.5 = 20 เมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'projectile'), 'projectile-intro', 'โพรเจกไทล์: ภาพรวมการเคลื่อนที่เป็นเส้นโค้ง', 'การเคลื่อนที่แบบโพรเจกไทล์คือการเคลื่อนที่แบบสองมิติภายใต้แรงโน้มถ่วงของโลกเพียงอย่างเดียว เส้นทางการเคลื่อนที่เป็นรูปพาราโบลา โดยการเคลื่อนที่ในแนวราบและแนวดิ่งเกิดขึ้นพร้อมกันแต่เป็นอิสระต่อกัน เวลาที่ใช้ในการเคลื่อนที่ทั้งสองแนวจะเท่ากันเสมอ ความเร็วในแนวราบคงตัวเพราะไม่มีแรงลัพธ์มากระทำ ส่วนแนวดิ่งมีความเร่งคงที่ g มีทิศพุ่งลง', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-intro'), 'youtube', 'https://www.youtube.com/watch?v=UTMXSCv2Slo', 'UTMXSCv2Slo', 'ฟิสิกส์ ม.4 บทที่ 7 การเคลื่อนที่แนวโค้ง ep.1 (การเคลื่อนที่แบบโพรเจกไทล์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'projectile-intro'), 'youtube', 'https://www.youtube.com/watch?v=ZrFyxC3x3-w', 'ZrFyxC3x3-w', 'ฟิสิกส์ ม.4 บทที่ 7 การเคลื่อนที่แนวโค้ง ep.2 (การเคลื่อนที่แบบโพรเจกไทล์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
