INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'quantum-bohr-model'), 'แบบทดสอบ: แบบจำลองอะตอมของบอร์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-bohr-model')), 'choice', 'สมมติฐานสำคัญของบอร์เกี่ยวกับวงโคจรของอิเล็กตรอนในอะตอมไฮโดรเจนคือข้อใด', '["อิเล็กตรอนโคจรได้เฉพาะรัศมีที่กำหนดให้เท่านั้น","อิเล็กตรอนอยู่นิ่งที่นิวเคลียส","อิเล็กตรอนไม่มีวงโคจร","อิเล็กตรอนโคจรได้ทุกรัศมี"]', '0', 'บอร์เสนอว่าอิเล็กตรอนโคจรได้เฉพาะวงโคจรที่เสถียรบางวง โดยมีเงื่อนไขโมเมนตัมเชิงมุม mvr = nh/2π รัศมีจึงถูกกำหนดเป็นค่าเฉพาะ (quantized)', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-bohr-model')), 'choice', 'เมื่ออิเล็กตรอนเปลี่ยนจากวงโคจรพลังงานสูงไปวงโคจรพลังงานต่ำ ผลคืออะไร', '["ปล่อยอิเล็กตรอนออกมา","ดูดซับโฟตอน","ปล่อยโฟตอนออกมา","ไม่มีการเปลี่ยนแปลง"]', '2', 'เมื่ออิเล็กตรอนตกจากระดับพลังงานสูงไปต่ำ พลังงานส่วนต่าง ΔE ปล่อยออกมาเป็นโฟตอนตาม ΔE = hf ทำให้เกิดเส้นสเปกตรัมการแผ่รังสี', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-bohr-model')), 'choice', 'พลังงานของอิเล็กตรอนในวงโคจรที่ n ของอะตอมไฮโดรเจนมีค่าเป็นอย่างไรตามแบบจำลองของบอร์', '["เป็นบวกเสมอ","เท่ากันทุกวง","เป็นไปอย่างต่อเนื่อง","มีค่าไม่ต่อเนื่องและเป็นลบ"]', '3', 'พลังงานอิเล็กตรอนในแบบจำลองบอร์มีค่าไม่ต่อเนื่อง (quantized) และเป็นลบ เพราะอิเล็กตรอนถูกยึดเหนี่ยวกับนิวเคลียส E = −13.6/n² อิเล็กตรอนวอลต์ ยิ่ง n มากพลังงานยิ่งสูง (เป็นลบน้อยลง)', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-bohr-model')), 'number', 'อิเล็กตรอนในอะตอมไฮโดรเจนเปลี่ยนจากระดับพลังงาน −1.51 อิเล็กตรอนโวลต์ ไปยังระดับ −3.40 อิเล็กตรอนโวลต์ พลังงานโฟตอนที่ปล่อยออกมาเท่ากับกี่อิเล็กตรอนโวลต์ (ตอบเป็นทศนิยม 2 ตำแหน่ง)', NULL, '{"value":1.89,"tolerance":0.005}', 'ΔE = Eสูง − Eต่ำ = (−1.51) − (−3.40) = 1.89 อิเล็กตรอนโวลต์ พลังงานส่วนนี้ปล่อยเป็นโฟตอน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'quantum-bohr-model')), 'number', 'อิเล็กตรอนในอะตอมไฮโดรเจนระดับ n = 2 มีพลังงาน −3.4 อิเล็กตรอนโวลต์ และระดับ n = 1 มีพลังงาน −13.6 อิเล็กตรอนโวลต์ ถ้าอิเล็กตรอนตกจาก n = 2 ไป n = 1 พลังงานโฟตอนที่ปล่อยเท่ากับกี่อิเล็กตรอนโวลต์ (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":10.2,"tolerance":0.05}', 'ΔE = −3.4 − (−13.6) = 10.2 อิเล็กตรอนโวลต์ พลังงานนี้ปล่อยเป็นโฟตอนเมื่ออิเล็กตรอนตกระดับ', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'quantum-atom'), 'quantum-de-broglie', 'สมบัติคลื่นของอนุภาค เดอบรอยล์', 'หลุยส์ เดอบรอยล์ เสนอสมมติฐานว่าอนุภาคของสสารที่กำลังเคลื่อนที่สามารถแสดงสมบัติเป็นคลื่นได้เช่นเดียวกับคลื่นแม่เหล็กไฟฟ้า ความยาวคลื่นของสสารเรียกว่าความยาวคลื่นเดอบรอยล์ คำนวณได้จากสมการ lambda = h/p = h/(mv) โดยที่ h คือค่าคงตัวของพลังค์ และ p คือโมเมนตัม สำหรับวัตถุขนาดใหญ่จะมีโมเมนตัมมากทำให้ความยาวคลื่นสั้นจนตรวจวัดไม่ได้ แต่สำหรับอิเล็กตรอนความยาวคลื่นจะมีค่าเทียบเท่าระยะห่างระหว่างอะตอม นำไปสู่การประดิษฐ์กล้องจุลทรรศน์อิเล็กตรอน', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'quantum-de-broglie'), 'youtube', 'https://www.youtube.com/watch?v=vBjPJqRarvs', 'vBjPJqRarvs', 'ฟิสิกส์ ม.6 บทที่ 19 ฟิสิกส์อะตอม ep.14 (ความยาวคลื่นเดอบรอยล์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
