INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'reflection-refraction-critical-angle'), 'แบบทดสอบ: ดัชนีหักเหและการสะท้อนกลับหมด', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-critical-angle')), 'choice', 'เงื่อนไขที่ทำให้เกิดการสะท้อนกลับหมดของแสงคือข้อใด', '["แสงเดินทางจากตัวกลางเบาไปยังตัวกลางหนาแน่นกว่า","มุมตกกระทบเท่ากับศูนย์","แสงเดินทางจากตัวกลางหนาแน่นไปยังหนาแน่นน้อย ด้วยมุมตกกระทบมากกว่ามุมวิกฤต","มุมตกกระทบน้อยกว่ามุมวิกฤต"]', '2', 'การสะท้อนกลับหมดต้องเดินทางจากหนาแน่นไปเบา และมุมตกกระทบมากกว่ามุมวิกฤต ทำให้แสงสะท้อนกลับทั้งหมด', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-critical-angle')), 'choice', 'มุมวิกฤต คือมุมตกกระทบที่ทำให้มุมหักเหมีค่าเท่าใด', '["0 องศา","90 องศา","45 องศา","180 องศา"]', '1', 'มุมวิกฤตคือมุมตกกระทบที่ทำให้แสงหักเหไปตามรอยต่อ (มุมหักเห 90 องศา) ถ้าเกินนี้จะสะท้อนกลับหมด', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-critical-angle')), 'choice', 'การสะท้อนกลับหมดถูกนำไปใช้ประโยชน์หลักในอุปกรณ์ใด', '["กระจกมองหลังรถยนต์","เลนส์แว่นตา","ใยแก้วนำแสง","กล้องดูดาว"]', '2', 'ใยแก้วนำแสงใช้การสะท้อนกลับหมดที่ผิวภายในเพื่อนำแสงเดินทางเป็นระยะไกลโดยสูญเสียน้อย', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-critical-angle')), 'number', 'แก้วมีดัชนีหักเห 1.5 อยู่ติดกับอากาศ (ดัชนีหักเห 1) ค่า sin ของมุมวิกฤตเท่ากับเท่าใด (ตอบเป็นทศนิยม 2 ตำแหน่ง)', NULL, '{"value":0.67,"tolerance":0.005}', 'sin θc = n2/n1 = 1/1.5 = 0.666... จึงตอบ 0.67', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-critical-angle')), 'number', 'น้ำมีดัชนีหักเห 1.33 อยู่ติดกับอากาศ (1) ค่า sin ของมุมวิกฤตเท่ากับเท่าใด (ตอบเป็นทศนิยม 2 ตำแหน่ง)', NULL, '{"value":0.75,"tolerance":0.005}', 'sin θc = n2/n1 = 1/1.33 = 0.75 (1/1.33 ≈ 0.75)', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'reflection-refraction'), 'reflection-refraction-curved-mirror', 'กระจกโค้ง (เว้า/นูน) และภาพ', 'กระจกโค้งทรงกลมแบ่งออกเป็นกระจกเว้าที่รวมแสงและกระจกนูนที่กระจายแสง โดยมีความยาวโฟกัสเป็นครึ่งหนึ่งของรัศมีความโค้ง f = R/2 ตำแหน่งและขนาดของภาพคำนวณได้จากสมการ 1/f = 1/s + 1/s'' และ m = -s''/s กระจกเว้าสามารถให้ได้ทั้งภาพจริงและภาพเสมือนขึ้นกับระยะวัตถุ ส่วนกระจกนูนจะให้ภาพเสมือน หัวตั้ง ขนาดเล็กกว่าวัตถุเสมอ จึงนิยมนำไปติดตั้งเป็นกระจกส่องหลังรถและกระจกโค้งตามมุมถนน', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'reflection-refraction-curved-mirror'), 'youtube', 'https://www.youtube.com/watch?v=2wZPVSYUHe8', '2wZPVSYUHe8', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.2 (ภาพที่เกิดจากกระจกโค้ง กระจกเว้า กระจกนูน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'reflection-refraction-curved-mirror'), 'youtube', 'https://www.youtube.com/watch?v=22MFeoDawrI', '22MFeoDawrI', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.3 (กระจกโค้งเว้า กระจกโค้งนูน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'reflection-refraction-curved-mirror'), 'thin-lens', 'จำลองการเกิดภาพจากกระจกโค้งเว้าและโค้งนูนตามระยะวัตถุ', '{"objectDistance":{"min":10,"max":60,"step":1,"default":36},"focalLength":{"min":8,"max":25,"step":1,"default":14},"isConcave":false}');
