INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'reflection-refraction-curved-mirror'), 'แบบทดสอบ: กระจกโค้ง (เว้า/นูน) และภาพ', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-curved-mirror')), 'choice', 'ความสัมพันธ์ระหว่างความยาวโฟกัส f และรัศมีความโค้ง R ของกระจกทรงกลมคือข้อใด', '["f = R/2","f = R","f = 2R","f = 3R"]', '0', 'จุดโฟกัสอยู่กลางทางระหว่างจุดยอดกับจุดศูนย์กลางความโค้ง จึงได้ f = R/2', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-curved-mirror')), 'choice', 'ภาพจากกระจกนูน (กระจกโค้งที่ผิวนูน) สำหรับวัตถุจริงที่อยู่หน้ากระจกเป็นภาพแบบใด', '["ภาพจริง กลับหัว","ภาพจริง ขยายใหญ่","ภาพเสมือน หัวตั้ง และเล็กกว่าวัตถุ","ภาพเสมือน กลับหัว"]', '2', 'กระจกนูนให้ภาพเสมือนหัวตั้งและเล็กลงเสมอไม่ว่าวัตถุอยู่ที่ตำแหน่งใด จึงใช้เป็นกระจกมองหลัง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-curved-mirror')), 'choice', 'สมการของกระจกทรงกลม (หรือเลนส์) ที่ใช้หาตำแหน่งภาพคือข้อใด เมื่อ f คือความยาวโฟกัส s คือระยะวัตถุ s'' คือระยะภาพ', '["1/f = s + s''","f = s − s''","1/f = 1/s + 1/s''","f = s × s''"]', '2', 'สมการกระจก-เลนส์คือ 1/f = 1/s + 1/s'' ใช้หาตำแหน่งภาพเมื่อรู้ระยะวัตถุและความยาวโฟกัส', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-curved-mirror')), 'number', 'กระจกเว้ารัศมีความโค้ง 30 เซนติเมตร ความยาวโฟกัสเท่ากับกี่เซนติเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":15,"tolerance":0.5}', 'f = R/2 = 30/2 = 15 เซนติเมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-curved-mirror')), 'number', 'กระจกเว้ามีความยาวโฟกัส 10 เซนติเมตร วางวัตถุไว้หน้ากระจก 20 เซนติเมตร ระยะภาพเท่ากับกี่เซนติเมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', '1/f = 1/s + 1/s'' → 1/10 = 1/20 + 1/s'' → 1/s'' = 1/20 → s'' = 20 เซนติเมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'reflection-refraction'), 'reflection-refraction-plane-mirror', 'กระจกเงาราบและภาพ', 'การเกิดภาพบนกระจกเงาราบเป็นผลมาจากกฎการสะท้อนของแสง โดยรังสีสะท้อนที่เข้าสู่ตาเสมือนว่าตัดกันที่ด้านหลังกระจก จึงเกิดเป็นภาพเสมือน (Virtual image) ที่ไม่สามารถเอาฉากมารับได้ ภาพที่ได้จะเป็นภาพหัวตั้ง มีขนาดเท่ากับวัตถุจริง (กำลังขยาย m = 1) และมีระยะภาพหลังกระจกเท่ากับระยะวัตถุหน้ากระจกพอดี (s'' = s) อีกทั้งยังมีสมบัติกลับซ้ายขวาหรือปรัศวภาควิโลม', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
