INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-plane-mirror')), 'choice', 'ภาพที่เกิดจากกระจกเงาราบเป็นภาพแบบใด', '["ภาพจริง กลับหัว","ภาพจริง หัวตั้ง","ภาพเสมือน หัวตั้ง ขนาดเท่าวัตถุ","ภาพเสมือน กลับหัว"]', '2', 'ภาพจากกระจกเงาราบเป็นภาพเสมือนหัวตั้ง ขนาดเท่ากับวัตถุ และอยู่หลังกระจกในระยะเท่ากับระยะของวัตถุ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-plane-mirror')), 'choice', 'วัตถุที่อยู่หน้ากระจกเงาราบในระยะ d ภาพจะปรากฏอยู่หลังกระจกในระยะเท่าใด', '["เท่ากับ d","ครึ่งหนึ่งของ d","เป็น 2 เท่าของ d","เป็นศูนย์"]', '0', 'สำหรับกระจกเงาราบ ระยะภาพหลังกระจกเท่ากับระยะวัตถุหน้ากระจกพอดี คือ d เท่ากัน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-plane-mirror')), 'choice', 'ข้อใดกล่าวถึงภาพจากกระจกเงาราบได้ถูกต้อง', '["ภาพกลับหัวและกลับซ้าย-ขวา","ภาพกลับหัวแต่ไม่กลับซ้าย-ขวา","ภาพหัวตั้งและกลับซ้าย-ขวา","ภาพหัวตั้งและไม่กลับซ้าย-ขวา"]', '1', 'ภาพจากกระจกเงาราบหัวตั้งตามปกติ แต่กลับซ้าย-ขวา เช่น ลายมือขวาทำให้ดูเหมือนมือซ้าย', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-plane-mirror')), 'number', 'วัตถุอยู่ห่างจากกระจกเงาราบ 1.5 เมตร ภาพอยู่ห่างจากกระจกไปทางด้านหลังกี่เมตร (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":1.5,"tolerance":0.05}', 'ระยะภาพหลังกระจกเงาราบเท่ากับระยะวัตถุ คือ 1.5 เมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-plane-mirror')), 'number', 'วัตถุอยู่ห่างจากกระจกเงาราบ 2 เมตร ระยะห่างระหว่างวัตถุกับภาพเท่ากับกี่เมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 'วัตถุอยู่หน้ากระจก 2 เมตร ภาพอยู่หลังกระจก 2 เมตร ระยะระหว่างวัตถุและภาพ = 2 + 2 = 4 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'reflection-refraction'), 'reflection-refraction-snells-law', 'การหักเหของแสงและกฎของสเนลล์', 'กฎของสเนลล์ระบุความสัมพันธ์ของการหักเหระหว่างตัวกลางสองชนิดด้วยสมการ n1 sin(θ1) = n2 sin(θ2) หรือ sin(θ1)/sin(θ2) = v1/v2 = λ1/λ2 โดย n คือดัชนีหักเหของตัวกลาง ดัชนีหักเหสัมพันธ์กับความเร็วแสงในสุญญากาศตามสูตร n = c/v เมื่อแสงเดินทางจากตัวกลางที่มีค่า n ต่ำไปยังตัวกลางที่มีค่า n สูง แสงจะหักเหเบนเข้าหาเส้นแนวฉาก ทำให้มุมหักเหน้อยกว่ามุมตกกระทบ', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'reflection-refraction-snells-law'), 'youtube', 'https://www.youtube.com/watch?v=O8nlR-roUgc', 'O8nlR-roUgc', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.5 (การหักเหของแสง,การสะท้อนกลับหมด,มุมวิกฤต)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'reflection-refraction-snells-law'), 'youtube', 'https://www.youtube.com/watch?v=Ga2fQedj7BQ', 'Ga2fQedj7BQ', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.4 (โจทย์กระจกโค้ง,การหักเหของแสง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
