INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'reflection-refraction-snells-law'), 'แบบทดสอบ: การหักเหของแสงและกฎของสเนลล์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-snells-law')), 'choice', 'กฎของสเนลล์ (Snell''s Law) สำหรับแสงที่หักเหผ่านผิวรอยต่อระหว่างตัวกลางสองชนิดคือข้อใด', '["n1 cos θ1 = n2 cos θ2","n1 sin θ1 = n2 sin θ2","θ1 = θ2 เสมอ","n1 = n2 เสมอ"]', '1', 'กฎของสเนลล์คือ n1 sin θ1 = n2 sin θ2 เมื่อ n คือดัชนีหักเหและ θ คือมุมกับเส้นแนวฉาก', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-snells-law')), 'choice', 'เมื่อแสงเดินทางจากอากาศเข้าสู่แก้ว (ตัวกลางหนาแน่นกว่า) มุมหักเหเทียบกับเส้นแนวฉากเป็นอย่างไร', '["น้อยกว่ามุมตกกระทบ","มากกว่ามุมตกกระทบ","เท่ากับมุมตกกระทบ","เท่ากับ 90 องศาเสมอ"]', '0', 'เมื่อเข้าสู่ตัวกลางหนาแน่นขึ้นแสงหักเหเข้าหาเส้นแนวฉาก ทำให้มุมหักเหน้อยกว่ามุมตกกระทบ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-snells-law')), 'choice', 'สาเหตุของการหักเหของแสงเมื่อเปลี่ยนตัวกลางคือข้อใด', '["สีของแสงเปลี่ยนไป","แสงเลี้ยวเบน","อัตราเร็วของแสงเปลี่ยนไป","แสงสะท้อนภายใน"]', '2', 'การหักเหเกิดเพราะอัตราเร็วของแสงในแต่ละตัวกลางต่างกัน คลื่นจึงเปลี่ยนทิศเมื่อข้ามรอยต่อ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-snells-law')), 'number', 'แสงในสุญญากาศมีความเร็ว 300000 กิโลเมตรต่อวินาที เคลื่อนที่ในแก้วด้วยความเร็ว 200000 กิโลเมตรต่อวินาที ดัชนีหักเหของแก้วเท่ากับเท่าใด (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":1.5,"tolerance":0.05}', 'n = c/v = 300000/200000 = 1.5', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'reflection-refraction-snells-law')), 'number', 'แสงในสุญญากาศมีความเร็ว 300000 กิโลเมตรต่อวินาที เดินทางในตัวกลางหนึ่งด้วยความเร็ว 250000 กิโลเมตรต่อวินาที ดัชนีหักเหของตัวกลางนี้เท่ากับเท่าใด (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":1.2,"tolerance":0.05}', 'n = c/v = 300000/250000 = 1.2', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'relativity'), 'relativity-mass-energy-equivalence', 'ความสมมูลมวลและพลังงาน E = mc²', 'ไอน์สไตน์ได้ค้นพบความสัมพันธ์ระหว่างมวลและพลังงานผ่านสมการที่โด่งดังที่สุด E = mc^2 ซึ่งระบุว่ามวลนิ่ง m0 มีพลังงานสะสมอยู่มหาศาลเรียกว่าพลังงานนิ่ง E0 = m0*c^2 สำหรับวัตถุที่กำลังเคลื่อนที่ด้วยความเร็ว v พลังงานทั้งหมดของระบบจะเป็น E = gamma*m0*c^2 และพลังงานจลน์สัมพัทธภาพคือ Ek = (gamma - 1)*m0*c^2 ความสมมูลนี้เป็นหัวใจของฟิสิกส์นิวเคลียร์ โดยมวลที่ลดลงเพียงเล็กน้อยในปฏิกิริยานิวเคลียร์สามารถเปลี่ยนเป็นพลังงานความร้อนและรังสีได้อย่างมหาศาล', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
