INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'relativity-mass-energy-equivalence'), 'modern-quantum', 'จำลองการแปลงมวลเป็นพลังงานสัมพัทธภาพตามสมการ E = mc²', '{"mode":"relativity","speedRatio":{"min":0.2,"max":0.98,"step":0.02,"default":0.76}}');
