INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'relativity-mass-energy-equivalence'), 'แบบทดสอบ: ความสมมูลมวลและพลังงาน E = mc²', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-mass-energy-equivalence')), 'choice', 'สมการความสมมูลมวลและพลังงานตามไอน์สไตน์คือข้อใด', '["E = mc²","E = mgh","E = hf","E = ½mv²"]', '0', 'E = mc² เป็นสมการความสมมูลมวลพลังงาน โดย c คืออัตราเร็วแสง พลังงานมหาศาลเกิดจากมวลแม้เพียงเล็กน้อย เพราะ c² มีค่ามาก', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-mass-energy-equivalence')), 'choice', 'เมื่อมวล 1 กิโลกรัม เปลี่ยนเป็นพลังงาน พลังงานที่ได้มีขนาดประมาณเท่าใด', '["เป็นศูนย์","เท่ากับ c จูล","เท่ากับ c² จูล ซึ่งมีค่ามหาศาล","เท่ากับ ½c² จูล"]', '2', 'E = mc² โดย c มีค่ามาก จึงได้พลังงานมหาศาลจากมวลเพียงเล็กน้อย แสดงถึงหลักการที่มวลสามารถเปลี่ยนเป็นพลังงานได้มหาศาล', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-mass-energy-equivalence')), 'choice', 'ในปฏิกิริยานิวเคลียร์ มวลรวมของผลิตภัณฑ์น้อยกว่ามวลรวมของสารตั้งต้น มวลที่หายไปไปอยู่ที่ใด', '["กลายเป็นประจุ","สะสมอยู่ในนิวตรอน","ถูกทำลายไปอย่างสิ้นเชิง","เปลี่ยนเป็นพลังงานตาม E = Δmc²"]', '3', 'มวลที่ลดลง (มวลพร่อง) เปลี่ยนเป็นพลังงานตามสมการ E = Δmc² มวลมหายไปโดยไม่ถูกทำลายโดยตรง แต่แปลงเป็นพลังงานจลน์และพลังงานรูปแบบอื่น', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-mass-energy-equivalence')), 'number', 'ตามสมการ E = mc² ถ้ามวลเพิ่มเป็น 2 เท่า โดยความเร็วแสงคงที่ พลังงานจะเพิ่มขึ้นเป็นกี่เท่าของเดิม (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.05}', 'E = mc² แปรผันตรงกับ m เมื่อ m เป็น 2 เท่า E จึงเป็น 2 เท่า', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-mass-energy-equivalence')), 'number', 'ตามสมการ E = mc² วัตถุก้อนหนึ่งมีพลังงาน 12 จูล แล้วเพิ่มมวลเป็น 3 เท่า โดยไม่เปลี่ยนค่าคงที่ พลังงานใหม่เป็นกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":36,"tolerance":0.5}', 'E = mc² แปรผันตรงกับ m พลังงานใหม่ = 3 × 12 = 36 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'relativity'), 'relativity-special-postulates', 'สัมพัทธภาพพิเศษและสมมติฐาน', 'ทฤษฎีสัมพัทธภาพพิเศษของอัลเบิร์ต ไอน์สไตน์ วางอยู่บนสัจพจน์สองข้อสำคัญ ข้อแรกคือกฎทางฟิสิกส์ทั้งหมดจะมีรูปแบบเดียวกันในทุกกรอบอ้างอิงเฉื่อย และข้อสองคืออัตราเร็วของแสงในสุญญากาศ (c ประมาณ 3x10^8 m/s) มีค่าคงที่เท่ากันเสมอสำหรับผู้สังเกตทุกคนโดยไม่ขึ้นกับความเร็วของแหล่งกำเนิดแสง สัจพจน์ทั้งสองข้อนี้ได้ลบล้างแนวคิดเรื่องเวลาและปริภูมิสัมบูรณ์ของนิวตัน นำไปสู่การทำความเข้าใจธรรมชาติใหม่ว่าระยะทางและเวลาจะเปลี่ยนไปตามความเร็วของผู้สังเกต', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
