INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-special-postulates')), 'choice', 'สมมติฐานข้อแรกของสัมพัทธภาพพิเศษกล่าวว่าอย่างไร', '["เวลาเท่ากันทุกกรอบ","กฎฟิสิกส์เหมือนกันในกรอบอ้างอิงเฉื่อยทุกกรอบ","อัตราเร็วแสงต่างกันตามกรอบอ้างอิง","มวลคงที่เสมอ"]', '1', 'สมมติฐานข้อแรก (หลักการสัมพัทธภาพ) กล่าวว่ากฎของฟิสิกส์เหมือนกันในกรอบอ้างอิงเฉื่อยทุกกรอบ จึงไม่มีการทดลองใดแยกได้ว่ากรอบไหนอยู่นิ่งจริง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-special-postulates')), 'choice', 'สมมติฐานข้อที่สองของสัมพัทธภาพพิเศษกล่าวว่าอย่างไร', '["อัตราเร็วแสงขึ้นกับผู้สังเกตที่เคลื่อนที่","อัตราเร็วแสงเพิ่มตามความเร็วแหล่งกำเนิด","อัตราเร็วแสงในสุญญากาศคงที่และเท่ากันสำหรับกรอบเฉื่อยทุกกรอบ","อัตราเร็วแสงเท่ากับศูนย์ในสุญญากาศ"]', '2', 'สมมติฐานข้อที่สองกล่าวว่าอัตราเร็วแสงในสุญญากาศ c มีค่าคงที่เท่ากันสำหรับผู้สังเกตในกรอบเฉื่อยทุกกรอบ ไม่ว่าผู้สังเกตหรือแหล่งกำเนิดจะเคลื่อนที่อย่างไร', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-special-postulates')), 'choice', 'กรอบอ้างอิงเฉื่อยคือกรอบแบบใด', '["กรอบที่หมุนได้","กรอบที่ความเร็วเปลี่ยนตลอดเวลา","กรอบที่เคลื่อนที่ด้วยความเร่งคงที่","กรอบที่เคลื่อนที่ด้วยความเร็วคงที่หรือหยุดนิ่ง"]', '3', 'กรอบอ้างอิงเฉื่อยคือกรอบที่อยู่นิ่งหรือเคลื่อนที่ด้วยความเร็วคงที่ (ไม่มีความเร่ง) ในกรอบเช่นนี้กฎของนิวตันใช้ได้ และเป็นกรอบที่พิจารณาในสัมพัทธภาพพิเศษ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-special-postulates')), 'number', 'จากสมมติฐานว่าอัตราเร็วแสงคงที่ ถ้าแหล่งกำเนิดแสงอยู่นิ่งและผู้สังเกตเคลื่อนที่เข้าหาแหล่งด้วยความเร็ว 0.6c อัตราเร็วแสงที่ผู้สังเกตวัดได้เป็นกี่เท่าของ c (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":1,"tolerance":0.5}', 'ตามสมมติฐานข้อที่สอง อัตราเร็วแสงในสุญญากาศคงที่ c สำหรับทุกกรอบเฉื่อย ไม่ขึ้นกับความเร็วผู้สังเกต ผู้สังเกตจึงวัดแสงได้ c เสมอ คือ 1 เท่าของ c', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-special-postulates')), 'number', 'ตามสมมติฐานข้อที่สอง อัตราเร็วแสงในสุญญากาศคงที่เท่ากับ c สำหรับทุกกรอบอ้างอิงเฉื่อย ถ้าแสงเดินทางในสุญญากาศเป็นเวลา 4 วินาที ระยะทางที่แสงเดินทางได้คิดเป็นเท่าใดของระยะที่แสงเดินทางได้ใน 1 วินาที (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.05}', 'ระยะทางแปรผันตรงกับเวลา เมื่อเวลามากขึ้น 4 เท่า ระยะทางจึงเป็น 4 เท่า เนื่องจากอัตราเร็วคงที่', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'relativity'), 'relativity-time-dilation-length-contraction', 'การยืดของเวลาและการหดของความยาว', 'เมื่อวัตถุเคลื่อนที่สัมพัทธ์ด้วยความเร็วเข้าใกล้ความเร็วแสง แฟกเตอร์ลอเรนตซ์ gamma = 1/sqrt(1 - v^2/c^2) จะมีค่ามากกว่า 1 เสมอ ส่งผลให้เวลาของผู้สังเกตที่เคลื่อนที่จะเดินช้าลงเมื่อมองจากกรอบนิ่ง เรียกว่าการยืดออกของเวลา (Time Dilation) ตามสมการ delta_t = gamma * delta_t0 ในขณะเดียวกัน ความยาวของวัตถุตามแนวการเคลื่อนที่จะหดสั้นลง เรียกว่าการหดสั้นของความยาว (Length Contraction) ตามสมการ L = L0 / gamma ปรากฏการณ์นี้ได้รับการพิสูจน์แล้วจากการยืดอายุของอนุภาคมิวออนและการทำงานของดาวเทียม GPS', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'relativity-time-dilation-length-contraction'), 'youtube', 'https://www.youtube.com/watch?v=GBqmfatFmi0', 'GBqmfatFmi0', 'ทฤษฎีสัมพัทธภาพพิเศษ ตอนที่ 1 การยืดของเวลาและการหดของความยาว', 'Physics Tips', 'https://www.youtube.com/channel/UC8ElpJwdpSGg2HaKe9blUgA', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'relativity-time-dilation-length-contraction'), 'youtube', 'https://www.youtube.com/watch?v=7i2HLKsggfM', '7i2HLKsggfM', 'ทฤษฏีสัมพัทธภาพพิเศษ PART 1 ตอน การหดของความยาวและ การยืดของเวลา', 'One To Many - A Brief Science', 'https://www.youtube.com/channel/UCJ1NapUKndO_3nYB80752nA', 2);
