INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-time-dilation-length-contraction')), 'choice', 'การยืดของเวลากล่าวว่าอย่างไร', '["เวลาของกรอบที่เคลื่อนที่เร็วเดินช้ากว่ากรอบที่หยุดนิ่ง","เวลาของกรอบที่เคลื่อนที่เร็วนาเดินเร็วขึ้น","เวลาเท่ากันทุกกรอบ","เวลาหยุดเดินเมื่อเคลื่อนที่"]', '0', 'การยืดของเวลา (time dilation) กล่าวว่าเวลาที่วัดในกรอบที่เคลื่อนที่สัมพัทธ์จะเดินช้ากว่าเวลาที่วัดในกรอบนิ่งในอัตรา t = t₀/√(1 − v²/c²)', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-time-dilation-length-contraction')), 'choice', 'การหดของความยาวเกิดขึ้นในทิศทางใด', '["ทิศตั้งฉากกับการเคลื่อนที่","ทิศขนาน (ตามแนว) กับการเคลื่อนที่","ทุกทิศทางเท่ากัน","ความยาวไม่หดเลย"]', '1', 'ความยาวหดเฉพาะทิศที่ขนานกับทิศการเคลื่อนที่ L = L₀√(1 − v²/c²) ส่วนความยาวที่ตั้งฉากกับทิศการเคลื่อนที่ไม่เปลี่ยนแปลง', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-time-dilation-length-contraction')), 'choice', 'ถ้าความเร็วของวัตถุเข้าใกล้ความเร็วแสง ความยาวของวัตถุตามทิศการเคลื่อนที่เมื่อผู้สังเกตนิ่งวัดได้ จะเป็นอย่างไร', '["เป็นศูนย์เสมอ","ยาวขึ้นเรื่อยๆ","สั้นลงเรื่อยๆ","ไม่เปลี่ยนแปลง"]', '2', 'เมื่อ v เข้าใกล้ c ตัวประกอบ γ = 1/√(1 − v²/c²) มีค่ามาก ความยาวหด (L = L₀/γ) จึงสั้นลงเรื่อยๆ จนเข้าใกล้ศูนย์ตามหลักการหดของความยาว', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-time-dilation-length-contraction')), 'number', 'ยานอวกาศเคลื่อนที่ด้วยความเร็ว 0.6c ผู้โดยสารบนยานวัดเวลาบนยานได้ 4 วินาที ผู้สังเกตบนโลกคำนวณว่าช่วงเวลานี้กินเวลากี่วินาที (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":5,"tolerance":0.05}', 'γ = 1/√(1 − 0.36) = 1/√0.64 = 1/0.8 = 1.25 ดังนั้น t = γ·t₀ = 1.25 × 4 = 5 วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'relativity-time-dilation-length-contraction')), 'number', 'แท่งยาว 20 เมตร ตามผู้สังเกตที่อยู่นิ่งกับแท่ง ยานอวกาศเคลื่อนที่ผ่านด้วยความเร็ว 0.6c ตามแนวแกนของแท่ง ความยาวของแท่งที่ผู้สังเกตบนยานวัดได้เท่ากับกี่เมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":16,"tolerance":0.5}', 'γ = 1/√(1 − 0.36) = 1.25 ดังนั้น L = L₀/γ = 20/1.25 = 16 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'oscillation-gravity'), 'simple-harmonic-motion', 'การเคลื่อนที่แบบฮาร์มอนิกอย่างง่าย', 'การเคลื่อนที่แบบฮาร์มอนิกอย่างง่าย (Simple Harmonic Motion, SHM) เป็นการเคลื่อนที่กลับไปกลับมาซ้ำรอยเดิมรอบตำแหน่งสมดุล โดยมีความเร่งแปรผันตรงกับการกระจัดแต่มีทิศตรงกันข้ามเสมอ (a = -ω²x) การกระจัดที่จุดสมดุลเป็นศูนย์และมีค่าสูงสุดที่จุดปลาย (x = A) ความเร็วจะมีค่าสูงสุดที่ตำแหน่งสมดุล (v_max = ωA) และเป็นศูนย์ที่จุดปลาย ส่วนความเร่งจะมีค่าสูงสุดที่จุดปลาย (a_max = ω²A)', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
