INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'simple-harmonic-motion')), 'choice', 'การเคลื่อนที่แบบฮาร์มอนิกอย่างง่าย (SHM) มีแรงฟื้นกลับที่มีสมบัติอย่างไร', '["แปรผันตรงกับการกระจัด และมีทิศตรงข้ามการกระจัด","แปรผันตรงกับเวลาที่แกว่ง","คงที่ตลอดทั้งรอบ","เป็นศูนย์เสมอ"]', '0', 'แรงฟื้นกลับ F ∝ −x คือแปรผันตรงกับขนาดการกระจัดและมีทิศตรงข้าม พุ่งกลับเข้าหาจุดสมดุล', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'simple-harmonic-motion')), 'choice', 'ถ้าเพิ่มแอมพลิจูดของการแกว่ง คาบของการเคลื่อนที่จะเป็นอย่างไร', '["เพิ่มขึ้น","ลดลง","ไม่เปลี่ยนแปลง","เป็นศูนย์"]', '2', 'คาบของ SHM ขึ้นกับสมบัติของระบบ (มวลและความแข็ง) ไม่ขึ้นกับแอมพลิจูด จึงไม่เปลี่ยนแปลงเมื่อเพิ่มแอมพลิจูด', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'simple-harmonic-motion')), 'choice', 'แอมพลิจูดของการแกว่งหมายถึงอะไร', '["ระยะการกระจัดจากจุดสมดุลถึงจุดสูงสุดของแต่ละข้าง","จำนวนรอบในหนึ่งวินาที","เวลาที่แกว่งครบหนึ่งรอบ","ความเร็วสูงสุดของวัตถุ"]', '0', 'แอมพลิจูดคือขนาดการกระจัดสูงสุดจากตำแหน่งสมดุล เป็นค่าบวกเสมอ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'simple-harmonic-motion')), 'number', 'วัตถุแกว่งครบ 20 รอบในเวลา 10 วินาที คาบการแกว่งมีค่ากี่วินาที', NULL, '{"value":0.5,"tolerance":0.05}', 'คาบคือเวลาต่อหนึ่งรอบ T = 10/20 = 0.5 วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'simple-harmonic-motion')), 'number', 'วัตถุแกว่งด้วยความถี่ 5 รอบต่อวินาที คาบการแกว่งมีค่ากี่วินาที', NULL, '{"value":0.2,"tolerance":0.05}', 'คาบคือส่วนกลับของความถี่ T = 1/f = 1/5 = 0.2 วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'sound'), 'sound-beats', 'บีต', 'ปรากฏการณ์บีตเกิดขึ้นเมื่อคลื่นเสียงสองขบวนที่มีความถี่ต่างกันเล็กน้อยเคลื่อนที่มารวมกันในหูของผู้ฟัง ทำให้เกิดเสียงดังและค่อยสลับกันเป็นจังหวะสม่ำเสมอ ความถี่บีต (f_B) เท่ากับผลต่างทางบวกของความถี่ทั้งสองแหล่ง f_B = |f1 - f2| โดยหูของมนุษย์สามารถแยกแยะจังหวะบีตได้ชัดเจนเมื่อความถี่บีตไม่เกินประมาณ 7 เฮิรตซ์ ปรากฏการณ์นี้นิยมนำไปใช้ในการเทียบเสียงเครื่องดนตรี เช่น การเทียบสายกีตาร์ให้มีความถี่ตรงกับส้อมเสียงมาตรฐาน', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-beats'), 'youtube', 'https://www.youtube.com/watch?v=N13pZxRmfeo', 'N13pZxRmfeo', 'ฟิสิกส์ ม.5 บทที่ 12 เสียง ep.6 (เสียงกับการได้ยิน, การสั่นพ้อง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-beats'), 'youtube', 'https://www.youtube.com/watch?v=i1FFE1JZuE0', 'i1FFE1JZuE0', 'ฟิสิกส์ ม.5 บทที่ 12 เสียง ep.7 (การสั่นพ้องของเสียง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-beats'), 'harmonic-wave', 'สังเกตการรวมกันของคลื่นเสียงสองความถี่ที่ใกล้เคียงกันจนเกิดบีต', '{"frequency":{"min":1,"max":10,"default":6},"wavelength":{"min":1,"max":10,"default":2},"amplitude":{"min":1,"max":5,"default":2.5}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-beats'), 'wave-tuner', 'ปรับแต่งความถี่ของคลื่นเสียงให้สอดคล้องกับจังหวะบีตเป้าหมาย', '{"tolerance":0.8,"targetSpeed":[9,36],"frequency":{"min":1,"max":10,"default":6},"wavelength":{"min":1,"max":10,"default":2}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-beats'), 'แบบทดสอบ: บีต', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-beats')), 'choice', 'บีตเกิดจากปรากฏการณ์ใด', '["คลื่นเสียงสองความถี่เท่ากันพอดีซ้อนทับกัน","คลื่นเสียงสองความถี่ที่ใกล้เคียงกันซ้อนทับกัน","เสียงที่มีความดังมากเกินไป","เสียงสะท้อนจากผนัง"]', '1', 'บีตเกิดเมื่อคลื่นเสียงสองความถี่ใกล้เคียงกันซ้อนทับกัน ทำให้แอมพลิจูดลัพธ์แกว่งเป็นจังหวะดัง-เบา', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-beats')), 'choice', 'ความถี่บีต fb หาได้จากความสัมพันธ์ใด เมื่อ f1 และ f2 เป็นความถี่ของเสียงทั้งสอง', '["fb = f1 + f2","fb = f1 × f2","fb = |f1 − f2|","fb = (f1 + f2)/2"]', '2', 'ความถี่บีตเท่ากับผลต่างของความถี่ทั้งสอง fb = |f1 − f2|', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-beats')), 'choice', 'จำนวนครั้งที่เสียงดังและเบาสลับกันต่อวินาทีเท่ากับปริมาณใด', '["ความถี่บีต","ความถี่ของเสียงที่สูงกว่า","ค่าเฉลี่ยของความถี่ทั้งสอง","แอมพลิจูดของคลื่นลัพธ์"]', '0', 'จำนวนจังหวะที่ได้ยินเสียงดัง-เบาต่อวินาทีเท่ากับความถี่บีต fb = |f1 − f2|', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-beats')), 'number', 'แหล่งกำเนิดเสียงสองแหล่งมีความถี่ 256 เฮิรตซ์ และ 260 เฮิรตซ์ ความถี่บีตเท่ากับกี่เฮิรตซ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 'fb = |260 − 256| = 4 เฮิรตซ์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-beats')), 'number', 'ได้ยินเสียงดัง-เบาสลับกัน 6 ครั้งต่อวินาที โดยแหล่งหนึ่งมีความถี่ 440 เฮิรตซ์ แหล่งที่สองมีความถี่สูงกว่าเล็กน้อย ความถี่ของแหล่งที่สองเท่ากับกี่เฮิรตซ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":446,"tolerance":0.5}', 'fb = |f2 − 440| = 6 และ f2 สูงกว่า จึงได้ f2 = 440 + 6 = 446 เฮิรตซ์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'sound'), 'sound-doppler', 'ปรากฏการณ์ดอปเพลอร์', 'ปรากฏการณ์ดอปเพลอร์คือการเปลี่ยนแปลงความถี่และระดับเสียงที่ผู้สังเกตได้รับเมื่อแหล่งกำเนิดเสียงหรือผู้สังเกตเคลื่อนที่สัมพัทธ์กัน ความถี่ปรากฏคำนวณได้จาก f_L = f_S * (v ± v_L) / (v ∓ v_S) โดย v คือความเร็วเสียงในอากาศ เมื่อแหล่งกำเนิดเคลื่อนที่เข้าหาผู้ฟัง ความยาวคลื่นด้านหน้าจะสั้นลงทำให้ได้ยินเสียงความถี่สูงขึ้น และเมื่อเคลื่อนที่ห่างออกไปจะได้ยินเสียงความถี่ต่ำลง หากแหล่งกำเนิดเคลื่อนที่เร็วกว่าเสียงจะเกิดคลื่นกระแทกและกรวยมัค', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-doppler'), 'youtube', 'https://www.youtube.com/watch?v=gf1EjigLlVs', 'gf1EjigLlVs', 'ฟิสิกส์ ม.5 บทที่ 12 เสียง ep.8 (ปรากฎการณ์ดอปเพลอร์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
