INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-doppler'), 'harmonic-wave', 'สังเกตความยาวคลื่นด้านหน้าและด้านหลังจากการเคลื่อนที่ของแหล่งกำเนิดเสียง', '{"frequency":{"min":1,"max":10,"default":5},"wavelength":{"min":1,"max":10,"default":2.5},"amplitude":{"min":1,"max":5,"default":2}}');
