INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-nature-speed'), 'wave-tuner', 'จูนคลื่นให้ได้อัตราเร็วตามเป้าหมาย', '{"tolerance":1}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-nature-speed'), 'แบบทดสอบ: ธรรมชาติของเสียงและอัตราเร็วเสียง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-nature-speed')), 'choice', 'เสียงจัดเป็นคลื่นชนิดใดในแง่ทิศการสั่นของอนุภาค', '["คลื่นตามยาว","คลื่นตามขวาง","คลื่นแม่เหล็กไฟฟ้า","คลื่นนิ่ง"]', '0', 'เสียงเป็นคลื่นตามยาว อนุภาคของตัวกลางสั่นไปตามแนวเดียวกับทิศการเคลื่อนที่ของเสียง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-nature-speed')), 'choice', 'โดยทั่วไปเสียงเดินทางในตัวกลางชนิดใดเร็วที่สุด', '["แก๊ส","ของเหลว","ของแข็ง","สุญญากาศ"]', '2', 'เสียงเดินทางได้เร็วสุดในของแข็ง เพราะอนุภาคอยู่ชิดกันและส่งแรงระหว่างกันได้ดี รองลงมาคือของเหลวและแก๊ส ส่วนสุญญากาศส่งเสียงไม่ได้', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-nature-speed')), 'choice', 'อัตราเร็วเสียงในอากาศแปรผันตามปริมาณใดเป็นสำคัญ', '["ความถี่ของเสียง","แอมพลิจูดของเสียง","อุณหภูมิของอากาศ","สีของแหล่งกำเนิดเสียง"]', '1', 'อัตราเร็วเสียงในอากาศเพิ่มขึ้นเมื่ออุณหภูมิเพิ่มขึ้น โดยไม่ขึ้นกับความถี่หรือแอมพลิจูดของเสียง', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-nature-speed')), 'number', 'เสียงในอากาศเคลื่อนที่ด้วยอัตราเร็ว 340 เมตรต่อวินาที ต้องใช้เวลากี่วินาทีเพื่อเดินทางเป็นระยะ 1020 เมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 't = s/v = 1020/340 = 3 วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-nature-speed')), 'number', 'เสียงเดินทางได้ระยะ 2720 เมตร ในเวลา 8 วินาที อัตราเร็วของเสียงเท่ากับกี่เมตรต่อวินาที (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":340,"tolerance":0.5}', 'v = s/t = 2720/8 = 340 เมตรต่อวินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'sound'), 'sound-standing-waves-pipes-strings', 'คลื่นนิ่งในท่อและสาย (การสั่นพ้อง)', 'คลื่นนิ่งเกิดจากการแทรกสอดของคลื่นสองขบวนที่เหมือนกันทุกประการแต่เคลื่อนที่สวนทางกัน เกิดจุดบัพที่ไม่มีการสั่นและจุดปฏิบัพที่สั่นด้วยแอมพลิจูดสูงสุด การสั่นพ้องในท่อปลายเปิดสองข้างเกิดความถี่ฮาร์มอนิก f_n = n v / (2L) เมื่อ n = 1, 2, 3... ส่วนท่อปลายปิดข้างหนึ่งจะเกิดเฉพาะฮาร์มอนิกคี่ f_n = n v / (4L) เมื่อ n = 1, 3, 5... หลักการนี้เป็นพื้นฐานในการออกแบบและปรับเสียงเครื่องดนตรีประเภทเป่าและเครื่องสาย', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-standing-waves-pipes-strings'), 'youtube', 'https://www.youtube.com/watch?v=i1FFE1JZuE0', 'i1FFE1JZuE0', 'ฟิสิกส์ ม.5 บทที่ 12 เสียง ep.7 (การสั่นพ้องของเสียง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-standing-waves-pipes-strings'), 'youtube', 'https://www.youtube.com/watch?v=N13pZxRmfeo', 'N13pZxRmfeo', 'ฟิสิกส์ ม.5 บทที่ 12 เสียง ep.6 (เสียงกับการได้ยิน, การสั่นพ้อง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-standing-waves-pipes-strings'), 'harmonic-wave', 'จำลองคลื่นนิ่งและการสั่นพ้องในท่อปลายเปิดและท่อปลายปิด', '{"frequency":{"min":1,"max":10,"default":3},"wavelength":{"min":1,"max":10,"default":4},"amplitude":{"min":1,"max":5,"default":3}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-standing-waves-pipes-strings'), 'wave-tuner', 'เทียบความถี่เรโซแนนซ์ให้คลื่นนิ่งมีอัตราเร็วตรงตามเป้าหมาย', '{"tolerance":1.2,"targetSpeed":[6,32],"frequency":{"min":1,"max":10,"default":3},"wavelength":{"min":1,"max":10,"default":4}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'sound-standing-waves-pipes-strings'), 'แบบทดสอบ: คลื่นนิ่งในท่อและสาย (การสั่นพ้อง)', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-standing-waves-pipes-strings')), 'choice', 'การสั่นพ้อง (resonance) เกิดเมื่อใด', '["เมื่อความถี่ของแรงกระทำภายนอกเท่ากับความถี่ธรรมชาติของระบบ","เมื่อความถี่ของแรงภายนอกมากกว่าความถี่ธรรมชาติเสมอ","เมื่อแอมพลิจูดมีค่าน้อยที่สุด","เมื่อคลื่นไม่มีการสะท้อน"]', '0', 'การสั่นพ้องเกิดเมื่อความถี่ของแรงขับเท่ากับความถี่ธรรมชาติ ทำให้ระบบสั่นด้วยแอมพลิจูดสูงสุด', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-standing-waves-pipes-strings')), 'choice', 'สำหรับท่อปลายเปิดทั้งสองข้าง ความยาวคลื่นของฮาร์มอนิกที่ 1 (ความถี่มูลฐาน) สัมพันธ์กับความยาวท่อ L อย่างไร', '["λ = 4L","λ = 2L","λ = L","λ = L/2"]', '1', 'ท่อปลายเปิดทั้งสองข้างมีปฏิบัพที่ปลายทั้งสอง ความยาวคลื่นฮาร์มอนิกที่ 1 เท่ากับ 2L', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-standing-waves-pipes-strings')), 'choice', 'สำหรับท่อปลายปิดข้างหนึ่ง (ปลายหนึ่งปิด อีกปลายเปิด) ความถี่มูลฐาน f หาได้จากสูตรใด เมื่อ v คืออัตราเร็วเสียง และ L คือความยาวท่อ', '["f = v/L","f = 2v/L","f = v/4L","f = v/2L"]', '2', 'ท่อปลายปิดข้างหนึ่งมีความยาวคลื่นฮาร์มอนิกที่ 1 เท่ากับ 4L ดังนั้น f = v/(4L)', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-standing-waves-pipes-strings')), 'number', 'สายเส้นหนึ่งยาว 1 เมตร ถูกทำให้สั่นแบบฮาร์มอนิกที่ 1 (คลื่นนิ่งเต็มช่วงเดียว) ความยาวคลื่นเท่ากับกี่เมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'สายปลายตรึงทั้งสองข้างคลื่นนิ่งฮาร์มอนิกที่ 1 มี λ = 2L = 2 × 1 = 2 เมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'sound-standing-waves-pipes-strings')), 'number', 'ท่อปลายปิดข้างหนึ่งยาว 0.25 เมตร อัตราเร็วเสียงในอากาศ 340 เมตรต่อวินาที ความถี่มูลฐานของท่อนี้เท่ากับกี่เฮิรตซ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":340,"tolerance":0.5}', 'f = v/(4L) = 340/(4 × 0.25) = 340/1 = 340 เฮิรตซ์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'straight-line-motion'), 'straight-line-motion-acceleration', 'ความเร่ง', 'ความเร่ง (a) คืออัตราการเปลี่ยนแปลงความเร็วต่อหนึ่งหน่วยเวลา เป็นปริมาณเวกเตอร์ นิยามโดยสมการ a = (v - u) / t โดย u คือความเร็วต้น และ v คือความเร็วปลาย เมื่อทิศทางของความเร่งไปทางเดียวกับความเร็ว วัตถุจะเคลื่อนที่เร็วขึ้น แต่ถ้าความเร่งมีทิศตรงข้ามกับความเร็ว วัตถุจะช้าลงซึ่งมักเรียกว่าความหน่วง วัตถุที่มีความเร่งเป็นศูนย์จะเคลื่อนที่ด้วยความเร็วคงที่เสมอ', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-acceleration'), 'youtube', 'https://www.youtube.com/watch?v=s0GISz9X7fY', 's0GISz9X7fY', 'ฟิสิกส์ ม.4 บทที่ 2 การเคลื่อนที่แนวตรง ep.2', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-acceleration'), 'youtube', 'https://www.youtube.com/watch?v=8NFA1OoGVwo', '8NFA1OoGVwo', 'ฟิสิกส์ ม.4 บทที่ 2 การเคลื่อนที่แนวตรง ep.5(สมการการเคลื่อนที่ด้วยความเร่งคงตัว,การตกอย่างอิสระ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-acceleration'), 'linear-motion', 'สังเกตอัตราการเปลี่ยนแปลงความเร็วเมื่อมีความเร่งบวกและลบ', '{"speed":{"min":0,"max":25,"default":5},"acceleration":{"min":-8,"max":8,"step":1,"default":3},"time":{"min":1,"max":8,"step":0.5,"default":4}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-acceleration'), 'balance-force', 'ปรับแรงและมวลเพื่อให้เกิดความเร่งเฉลี่ยตรงเป้าหมาย', '{"targetAcc":[1.5,4.5],"tolerance":0.2,"force":{"min":20,"max":90,"default":48},"mass":{"min":2,"max":10,"default":5}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-acceleration'), 'แบบทดสอบ: ความเร่ง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-acceleration')), 'choice', 'หน่วยของความเร่งในระบบเอสไอคือข้อใด', '["เมตรต่อวินาที","เมตรต่อวินาทีกำลังสอง","นิวตัน","จูล"]', '1', 'ความเร่งคือความเร็วที่เปลี่ยนต่อเวลา จึงมีหน่วยเป็น เมตร/วินาที² ไม่ใช่ เมตร/วินาที ซึ่งเป็นหน่วยความเร็ว', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-acceleration')), 'choice', 'รถเร่งความเร็วจาก 8 เป็น 14 เมตร/วินาทีในเวลา 3 วินาที ความเร่งเป็นเท่าใด', '["6 เมตร/วินาที²","3 เมตร/วินาที²","2 เมตร/วินาที²","0.5 เมตร/วินาที²"]', '2', 'a = (v - u)/t = (14 - 8)/3 = 2 เมตร/วินาที²', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-acceleration')), 'choice', 'เมื่อความเร็วลดลงอย่างสม่ำเสมอ ความเร่งมีค่าเป็นอย่างไร', '["เป็นบวกเสมอ","เป็นศูนย์","คงที่และทิศเดียวกับความเร็ว","เป็นลบหรือตรงข้ามกับความเร็ว"]', '3', 'ความเร็วลดลงหมายถึงความเร่งมีทิศตรงข้ามกับความเร็ว อาจแทนด้วยค่าลบเมื่อกำหนดทิศเดียวกับความเร็วเป็นบวก', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-acceleration')), 'number', 'รถเปลี่ยนความเร็วจาก 5 เป็น 15 เมตร/วินาทีในเวลา 4 วินาที ความเร่งเป็นเท่าใด (ตอบเป็นเมตร/วินาที² ทศนิยม 1 ตำแหน่ง)', NULL, '{"value":2.5,"tolerance":0.05}', 'a = (15 - 5)/4 = 10/4 = 2.5 เมตร/วินาที²', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-acceleration')), 'number', 'รถเริ่มจากหยุดนิ่งมีความเร่ง 3 เมตร/วินาที² นาน 6 วินาที ความเร็วปลายเป็นเท่าใด (ตอบเป็นเมตร/วินาที จำนวนเต็ม)', NULL, '{"value":18,"tolerance":0.5}', 'v = u + at = 0 + 3 x 6 = 18 เมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'straight-line-motion'), 'straight-line-motion-application', 'การประยุกต์สมการการเคลื่อนที่', 'การแก้โจทย์ประยุกต์การเคลื่อนที่แนวตรง เช่น การไล่กวดกันของรถสองคันหรือระยะเบรกปลอดภัย ต้องตั้งสมการการเคลื่อนที่ของแต่ละวัตถุเทียบกับจุดอ้างอิงและเวลาเดียวกัน ระยะหยุดรถทั้งหมดประกอบด้วยระยะที่รถแล่นระหว่างคนขับตอบสนอง (Reaction distance: s = vt) รวมกับระยะเบรกจากความหน่วง (Braking distance: v² = u² + 2as) การเข้าใจตัวแปรช่วยแก้ปัญหาในชีวิตจริงได้อย่างปลอดภัย', 'senior', 6, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-application'), 'youtube', 'https://www.youtube.com/watch?v=8NFA1OoGVwo', '8NFA1OoGVwo', 'ฟิสิกส์ ม.4 บทที่ 2 การเคลื่อนที่แนวตรง ep.5(สมการการเคลื่อนที่ด้วยความเร่งคงตัว,การตกอย่างอิสระ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-application'), 'linear-motion', 'จำลองการเบรกและการเร่งแซงของยานพาหนะบนถนนตรง', '{"speed":{"min":0,"max":30,"default":25},"acceleration":{"min":-10,"max":5,"step":1,"default":-5},"time":{"min":1,"max":8,"step":0.5,"default":5}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-application'), 'balance-force', 'ควบคุมระยะเบรกและความเร่งหยุดรถให้ปลอดภัยตรงตามเป้า', '{"targetAcc":[1.8,4.8],"tolerance":0.16,"force":{"min":25,"max":100,"default":60},"mass":{"min":2,"max":10,"default":5}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-application'), 'แบบทดสอบ: การประยุกต์สมการการเคลื่อนที่', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-application')), 'choice', 'รถวิ่งด้วยความเร็ว 20 เมตร/วินาที เบรกจนหยุดในเวลา 5 วินาที ความเร่งของรถเป็นเท่าใด', '["4 เมตร/วินาที²","-4 เมตร/วินาที²","-5 เมตร/วินาที²","0"]', '1', 'a = (v - u)/t = (0 - 20)/5 = -4 เมตร/วินาที² เครื่องหมายลบแสดงว่าความเร่งตรงข้ามกับการเคลื่อนที่', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-application')), 'choice', 'โยนวัตถุขึ้นในแนวดิ่งด้วยความเร็วต้น 30 เมตร/วินาที ใช้เวลาขึ้นถึงจุดสูงสุดเท่าใด (ใช้ g = 10 เมตร/วินาที²)', '["1 วินาที","2 วินาที","3 วินาที","6 วินาที"]', '2', 'ที่จุดสูงสุด v = 0 จาก v = u - gt ได้ t = u/g = 30/10 = 3 วินาที', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-application')), 'choice', 'จากข้อก่อนที่โยนขึ้นด้วยความเร็วต้น 30 เมตร/วินาที เวลาที่วัตถุออกจากมือแล้วกลับมาถึงมือ (เวลาบินทั้งหมด) เป็นเท่าใด (ใช้ g = 10 เมตร/วินาที²)', '["1.5 วินาที","3 วินาที","4 วินาที","6 วินาที"]', '3', 'เวลาลงเท่ากับเวลาขึ้น คือ 3 วินาที จึงรวมเป็น 6 วินาที (เวลาบินทั้งหมด = 2u/g)', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-application')), 'number', 'รถวิ่งด้วยความเร็ว 15 เมตร/วินาที แล้วเบรกด้วยความเร่ง -5 เมตร/วินาที² ใช้เวลากี่วินาทีจึงหยุดนิ่ง (ตอบเป็นวินาที จำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 't = (v - u)/a = (0 - 15)/(-5) = 3 วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-application')), 'number', 'โยนวัตถุขึ้นในแนวดิ่งด้วยความเร็วต้น 40 เมตร/วินาที ใช้เวลากี่วินาทีถึงจุดสูงสุด (ใช้ g = 10 เมตร/วินาที² ตอบเป็นวินาที จำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 't = u/g = 40/10 = 4 วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'straight-line-motion'), 'straight-line-motion-distance-displacement', 'ระยะทาง การกระจัด อัตราเร็ว ความเร็ว', 'ระยะทาง (s) คือความยาวตามแนวเส้นทางจริงที่วัตถุเคลื่อนที่ เป็นปริมาณสเกลาร์ ในขณะที่การกระจัด (Δx หรือ s เวกเตอร์) คือระยะห่างจากจุดเริ่มต้นถึงจุดสุดท้ายตามแนวเส้นตรง เป็นปริมาณเวกเตอร์ อัตราเร็วเฉลี่ยคำนวณจากระยะทางหารด้วยเวลา (v = s/t) ส่วนความเร็วเฉลี่ยคำนวณจากการกระจัดหารด้วยเวลา (v = Δx/Δt) วัตถุที่เคลื่อนที่กลับมาจุดเดิมจะมีการกระจัดเป็นศูนย์แม้ระยะทางจะมีค่าก็ตาม', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-distance-displacement'), 'youtube', 'https://www.youtube.com/watch?v=QRswdh0cDvs', 'QRswdh0cDvs', 'ฟิสิกส์ ม.4 บทที่ 2 การเคลื่อนที่แนวตรง ep.1(ระยะทาง, การกระจัด, อัตราเร็ว, ความเร็ว)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-distance-displacement'), 'youtube', 'https://www.youtube.com/watch?v=s0GISz9X7fY', 's0GISz9X7fY', 'ฟิสิกส์ ม.4 บทที่ 2 การเคลื่อนที่แนวตรง ep.2', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-distance-displacement'), 'linear-motion', 'สังเกตความต่างระหว่างระยะทางกับการกระจัดและอัตราเร็วกับความเร็ว', '{"speed":{"min":0,"max":24,"default":12},"acceleration":{"min":-6,"max":6,"step":1,"default":0},"time":{"min":1,"max":10,"step":0.5,"default":5}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-distance-displacement'), 'balance-force', 'สร้างความเร่งคงที่เพื่อกำหนดอัตราเร็วปลายให้เข้าเป้า', '{"targetAcc":[1.1,4.1],"tolerance":0.15,"force":{"min":15,"max":80,"default":32},"mass":{"min":1,"max":8,"default":4}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-distance-displacement'), 'แบบทดสอบ: ระยะทาง การกระจัด อัตราเร็ว ความเร็ว', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-distance-displacement')), 'choice', 'รถวิ่งไปทางทิศตะวันออก 30 กิโลเมตร แล้วย้อนกลับทางทิศตะวันตก 30 กิโลเมตร การกระจัดมีขนาดเท่าใด', '["0 กิโลเมตร","30 กิโลเมตร","60 กิโลเมตร","90 กิโลเมตร"]', '0', 'กลับมาที่จุดเริ่มต้นพอดี การกระจัดจึงเป็น 0 กิโลเมตร เพราะวัดจากจุดเริ่มต้นถึงจุดสุดท้าย', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-distance-displacement')), 'choice', 'จากข้อก่อน ระยะทางรวมที่รถวิ่งได้เป็นเท่าใด', '["0 กิโลเมตร","60 กิโลเมตร","30 กิโลเมตร","90 กิโลเมตร"]', '1', 'ระยะทางคือความยาวเส้นทางที่วิ่งจริงรวมกัน = 30 + 30 = 60 กิโลเมตร', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-distance-displacement')), 'choice', 'อัตราเร็วเฉลี่ยคำนวณได้จากสูตรใด', '["การกระจัดหารด้วยเวลา","แรงหารด้วยมวล","ระยะทางรวมหารด้วยช่วงเวลาทั้งหมด","ความเร่งคูณด้วยเวลา"]', '2', 'อัตราเร็วเฉลี่ย = ระยะทางรวม / เวลาทั้งหมด ส่วนการกระจัด/เวลา คือความเร็วเฉลี่ย', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-distance-displacement')), 'number', 'คนวิ่งได้การกระจัด 50 เมตรในเวลา 20 วินาที ความเร็วเฉลี่ยเป็นเท่าใด (ตอบเป็นเมตร/วินาที ทศนิยม 1 ตำแหน่ง)', NULL, '{"value":2.5,"tolerance":0.05}', 'ความเร็วเฉลี่ย = การกระจัด / เวลา = 50 / 20 = 2.5 เมตร/วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-distance-displacement')), 'number', 'รถวิ่งได้ระยะทางรวม 300 เมตรในเวลา 60 วินาที อัตราเร็วเฉลี่ยเป็นเท่าใด (ตอบเป็นเมตร/วินาที จำนวนเต็ม)', NULL, '{"value":5,"tolerance":0.5}', 'อัตราเร็วเฉลี่ย = 300 / 60 = 5 เมตร/วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'straight-line-motion'), 'straight-line-motion-free-fall', 'การตกอย่างอิสระและการเคลื่อนที่แนวดิ่ง', 'การตกอย่างอิสระคือการเคลื่อนที่ของวัตถุภายใต้แรงดึงดูดของโลกเพียงอย่างเดียวโดยไม่มีแรงต้านอากาศ วัตถุทุกชนิดจะตกด้วยความเร่งโน้มถ่วง g ซึ่งมีค่าประมาณ 9.8 หรือ 10 m/s² ในทิศพุ่งลงสู่จุดศูนย์กลางโลก เมื่อโยนวัตถุขึ้นตรงๆ ความเร็วที่จุดสูงสุดจะเป็นศูนย์ชั่วขณะ (v = 0) และเวลาขาขึ้นจะเท่ากับเวลาขาลงหากกลับมาที่ระดับความสูงเดิม', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-free-fall'), 'youtube', 'https://www.youtube.com/watch?v=EpfYvKi-2iA', 'EpfYvKi-2iA', 'ฟิสิกส์ ม.4 บทที่ 2 การเคลื่อนที่แนวตรง ep.6(การตกอย่างอิสระ, การเคลื่อนที่ในแนวดิ่ง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'straight-line-motion-free-fall'), 'youtube', 'https://www.youtube.com/watch?v=8NFA1OoGVwo', '8NFA1OoGVwo', 'ฟิสิกส์ ม.4 บทที่ 2 การเคลื่อนที่แนวตรง ep.5(สมการการเคลื่อนที่ด้วยความเร่งคงตัว,การตกอย่างอิสระ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
