INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-kinematic-equations')), 'choice', 'สมการ v = u + at ใช้ได้ในกรณีใด', '["ความเร่งคงตัว","ความเร่งเปลี่ยนตลอดเวลา","ความเร็วคงตัวเท่านั้น","วัตถุหยุดนิ่งเท่านั้น"]', '0', 'สมการนี้มีเงื่อนไขว่าความเร่งต้องคงตัวในช่วงที่พิจารณา จึงใช้ได้เมื่อความเร่งไม่เปลี่ยน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-kinematic-equations')), 'choice', 'ในการตกอย่างอิสระใกล้ผิวโลก เราจะแทนค่าความเร่งในสมการด้วยปริมาณใด', '["ระยะทางที่ตกลงมา","g (ประมาณ 9.8 เมตร/วินาที²)","ความเร็วจริงของวัตถุ","มวลของวัตถุ"]', '1', 'ความเร่งของการตกอย่างอิสระคือความเร่งโน้มถ่วง g ประมาณ 9.8 เมตร/วินาที² ไม่ขึ้นกับมวลของวัตถุ', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-kinematic-equations')), 'choice', 'รถเริ่มจากหยุดนิ่งมีความเร่ง 4 เมตร/วินาที² นาน 5 วินาที ความเร็วปลายเป็นเท่าใด', '["9 เมตร/วินาที","5 เมตร/วินาที","20 เมตร/วินาที","4 เมตร/วินาที"]', '2', 'v = u + at = 0 + 4 x 5 = 20 เมตร/วินาที', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-kinematic-equations')), 'number', 'รถมีความเร็วต้น 10 เมตร/วินาทีและความเร่ง 2 เมตร/วินาที² นาน 5 วินาที ความเร็วปลายเป็นเท่าใด (ตอบเป็นเมตร/วินาที จำนวนเต็ม)', NULL, '{"value":20,"tolerance":0.5}', 'v = u + at = 10 + 2 x 5 = 20 เมตร/วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'straight-line-motion-kinematic-equations')), 'number', 'วัตถุเริ่มจากหยุดนิ่งมีความเร่ง 5 เมตร/วินาที² นาน 4 วินาที ได้ระยะทางเท่าใด (s = ½at² ตอบเป็นเมตร จำนวนเต็ม)', NULL, '{"value":40,"tolerance":0.5}', 's = ½ x 5 x 4² = ½ x 5 x 16 = 40 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'temperature-heat'), 'temperature-heat-phase-change', 'การเปลี่ยนสถานะและความร้อนแฝง', 'การเปลี่ยนสถานะของสสารเกิดขึ้นเมื่อโมเลกุลได้รับหรือสูญเสียพลังงานความร้อนจนเปลี่ยนแรงยึดเหนี่ยวระหว่างอนุภาค โดยในระหว่างการเปลี่ยนสถานะอุณหภูมิจะคงที่ ปริมาณความร้อนที่ใช้คำนวณจาก Q = mL โดย L คือความร้อนแฝงจำเพาะของการหลอมเหลวหรือการกลายเป็นไอ กราฟความร้อนเทียบกับอุณหภูมิจะปรากฏเป็นเส้นราบในขณะที่เกิดการเปลี่ยนสถานะ เช่น น้ำแข็งกำลังละลายเป็นน้ำที่ 0 องศาเซลเซียส', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'temperature-heat-phase-change'), 'youtube', 'https://www.youtube.com/watch?v=6WBq9Pk5478', '6WBq9Pk5478', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.2 (พลังงานความร้อนที่ทำให้สารเปลี่ยนแปลงอุณหภูมิและสถานะ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'temperature-heat-phase-change'), 'youtube', 'https://www.youtube.com/watch?v=yXUgSGC7MAg', 'yXUgSGC7MAg', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.1(ความร้อน อุณหภูมิ ความจุความร้อนจำเพาะ ความร้อนแฝงจำเพาะ )', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'temperature-heat-phase-change'), 'ideal-gas', 'จำลองภาวะไอและการรักษาความดันในกระบวนการรับความร้อน', '{"temperature":{"min":200,"max":600,"step":20,"default":520},"volume":{"min":2,"max":10,"step":0.5,"default":5.5},"moles":{"min":0.5,"max":3,"step":0.5,"default":1.5}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'temperature-heat-phase-change'), 'thermal-piston', 'ปรับความดันคงที่จำลองช่วงการเปลี่ยนสถานะของสาร', '{"tolerance":11,"targetPressure":[160,300],"temperature":{"min":200,"max":600,"default":460},"volume":{"min":2,"max":10,"step":0.5,"default":5.5}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'temperature-heat-phase-change'), 'แบบทดสอบ: การเปลี่ยนสถานะและความร้อนแฝง', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-phase-change')), 'choice', 'ระหว่างที่น้ำแข็งกำลังละลายจนหมด อุณหภูมิของส่วนผสมเป็นอย่างไร', '["เพิ่มขึ้นตลอดเวลา","คงที่ตลอด","ลดลงตลอดเวลา","เพิ่มขึ้นแล้วลดลง"]', '1', 'ระหว่างการเปลี่ยนสถานะ อุณหภูมิคงที่เพราะความร้อนที่ได้รับใช้ไปทำลายพันธะระหว่างโมเลกุล ไม่ได้ทำให้อุณหภูมิเพิ่ม', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-phase-change')), 'choice', 'ความร้อนแฝงจำเพาะของการหลอมเหลวคือความร้อนที่ทำให้สารใดเปลี่ยนสถานะ', '["สารทั้งหมดละลายในน้ำ","สารมวล 1 กิโลกรัม อุณหภูมิเพิ่ม 1 องศา","สารมวล 1 กิโลกรัม เปลี่ยนจากของแข็งเป็นของเหลวที่จุดหลอมเหลว","สารระเหยจนหมด"]', '2', 'ความร้อนแฝงจำเพาะการหลอมเหลว Lf คือความร้อนที่ทำให้สารมวลหนึ่งหน่วยเปลี่ยนสถานะจากของแข็งเป็นของเหลวที่อุณหภูมิคงที่', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-phase-change')), 'choice', 'น้ำเดือดกลายเป็นไอที่ 100 องศาเซลเซียส น้ำกับไอน้ำที่ได้มีอุณหภูมิเป็นอย่างไร', '["เท่ากันที่ 100 องศาเซลเซียส","ไอน้ำร้อนกว่าน้ำ","น้ำร้อนกว่าไอน้ำ","ไอน้ำเย็นกว่าน้ำ"]', '0', 'ขณะเปลี่ยนสถานะ น้ำกับไอน้ำมีอุณหภูมิเท่ากันที่จุดเดือด 100 องศาเซลเซียส ความร้อนที่ให้เป็นความร้อนแฝงไม่ใช่การเพิ่มอุณหภูมิ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-phase-change')), 'number', 'น้ำแข็งมวล 0.5 กิโลกรัม ที่จุดหลอมเหลว ความร้อนแฝงจำเพาะการหลอมเหลวของน้ำแข็ง 334000 จูล/กิโลกรัม ต้องใช้ความร้อนกี่จูลจึงจะละลายหมด (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":167000,"tolerance":0.5}', 'Q = mL = 0.5 × 334000 = 167000 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-phase-change')), 'number', 'ไอน้ำมวล 0.2 กิโลกรัม ควบแน่นเป็นน้ำที่จุดเดือด ความร้อนแฝงจำเพาะการกลายเป็นไอของน้ำ 2260000 จูล/กิโลกรัม คายความร้อนกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":452000,"tolerance":0.5}', 'Q = mL = 0.2 × 2260000 = 452000 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'temperature-heat'), 'temperature-heat-specific-heat', 'ความจุความร้อนและความร้อนจำเพาะ', 'ความจุความร้อน (C) คือปริมาณพลังงานความร้อนที่ทำให้สารทั้งก้อนมีอุณหภูมิเปลี่ยนไปหนึ่งหน่วย ส่วนความร้อนจำเพาะ (c) คือความร้อนต่อหนึ่งหน่วยมวลตามสมการ Q = mcΔT = CΔT สารที่มีค่า c สูง เช่น น้ำ จะต้องใช้ความร้อนปริมาณมากในการทำให้อุณหภูมิเปลี่ยน ทำให้มีอุณหภูมิเปลี่ยนแปลงช้ากว่าสารที่มีค่า c ต่ำ เช่น โลหะ สมบัตินี้ทำให้น้ำถูกนำไปใช้เป็นสารหล่อเย็นในเครื่องยนต์และช่วยควบคุมสภาพอากาศชายฝั่งทะเล', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'temperature-heat-specific-heat'), 'youtube', 'https://www.youtube.com/watch?v=6WBq9Pk5478', '6WBq9Pk5478', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.2 (พลังงานความร้อนที่ทำให้สารเปลี่ยนแปลงอุณหภูมิและสถานะ)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
