INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'temperature-heat-specific-heat'), 'ideal-gas', 'สังเกตอัตราการรับความร้อนและการเปลี่ยนแปลงสถานะของแก๊ส', '{"temperature":{"min":200,"max":600,"step":20,"default":360},"volume":{"min":2,"max":10,"step":0.5,"default":4.5},"moles":{"min":0.5,"max":3,"step":0.5,"default":1.8}}');
