INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-specific-heat')), 'choice', 'ความจุความร้อนของวัตถุคือปริมาณใด', '["ความร้อนทั้งหมดที่วัตถุสะสมไว้","มวลต่อปริมาตรของวัตถุ","ความร้อนที่ทำให้วัตถุอุณหภูมิเปลี่ยน 1 หน่วยอุณหภูมิ","ความร้อนที่ทำให้วัตถุเปลี่ยนสถานะ"]', '2', 'ความจุความร้อน C = Q/ΔT คือความร้อนที่ทำให้วัตถุมีอุณหภูมิเปลี่ยน 1 หน่วย มักใช้หน่วยจูลต่อองศาเซลเซียส', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-specific-heat')), 'choice', 'ความร้อนจำเพาะของสารหมายถึงอะไร', '["ความร้อนที่ทำวัตถุมวล 1 กิโลกรัม อุณหภูมิเปลี่ยน 1 องศาเซลเซียส","ความร้อนที่ทำวัตถุทั้งหมดละลาย","อุณหภูมิสูงสุดที่สารทนได้","ความร้อนที่สะสมในสาร 1 ลิตร"]', '0', 'ความร้อนจำเพาะ c = Q/(mΔT) คือความร้อนที่ทำวัตถุมวลหนึ่งหน่วยอุณหภูมิเปลี่ยนหนึ่งหน่วย หน่วยจูล/กิโลกรัม·องศาเซลเซียส', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-specific-heat')), 'choice', 'น้ำกับเหล็กมวลเท่ากัน ได้รับความร้อนเท่ากัน ข้อใดถูกต้อง ถ้าความร้อนจำเพาะของน้ำมากกว่าเหล็ก', '["อุณหภูมิน้ำเพิ่มมากกว่าเหล็ก","อุณหภูมิน้ำเพิ่มน้อยกว่าเหล็ก","อุณหภูมิทั้งคู่เพิ่มเท่ากัน","น้ำร้อนเร็วกว่าเหล็กเสมอ"]', '1', 'จาก ΔT = Q/(mc) เมื่อ m และ Q เท่ากัน สารที่มี c มากกว่าจะมี ΔT น้อยกว่า น้ำจึงอุณหภูมิเพิ่มช้ากว่าเหล็ก', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-specific-heat')), 'number', 'น้ำมวล 2 กิโลกรัม ความร้อนจำเพาะ 4200 จูล/กิโลกรัม·องศาเซลเซียส ได้รับความร้อนทำให้อุณหภูมิเพิ่มขึ้น 5 องศาเซลเซียส ต้องใช้ความร้อนกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":42000,"tolerance":0.5}', 'Q = mcΔT = 2 × 4200 × 5 = 42000 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'temperature-heat-specific-heat')), 'number', 'โลหะมวล 0.5 กิโลกรัม ได้รับความร้อน 4000 จูล แล้วอุณหภูมิเพิ่มขึ้น 20 องศาเซลเซียส ความร้อนจำเพาะของโลหะนี้เป็นกี่จูล/กิโลกรัม·องศาเซลเซียส (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":400,"tolerance":0.5}', 'c = Q/(mΔT) = 4000/(0.5 × 20) = 4000/10 = 400 จูล/กิโลกรัม·องศาเซลเซียส', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'temperature-heat'), 'temperature-heat-thermal-equilibrium', 'สมดุลความร้อน', 'เมื่อวัตถุสองชิ้นที่มีอุณหภูมิต่างกันถูกนำมาสัมผัสกันในระบบปิดทางความร้อน จะเกิดการถ่ายโอนพลังงานความร้อนจากวัตถุที่ร้อนกว่าไปยังวัตถุที่เย็นกว่าจนกระทั่งทั้งสองมีอุณหภูมิสุดท้ายเท่ากัน เกิดเป็นสมดุลความร้อน ตามกฎการอนุรักษ์พลังงานจะได้ Q_สูญเสีย = Q_ได้รับ หรือ ΣQ = 0 กฎข้อที่ศูนย์ของเทอร์โมไดนามิกส์จึงเป็นรากฐานสำคัญที่ทำให้เราสามารถใช้เทอร์โมมิเตอร์วัดอุณหภูมิของวัตถุได้อย่างแม่นยำ', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-equilibrium'), 'youtube', 'https://www.youtube.com/watch?v=6ghR0S27kfA', '6ghR0S27kfA', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.3 (สมดุลความร้อน การเปลี่ยนรูปพลังงาน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'temperature-heat-thermal-equilibrium'), 'youtube', 'https://www.youtube.com/watch?v=ULA0ixbVoEE', 'ULA0ixbVoEE', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.4 (การถ่ายโอนความร้อน, กฎของบอยล์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
