INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-first-law'), 'แบบทดสอบ: กฎข้อที่ 1 ของเทอร์โมไดนามิกส์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-first-law')), 'choice', 'กฎข้อที่ 1 ของเทอร์โมไดนามิกส์คือหลักการใด', '["การอนุรักษ์พลังงานของระบบ","เอนโทรปีต้องเพิ่มเสมอ","ความร้อนไหลจากเย็นไปร้อนเองได้","พลังงานสร้างได้และทำลายได้"]', '0', 'กฎข้อที่ 1 กล่าวว่า Q = ΔU + W เป็นการอนุรักษ์พลังงาน ความร้อนที่ให้ระบบเปลี่ยนเป็นพลังงานภายในและงาน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-first-law')), 'choice', 'ในสมการ Q = ΔU + W สำหรับแก๊สในกระบอกสูบ ตัว W คืออะไร', '["งานจากภายนอกกระทำต่อแก๊ส","งานที่แก๊สกระทำต่อภายนอก","กำลังของแก๊ส","น้ำหนักของแก๊ส"]', '1', 'W ในสมการนี้เป็นงานที่ระบบ(แก๊ส)กระทำต่อสิ่งแวดล้อม เช่น ผลักฝาสูบออก ซึ่งเป็นผลของปริมาตรเปลี่ยน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-first-law')), 'choice', 'กระบวนการที่ Q = 0 เรียกว่ากระบวนการใด', '["อุณหภูมิคงตัว (isothermal)","ความดันคงตัว (isobaric)","อะเดียแบติก","ปริมาตรคงตัว (isochoric)"]', '2', 'กระบวนการอะเดียแบติกคือกระบวนการที่ไม่มีการแลกเปลี่ยนความร้อนกับภายนอก Q = 0', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-first-law')), 'number', 'แก๊สได้รับความร้อน 1000 จูล และพลังงานภายในเพิ่มขึ้น 400 จูล งานที่แก๊สกระทำเป็นกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":600,"tolerance":0.5}', 'Q = ΔU + W → W = Q − ΔU = 1000 − 400 = 600 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-first-law')), 'number', 'แก๊สคายความร้อน 300 จูล (Q = −300) และมีงานจากภายนอกสู่แก๊ส 200 จูล (W = −200) พลังงานภายในเปลี่ยนไปกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":-100,"tolerance":0.5}', 'ΔU = Q − W = (−300) − (−200) = −100 จูล พลังงานภายในลดลง 100 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'thermodynamics'), 'thermodynamics-gas-processes', 'กระบวนการของแก๊ส', 'กระบวนการของแก๊สมี 4 แบบสำคัญ ได้แก่ กระบวนการไอโซบาริก (ความดันคงตัว, W = PΔV), กระบวนการไอโซคอริก (ปริมาตรคงตัว, W = 0 ดังนั้น Q = ΔU), กระบวนการไอโซเทอร์มอล (อุณหภูมิคงตัว, ΔU = 0 ดังนั้น Q = W) และกระบวนการแอเดียแบติก (ไม่มีการถ่ายโอนความร้อน Q = 0 ดังนั้น W = -ΔU) การวิเคราะห์ชนิดของกระบวนการช่วยให้คำนวณพลังงานความร้อนและงานกลในแต่ละขั้นตอนได้อย่างเป็นระบบ', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes'), 'youtube', 'https://www.youtube.com/watch?v=sfPgwsAIDnw', 'sfPgwsAIDnw', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.10 (กฎข้อที่ 1 ทางเทอร์โมไดนามิกส์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes'), 'youtube', 'https://www.youtube.com/watch?v=MixKfNgltBw', 'MixKfNgltBw', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.9(พลังงานภายใน,งานเนื่องจากากรเปลี่ยนแปลงปริมาตรแก๊ส)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes'), 'ideal-gas', 'ศึกษาเส้นทางกระบวนการไอโซเทอร์มอล ไอโซบาริก และไอโซคอริก', '{"temperature":{"min":200,"max":600,"step":20,"default":350},"volume":{"min":2,"max":10,"step":0.5,"default":5},"moles":{"min":0.5,"max":3,"step":0.5,"default":1.1}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes'), 'thermal-piston', 'ควบคุมกระบวนการทางอุณหพลศาสตร์ให้ความดันบรรลุเป้าหมาย', '{"tolerance":13,"targetPressure":[140,300],"temperature":{"min":200,"max":600,"default":340},"volume":{"min":2,"max":10,"step":0.5,"default":5}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes'), 'แบบทดสอบ: กระบวนการของแก๊ส', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes')), 'choice', 'กระบวนการอุณหภูมิคงตัวของแก๊สอุดมคติมีสมบัติใด', '["ความดันคงที่","พลังงานภายในคงที่","ปริมาตรคงที่","งานเป็นศูนย์"]', '1', 'กระบวนการอุณหภูมิคงตัว (isothermal) T คงที่ จึง ΔU = 0 ความร้อนที่ให้เท่ากับงานที่แก๊สกระทำ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes')), 'choice', 'กระบวนการปริมาตรคงตัวของแก๊สมีลักษณะใด', '["อุณหภูมิคงที่","ความดันคงที่","งานที่แก๊สกระทำเป็นศูนย์","ความร้อนไม่มีการแลกเปลี่ยน"]', '2', 'กระบวนการปริมาตรคงตัว (isochoric) ΔV = 0 จึง W = 0 ความร้อนทั้งหมดเปลี่ยนเป็นพลังงานภายใน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes')), 'choice', 'กระบวนการอะเดียแบติกคือกระบวนการแบบใด', '["ไม่มีการแลกเปลี่ยนความร้อนกับภายนอก","อุณหภูมิคงที่","ความดันคงที่","ปริมาตรคงที่"]', '0', 'กระบวนการอะเดียแบติกคือ Q = 0 ไม่มีการแลกเปลี่ยนความร้อนกับสิ่งแวดล้อม งานทำได้จากพลังงานภายใน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes')), 'number', 'ในกระบวนการอุณหภูมิคงตัว แก๊สได้รับความร้อน 500 จูล พลังงานภายในไม่เปลี่ยน งานที่แก๊สกระทำเป็นกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":500,"tolerance":0.5}', 'กระบวนการ isothermal ΔU = 0 จาก Q = ΔU + W → W = Q = 500 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-gas-processes')), 'number', 'ในกระบวนการปริมาตรคงตัว แก๊สได้รับความร้อน 300 จูล งานเป็นศูนย์ พลังงานภายในเพิ่มขึ้นกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":300,"tolerance":0.5}', 'Q = ΔU + W และ W = 0 → ΔU = Q = 300 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'thermodynamics'), 'thermodynamics-internal-energy', 'พลังงานภายในของแก๊ส', 'พลังงานภายใน (U) ของระบบแก๊สอุดมคติคือผลรวมของพลังงานจลน์ของทุกโมเลกุลในระบบ สำหรับแก๊สอะตอมเดี่ยวคำนวณได้จาก U = (3/2) nRT = (3/2) PV การเปลี่ยนแปลงพลังงานภายในจึงขึ้นอยู่กับผลต่างอุณหภูมิโดยตรง คือ ΔU = (3/2) nR ΔT ถ้าอุณหภูมิของระบบเพิ่มขึ้น พลังงานภายในจะเพิ่มขึ้น (ΔU > 0) และถ้าอุณหภูมิลดลง พลังงานภายในจะลดลง (ΔU < 0)', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy'), 'youtube', 'https://www.youtube.com/watch?v=MixKfNgltBw', 'MixKfNgltBw', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.9(พลังงานภายใน,งานเนื่องจากากรเปลี่ยนแปลงปริมาตรแก๊ส)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy'), 'youtube', 'https://www.youtube.com/watch?v=sfPgwsAIDnw', 'sfPgwsAIDnw', 'ฟิสิกส์ ม.6 บทที่ 16 ความร้อนและแก๊ส ep.10 (กฎข้อที่ 1 ทางเทอร์โมไดนามิกส์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy'), 'ideal-gas', 'สังเกตการเปลี่ยนแปลงพลังงานภายใน U เมื่อเปลี่ยนอุณหภูมิแก๊ส', '{"temperature":{"min":200,"max":600,"step":20,"default":320},"volume":{"min":2,"max":10,"step":0.5,"default":4},"moles":{"min":0.5,"max":3,"step":0.5,"default":1.2}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy'), 'thermal-piston', 'ปรับตัวแปรอุณหภูมิและปริมาตรเพื่อคุมพลังงานภายในและความดัน', '{"tolerance":12,"targetPressure":[130,270],"temperature":{"min":200,"max":600,"default":320},"volume":{"min":2,"max":10,"step":0.5,"default":4.5}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy'), 'แบบทดสอบ: พลังงานภายในของแก๊ส', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy')), 'choice', 'พลังงานภายในของแก๊สอุดมคติในภาชนะขึ้นอยู่กับปริมาณใดเป็นหลัก', '["ปริมาตรเท่านั้น","ความดันเท่านั้น","อุณหภูมิ","ขนาดภาชนะ"]', '2', 'พลังงานภายในเป็นพลังงานจลน์รวมของโมเลกุล ซึ่งขึ้นกับอุณหภูมิสัมบูรณ์ สำหรับแก๊สอุดมคติ U = 1.5nRT', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy')), 'choice', 'ในกระบวนการอุณหภูมิคงตัว (isothermal) สำหรับแก๊สอุดมคติ พลังงานภายในเปลี่ยนอย่างไร', '["คงที่","เพิ่มขึ้น","ลดลง","เพิ่มแล้วลดลง"]', '0', 'เมื่ออุณหภูมิคงที่ พลังงานภายในคงที่ เพราะ U ขึ้นกับ T เท่านั้น การยุบตัวหรือขยายจึงไม่เปลี่ยน U', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy')), 'choice', 'แก๊สอะตอมเดี่ยวมีสูตรพลังงานภายในตามข้อใด', '["U = nRT","U = 1.5nRT","U = 0.5nRT","U = 2nRT"]', '1', 'แก๊สอะตอมเดี่ยวมี 3 องศาอิสระการเคลื่อนที่ จึงมี U = 1.5nRT', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy')), 'number', 'แก๊สอะตอมเดี่ยว 2 โมล อุณหภูมิ 300 เคลวิน R = 8.3 จูล/โมล·เคลวิน มีพลังงานภายในกี่จูล (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":7470,"tolerance":0.5}', 'U = 1.5nRT = 1.5 × 2 × 8.3 × 300 = 7470 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'thermodynamics-internal-energy')), 'number', 'แก๊สอุดมคติ 1 โมล อุณหภูมิเพิ่มจาก 300 เคลวินเป็น 600 เคลวิน พลังงานภายในเพิ่มขึ้นกี่เท่าของเดิม (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.05}', 'U แปรผันตรงกับ T 600/300 = 2 เท่า', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'thermodynamics'), 'thermodynamics-work-by-gas', 'งานที่แก๊สกระทำ', 'งานที่แก๊สกระทำ (W) ในการขยายตัวหรือหดตัวเท่ากับพื้นที่ใต้กราฟความสัมพันธ์ระหว่างความดันกับปริมาตร (กราฟ P-V) เมื่อความดันคงตัว งานคำนวณได้ง่ายจากสูตร W = P ΔV = P(V2 - V1) หากแก๊สขยายตัว (ΔV > 0) แก๊สจะทำงานต่อสิ่งแวดล้อมทำให้ W เป็นบวก แต่ถ้าแก๊สถูกอัดให้ปริมาตรลดลง (ΔV < 0) งานจะเป็นลบ แสดงว่าสิ่งแวดล้อมเป็นฝ่ายทำงานให้แก่ระบบแก๊ส', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
