INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-physical-quantities')), 'choice', 'หน่วยพื้นฐานของเวลาในระบบเอสไอคือข้อใด', '["เมตร","กิโลกรัม","วินาที","แอมแปร์ต่อวินาที"]', '2', 'วินาทีเป็นหน่วยพื้นฐานของเวลา ส่วนเมตรเป็นหน่วยของความยาวและกิโลกรัมเป็นหน่วยของมวล', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-physical-quantities')), 'choice', 'ข้อใดเป็นปริมาณทางฟิสิกส์ที่วัดได้และรายงานพร้อมหน่วย', '["ความสวยงามของภาพ","ความยาวของวัตถุ","ความสุขของคน","มวลของวัตถุ"]', '3', 'ความยาวและมวลเป็นปริมาณทางฟิสิกส์ที่วัดได้จริง ส่วนความสวยงามและความสุขไม่ใช่ปริมาณที่วัดเป็นตัวเลขได้ตรงๆ ข้อนี้จึงตอบมวลซึ่งเป็นปริมาณทางฟิสิกส์', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-physical-quantities')), 'choice', 'หน่วย เมตร/วินาที ของความเร็วเป็นหน่วยประเภทใด', '["หน่วยอนุพันธ์","หน่วยพื้นฐาน","หน่วยของมวล","หน่วยของเวลา"]', '0', 'ความเร็วได้จากความยาวหารด้วยเวลา จึงเป็นปริมาณอนุพันธ์และมีหน่วยอนุพันธ์ คือ เมตร/วินาที', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-physical-quantities')), 'number', 'ความยาว 3.5 กิโลเมตรคิดเป็นกี่เมตร (ตอบเป็นเมตร จำนวนเต็ม)', NULL, '{"value":3500,"tolerance":0.5}', '1 กิโลเมตร = 1000 เมตร ดังนั้น 3.5 x 1000 = 3500 เมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-physical-quantities')), 'number', 'เวลานาน 2 ชั่วโมงคิดเป็นกี่วินาที (ตอบเป็นวินาที จำนวนเต็ม)', NULL, '{"value":7200,"tolerance":0.5}', '1 ชั่วโมง = 3600 วินาที ดังนั้น 2 x 3600 = 7200 วินาที', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'units-measurement'), 'units-measurement-significant-figures', 'เลขนัยสำคัญ', 'เลขนัยสำคัญคือจำนวนตัวเลขที่ได้จากการวัดจริงรวมกับตัวเลขประมาณค่าอีกหนึ่งตัว โดยตัวเลขที่ไม่ใช่ศูนย์ทุกตัวถือเป็นเลขนัยสำคัญ ส่วนเลขศูนย์มีกฎเฉพาะขึ้นอยู่กับตำแหน่ง สำหรับการบวกลบผลลัพธ์ต้องมีจำนวนตำแหน่งทศนิยมเท่ากับตัวตั้งที่มีทศนิยมน้อยที่สุด ส่วนการคูณหารผลลัพธ์ต้องมีจำนวนตัวเลขนัยสำคัญเท่ากับตัวตั้งที่มีเลขนัยสำคัญน้อยที่สุด', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
