INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-significant-figures')), 'choice', 'จำนวน 25.0 มีเลขนัยสำคัญกี่ตัว', '["3 ตัว","2 ตัว","1 ตัว","4 ตัว"]', '0', 'ศูนย์ท้ายหลังจุดทศนิยมนับเป็นนัยสำคัญ เพราะบอกความแม่นยำ ตัวเลข 2, 5 และ 0 จึงรวมเป็น 3 ตัว', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-significant-figures')), 'choice', 'จำนวน 0.0045 มีเลขนัยสำคัญกี่ตัว', '["4 ตัว","2 ตัว","3 ตัว","5 ตัว"]', '1', 'ศูนย์ที่อยู่หน้าตัวเลขไม่ใช่ตัวบอกตำแหน่งและไม่นับความแม่นยำ จึงนับเฉพาะ 4 และ 5 รวมเป็น 2 ตัว', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-significant-figures')), 'choice', 'ผลบวก 12.1 + 3.25 ตามกฎเลขนัยสำคัญควรตอบด้วยทศนิยมกี่ตำแหน่ง', '["2 ตำแหน่ง","3 ตำแหน่ง","1 ตำแหน่ง","4 ตำแหน่ง"]', '2', 'การบวกลบ ให้ตอบตามจำนวนทศนิยมของตัวที่มีทศนิยมน้อยที่สุด คือ 12.1 ซึ่งมี 1 ตำแหน่ง จึงตอบ 1 ตำแหน่ง', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-significant-figures')), 'number', 'จำนวน 345 มีเลขนัยสำคัญกี่ตัว (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'เลข 3, 4, 5 ล้วนไม่ใช่ศูนย์และเป็นนัยสำคัญทุกตัว จึงมี 3 ตัว', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'units-measurement-significant-figures')), 'number', 'จำนวน 0.050 มีเลขนัยสำคัญกี่ตัว (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'ศูนย์แรกหน้าเลข 5 ไม่นับ ส่วนศูนย์ท้ายหลังเลข 5 และหลังจุดทศนิยมนับ จึงมี 2 ตัว (5 และ 0)', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'units-measurement'), 'units-measurement-unit-conversion', 'การเปลี่ยนหน่วย', 'การเปลี่ยนหน่วยในวิชาฟิสิกส์ใช้หลักการตัวประกอบเปลี่ยนหน่วย (Unit Factor Method) เพื่อแปลงหน่วยเดิมไปเป็นหน่วยที่ต้องการอย่างถูกต้อง เช่น การแปลงความเร็วจาก km/h เป็น m/s ต้องคูณด้วย 5/18 หรือคูณด้วย 1000 m แล้วหารด้วย 3600 s การใช้คำอุปสรรคเช่น กิโล (10^3), มิลลิ (10^-3) และเซนติ (10^-2) ช่วยจัดการตัวเลขที่มีขนาดใหญ่หรือเล็กมากได้อย่างมีประสิทธิภาพ', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
