INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-component-arithmetic')), 'choice', 'ขั้นแรกของการบวกเวกเตอร์ด้วยวิธีองค์ประกอบคือข้อใด', '["คูณเวกเตอร์ทั้งสองเข้าด้วยกัน","แยกแต่ละเวกเตอร์เป็นองค์ประกอบในแกน x และแกน y","หาผลคูณเชิงเวกเตอร์ของทั้งสอง","วัดมุมระหว่างเวกเตอร์เพียงอย่างเดียว"]', '1', 'วิธีองค์ประกอบเริ่มจากแตกแต่ละเวกเตอร์เป็นแกน x และ y แล้วจึงรวมองค์ประกอบในแกนเดียวกัน', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-component-arithmetic')), 'choice', 'เวกเตอร์ A มีองค์ประกอบ x=3, y=4 และเวกเตอร์ B มีองค์ประกอบ x=1, y=2 เวกเตอร์ลัพธ์ A + B มีองค์ประกอบ x และ y เป็นเท่าใด', '["x = 2, y = 2","x = 3, y = 4","x = 4, y = 6","x = 5, y = 8"]', '2', 'บวกองค์ประกอบแกนเดียวกัน x = 3 + 1 = 4 และ y = 4 + 2 = 6 อย่าลืมบวกทีละแกน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-component-arithmetic')), 'choice', 'เวกเตอร์ C มีองค์ประกอบ x=5, y=7 เมื่อลบด้วยเวกเตอร์ D (x=2, y=3) ผลลัพธ์ C − D มีองค์ประกอบ x และ y เป็นเท่าใด', '["x = 2, y = 3","x = 5, y = 7","x = 7, y = 10","x = 3, y = 4"]', '3', 'ลบองค์ประกอบแกนเดียวกัน x = 5 − 2 = 3 และ y = 7 − 3 = 4', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-component-arithmetic')), 'number', 'เวกเตอร์ลัพธ์มีองค์ประกอบ x = 6 หน่วย และ y = 8 หน่วย มีขนาดเท่าใด (ตอบเป็นหน่วย จำนวนเต็ม)', NULL, '{"value":10,"tolerance":0.5}', 'ขนาด = √(6² + 8²) = √100 = 10 หน่วย', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'vectors-component-arithmetic')), 'number', 'เวกเตอร์สองตัวตั้งฉากกันขนาด 8 และ 15 หน่วย เวกเตอร์ลัพธ์มีขนาดเท่าใด (ตอบเป็นหน่วย จำนวนเต็ม)', NULL, '{"value":17,"tolerance":0.5}', 'ขนาด = √(8² + 15²) = √289 = 17 หน่วย', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'vectors'), 'vectors-scalar-vector', 'ปริมาณเวกเตอร์และสเกลาร์', 'ปริมาณทางฟิสิกส์จำแนกเป็นสองประเภทหลัก คือ ปริมาณสเกลาร์ที่มีเพียงขนาด เช่น มวล ระยะทาง อัตราเร็ว และพลังงาน กับปริมาณเวกเตอร์ที่มีทั้งขนาดและทิศทาง เช่น การกระจัด ความเร็ว ความเร่ง และแรง เวกเตอร์สามารถเขียนแทนด้วยลูกศร โดยความยาวลูกศรแทนขนาดและหัวลูกศรระบุทิศทาง การรวมเวกเตอร์ต้องคำนึงถึงทิศทางเสมอไม่สามารถบวกลบแบบเลขพีชคณิตทั่วไปได้', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
