INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-diffraction')), 'choice', 'การเลี้ยวเบนของคลื่นหมายถึงปรากฏการณ์ใด', '["คลื่นสะท้อนกลับที่ผิว","คลื่นเปลี่ยนความถี่เมื่อเข้าตัวกลางใหม่","คลื่นแผ่กระจายอ้อมสิ่งกีดขวางหรือขอบช่องแคบ","คลื่นถูกดูดกลืนโดยสิ่งกีดขวาง"]', '2', 'การเลี้ยวเบนคือการที่คลื่นอ้อมหรือแผ่กระจายไปรอบขอบสิ่งกีดขวางหรือช่องแคบ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-diffraction')), 'choice', 'การเลี้ยวเบนจะเด่นชัดที่สุดเมื่อขนาดของช่องแคบหรือสิ่งกีดขวางมีค่าใกล้เคียงกับปริมาณใด', '["ความยาวคลื่น","ความถี่ของคลื่น","คาบของคลื่น","อัตราเร็วของคลื่น"]', '0', 'การเลี้ยวเบนเด่นชัดเมื่อขนาดช่องแคบหรือสิ่งกีดขวางเปรียบเทียบได้กับขนาดความยาวคลื่น', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-diffraction')), 'choice', 'เหตุใดเสียงจึงเลี้ยวเบนได้ชัดเจนกว่าแสงเมื่อพบสิ่งกีดขวางที่มีขนาดเท่ากัน', '["เสียงมีความถี่สูงกว่า","เสียงมีความยาวคลื่นยาวกว่ามาก","เสียงเคลื่อนที่ช้ากว่า","เสียงเป็นคลื่นตามยาว"]', '1', 'เสียงมีความยาวคลื่นยาวกว่าแสงมาก จึงเทียบได้กับขนาดสิ่งกีดขวาง ทำให้เลี้ยวเบนเด่นชัดกว่าแสง', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-diffraction')), 'number', 'คลื่นน้ำมีความถี่ 2 เฮิรตซ์ และเคลื่อนที่ด้วยอัตราเร็ว 3 เมตรต่อวินาที ความยาวคลื่นเท่ากับกี่เมตร (ตอบเป็นทศนิยม 1 ตำแหน่ง)', NULL, '{"value":1.5,"tolerance":0.05}', 'λ = v/f = 3/2 = 1.5 เมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-diffraction')), 'number', 'คลื่นมีความยาวคลื่น 2 เมตร และเคลื่อนที่ด้วยอัตราเร็ว 8 เมตรต่อวินาที ความถี่ของคลื่นเท่ากับกี่เฮิรตซ์ (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":4,"tolerance":0.5}', 'f = v/λ = 8/2 = 4 เฮิรตซ์', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'wave-properties'), 'wave-properties-interference', 'การแทรกสอดของคลื่น', 'การแทรกสอดเกิดขึ้นเมื่อคลื่นต่อเนื่องสองขบวนจากแหล่งกำเนิดอาพันธ์เคลื่อนที่มาพบกันในตัวกลางเดียวกันตามหลักการซ้อนทับ ถ้าคลื่นมาพบกันด้วยเฟสตรงกันจะเกิดการแทรกสอดแบบเสริม เกิดแนวปฏิบัพ (Antinode) ซึ่งมีผลต่างระยะทาง |S1P - S2P| = nλ เมื่อ n = 0, 1, 2... แต่ถ้าคลื่นมาพบกันด้วยเฟสตรงข้ามจะเกิดการแทรกสอดแบบหักล้าง เกิดแนวบัพ (Node) ซึ่งมีผลต่างระยะทาง |S1P - S2P| = (n - 1/2)λ', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
