INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-reflection')), 'choice', 'กฎการสะท้อนของคลื่นกล่าวว่ามุมสะท้อนเทียบกับมุมตกกระทบเป็นอย่างไร', '["มุมสะท้อนมากกว่ามุมตกกระทบ","มุมสะท้อนน้อยกว่ามุมตกกระทบ","มุมสะท้อนเท่ากับมุมตกกระทบ","มุมสะท้อนเป็นศูนย์เสมอ"]', '2', 'กฎการสะท้อน: มุมสะท้อนเท่ากับมุมตกกระทบ โดยทั้งสองวัดจากเส้นแนวฉาก', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-reflection')), 'choice', 'เมื่อคลื่นในเส้นเชือกสะท้อนจากปลายตรึง (ปลายยึดแน่น) เฟสของคลื่นสะท้อนเป็นอย่างไร', '["เหมือนเดิมทุกประการ","กลับเฟสไป 180 องศา","เลื่อนไป 90 องศา","ความถี่เปลี่ยนไป"]', '1', 'การสะท้อนจากปลายตรึงทำให้คลื่นสะท้อนมีเฟสกลับ 180 องศา เกิดปฏิบัพที่ปลาย', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-reflection')), 'choice', 'เมื่อคลื่นสะท้อนจากปลายอิสระในเส้นเชือก เฟสของคลื่นสะท้อนเป็นอย่างไร', '["เหมือนเดิมไม่กลับเฟส","กลับเฟส 180 องศา","หายไปครึ่งหนึ่ง","ความถี่เพิ่มเป็นสองเท่า"]', '0', 'การสะท้อนจากปลายอิสระไม่กลับเฟส คลื่นสะท้อนมีเฟสเดียวกันกับคลื่นตกกระทบ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-reflection')), 'number', 'คลื่นตกกระทบผิวทำมุม 25 องศากับเส้นแนวฉาก มุมสะท้อนเท่ากับกี่องศา (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":25,"tolerance":0.5}', 'มุมสะท้อนเท่ากับมุมตกกระทบ จึงเป็น 25 องศา', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-reflection')), 'number', 'คลื่นตกกระทบผิวทำมุม 60 องศากับแนวของผิว (แนวระดับ) มุมที่คลื่นสะท้อนทำกับเส้นแนวฉากเท่ากับกี่องศา (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":30,"tolerance":0.5}', 'มุมตกกระทบวัดจากเส้นแนวฉาก = 90 − 60 = 30 องศา มุมสะท้อนจึงเท่ากับ 30 องศา', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'wave-properties'), 'wave-properties-refraction', 'การหักเหของคลื่น', 'การหักเหของคลื่นเกิดจากการที่คลื่นเคลื่อนที่ผ่านรอยต่อระหว่างสองตัวกลางที่มีสมบัติต่างกัน ทำให้อัตราเร็วและความยาวคลื่นเปลี่ยนไป แต่ความถี่ของคลื่นจะคงที่เสมอเนื่องจากขึ้นกับแหล่งกำเนิดเดิม เป็นไปตามความสัมพันธ์ sin(θ1)/sin(θ2) = v1/v2 = λ1/λ2 เช่น คลื่นผิวน้ำที่เคลื่อนที่จากเขตน้ำลึกไปยังเขตน้ำตื้นจะมีความเร็วและความยาวคลื่นลดลง ส่งผลให้แนวหน้าคลื่นเบนเข้าหาเส้นแนวฉาก', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
