INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'wave-properties-refraction'), 'แบบทดสอบ: การหักเหของคลื่น', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-refraction')), 'choice', 'เมื่อคลื่นเคลื่อนที่จากน้ำลึกเข้าสู่น้ำตื้น ความยาวคลื่นเป็นอย่างไร', '["ลดลง","เพิ่มขึ้น","ไม่เปลี่ยนแปลง","กลายเป็นศูนย์"]', '0', 'เมื่อเข้าสู่น้ำตื้นคลื่นเคลื่อนที่ช้าลง แต่ความถี่คงที่ ความยาวคลื่นจึงลดลง (λ ∝ v)', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-refraction')), 'choice', 'เมื่อคลื่นเข้าสู่ตัวกลางใหม่และหักเห ความถี่ของคลื่นเป็นอย่างไร', '["เพิ่มขึ้น","คงเดิม","ลดลง","ไม่แน่นอนขึ้นกับตัวกลาง"]', '1', 'ความถี่ของคลื่นถูกกำหนดโดยแหล่งกำเนิด จึงไม่เปลี่ยนเมื่อเปลี่ยนตัวกลาง มีเพียงอัตราเร็วและความยาวคลื่นที่เปลี่ยน', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-refraction')), 'choice', 'เมื่อคลื่นเคลื่อนที่จากบริเวณที่เร็วกว่าเข้าสู่บริเวณที่ช้ากว่าในแนวเฉียง คลื่นจะหักเหไปทางใด', '["หักเหออกห่างจากเส้นแนวฉาก","เคลื่อนที่ตรงต่อไปแนวเดิม","หักเหเข้าหาเส้นแนวฉาก","สะท้อนกลับที่ผิว"]', '2', 'เมื่อคลื่นเข้าสู่บริเวณที่ช้าลง คลื่นจะหักเหเข้าหาเส้นแนวฉาก ทำให้มุมหักเหน้อยกว่ามุมตกกระทบ', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-refraction')), 'number', 'คลื่นน้ำในบริเวณลึกมีอัตราเร็ว 12 เมตรต่อวินาที และความยาวคลื่น 4 เมตร เมื่อเข้าสู่น้ำตื้นอัตราเร็วลดเหลือ 6 เมตรต่อวินาที ความยาวคลื่นในน้ำตื้นเท่ากับกี่เมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":2,"tolerance":0.5}', 'ความถี่คงที่ ดังนั้น λ ∝ v, λ2 = λ1 × v2/v1 = 4 × 6/12 = 2 เมตร', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'wave-properties-refraction')), 'number', 'คลื่นน้ำในบริเวณลึกมีอัตราเร็ว 10 เมตรต่อวินาที และความยาวคลื่น 6 เมตร เมื่อเข้าสู่น้ำตื้นอัตราเร็วลดเหลือ 5 เมตรต่อวินาที ความยาวคลื่นในน้ำตื้นเท่ากับกี่เมตร (ตอบเป็นจำนวนเต็ม)', NULL, '{"value":3,"tolerance":0.5}', 'λ2 = λ1 × v2/v1 = 6 × 5/10 = 3 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'work-energy'), 'work-energy-conservation', 'การอนุรักษ์พลังงานกล', 'กฎการอนุรักษ์พลังงานกลระบุว่า หากในระบบมีเฉพาะแรงอนุรักษ์กระทำ เช่น แรงโน้มถ่วงหรือแรงสปริง พลังงานกลรวม (E = Ek + Ep) จะมีค่าคงที่เสมอ นั่นคือ E1 = E2 แต่หากมีแรงไม่อนุรักษ์กระทำ เช่น แรงเสียดทานหรืองานจากแรงภายนอก สมการจะเปลี่ยนเป็น E1 + W_ภายนอก = E2 + W_f พลังงานไม่สามารถสร้างขึ้นใหม่หรือทำลายได้ แต่เปลี่ยนรูปจากรูปหนึ่งไปสู่อีกรูปหนึ่งได้', 'senior', 4, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-conservation'), 'youtube', 'https://www.youtube.com/watch?v=y6eSPTZpLoo', 'y6eSPTZpLoo', 'ฟิสิกส์ ม.4 บทที่ 5 งานและพลังงาน ep.6 (กฎการอนุรักษ์พลังงานกล)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-conservation'), 'youtube', 'https://www.youtube.com/watch?v=yZDgsvovQrk', 'yZDgsvovQrk', 'ฟิสิกส์ ม.4 บทที่ 5 งานและพลังงาน ep.5 (กฎการอนุรักษ์พลังงาน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 2);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-conservation'), 'newton-force', 'สังเกตการถ่ายโอนพลังงานระหว่างพลังงานกลและการสูญเสียจากแรงต้าน', '{"force":{"min":10,"max":90,"default":50},"mass":{"min":1,"max":15,"default":5},"friction":{"min":0,"max":0.5,"step":0.05,"default":0.1}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-conservation'), 'balance-force', 'ควบคุมความเร่งเพื่อให้การเปลี่ยนรูปพลังงานเป็นไปตามกฎอนุรักษ์', '{"targetAcc":[1.4,4.6],"tolerance":0.15,"force":{"min":18,"max":92,"default":46},"mass":{"min":1,"max":9,"default":4}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-conservation'), 'แบบทดสอบ: การอนุรักษ์พลังงานกล', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-conservation')), 'choice', 'สภาพที่พลังงานกลรวมของวัตถุคงที่คือข้อใด', '["มีแรงเสียดทานมาก","ไม่มีแรงที่ไม่ใช่อนุรักษ์ เช่น แรงเสียดทาน มากระทำ","วัตถุหยุดนิ่งเท่านั้น","มีความเร็วคงที่เท่านั้น"]', '1', 'พลังงานกลรวมคงที่เมื่อมีแต่แรงอนุรักษ์ (เช่น แรงโน้มถ่วง) ถ้ามีแรงเสียดทานพลังงานกลจะลดลง', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-conservation')), 'choice', 'วัตถุตกลงอย่างอิสระจากความสูง h ถึงพื้น ความเร็วปลาย v ที่ได้ มาจากความสัมพันธ์ข้อใด', '["mgh = ½mv²","mgh = mv","½mv² = mgh²","mgh = ½mv"]', '0', 'พลังงานศักย์ที่จุดสูงสุดเปลี่ยนเป็นพลังงานจลน์ที่พื้น แรงโน้มถ่วงเป็นแรงอนุรักษ์ จึงได้ mgh = ½mv²', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-conservation')), 'choice', 'ลูกบอลถูกโยนขึ้น เมื่ออยู่ที่ความสูงครึ่งหนึ่งของจุดสูงสุด พลังงานของลูกบอลมีลักษณะอย่างไร', '["เป็นพลังงานจลน์ล้วน","มีทั้งพลังงานจลน์และพลังงานศักย์","เป็นพลังงานศักย์ล้วน","ไม่มีพลังงาน"]', '1', 'ที่ความสูงครึ่งหนึ่งวัตถุยังมีความเร็วจึงมีพลังงานจลน์ และอยู่สูงจากพื้นจึงมีพลังงานศักย์ พลังงานทั้งสองผลรวมคงที่', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-conservation')), 'number', 'วัตถุตกจากจุดหยุดนิ่งสูง 5 เมตรจากพื้น ก่อนถึงพื้นพอดีมีความเร็วกี่เมตร/วินาที (ใช้ g = 10 เมตร/วินาที²)', NULL, '{"value":10,"tolerance":0.5}', 'mgh = ½mv² ได้ v = √(2gh) = √(2 × 10 × 5) = √100 = 10 เมตร/วินาที', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-conservation')), 'number', 'ลูกบอลถูกขว้างขึ้นจากพื้นด้วยความเร็วต้น 10 เมตร/วินาที ขึ้นไปได้สูงสุดกี่เมตร (ใช้ g = 10 เมตร/วินาที²)', NULL, '{"value":5,"tolerance":0.5}', 'จาก ½mv² = mgh ได้ h = v²/(2g) = 100/20 = 5 เมตร', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'work-energy'), 'work-energy-constant-force', 'งานโดยแรงคงตัว', 'งาน (W) ในทางฟิสิกส์เกิดขึ้นเมื่อมีแรงกระทำต่อวัตถุแล้วทำให้วัตถุเกิดการกระจัดตามแนวแรง คำนวณได้จากผลคูณสเกลาร์ W = F s cos θ โดย θ คือมุมระหว่างแนวแรงกับการกระจัด งานมีหน่วยเป็นจูล (J) งานจะมีค่าเป็นบวกเมื่อแรงมีทิศเดียวกับการเคลื่อนที่ เป็นลบเมื่อแรงมีทิศตรงข้าม เช่น งานของแรงเสียดทาน และเป็นศูนย์เมื่อแรงตั้งฉากกับการเคลื่อนที่ เช่น แรงแนวฉากหรือน้ำหนักบนพื้นราบ', 'senior', 1, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-constant-force'), 'youtube', 'https://www.youtube.com/watch?v=1ShY0B3hTOY', '1ShY0B3hTOY', 'ฟิสิกส์ ม.4 บทที่ 5 งานและพลังงาน ep.1 (งาน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
