INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-constant-force'), 'newton-force', 'สังเกตงานที่เกิดจากแรงดึงวัตถุให้เคลื่อนที่ไปตามแนวราบ', '{"force":{"min":10,"max":95,"default":45},"mass":{"min":1,"max":15,"default":5},"friction":{"min":0,"max":0.5,"step":0.05,"default":0.1}}');
