INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-constant-force'), 'แบบทดสอบ: งานโดยแรงคงตัว', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-constant-force')), 'choice', 'งานที่แรงคงตัว F กระทำต่อวัตถุที่เคลื่อนที่ระยะทาง s โดย θ คือมุมระหว่างแรงกับแนวการเคลื่อนที่ หาได้จากสูตรใด', '["W = F s sin θ","W = F s cos θ","W = F s","W = F s / cos θ"]', '1', 'งานนิยามเป็นผลคูณของแรงกับระยะกระจัดในทิศของแรง จึงเป็น W = Fs cos θ', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-constant-force')), 'choice', 'หน่วยของงานในระบบเอสไอคือข้อใด', '["นิวตัน","วัตต์","จูล","กิโลกรัมเมตร"]', '2', 'งานมีหน่วยเป็นจูล โดย 1 จูล = 1 นิวตัน × 1 เมตร', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-constant-force')), 'choice', 'แรงกระทำตั้งฉากกับแนวการเคลื่อนที่ของวัตถุตลอดทาง งานของแรงนี้มีค่าเท่าใด', '["เท่ากับผลคูณของแรงกับระยะทาง","เป็นศูนย์","เท่ากับครึ่งหนึ่งของผลคูณ","ติดลบ"]', '1', 'เมื่อ θ = 90 องศา cos θ = 0 งานจึงเป็นศูนย์ เช่นแรงสู่ศูนย์กลางตั้งฉากกับความเร็วไม่ทำงาน', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-constant-force')), 'number', 'ใช้แรง 20 นิวตัน ผลักกล่องในแนวตรงไปตามพื้นราบ ระยะ 5 เมตร ในทิศเดียวกับแรง งานที่ทำมีค่ากี่จูล', NULL, '{"value":100,"tolerance":0.5}', 'W = Fs = 20 × 5 = 100 จูล เพราะแรงและระยะทางอยู่ในทิศเดียวกัน', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-constant-force')), 'number', 'ใช้แรง 50 นิวตัน ดึงวัตถุทำมุม 60 องศากับแนวการเคลื่อนที่ ไปเป็นระยะ 4 เมตร งานที่ทำมีค่ากี่จูล (cos 60° = 0.5)', NULL, '{"value":100,"tolerance":0.5}', 'W = Fs cos θ = 50 × 4 × cos 60° = 50 × 4 × 0.5 = 100 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'work-energy'), 'work-energy-kinetic-theorem', 'พลังงานจลน์และทฤษฎีบทงาน-พลังงาน', 'พลังงานจลน์ (Ek) คือพลังงานที่สะสมอยู่ในวัตถุที่กำลังเคลื่อนที่ มีค่าเท่ากับ Ek = (1/2)mv² ทฤษฎีบทงาน-พลังงาน (Work-Energy Theorem) ระบุว่า งานรวมของแรงลัพธ์ทั้งหมดที่กระทำต่อวัตถุจะเท่ากับการเปลี่ยนแปลงพลังงานจลน์ของวัตถุเสมอ นั่นคือ W_net = ΔEk = (1/2)mv² - (1/2)mu² ทฤษฎีนี้ช่วยให้เราสามารถคำนวณความเร็วของวัตถุได้โดยไม่ต้องทราบความเร่งหรือเวลา', 'senior', 2, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-kinetic-theorem'), 'youtube', 'https://www.youtube.com/watch?v=to73ui0N5RA', 'to73ui0N5RA', 'ฟิสิกส์ ม.4 บทที่ 5 งานและพลังงาน ep.3 (พลังงานจลน์, พลังงานศักย์โน้มถ่วง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-kinetic-theorem'), 'newton-force', 'ทดสอบการเปลี่ยนแปลงพลังงานจลน์ของวัตถุเมื่อแรงกระทำต่อเนื่อง', '{"force":{"min":15,"max":100,"default":60},"mass":{"min":1,"max":16,"default":4},"friction":{"min":0,"max":0.5,"step":0.05,"default":0.1}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-kinetic-theorem'), 'balance-force', 'ส่งถ่ายพลังงานจลน์ผ่านความเร่งเป้าหมายได้อย่างแม่นยำ', '{"targetAcc":[1.6,4.8],"tolerance":0.15,"force":{"min":20,"max":96,"default":50},"mass":{"min":1,"max":8,"default":4}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-kinetic-theorem'), 'แบบทดสอบ: พลังงานจลน์และทฤษฎีบทงาน-พลังงาน', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-kinetic-theorem')), 'choice', 'พลังงานจลน์ของวัตถุมวล m เคลื่อนที่ด้วยอัตราเร็ว v มีค่าตามข้อใด', '["K = mv","K = mv²","K = ½mv²","K = ½mv"]', '2', 'พลังงานจลน์ K = ½mv² มีหน่วยเป็นจูลและแปรผันกับกำลังสองของอัตราเร็ว', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-kinetic-theorem')), 'choice', 'ทฤษฎีบทงาน-พลังงานกล่าวว่า งานลัพธ์ที่ทำต่อวัตถุมีค่าเท่ากับอะไร', '["การเปลี่ยนแปลงพลังงานจลน์ของวัตถุ","พลังงานศักย์ของวัตถุ","โมเมนตัมของวัตถุ","แรงคูณกับเวลา"]', '0', 'งานลัพธ์ W = ΔK หรือการเปลี่ยนแปลงพลังงานจลน์ โดยงานลัพธ์ทำให้อัตราเร็วเปลี่ยนไป', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-kinetic-theorem')), 'choice', 'ถ้าอัตราเร็วของวัตถุเพิ่มขึ้นเป็น 2 เท่า พลังงานจลน์จะเปลี่ยนเป็นกี่เท่าของเดิม', '["2 เท่า","4 เท่า","ครึ่งหนึ่ง","เท่าเดิม"]', '1', 'K แปรผันกับ v² เมื่อ v เป็น 2 เท่า K จึงเป็น 4 เท่าของเดิม', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-kinetic-theorem')), 'number', 'วัตถุมวล 2 กิโลกรัม เคลื่อนที่ด้วยอัตราเร็ว 3 เมตร/วินาที มีพลังงานจลน์กี่จูล', NULL, '{"value":9,"tolerance":0.5}', 'K = ½mv² = ½ × 2 × 3² = 9 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-kinetic-theorem')), 'number', 'วัตถุมวล 2 กิโลกรัม เริ่มจากหยุดนิ่ง ถูกแรงลัพธ์ 20 นิวตัน กระทำในแนวการเคลื่อนที่เป็นระยะ 5 เมตร พลังงานจลน์สุดท้ายมีค่ากี่จูล', NULL, '{"value":100,"tolerance":0.5}', 'งานลัพธ์ W = Fs = 20 × 5 = 100 จูล และเริ่มจากนิ่งจึงเท่ากับพลังงานจลน์สุดท้าย 100 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'work-energy'), 'work-energy-potential-energy', 'พลังงานศักย์โน้มถ่วงและยืดหยุ่น', 'พลังงานศักย์คือพลังงานที่สะสมอยู่ในระบบเนื่องจากตำแหน่งหรือการจัดวาง พลังงานศักย์โน้มถ่วงคำนวณจาก Ep = mgh โดย h คือความสูงวัดจากระดับอ้างอิง ส่วนพลังงานศักย์ยืดหยุ่นในสปริงคำนวณจาก Eps = (1/2)kx² โดย k คือค่าคงตัวสปริง และ x คือระยะยืดหรือหดจากตำแหน่งสมดุล พลังงานศักย์ทั้งสองประเภทจะเปลี่ยนกลับเป็นพลังงานจลน์เมื่อวัตถุเคลื่อนที่', 'senior', 3, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-potential-energy'), 'youtube', 'https://www.youtube.com/watch?v=q-gYA6PonO4', 'q-gYA6PonO4', 'ฟิสิกส์ ม.4 บทที่ 5 งานและพลังงาน ep.4 (พลังงานศักย์ยืดหยุ่น, หลักของงานและพลังงาน)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-potential-energy'), 'newton-force', 'จำลองการสะสมพลังงานเมื่อออกแรงต้านแรงดึงกลับของระบบ', '{"force":{"min":10,"max":85,"default":40},"mass":{"min":1,"max":14,"default":4},"friction":{"min":0,"max":0.4,"step":0.05,"default":0.05}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-potential-energy'), 'balance-force', 'ปรับสมดุลแรงผลักและมวลเพื่อให้ได้ความเร่งเทียบเท่าพลังงานศักย์', '{"targetAcc":[1.3,4.2],"tolerance":0.16,"force":{"min":16,"max":86,"default":40},"mass":{"min":2,"max":9,"default":5}}');
INSERT INTO quizzes (lesson_id, title, pass_score) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-potential-energy'), 'แบบทดสอบ: พลังงานศักย์', 60) ON CONFLICT(lesson_id) DO UPDATE SET title=excluded.title, pass_score=excluded.pass_score;
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-potential-energy')), 'choice', 'พลังงานศักย์โน้มถ่วงของวัตถุมวล m อยู่สูงจากระดับอ้างอิงเป็นระยะ h มีค่าตามข้อใด', '["U = mgh","U = ½mgh","U = mgh²","U = mg/h"]', '0', 'พลังงานศักย์โน้มถ่วง U = mgh เป็นพลังงานสะสมจากตำแหน่งที่อยู่สูงขึ้น', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-potential-energy')), 'choice', 'สปริงค่าคงที่ k ยืดออกเป็นระยะ x จากตำแหน่งสมดุล พลังงานศักย์ยืดหยุ่นมีค่าตามข้อใด', '["U = kx","U = ½kx²","U = kx²","U = ½kx"]', '1', 'พลังงานศักย์ยืดหยุ่น U = ½kx² สะสมในสปริงที่ยืดหรือหด', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-potential-energy')), 'choice', 'ถ้ายืดสปริงออกเป็น 2 เท่าของเดิม พลังงานศักย์ยืดหยุ่นเปลี่ยนเป็นกี่เท่าของเดิม', '["2 เท่า","4 เท่า","เท่าเดิม","ครึ่งหนึ่ง"]', '1', 'จาก U = ½kx² แปรผันกับกำลังสองของการยืด เมื่อ x เป็น 2 เท่า U จึงเป็น 4 เท่า', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-potential-energy')), 'number', 'วัตถุมวล 2 กิโลกรัม ยกขึ้นอยู่สูง 5 เมตรจากพื้น พลังงานศักย์โน้มถ่วงมีค่ากี่จูล (ใช้ g = 10 เมตร/วินาที²)', NULL, '{"value":100,"tolerance":0.5}', 'U = mgh = 2 × 10 × 5 = 100 จูล', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-potential-energy')), 'number', 'สปริงค่าคงที่ 200 นิวตัน/เมตร ถูกยืดออก 0.1 เมตร พลังงานศักย์ยืดหยุ่นมีค่ากี่จูล', NULL, '{"value":1,"tolerance":0.5}', 'U = ½kx² = ½ × 200 × 0.1² = ½ × 200 × 0.01 = 1 จูล', 5);
INSERT INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) VALUES ((SELECT id FROM chapters WHERE slug = 'work-energy'), 'work-energy-power-efficiency', 'กำลังและประสิทธิภาพ', 'กำลัง (P) คืออัตราการทำงานหรือปริมาณพลังงานที่ถ่ายโอนในหนึ่งหน่วยเวลา คำนวณจาก P = W/t หรือสำหรับแรงคงตัวที่ทำให้วัตถุเคลื่อนที่ด้วยความเร็ว v จะได้ P = F v กำลังมีหน่วยเป็นวัตต์ (W) หรือจูลต่อวินาที ประสิทธิภาพ (Efficiency, Eff) ของเครื่องจักรบอกถึงสัดส่วนพลังงานที่นำไปใช้ประโยชน์ได้เทียบกับพลังงานที่ป้อนเข้าทั้งหมด โดยคำนวณจาก Eff = (งานที่ได้ / งานที่ใส่) × 100%', 'senior', 5, 'published') ON CONFLICT(slug) DO UPDATE SET chapter_id=excluded.chapter_id, title=excluded.title, summary=excluded.summary, level=excluded.level, sort_order=excluded.sort_order, status=excluded.status;
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-power-efficiency'), 'youtube', 'https://www.youtube.com/watch?v=bNzj4t6Edtk', 'bNzj4t6Edtk', 'ฟิสิกส์ ม.4 บทที่ 5 งานและพลังงาน ep.2 (งานพื้นที่ใต้กราฟ, กำลัง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/channel/UCnRGVpAjNHe8tJT3BtqFAuw', 1);
