INSERT INTO animations (lesson_id, engine, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-power-efficiency'), 'newton-force', 'วัดอัตราการทำงานต่อหนึ่งหน่วยเวลาเมื่อวัตถุเคลื่อนที่ด้วยความเร็วต่างๆ', '{"force":{"min":15,"max":95,"default":55},"mass":{"min":2,"max":18,"default":6},"friction":{"min":0.05,"max":0.6,"step":0.05,"default":0.2}}');
INSERT INTO games (lesson_id, template, title, config_json) VALUES ((SELECT id FROM lessons WHERE slug = 'work-energy-power-efficiency'), 'balance-force', 'ปรับกำลังขับเคลื่อนให้สร้างความเร่งเข้าสู่ขอบเขตเป้าหมาย', '{"targetAcc":[1.7,4.7],"tolerance":0.14,"force":{"min":22,"max":96,"default":52},"mass":{"min":2,"max":10,"default":5}}');
