INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-power-efficiency')), 'choice', 'กำลัง P หาได้จากสูตรใด โดย W คืองาน และ t คือเวลา', '["P = Wt","P = W/t","P = t/W","P = ½Wt"]', '1', 'กำลังคืออัตราการทำงานต่อหน่วยเวลา P = W/t ยิ่งทำงานเร็วเท่าใดกำลังยิ่งมาก', 1);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-power-efficiency')), 'choice', 'หน่วยของกำลังในระบบเอสไอคือข้อใด', '["จูล","นิวตัน","วัตต์","เมตร/วินาที"]', '2', 'กำลังมีหน่วยเป็นวัตต์ โดย 1 วัตต์ = 1 จูล/วินาที', 2);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-power-efficiency')), 'choice', 'ประสิทธิภาพของเครื่องจักรคำนวณจากความสัมพันธ์ข้อใด', '["งานที่ได้ หาร งานที่ใส่ คูณ 100 เปอร์เซ็นต์","งานที่ใส่ หาร งานที่ได้ คูณ 100 เปอร์เซ็นต์","กำลัง คูณ เวลา","งานที่ได้ คูณ งานที่ใส่"]', '0', 'ประสิทธิภาพ = (งานที่ได้/งานที่ใส่) × 100% วัดว่าเครื่องเปลี่ยนพลังงานเข้าสู่พลังงานเป็นประโยชน์ได้ดีเพียงใด', 3);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-power-efficiency')), 'number', 'เครื่องจักรทำงานได้ 200 จูล ในเวลา 10 วินาที กำลังของเครื่องจักรมีค่ากี่วัตต์', NULL, '{"value":20,"tolerance":0.5}', 'P = W/t = 200/10 = 20 วัตต์', 4);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE lesson_id = (SELECT id FROM lessons WHERE slug = 'work-energy-power-efficiency')), 'number', 'เครื่องจักรให้งานที่เป็นประโยชน์ 90 จูล จากพลังงานที่ใส่เข้าไป 150 จูล ประสิทธิภาพของเครื่องจักรมีค่ากี่เปอร์เซ็นต์', NULL, '{"value":60,"tolerance":0.5}', 'ประสิทธิภาพ = (90/150) × 100 = 60 เปอร์เซ็นต์', 5);
